INSERT INTO `pvn_audit_logs` VALUES (43, 1, 'update', 'Leader', 1, '{\"description\":\"Bà Nguyễn Thị Minh Huệ có hơn 20 năm kinh nghiệm trong lĩnh vực quản trị doanh nghiệp và đầu tư chiến lược.\\n\\nVới 15 năm gắn bó cùng Đông Sơn Holdings, bà đã dẫn dắt công ty vượt qua nhiều giai đoạn chuyển mình quan trọng, khẳng định vị thế của tập đoàn trong các lĩnh vực trọng yếu.\",\"stat2_label\":\"Năm tại tập đoàn\",\"updated_at\":\"2026-08-07 01:32:29\"}', '{\"description\":\"Bà Nguyễn Thị Minh Huệ có hơn 20 năm kinh nghiệm trong lĩnh vực quản trị doanh nghiệp và đầu tư chiến lược.\\r\\n\\r\\nVới 15 năm gắn bó cùng Đông Sơn Holdings, bà đã dẫn dắt công ty vượt qua nhiều giai đoạn chuyển mình quan trọng, khẳng định vị thế của tập đoàn trong các lĩnh vực trọng yếu.\",\"stat2_label\":\"Năm tại công ty\",\"updated_at\":{\"expression\":\"NOW()\",\"params\":[]}}', '14.238.34.100', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', '2026-08-11 16:39:10');
INSERT INTO `pvn_audit_logs` VALUES (44, 1, 'update', 'Leader', 1, '{\"description\":\"Bà Nguyễn Thị Minh Huệ có hơn 20 năm kinh nghiệm trong lĩnh vực quản trị doanh nghiệp và đầu tư chiến lược.\\r\\n\\r\\nVới 15 năm gắn bó cùng Đông Sơn Holdings, bà đã dẫn dắt công ty vượt qua nhiều giai đoạn chuyển mình quan trọng, khẳng định vị thế của tập đoàn trong các lĩnh vực trọng yếu.\",\"updated_at\":\"2026-08-11 16:39:10\"}', '{\"description\":\"Bà Nguyễn Thị Minh Huệ có hơn 20 năm kinh nghiệm trong lĩnh vực quản trị doanh nghiệp và đầu tư chiến lược.\\r\\n\\r\\nVới 15 năm gắn bó cùng Đông Sơn Holdings, bà đã dẫn dắt công ty vượt qua nhiều giai đoạn chuyển mình quan trọng, khẳng định vị thế của công ty trong các lĩnh vực trọng yếu.\",\"updated_at\":{\"expression\":\"NOW()\",\"params\":[]}}', '14.238.34.100', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', '2026-08-11 16:39:58');
