INSERT INTO `pvn_audit_logs` VALUES (50, 1, 'update', 'BusinessSector', 5, '{\"hero_subtitle\":\"Kế thừa truyền thống kỷ luật và uy tín từ Lữ đoàn 319, chúng tôi tiên phong ứng dụng công nghệ hiện đại để xây dựng những công trình mang tầm vóc quốc gia, đảm bảo tiến độ, chất lượng và hiệu quả vượt trội.\",\"updated_at\":\"2026-08-11 14:36:56\",\"heritage_body\":\"Mảng thi công xây lắp của Đông Sơn Holdings tự hào kế thừa truyền thống kỷ luật, chuyên nghiệp và uy tín từ Lữ đoàn 319. Chúng tôi không chỉ xây dựng các công trình, mà còn kiến tạo những giá trị bền vững cho xã hội.\\n\\nVới đội ngũ lãnh đạo dày dạn kinh nghiệm, lực lượng lao động tay nghề cao và sự đầu tư mạnh mẽ vào công nghệ quản lý dự án hiện đại, Đông Sơn cam kết mang đến những giải pháp thi công tối ưu, đáp ứng những tiêu chuẩn khắt khe nhất về an toàn, chất lượng và tiến độ.\"}', '{\"hero_subtitle\":null,\"updated_at\":{\"expression\":\"NOW()\",\"params\":[]},\"heritage_body\":\"Mảng thi công xây lắp của Đông Sơn Holdings tự hào kế thừa truyền thống kỷ luật, chuyên nghiệp và uy tín từ Lữ đoàn 319. Chúng tôi không chỉ xây dựng các công trình, mà còn kiến tạo những giá trị bền vững cho xã hội.\\r\\n\\r\\nVới đội ngũ lãnh đạo dày dạn kinh nghiệm, lực lượng lao động tay nghề cao và sự đầu tư mạnh mẽ vào công nghệ quản lý dự án hiện đại, Đông Sơn cam kết mang đến những giải pháp thi công tối ưu, đáp ứng những tiêu chuẩn khắt khe nhất về an toàn, chất lượng và tiến độ.\"}', '14.238.34.100', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', '2026-08-11 16:57:57');
INSERT INTO `pvn_audit_logs` VALUES (51, 1, 'update', 'BusinessSector', 5, '{\"updated_at\":\"2026-08-11 16:57:57\",\"legacy_text\":\"Từ Lữ đoàn 319, chúng tôi mang theo tinh thần thép và sự chính xác tuyệt đối vào mỗi công trình kiến tạo.\"}', '{\"updated_at\":{\"expression\":\"NOW()\",\"params\":[]},\"legacy_text\":null}', '14.238.34.100', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', '2026-08-11 16:58:09');
INSERT INTO `pvn_audit_logs` VALUES (52, 1, 'update', 'BusinessSector', 5, '{\"updated_at\":\"2026-08-11 16:58:09\",\"heritage_body\":\"Mảng thi công xây lắp của Đông Sơn Holdings tự hào kế thừa truyền thống kỷ luật, chuyên nghiệp và uy tín từ Lữ đoàn 319. Chúng tôi không chỉ xây dựng các công trình, mà còn kiến tạo những giá trị bền vững cho xã hội.\\r\\n\\r\\nVới đội ngũ lãnh đạo dày dạn kinh nghiệm, lực lượng lao động tay nghề cao và sự đầu tư mạnh mẽ vào công nghệ quản lý dự án hiện đại, Đông Sơn cam kết mang đến những giải pháp thi công tối ưu, đáp ứng những tiêu chuẩn khắt khe nhất về an toàn, chất lượng và tiến độ.\"}', '{\"updated_at\":{\"expression\":\"NOW()\",\"params\":[]},\"heritage_body\":\"Mảng thi công xây lắp của Đông Sơn Holdings tự hào kế thừa truyền thống kỷ luật, chuyên nghiệp và uy tín từ Tổng công ty 319 - Bộ Quốc phòng. Chúng tôi không chỉ xây dựng các công trình, mà còn kiến tạo những giá trị bền vững cho xã hội.\\r\\n\\r\\nVới đội ngũ lãnh đạo dày dạn kinh nghiệm, lực lượng lao động tay nghề cao và sự đầu tư mạnh mẽ vào công nghệ quản lý dự án hiện đại, Đông Sơn cam kết mang đến những giải pháp thi công tối ưu, đáp ứng những tiêu chuẩn khắt khe nhất về an toàn, chất lượng và tiến độ.\"}', '14.238.34.100', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', '2026-08-11 16:58:43');
INSERT INTO `pvn_audit_logs` VALUES (53, 1, 'update', 'BusinessSector', 7, '{\"updated_at\":\"2026-08-11 14:36:56\",\"legacy_year\":\"2020\",\"heritage_body\":\"Đông Sơn Holdings phát triển nhà ở xã hội và khu đô thị bền vững. Dự án Nhà ở xã hội Bãi Viên – Nam Định gồm 1.100 căn hộ với tổng vốn hơn 909 tỷ đồng.\\n\\nChúng tôi chú trọng quy hoạch đồng bộ hạ tầng, tiện ích và cảnh quan, hướng tới những khu đô thị xanh, thông minh và giàu bản sắc.\"}', '{\"updated_at\":{\"expression\":\"NOW()\",\"params\":[]},\"legacy_year\":\"2025\",\"heritage_body\":\"Đông Sơn Holdings phát triển nhà ở xã hội và khu đô thị bền vững. Dự án Nhà ở xã hội Bãi Viên – Nam Định gồm 1.100 căn hộ với tổng vốn hơn 909 tỷ đồng.\\r\\n\\r\\nChúng tôi chú trọng quy hoạch đồng bộ hạ tầng, tiện ích và cảnh quan, hướng tới những khu đô thị xanh, thông minh và giàu bản sắc.\"}', '14.238.34.100', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', '2026-08-11 17:03:17');
