INSERT INTO `pvn_business_sectors` VALUES (5, 'thi-cong-xay-lap', '01', 'Thi công & Xây lắp', 'Thi công và xây lắp', 'Nền móng cho mọi công trình', 'Tổng thầu thi công các công trình giao thông, hạ tầng kỹ thuật, thủy lợi, dân dụng và công nghiệp trên toàn quốc.', NULL, NULL, 'Tổng thầu thi công các công trình giao thông, hạ tầng kỹ thuật, thủy lợi, dân dụng và công nghiệp trên toàn quốc.', 'Thi công & Xây lắp', 'Năng lực tổng thầu EPC cho các công trình trọng điểm, đảm bảo tiến độ, chất lượng và an toàn lao động.', 21, NULL, 'Khám phá dự án', '#du-an', 'Xem thi công của chúng tôi', 1, 1, 1, 1, '2026-07-24 16:45:10', '2026-08-12 02:57:43', NULL, NULL, '2009', 'Kế Thừa Truyền thống', NULL, 'Chúng tôi không chỉ xây dựng các công trình, mà còn kiến tạo những giá trị bền vững cho xã hội.', '100', '+', 'Dự án hoàn thành', 'Dự án', '5000', '+', 'Nhân sự chất lượng cao', 'Nhân sự', 'Kế Thừa Truyền thống, Kiến Tạo Tương Lai', 'Mảng thi công xây lắp của Đông Sơn Holdings tự hào kế thừa truyền thống kỷ luật, chuyên nghiệp và uy tín từ Tổng công ty 319 - Bộ Quốc phòng. Chúng tôi không chỉ xây dựng các công trình, mà còn kiến tạo những giá trị bền vững cho xã hội.\r\n\r\nVới đội ngũ lãnh đạo dày dạn kinh nghiệm, lực lượng lao động tay nghề cao và sự đầu tư mạnh mẽ vào công nghệ quản lý dự án hiện đại, Đông Sơn cam kết mang đến những giải pháp thi công tối ưu, đáp ứng những tiêu chuẩn khắt khe nhất về an toàn, chất lượng và tiến độ.', NULL, 'Năng Lực Cốt Lõi', 'Chúng tôi cung cấp các giải pháp thi công toàn diện, bao phủ nhiều lĩnh vực trọng điểm của nền kinh tế, đảm bảo năng lực thực thi vượt trội cho mọi quy mô dự án.');
INSERT INTO `pvn_business_sectors` VALUES (6, 'dau-tu-bot-ha-tang', '02', 'Đầu tư BOT & Hạ tầng', 'Đầu tư BOT & Hạ tầng', 'Kết nối hành lang kinh tế', 'Trở thành doanh nghiệp uy tín trong lĩnh vực năng lượng, bất động sản và xây lắp.', 'Đầu tư các dự án hạ tầng giao thông theo hình thức BOT, kết nối những hành lang kinh tế trọng điểm và tạo động lực tăng trưởng dài hạn cho các địa phương.', NULL, 'Đầu tư các dự án hạ tầng giao thông theo hình thức BOT. Dự án tiêu biểu: BOT Hà Nội – Bắc Giang với tổng mức đầu tư 4.213 tỷ đồng.', 'Đầu tư BOT & Hạ tầng', 'Đầu tư các dự án hạ tầng giao thông theo hình thức BOT. Dự án tiêu biểu: BOT Hà Nội – Bắc Giang với tổng mức đầu tư 4.213 tỷ đồng.', 6, NULL, 'Khám phá dự án', '#du-an', 'Tìm hiểu mô hình BOT', 2, 1, 1, 1, '2026-07-24 16:45:10', '2026-08-11 14:36:56', NULL, NULL, '2014', 'Dấu Ấn Hạ Tầng', 'Khởi đầu với dự án BOT Hà Nội – Bắc Giang, Đông Sơn khẳng định năng lực đầu tư hạ tầng giao thông quy mô lớn.', 'Mỗi tuyến đường chúng tôi đầu tư là một mạch máu kết nối tăng trưởng cho vùng kinh tế.', '4213', ' tỷ', 'Tổng mức đầu tư BOT', 'Đầu tư BOT', '20', '+', 'Năm kinh nghiệm', 'Kinh nghiệm', 'Đầu Tư Hạ Tầng, Kết Nối Tương Lai', 'Đông Sơn Holdings đầu tư các dự án hạ tầng giao thông theo hình thức BOT, với dự án tiêu biểu BOT Hà Nội – Bắc Giang có tổng mức đầu tư 4.213 tỷ đồng.\n\nChúng tôi theo đuổi mô hình đầu tư minh bạch, quản trị dòng vốn chặt chẽ và vận hành hiệu quả, bảo đảm hài hòa lợi ích giữa nhà nước, nhà đầu tư và người dân.', NULL, 'Năng Lực Đầu Tư', 'Từ chuẩn bị dự án đến vận hành khai thác, chúng tôi làm chủ toàn bộ chuỗi giá trị đầu tư hạ tầng giao thông theo hình thức BOT.');
INSERT INTO `pvn_business_sectors` VALUES (7, 'nha-o-do-thi', '03', 'Nhà ở & Đô thị', 'Nhà ở & Đô thị', 'Kiến tạo không gian sống', 'Phát triển nhà ở xã hội và khu đô thị bền vững, nâng tầm chất lượng sống cho cộng đồng.', 'Phát triển nhà ở xã hội và khu đô thị bền vững, nâng tầm chất lượng sống cho cộng đồng với những không gian sống nhân văn và hiện đại.', NULL, 'Phát triển nhà ở xã hội và khu đô thị bền vững. Dự án Nhà ở xã hội Bãi Viên – Nam Định: 1.100 căn hộ, tổng vốn hơn 909 tỷ đồng.', 'Nhà ở & Đô thị', 'Dự án Nhà ở xã hội Bãi Viên – Nam Định: 1.100 căn hộ, tổng vốn hơn 909 tỷ đồng.', 10, NULL, 'Khám phá dự án', '#du-an', 'Khám phá khu đô thị', 3, 1, 1, 1, '2026-07-24 16:45:10', '2026-08-11 17:03:17', NULL, NULL, '2025', 'Không Gian Sống', 'Từ dự án Nhà ở xã hội Bãi Viên – Nam Định, Đông Sơn hiện thực hóa cam kết an cư cho hàng nghìn gia đình.', 'Chúng tôi kiến tạo không chỉ những căn nhà, mà là những cộng đồng đáng sống.', '1100', '+', 'Căn hộ đã phát triển', 'Căn hộ', '909', ' tỷ', 'Tổng vốn đầu tư', 'Vốn đầu tư', 'Kiến Tạo Không Gian Sống Bền Vững', 'Đông Sơn Holdings phát triển nhà ở xã hội và khu đô thị bền vững. Dự án Nhà ở xã hội Bãi Viên – Nam Định gồm 1.100 căn hộ với tổng vốn hơn 909 tỷ đồng.\r\n\r\nChúng tôi chú trọng quy hoạch đồng bộ hạ tầng, tiện ích và cảnh quan, hướng tới những khu đô thị xanh, thông minh và giàu bản sắc.', NULL, 'Năng Lực Phát Triển', 'Làm chủ toàn bộ quá trình từ quy hoạch, phát triển dự án đến thi công và bàn giao các khu nhà ở, đô thị hiện đại.');
INSERT INTO `pvn_business_sectors` VALUES (8, 'nang-luong-kcn', '04', 'Năng lượng & KCN', 'Năng lượng & KCN', 'Động lực tăng trưởng xanh', 'Đầu tư phát triển khu công nghiệp và năng lượng tái tạo, tạo nền tảng tăng trưởng dài hạn.', 'Định hướng chiến lược mới: đầu tư phát triển khu công nghiệp và năng lượng tái tạo, tạo nền tảng tăng trưởng xanh và bền vững cho tương lai.', NULL, 'Định hướng chiến lược mới: đầu tư phát triển khu công nghiệp và năng lượng tái tạo, tạo nền tảng tăng trưởng dài hạn.', 'Năng lượng & KCN', 'Định hướng chiến lược mới: phát triển hạ tầng khu công nghiệp gắn với năng lượng tái tạo.', 21, NULL, 'Khám phá dự án', '#du-an', 'Tìm hiểu định hướng xanh', 4, 1, 1, 1, '2026-07-24 16:45:10', '2026-08-11 14:36:56', NULL, NULL, '2024', 'Tăng Trưởng Xanh', 'Mở rộng sang khu công nghiệp và năng lượng tái tạo, Đông Sơn đón đầu xu hướng phát triển bền vững.', 'Năng lượng sạch và hạ tầng công nghiệp là nền tảng cho tăng trưởng dài hạn.', '50', '+', 'MW năng lượng tái tạo', 'Năng lượng', '300', ' ha', 'Quỹ đất công nghiệp', 'Quỹ đất', 'Động Lực Tăng Trưởng Xanh', 'Đông Sơn Holdings xác định năng lượng tái tạo và khu công nghiệp là định hướng chiến lược mới, tạo nền tảng tăng trưởng dài hạn.\n\nChúng tôi đầu tư phát triển hạ tầng khu công nghiệp gắn với các nguồn năng lượng sạch, hướng tới mục tiêu phát triển bền vững và trung hòa carbon.', NULL, 'Năng Lực Chiến Lược', 'Đầu tư đồng bộ hạ tầng khu công nghiệp và các dự án năng lượng tái tạo, đón đầu xu hướng chuyển dịch năng lượng.');
INSERT INTO `pvn_contact_messages` VALUES (1, 'Phạm Văn Nhất', '0975498885', 'phamnhat.cn06@gmail.com', 'Test liện hệ', 'new', NULL, '14.238.34.100', 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/151.0.0.0 Safari/537.36', '2026-08-11 15:15:57', '2026-08-11 15:15:57', NULL);
INSERT INTO `pvn_core_values` VALUES (7, 'Trách nhiệm', 'Cam kết thực hiện đúng tiến độ, chất lượng và an toàn lao động trong mọi dự án thi công.', 20, 'default', 1, 1, '2026-07-24 16:45:10', '2026-07-24 16:45:10', NULL);
INSERT INTO `pvn_core_values` VALUES (8, 'Chuyên nghiệp', 'Đội ngũ kỹ sư, cán bộ kỹ thuật nhiều năm kinh nghiệm trên các công trình trọng điểm quốc gia.', 17, 'award', 2, 1, '2026-07-24 16:45:10', '2026-07-24 16:45:10', NULL);
INSERT INTO `pvn_core_values` VALUES (9, 'Đổi mới', 'Không ngừng ứng dụng công nghệ thi công tiên tiến, nâng cao năng lực quản trị và triển khai dự án.', 18, 'inner', 3, 1, '2026-07-24 16:45:10', '2026-07-24 16:45:10', NULL);
INSERT INTO `pvn_core_values` VALUES (10, 'Tin cậy', 'Đối tác tin cậy của các tổng công ty nhà nước, chủ đầu tư lớn và ban quản lý dự án quốc gia.', 19, 'default', 4, 1, '2026-07-24 16:45:10', '2026-07-24 16:45:10', NULL);
INSERT INTO `pvn_hero_slides` VALUES (5, 'Đông Sơn Holdings', 'Trở thành doanh nghiệp uy tín trong lĩnh vực\nnăng lượng, bất động sản và xây lắp', 21, 28, 'Khám phá dự án', '#du-an', 'Lĩnh vực hoạt động', '#linh-vuc', 50, 1, 1, '2026-07-24 16:45:10', '2026-07-24 16:45:10', NULL);
INSERT INTO `pvn_hero_slides` VALUES (6, 'Hạ tầng & BOT', 'Kết nối hành lang kinh tế, kiến tạo những\ntuyến giao thông trọng điểm quốc gia', 21, 28, 'Khám phá dự án', '#du-an', 'Lĩnh vực hoạt động', '#linh-vuc', 50, 2, 1, '2026-07-24 16:45:10', '2026-07-24 16:45:10', NULL);
INSERT INTO `pvn_hero_slides` VALUES (7, 'Bất động sản', 'Phát triển các khu đô thị và nhà ở bền vững,\nnâng tầm chất lượng sống cho cộng đồng', 21, 28, 'Khám phá dự án', '#du-an', 'Lĩnh vực hoạt động', '#linh-vuc', 50, 3, 1, '2026-07-24 16:45:10', '2026-07-24 16:45:10', NULL);
INSERT INTO `pvn_hero_slides` VALUES (8, 'Năng lượng', 'Đầu tư năng lượng tái tạo và khu công nghiệp,\nhướng tới một tương lai xanh và bền vững', 21, 28, 'Khám phá dự án', '#du-an', 'Lĩnh vực hoạt động', '#linh-vuc', 50, 4, 1, '2026-07-24 16:45:10', '2026-07-24 16:45:10', NULL);
INSERT INTO `pvn_leaders` VALUES (1, 'Nguyễn Thị Minh Huệ', 'Chủ tịch Hội đồng quản trị', 'Bà Nguyễn Thị Minh Huệ có hơn 20 năm kinh nghiệm trong lĩnh vực quản trị doanh nghiệp và đầu tư chiến lược.\r\n\r\nVới 15 năm gắn bó cùng Đông Sơn Holdings, bà đã dẫn dắt công ty vượt qua nhiều giai đoạn chuyển mình quan trọng, khẳng định vị thế của công ty trong các lĩnh vực trọng yếu.', NULL, 1, '20+', 'Năm kinh nghiệm', '15', 'Năm tại công ty', 1, 1, '2026-08-07 01:32:29', '2026-08-11 16:39:58', NULL);
INSERT INTO `pvn_leaders` VALUES (2, 'Nguyễn Thành Trung', 'Phó Chủ tịch HĐQT', 'Ông có hơn 20 năm kinh nghiệm trong quản trị điều hành, đóng vai trò then chốt trong định hướng phát triển của tập đoàn.', NULL, 0, NULL, NULL, NULL, NULL, 2, 1, '2026-08-07 01:32:29', '2026-08-07 01:32:29', NULL);
INSERT INTO `pvn_leaders` VALUES (3, 'Nguyễn Tiến Hưng', 'Thành viên HĐQT / Tổng giám đốc', 'Nắm giữ vai trò chỉ huy điều hành, chịu trách nhiệm triển khai chiến lược và vận hành toàn diện các hoạt động kinh doanh.', NULL, 0, NULL, NULL, NULL, NULL, 3, 1, '2026-08-07 01:32:29', '2026-08-07 01:32:29', NULL);
INSERT INTO `pvn_leaders` VALUES (4, 'Lại Thành Nam', 'Thành viên HĐQT', 'Kỹ sư xây dựng với 17 năm kinh nghiệm, đóng góp quan trọng vào năng lực thi công và quản lý dự án của tập đoàn.', NULL, 0, NULL, NULL, NULL, NULL, 4, 1, '2026-08-07 01:32:29', '2026-08-07 01:32:29', NULL);
INSERT INTO `pvn_leaders` VALUES (5, 'Nguyễn Giang Nam', 'Thành viên HĐQT', 'Chuyên gia tài chính và đầu tư (M&A), đóng góp vào chiến lược vốn và mở rộng danh mục đầu tư của tập đoàn.', NULL, 0, NULL, NULL, NULL, NULL, 5, 1, '2026-08-07 01:32:29', '2026-08-07 01:32:29', NULL);
