INSERT INTO `pvn_news_posts` VALUES (1, 'chao-moi-nguoi-1', 6, 'Chào tất cả mọi người!', NULL, '<!-- wp:paragraph -->\n<p>Cảm ơn vì đã sử dụng WordPress. Đây là bài viết đầu tiên của bạn. Sửa hoặc xóa nó, và bắt đầu bài viết của bạn nhé!</p>\n<!-- /wp:paragraph -->', NULL, '2023-09-22 08:45:05', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/chao-moi-nguoi/', 0, '2026-08-12 01:58:48', '2026-08-12 01:58:48', NULL);
INSERT INTO `pvn_news_posts` VALUES (2, 'goi-thau-xay-lap-thuoc-du-an-nha-van-hoa-sinh-vien-thanh-pho-tai-dai-hoc-quoc-gia-thanh-pho-ho-chi-minh-364', 7, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN NHÀ VĂN HÓA SINH VIÊN THÀNH PHỐ TẠI ĐẠI HỌC QUỐC GIA THÀNH PHỐ HỒ CHÍ MINH', NULL, '<p data-start=\"97\" data-end=\"353\">Dự án xây dựng Nhà Văn hóa Sinh viên Thành phố tại Đại học Quốc gia Thành phố Hồ Chí Minh là công trình văn hóa – giáo dục có ý nghĩa quan trọng, phục vụ nhu cầu sinh hoạt, học tập, giao lưu và tổ chức sự kiện của đông đảo sinh viên trên địa bàn Thành phố.</p>\n<p data-start=\"355\" data-end=\"767\">Công trình được đầu tư xây dựng với mục tiêu hình thành một không gian sinh hoạt cộng đồng hiện đại, đa chức năng, đáp ứng các hoạt động văn hóa, hội thảo, triển lãm, biểu diễn nghệ thuật và các chương trình hỗ trợ sinh viên. Với vị trí nằm trong khu đô thị đại học quy mô lớn, dự án đóng vai trò là điểm nhấn kiến trúc, góp phần hoàn thiện hạ tầng xã hội và nâng cao chất lượng đời sống tinh thần cho sinh viên.</p>\n<p data-start=\"769\" data-end=\"1033\">Quá trình thi công đòi hỏi sự phối hợp chặt chẽ giữa các đơn vị liên quan nhằm đảm bảo yêu cầu kỹ thuật, mỹ thuật và tiến độ thực hiện. Công trình được triển khai theo các tiêu chuẩn xây dựng hiện hành, chú trọng tính bền vững, an toàn và hiệu quả sử dụng lâu dài.</p>\n<p data-start=\"1035\" data-end=\"1360\" data-is-last-node=\"\" data-is-only-node=\"\">Sau khi hoàn thành và đưa vào hoạt động, Nhà Văn hóa Sinh viên Thành phố không chỉ đáp ứng nhu cầu sinh hoạt văn hóa của sinh viên Đại học Quốc gia TP. Hồ Chí Minh mà còn là địa điểm tổ chức nhiều sự kiện quy mô lớn, góp phần thúc đẩy các hoạt động giao lưu học thuật, sáng tạo và phát triển kỹ năng toàn diện cho thế hệ trẻ.</p>\n <img class=\"alignnone wp-image-374 size-full\" src=\"/uploads/news/2023/10/CT-nha-van-hoa-sinh-vien.jpg\" alt=\"\" width=\"653\" height=\"446\" />', NULL, '2023-10-11 10:09:03', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/goi-thau-xay-lap-thuoc-du-an-nha-van-hoa-sinh-vien-thanh-pho-tai-dai-hoc-quoc-gia-thanh-pho-ho-chi-minh/', 0, '2026-08-12 01:59:17', '2026-08-12 01:59:17', NULL);
INSERT INTO `pvn_news_posts` VALUES (3, 'goi-thau-xay-lap-xay-dung-thiet-bi-dieu-hoa-pccc-may-bom-va-hang-muc-chung-thuoc-cong-trinh-xay-dung-tru-so-vien-kiem-sat-nhan-dan-quan-7-391', 9, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN XÂY DỰNG TRỤ SỞ VIỆN KIỂM SÁT NHÂN DÂN QUẬN 7', NULL, '<p data-start=\"62\" data-end=\"297\">Công trình xây dựng Trụ sở Viện Kiểm sát nhân dân Quận 7 là dự án thuộc lĩnh vực công trình hành chính – tư pháp, góp phần hoàn thiện cơ sở vật chất phục vụ hoạt động của các cơ quan bảo vệ pháp luật trên địa bàn Thành phố Hồ Chí Minh.</p>\n<p data-start=\"299\" data-end=\"692\">Dự án được triển khai với mục tiêu xây dựng trụ sở làm việc khang trang, đồng bộ, đáp ứng yêu cầu về công năng sử dụng, tiêu chuẩn kỹ thuật và tính trang nghiêm của một cơ quan tư pháp. Công trình bao gồm các hạng mục phục vụ hoạt động chuyên môn, khu làm việc của cán bộ, công chức, cùng hệ thống hạ tầng kỹ thuật được đầu tư hiện đại, đảm bảo điều kiện làm việc ổn định, an toàn và hiệu quả.</p>\n<p data-start=\"694\" data-end=\"924\">Trong quá trình thi công, đơn vị thực hiện đã tuân thủ nghiêm ngặt các quy định về chất lượng, an toàn lao động và tiến độ, đồng thời đảm bảo yêu cầu về kiến trúc phù hợp với tính chất đặc thù của công trình hành chính – tư pháp.</p>\n<p data-start=\"926\" data-end=\"1188\" data-is-last-node=\"\" data-is-only-node=\"\">Sau khi hoàn thành và đưa vào sử dụng, trụ sở mới của Viện Kiểm sát nhân dân Quận 7 góp phần nâng cao điều kiện làm việc, tăng cường hiệu quả hoạt động nghiệp vụ, đồng thời thể hiện sự quan tâm đầu tư của Nhà nước đối với hệ thống cơ quan tư pháp tại địa phương.</p>', 281, '2023-10-11 10:27:02', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/goi-thau-xay-lap-xay-dung-thiet-bi-dieu-hoa-pccc-may-bom-va-hang-muc-chung-thuoc-cong-trinh-xay-dung-tru-so-vien-kiem-sat-nhan-dan-quan-7/', 0, '2026-08-12 01:59:17', '2026-08-12 01:59:17', NULL);
INSERT INTO `pvn_news_posts` VALUES (4, 'ef-83-98goi-thau-so-15-xay-dung-ha-tang-ky-thuat-khu-cac-dai-doi-truc-thuoc-thuoc-cong-trinh-doanh-trai-so-chi-huy-lu-doan-va-cac-dai-doi-truc-thuoc-lu-doan-950-quan-khu-9-393', 9, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN LỮ ĐOÀN 950 - QUÂN KHU 9', NULL, '<p data-start=\"41\" data-end=\"257\">Công trình Lữ đoàn 950 thuộc Quân khu 9 là dự án xây dựng phục vụ nhiệm vụ quốc phòng, góp phần củng cố cơ sở hạ tầng doanh trại, đáp ứng yêu cầu huấn luyện, sẵn sàng chiến đấu và xây dựng đơn vị chính quy, hiện đại.</p>\n<p data-start=\"259\" data-end=\"569\">Dự án bao gồm các hạng mục công trình doanh trại, nhà làm việc, nhà ở bộ đội, khu kỹ thuật và hệ thống hạ tầng kỹ thuật đồng bộ. Với đặc thù là công trình quốc phòng, yêu cầu đặt ra không chỉ về chất lượng, tiến độ mà còn về tính bảo mật, an toàn và tuân thủ nghiêm ngặt các tiêu chuẩn, quy chuẩn chuyên ngành.</p>\n<p data-start=\"571\" data-end=\"903\">Trong quá trình triển khai, đơn vị thi công đã tổ chức thi công khoa học, huy động nhân lực, vật tư, thiết bị phù hợp, đảm bảo hoàn thành các hạng mục theo đúng yêu cầu kỹ thuật và kế hoạch đề ra. Công tác quản lý chất lượng, an toàn lao động và vệ sinh môi trường được thực hiện chặt chẽ, đáp ứng tiêu chuẩn của công trình quân sự.</p>\n<p data-start=\"905\" data-end=\"1184\" data-is-last-node=\"\" data-is-only-node=\"\">Sau khi hoàn thành và bàn giao đưa vào sử dụng, công trình Lữ đoàn 950 góp phần nâng cao điều kiện làm việc, sinh hoạt và huấn luyện của cán bộ, chiến sĩ; đồng thời tăng cường tiềm lực quốc phòng, xây dựng đơn vị vững mạnh toàn diện, đáp ứng yêu cầu nhiệm vụ trong tình hình mới.</p>\n <img class=\"alignnone wp-image-395 size-full\" src=\"https://htds.vn/wp-content/uploads/2023/10/quankhu9_1.jpg\" alt=\"\" width=\"1618\" height=\"984\" />', NULL, '2023-10-11 10:28:50', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/%ef%83%98goi-thau-so-15-xay-dung-ha-tang-ky-thuat-khu-cac-dai-doi-truc-thuoc-thuoc-cong-trinh-doanh-trai-so-chi-huy-lu-doan-va-cac-dai-doi-truc-thuoc-lu-doan-950-quan-khu-9/', 0, '2026-08-12 02:01:00', '2026-08-12 02:01:00', NULL);
INSERT INTO `pvn_news_posts` VALUES (5, 'thi-cong-xay-dung-cung-cap-va-lap-dat-thiet-bi-xay-dung-bao-hiem-cong-trinh-va-thiet-bi-dien-thuoc-cong-trinh-dau-tu-xay-dung-vien-chan-thuong-chinh-hinh-benh-vien-quan-y-175-397', 9, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN XÂY DỰNG BỆNH VIỆN QUÂN Y 175', NULL, '<p data-start=\"53\" data-end=\"373\">Công trình đầu tư xây dựng Bệnh viện Quân y 175 là dự án y tế – quốc phòng có quy mô lớn, giữ vai trò quan trọng trong hệ thống khám, chữa bệnh của Quân đội và khu vực phía Nam. Dự án được triển khai nhằm nâng cao năng lực điều trị, đáp ứng yêu cầu chăm sóc sức khỏe cho cán bộ, chiến sĩ và nhân dân trong tình hình mới.</p>\n<p data-start=\"375\" data-end=\"727\">Với tính chất là công trình bệnh viện hiện đại, dự án đòi hỏi yêu cầu cao về tiêu chuẩn kỹ thuật, công năng sử dụng và hệ thống hạ tầng chuyên ngành y tế. Các hạng mục được đầu tư đồng bộ, bao gồm khu khám chữa bệnh, khu điều trị nội trú, các trung tâm kỹ thuật cao cùng hệ thống hạ tầng kỹ thuật phụ trợ, đảm bảo vận hành an toàn, hiệu quả và lâu dài.</p>\n<p data-start=\"729\" data-end=\"1046\">Quá trình thi công được tổ chức khoa học, tuân thủ nghiêm ngặt các quy định về chất lượng, an toàn lao động và tiêu chuẩn xây dựng công trình y tế. Đặc biệt, việc triển khai dự án trong môi trường bệnh viện đang hoạt động đòi hỏi sự phối hợp chặt chẽ, đảm bảo không ảnh hưởng đến công tác khám chữa bệnh thường xuyên.</p>\n<p data-start=\"1048\" data-end=\"1321\" data-is-last-node=\"\" data-is-only-node=\"\">Sau khi hoàn thành, công trình góp phần nâng cao năng lực tiếp nhận, điều trị và cấp cứu, từng bước hiện đại hóa Bệnh viện Quân y 175 theo định hướng phát triển thành bệnh viện đa khoa, chuyên sâu, đáp ứng yêu cầu nhiệm vụ quốc phòng kết hợp với chăm sóc sức khỏe nhân dân.</p>\n <img class=\"alignnone wp-image-399 size-full\" src=\"/uploads/news/2023/10/bv6.jpg\" alt=\"\" width=\"1280\" height=\"720\" /> <img class=\"alignnone wp-image-400 size-full\" src=\"/uploads/news/2023/10/bv2.jpg\" alt=\"\" width=\"660\" height=\"368\" /> <img class=\"alignnone wp-image-401 size-full\" src=\"/uploads/news/2023/10/bv3.jpg\" alt=\"\" width=\"1280\" height=\"720\" /> <img class=\"alignnone wp-image-402 size-full\" src=\"/uploads/news/2023/10/bv4.jpg\" alt=\"\" width=\"1280\" height=\"720\" /> <img class=\"alignnone wp-image-403 size-full\" src=\"/uploads/news/2023/10/bv5.jpg\" alt=\"\" width=\"1280\" height=\"720\" />', NULL, '2023-10-11 10:38:47', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thi-cong-xay-dung-cung-cap-va-lap-dat-thiet-bi-xay-dung-bao-hiem-cong-trinh-va-thiet-bi-dien-thuoc-cong-trinh-dau-tu-xay-dung-vien-chan-thuong-chinh-hinh-benh-vien-quan-y-175/', 0, '2026-08-12 02:01:22', '2026-08-12 02:01:22', NULL);
INSERT INTO `pvn_news_posts` VALUES (6, 'thay-ngoi-den-chinh-thap-nha-van-bia-cong-tam-quan-thuoc-du-an-son-mau-go-cac-cot-sua-chua-nen-san-va-thay-moi-cac-bia-da-khac-ten-liet-sy-den-tuong-niem-liet-sy-ben-duoc-cu-chi-405', 7, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN CẢI TẠO ĐỀN TƯỞNG NIỆM LIỆT SỸ BẾN DƯỢC – CỦ CHI', NULL, '<p data-start=\"65\" data-end=\"306\">Công trình cải tạo Đền Tưởng niệm Liệt sỹ Bến Dược tại huyện Củ Chi là dự án mang ý nghĩa chính trị, lịch sử và nhân văn sâu sắc, góp phần gìn giữ và tôn vinh công lao to lớn của các anh hùng liệt sỹ đã hy sinh vì độc lập, tự do của Tổ quốc.</p>\n<p data-start=\"308\" data-end=\"693\">Đền Tưởng niệm Liệt sỹ Bến Dược là địa chỉ đỏ, nơi tri ân các thế hệ đã ngã xuống trong các cuộc kháng chiến, đồng thời là điểm đến giáo dục truyền thống yêu nước cho cán bộ, chiến sĩ và nhân dân. Việc cải tạo công trình nhằm nâng cấp, hoàn thiện các hạng mục kiến trúc, cảnh quan và hạ tầng kỹ thuật, đảm bảo tính trang nghiêm, bền vững và phù hợp với giá trị lịch sử của khu di tích.</p>\n<p data-start=\"695\" data-end=\"1038\">Trong quá trình thi công, các yêu cầu về bảo tồn yếu tố kiến trúc truyền thống, giữ gìn cảnh quan và không gian tâm linh được đặt lên hàng đầu. Đơn vị thực hiện đã tổ chức triển khai các hạng mục một cách cẩn trọng, đảm bảo chất lượng, tiến độ và tính thẩm mỹ, đồng thời tuân thủ nghiêm các quy định liên quan đến công trình văn hóa – lịch sử.</p>\n<p data-start=\"1040\" data-end=\"1308\" data-is-last-node=\"\" data-is-only-node=\"\">Sau khi hoàn thành, công trình cải tạo Đền Tưởng niệm Liệt sỹ Bến Dược không chỉ nâng cao điều kiện đón tiếp, tổ chức các hoạt động tưởng niệm, mà còn góp phần gìn giữ giá trị lịch sử, phát huy ý nghĩa tri ân và giáo dục truyền thống cho các thế hệ hôm nay và mai sau.</p>\n <img class=\"alignnone wp-image-407 size-full\" src=\"/uploads/news/2023/10/chua2.jpg\" alt=\"\" width=\"1000\" height=\"667\" /> <img class=\"alignnone wp-image-408 size-full\" src=\"/uploads/news/2023/10/chua3.jpg\" alt=\"\" width=\"638\" height=\"827\" />', 282, '2023-10-11 11:17:26', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thay-ngoi-den-chinh-thap-nha-van-bia-cong-tam-quan-thuoc-du-an-son-mau-go-cac-cot-sua-chua-nen-san-va-thay-moi-cac-bia-da-khac-ten-liet-sy-den-tuong-niem-liet-sy-ben-duoc-cu-chi/', 0, '2026-08-12 02:01:23', '2026-08-12 02:01:23', NULL);
INSERT INTO `pvn_news_posts` VALUES (7, 'nhanh-nguyen-oanh-nguyen-kiem-nhanh-nguyen-oanh-nguyen-kiem-thuoc-cong-trinh-xay-dung-cau-vuot-thep-tai-nut-giao-nga-6-go-vap-410', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN CẦU VƯỢT THÉP TẠI NÚT GIAO NGÃ 6 - GÒ VẤP', NULL, '<p data-start=\"56\" data-end=\"266\">Công trình xây dựng cầu vượt thép tại nút giao Ngã 6 Gò Vấp là dự án giao thông trọng điểm nhằm giảm ùn tắc và nâng cao năng lực lưu thông tại một trong những điểm giao thông phức tạp của Thành phố Hồ Chí Minh.</p>\n<p data-start=\"268\" data-end=\"576\">Ngã 6 Gò Vấp là nút giao kết nối nhiều trục đường huyết mạch, có mật độ phương tiện lưu thông cao, thường xuyên xảy ra tình trạng ùn ứ vào giờ cao điểm. Việc đầu tư xây dựng cầu vượt thép góp phần phân luồng giao thông theo hướng tách dòng phương tiện, giảm xung đột giao cắt và rút ngắn thời gian di chuyển.</p>\n<p data-start=\"578\" data-end=\"910\">Công trình được thi công theo kết cấu thép lắp ghép hiện đại, đảm bảo tiến độ nhanh, hạn chế tối đa ảnh hưởng đến sinh hoạt và lưu thông của người dân trong quá trình triển khai. Các yêu cầu về an toàn lao động, kỹ thuật thi công và chất lượng công trình được kiểm soát chặt chẽ, tuân thủ đầy đủ các tiêu chuẩn, quy chuẩn hiện hành.</p>\n<img class=\"alignnone wp-image-388 size-full\" src=\"/uploads/news/2023/10/WP_20161211_16_54_17_Pro-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1440\" /><img class=\"alignnone wp-image-411 size-full\" src=\"/uploads/news/2023/10/duong1.jpg\" alt=\"\" width=\"1583\" height=\"891\" /> <img class=\"alignnone wp-image-412 size-full\" src=\"/uploads/news/2023/10/duong2.jpg\" alt=\"\" width=\"800\" height=\"404\" />', 283, '2023-10-11 11:20:01', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nhanh-nguyen-oanh-nguyen-kiem-nhanh-nguyen-oanh-nguyen-kiem-thuoc-cong-trinh-xay-dung-cau-vuot-thep-tai-nut-giao-nga-6-go-vap/', 0, '2026-08-12 02:01:24', '2026-08-12 02:01:24', NULL);
INSERT INTO `pvn_news_posts` VALUES (8, 'goi-thau-xay-lap-thuoc-cong-trinh-xay-dung-duong-truc-chinh-vao-khu-lien-hop-the-duc-the-thao-rach-chiec-doan-tu-nga-ba-cat-lai-den-khu-a-giai-doan-1-quan-2-414', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN ĐƯỜNG TRỤC CHÍNH VÀO KHU LIÊN HỢP THỂ DỤC THỂ THAO RẠCH CHIẾC', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-9\" data-testid=\"conversation-turn-368\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"bdae07cc-d055-4309-a5f3-6e275f11be94\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"82\" data-end=\"295\">Dự án thi công đường trục chính vào Khu liên hợp Thể dục Thể thao Rạch Chiếc là công trình hạ tầng giao thông quan trọng, góp phần hoàn thiện hệ thống kết nối đến khu thể thao trọng điểm của Thành phố Hồ Chí Minh.</p>\n<p data-start=\"297\" data-end=\"681\">Tuyến đường được xây dựng nhằm đảm bảo năng lực lưu thông, phục vụ nhu cầu tổ chức các sự kiện thể thao quy mô lớn, đồng thời tạo điều kiện thuận lợi cho việc khai thác, vận hành và phát triển đồng bộ khu liên hợp trong tương lai. Với yêu cầu kỹ thuật cao, tiến độ gấp rút và tiêu chuẩn thi công nghiêm ngặt, dự án đòi hỏi năng lực tổ chức, điều hành và kiểm soát chất lượng chặt chẽ.</p>\n<p data-start=\"683\" data-end=\"1107\" data-is-last-node=\"\" data-is-only-node=\"\">Trong quá trình triển khai, đơn vị thi công đã huy động nguồn lực nhân sự, máy móc thiết bị hiện đại, áp dụng các biện pháp kỹ thuật phù hợp nhằm đảm bảo an toàn lao động, chất lượng công trình và tiến độ theo kế hoạch. Công trình sau khi hoàn thành góp phần hoàn thiện hạ tầng khu vực Rạch Chiếc, tăng cường khả năng kết nối giao thông và tạo động lực thúc đẩy phát triển đô thị tại khu vực phía Đông Thành phố Hồ Chí Minh.</p>\n\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</article></div>\n<img class=\"alignnone wp-image-415 size-full\" src=\"/uploads/news/2023/10/truc1.jpg\" alt=\"\" width=\"812\" height=\"624\" /> <img class=\"alignnone wp-image-416 size-full\" src=\"/uploads/news/2023/10/truc2.jpg\" alt=\"\" width=\"769\" height=\"621\" />  <img class=\"alignnone wp-image-418 size-full\" src=\"/uploads/news/2023/10/truc4.jpg\" alt=\"\" width=\"774\" height=\"559\" />', 284, '2023-10-08 11:42:55', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/goi-thau-xay-lap-thuoc-cong-trinh-xay-dung-duong-truc-chinh-vao-khu-lien-hop-the-duc-the-thao-rach-chiec-doan-tu-nga-ba-cat-lai-den-khu-a-giai-doan-1-quan-2/', 0, '2026-08-12 02:01:25', '2026-08-12 02:01:25', NULL);
INSERT INTO `pvn_news_posts` VALUES (9, 'goi-thau-xay-lap-xay-dung-cau-duong-dau-cau-cay-xanh-chieu-sang-cong-cong-dam-bao-giao-thong-thuy-thuoc-du-an-xay-dung-cau-rach-rop-1-giai-doan-2-huyen-nha-be-420', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN CẦU RẠCH RỘP 1 – HUYỆN NHÀ BÈ (GIAI ĐOẠN 2)', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-10\" data-testid=\"conversation-turn-370\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"62e24b67-e7ca-4f24-b4af-aa1f95786241\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"64\" data-end=\"423\">Dự án xây dựng Cầu Rạch Rộp 1 (Giai đoạn 2) tại huyện Nhà Bè là công trình giao thông quan trọng nhằm hoàn thiện hạ tầng kết nối khu vực phía Nam Thành phố Hồ Chí Minh. Công trình được triển khai trong bối cảnh nhu cầu đi lại và vận chuyển hàng hóa tại địa bàn ngày càng gia tăng, đòi hỏi hệ thống giao thông đồng bộ, an toàn và có năng lực khai thác cao hơn.</p>\n<p data-start=\"425\" data-end=\"744\">Giai đoạn 2 của dự án tập trung hoàn thiện các hạng mục còn lại, nâng cao khả năng lưu thông và đảm bảo tính ổn định, bền vững của công trình. Với đặc thù thi công trong điều kiện địa chất yếu và khu vực sông nước, dự án yêu cầu giải pháp kỹ thuật phù hợp, kiểm soát chất lượng nghiêm ngặt và tổ chức thi công khoa học.</p>\n<p data-start=\"746\" data-end=\"1141\" data-is-last-node=\"\" data-is-only-node=\"\">Sau khi hoàn thành, Cầu Rạch Rộp 1 góp phần cải thiện điều kiện đi lại của người dân, giảm tải cho các tuyến đường lân cận, đồng thời thúc đẩy phát triển kinh tế – xã hội tại huyện Nhà Bè và khu vực phía Nam thành phố. Công trình không chỉ mang ý nghĩa về mặt hạ tầng giao thông mà còn tạo động lực cho quá trình đô thị hóa và mở rộng không gian phát triển của khu vực trong những năm tiếp theo.</p>\n\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</article></div>\n<img class=\"alignnone wp-image-421 size-full\" src=\"/uploads/news/2023/10/rachrop1.jpg\" alt=\"\" width=\"841\" height=\"848\" /> <img class=\"alignnone wp-image-422 size-full\" src=\"/uploads/news/2023/10/rachrop2.jpg\" alt=\"\" width=\"763\" height=\"848\" /> <img class=\"alignnone wp-image-423 size-full\" src=\"/uploads/news/2023/10/rachrop3.jpg\" alt=\"\" width=\"843\" height=\"862\" /> <img class=\"alignnone wp-image-424 size-full\" src=\"/uploads/news/2023/10/rachrop4.jpg\" alt=\"\" width=\"763\" height=\"866\" /> <img class=\"alignnone wp-image-425 size-full\" src=\"/uploads/news/2023/10/rachrop5.jpg\" alt=\"\" width=\"720\" height=\"1280\" /> <img class=\"alignnone wp-image-426 size-full\" src=\"/uploads/news/2023/10/rachrop6.jpg\" alt=\"\" width=\"720\" height=\"1280\" /> <img class=\"alignnone wp-image-427 size-full\" src=\"/uploads/news/2023/10/rachrop7.jpg\" alt=\"\" width=\"1280\" height=\"720\" /> <img class=\"alignnone wp-image-428 size-full\" src=\"/uploads/news/2023/10/rachrop8.jpg\" alt=\"\" width=\"1280\" height=\"720\" /> <img class=\"alignnone wp-image-429 size-full\" src=\"/uploads/news/2023/10/rachrop9.jpg\" alt=\"\" width=\"720\" height=\"1280\" /> <img class=\"alignnone wp-image-430 size-full\" src=\"/uploads/news/2023/10/rachrop10.jpg\" alt=\"\" width=\"720\" height=\"1280\" />', 285, '2023-10-08 11:48:22', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/goi-thau-xay-lap-xay-dung-cau-duong-dau-cau-cay-xanh-chieu-sang-cong-cong-dam-bao-giao-thong-thuy-thuoc-du-an-xay-dung-cau-rach-rop-1-giai-doan-2-huyen-nha-be/', 0, '2026-08-12 02:01:27', '2026-08-12 02:01:27', NULL);
INSERT INTO `pvn_news_posts` VALUES (10, 'bot-ha-noi-bac-giang-522', 11, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN ĐẦU TƯ DỰ ÁN BOT HÀ NỘI - BẮC GIANG', NULL, '<p data-start=\"0\" data-end=\"163\"><strong data-start=\"35\" data-end=\"49\">Tên dự án:</strong> Dự án Đầu tư xây dựng công trình cải tạo, nâng cấp Quốc lộ 1 đoạn Hà Nội – Bắc Giang theo hình thức hợp đồng BOT.</p>\n<p data-start=\"165\" data-end=\"290\"><strong data-start=\"165\" data-end=\"185\">Tổng mức đầu tư:</strong> 4.213 tỷ đồng.<br data-start=\"200\" data-end=\"203\" /><strong data-start=\"203\" data-end=\"227\">Thời gian thực hiện:</strong> 2014 – 2016.<br data-start=\"240\" data-end=\"243\" /><strong data-start=\"243\" data-end=\"282\" data-is-only-node=\"\">Thời gian thu phí dự kiến:</strong> 21 năm.</p>\n<span class=\"fontstyle0\">Kể từ ngày 24/12/2025, Đông Sơn chính thức hoàn thành thương vụ M&amp;A trọng điểm với quyết định chi 185 tỷ đồng để nâng tỷ lệ sở hữu từ 25% lên 58% vốn tại dự án BOT Hà Nội – Bắc Giang, đánh dấu bước ngoặt tài chính quan trọng khi chính thức hợp nhất toàn bộ doanh thu và dòng tiền bền vững của dự án vào hệ thống.</span>\n<p data-start=\"292\" data-end=\"578\">Dự án được triển khai theo hình thức hợp đồng BOT (Xây dựng – Kinh doanh – Chuyển giao), với mục tiêu cải tạo, nâng cấp tuyến Quốc lộ 1 đoạn Hà Nội – Bắc Giang, góp phần hoàn thiện hạ tầng giao thông trên trục huyết mạch kết nối Thủ đô Hà Nội với các tỉnh trung du và miền núi phía Bắc.</p>\n<p data-start=\"580\" data-end=\"1019\">Nhà đầu tư thực hiện dự án là Liên danh gồm: Công ty Cổ phần Tập đoàn Đại Dương (OGC), Tổng công ty Xây dựng và Xuất nhập khẩu Việt Nam (Vinaconex), Công ty Cổ phần Đầu tư và Thương mại 319 (nay là Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn) và Công ty Cổ phần Đầu tư Văn Phú – Invest. Trong đó, sự tham gia của Đông Sơn thể hiện vai trò tích cực của doanh nghiệp trong lĩnh vực đầu tư hạ tầng giao thông theo mô hình đối tác công – tư (PPP).</p>\n<p data-start=\"1021\" data-end=\"1394\" data-is-last-node=\"\" data-is-only-node=\"\">Sau khi hoàn thành và đưa vào khai thác, dự án đã góp phần nâng cao năng lực thông hành, giảm ùn tắc và tai nạn giao thông, đồng thời thúc đẩy phát triển kinh tế – xã hội khu vực. Việc tổ chức thu phí hoàn vốn được thực hiện theo phương án tài chính được cơ quan nhà nước có thẩm quyền phê duyệt, đảm bảo hài hòa lợi ích giữa Nhà nước, nhà đầu tư và người sử dụng đường bộ.</p>\n <img class=\"alignnone wp-image-693 size-full\" src=\"/uploads/news/2023/10/5.jpg\" alt=\"\" width=\"735\" height=\"490\" /> <img class=\"alignnone wp-image-694 size-full\" src=\"/uploads/news/2023/10/6.jpg\" alt=\"\" width=\"1024\" height=\"576\" />  <img class=\"alignnone wp-image-697 size-full\" src=\"/uploads/news/2023/10/4.jpg\" alt=\"\" width=\"720\" height=\"405\" />\n\n&nbsp;\n\n&nbsp;\n\n&nbsp;\n\n&nbsp;', 286, '2023-11-10 04:44:48', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bot-ha-noi-bac-giang/', 0, '2026-08-12 02:01:27', '2026-08-12 02:01:27', NULL);
INSERT INTO `pvn_news_posts` VALUES (11, 'thu-moi-va-tai-lieu-hop-dhdcd-bat-thuong-nam-2023-565', 12, 'THƯ MỜI & TÀI LIỆU HỌP ĐẠI HỘI ĐỒNG CỔ ĐÔNG BẤT THƯỜNG NĂM 2023', NULL, 'Tài liệu họp Đại hội đồng cổ đông bất thường năm 2023\n<ol>\n 	<li>Thư mời họp</li>\n 	<li>Mẫu Giấy ủy quyền/đăng ký tham dự</li>\n 	<li>Chương trình họp</li>\n 	<li>Dự thảo Quy chế làm việc</li>\n 	<li>Thông báo đề cử, ứng cử ứng viên HĐQT/thành viên độc lập HĐQT/BKS</li>\n 	<li>Dự thảo Quy chế bầu cử</li>\n 	<li>Tờ trình bầu miễn nhiệm và bầu bổ sung thành viên Ban kiểm soát</li>\n 	<li>Tờ trình bầu bổ sung thành viên HĐQT/thành viên độc lập HĐQT</li>\n 	<li>Tờ trình thông qua toàn văn Điều lệ Công ty, Quy chế quản trị nội bộ, Quy chế hoạt động HĐQT, Quy chế hoạt động Ban kiểm soát</li>\n 	<li>Mẫu phiếu biểu quyết, Phiếu bầu cử</li>\n</ol>', 287, '2023-10-19 14:41:17', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thu-moi-va-tai-lieu-hop-dhdcd-bat-thuong-nam-2023/', 0, '2026-08-12 02:01:28', '2026-08-12 02:01:28', NULL);
INSERT INTO `pvn_news_posts` VALUES (12, 'dong-son-thi-cong-cau-vuot-song-day-noi-ninh-binh-va-nam-dinh-567', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN CẦU VƯỢT SÔNG ĐÁY NỐI NINH BÌNH - NAM ĐỊNH', NULL, '<p data-start=\"92\" data-end=\"260\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn tham gia thi công dự án cầu vượt sông Đáy – công trình thành phần thuộc tuyến đường bộ cao tốc Ninh Bình – Nam Định – Thái Bình.</p>\n<p data-start=\"262\" data-end=\"826\">Tuyến cao tốc có tổng chiều dài khoảng 87 km, được thiết kế với quy mô 4 làn xe hoàn chỉnh, giữ vai trò quan trọng trong việc kết nối khu vực duyên hải Bắc Bộ, tạo động lực phát triển kinh tế – xã hội cho các tỉnh Ninh Bình, Nam Định và Thái Bình. Dự án được tách thành dự án độc lập và dự kiến đầu tư theo hình thức đối tác công tư (PPP), triển khai theo chỉ đạo của Thủ tướng Chính phủ trong giai đoạn năm 2023 – đầu năm 2024. Trong đó, tỉnh Nam Định chịu trách nhiệm bố trí kinh phí thực hiện công tác giải phóng mặt bằng đối với đoạn tuyến đi qua địa bàn tỉnh.</p>\n<p data-start=\"828\" data-end=\"1072\">Hạng mục cầu vượt sông Đáy có ý nghĩa đặc biệt quan trọng, không chỉ đảm bảo tính liên thông của toàn tuyến cao tốc mà còn góp phần tăng cường kết nối giao thông liên vùng, rút ngắn thời gian di chuyển và giảm tải cho hệ thống quốc lộ hiện hữu.</p>\n<p data-start=\"1074\" data-end=\"1361\" data-is-last-node=\"\" data-is-only-node=\"\">Trong vai trò là nhà thầu phụ của công trình, CTCP Đầu tư Hạ tầng Đông Sơn triển khai thi công các hạng mục được giao với tinh thần trách nhiệm cao, tuân thủ nghiêm ngặt các yêu cầu về kỹ thuật, chất lượng, an toàn lao động và bảo vệ môi trường, góp phần bảo đảm tiến độ chung của dự án.</p>\n<img class=\"alignnone wp-image-721 size-full\" src=\"/uploads/news/2023/10/120230929102026-1695971698737-16959716989441523216762.png\" alt=\"\" width=\"960\" height=\"540\" /><img class=\"alignnone wp-image-722 size-full\" src=\"/uploads/news/2023/10/ndo_br_img-1636-385.jpg.webp\" alt=\"\" width=\"1241\" height=\"682\" /><img class=\"alignnone wp-image-607 size-full\" src=\"/uploads/news/2023/10/Song-Day-2.jpg\" alt=\"\" width=\"1280\" height=\"960\" />', 288, '2023-11-08 14:54:28', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-thi-cong-cau-vuot-song-day-noi-ninh-binh-va-nam-dinh/', 0, '2026-08-12 02:01:28', '2026-08-12 02:01:28', NULL);
INSERT INTO `pvn_news_posts` VALUES (13, 'dong-son-to-chuc-thanh-cong-dai-hoi-dong-co-dong-bat-thuong-nam-2023-598', 12, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TỔ CHỨC THÀNH CÔNG ĐẠI HỘI ĐỒNG CỔ ĐÔNG BẤT THƯỜNG NĂM 2023', NULL, 'Ngày 30/10/2023, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã tổ chức thành công cuộc họp Đại hội đồng cổ đông bất thường năm 2023. Tại Đại hội, các cổ đông đã bầu bổ sung 02 thành viên Hội đồng quản trị gồm các ông/bà sau:\n<ol>\n 	<li>Ông Nguyễn Thành Trung: Thành viên độc lập HĐQT</li>\n 	<li>Ông Lại Thành Nam: Thành viên HĐQT</li>\n</ol>\nBầu bổ sung ông/bà sau đây vào Ban kiểm soát của Công ty:\n<ol>\n 	<li>Bà Mai Thị Hà: Thành viên Ban kiểm soát</li>\n</ol>\nTheo đó, kể từ ngày 30/10/2023, Hội đồng quản trị của Công ty gồm các ông/bà sau:\n<ol>\n 	<li>Bà Nguyễn Thị Minh Huệ: Chủ tịch HĐQT</li>\n 	<li>Ông Nguyễn Tiến Hưng: Thành viên HĐQT kiêm Tổng Giám đốc</li>\n 	<li>Ông Nguyễn Thành Trung: Thành viên độc lập HĐQT</li>\n 	<li>Ông Nguyễn Giang Nam: Thành viên HĐQT</li>\n 	<li>Ông Lại Thành Nam: Thành viên HĐQT</li>\n</ol>\nKể từ ngày 30/10/2023, Ban Kiểm soát của Công ty gồm các ông/bà sau:\n<ol>\n 	<li>Bà Lý Thị Thu Hà: Thành viên BKS</li>\n 	<li>Bà Đỗ Thùy Dương: Thành viên BKS</li>\n 	<li>Bà Mai Thị Hà: Thành viên BKS</li>\n</ol>\nNhân dịp này, Bà Nguyễn Thị Minh Huệ - Chủ tịch HĐQT Công ty cũng gửi lời cảm ơn chân thành đến các quý vị cổ đông đã luôn ủng hộ, đồng hành cùng Công ty trong suốt thời gian vừa qua. Hội đồng quản trị tin tưởng rằng với tinh thần trách nhiệm cao trong công tác quản lý, điều hành của Hội đồng quản trị, Ban điều hành và sự nỗ lực của toàn thể cán bộ nhân viên, Công ty Đông Sơn sẽ ngày càng phát triển, khẳng định uy tín và thương hiệu trên thị trường.', 289, '2023-10-31 09:51:55', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-to-chuc-thanh-cong-dai-hoi-dong-co-dong-bat-thuong-nam-2023/', 0, '2026-08-12 02:01:28', '2026-08-12 02:01:28', NULL);
INSERT INTO `pvn_news_posts` VALUES (14, 'dong-son-thi-cong-cau-song-so-thuoc-du-an-xay-dung-tuyen-duong-bo-moi-nam-dinh-lac-quan-duong-bo-ven-bien-601', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN TUYẾN ĐƯỜNG BỘ MỚI NAM ĐỊNH - LẠC QUẦN - ĐƯỜNG BỘ VEN BIỂN', NULL, '<p data-start=\"108\" data-end=\"299\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn tham gia thi công dự án tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển, một trong những công trình giao thông quan trọng của tỉnh Nam Định.</p>\n<p data-start=\"301\" data-end=\"552\">Tuyến đường có tổng chiều dài khoảng 24,65 km, được khởi công vào cuối năm 2022, giữ vai trò kết nối khu vực trung tâm tỉnh với các huyện ven biển, đồng thời tạo trục giao thông chiến lược liên kết với tuyến đường bộ ven biển khu vực đồng bằng Bắc Bộ.</p>\n<p data-start=\"554\" data-end=\"930\">Trên địa bàn huyện Giao Thủy, tuyến đường có điểm đầu tại cầu vượt sông Sò, tiếp giáp với địa phận huyện Hải Hậu. Dự án bao gồm các hạng mục cầu quan trọng như một cầu lớn vượt sông Sò và hai cầu nhỏ, trong đó có cầu Cồn Giữa thuộc xã Giao Thịnh. Các công trình cầu được thiết kế, thi công đảm bảo yêu cầu kỹ thuật, an toàn và phù hợp với điều kiện địa chất, thủy văn khu vực.</p>\n<p data-start=\"932\" data-end=\"1203\">Việc đầu tư xây dựng tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển góp phần hoàn thiện mạng lưới hạ tầng giao thông, mở rộng không gian phát triển kinh tế – xã hội, thúc đẩy giao thương, du lịch và khai thác hiệu quả tiềm năng kinh tế biển của tỉnh Nam Định.</p>\n<p data-start=\"1205\" data-end=\"1423\" data-is-last-node=\"\" data-is-only-node=\"\">Với kinh nghiệm triển khai nhiều dự án hạ tầng quy mô lớn, CTCP Đầu tư Hạ tầng Đông Sơn cam kết thi công công trình đảm bảo chất lượng, tiến độ và an toàn, góp phần đưa dự án sớm hoàn thành và phát huy hiệu quả đầu tư.</p>\n<img class=\"alignnone wp-image-725 size-full\" src=\"/uploads/news/2023/10/1-20230927154649347.jpg\" alt=\"\" width=\"1000\" height=\"594\" /> <img class=\"alignnone wp-image-726 size-full\" src=\"/uploads/news/2023/10/6-2023092715465827.jpg\" alt=\"\" width=\"1000\" height=\"609\" />', 290, '2023-10-31 10:08:29', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-thi-cong-cau-song-so-thuoc-du-an-xay-dung-tuyen-duong-bo-moi-nam-dinh-lac-quan-duong-bo-ven-bien/', 0, '2026-08-12 02:01:29', '2026-08-12 02:01:29', NULL);
INSERT INTO `pvn_news_posts` VALUES (15, 'dong-son-thi-cong-xay-moi-cau-dong-hoi-xa-xuan-quang-1-huyen-dong-xuan-tinh-phu-yen-610', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN XÂY MỚI CẦU ĐỒNG NỘI, TỈNH PHÚ YÊN', NULL, '<p data-start=\"84\" data-end=\"290\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn được lựa chọn là nhà thầu thi công xây dựng và lắp đặt thiết bị toàn bộ công trình thuộc dự án “Xây mới cầu Đồng Hội, xã Xuân Quang 1, huyện Đồng Xuân, tỉnh Phú Yên”.</p>\n<p data-start=\"292\" data-end=\"738\">Dự án xây dựng cầu Đồng Hội có ý nghĩa quan trọng trong việc hoàn thiện hệ thống hạ tầng giao thông khu vực, góp phần tạo động lực thúc đẩy phát triển kinh tế – xã hội địa phương. Công trình không chỉ phục vụ nhu cầu đi lại của người dân, vận chuyển nông sản và hàng hóa, mà còn tăng cường khả năng kết nối liên thông giữa tuyến ĐT.647 và tuyến La Hai – Đồng Hội (ĐH.42), hình thành trục giao thông thuận lợi cho khu vực phía Tây huyện Đồng Xuân.</p>\n<p data-start=\"740\" data-end=\"1003\">Bên cạnh đó, việc đầu tư xây dựng cầu mới còn góp phần khai thác tiềm năng, thế mạnh du lịch sinh thái của địa phương, đồng thời nâng cao năng lực ứng cứu, đảm bảo giao thông thông suốt trong điều kiện thiên tai, bão lũ thường xuyên xảy ra tại khu vực miền Trung.</p>\n<p data-start=\"1005\" data-end=\"1270\" data-is-last-node=\"\" data-is-only-node=\"\">Với vai trò là đơn vị thi công, Đông Sơn cam kết triển khai dự án đúng tiến độ, đảm bảo chất lượng kỹ thuật, an toàn lao động và tuân thủ đầy đủ các quy định hiện hành, góp phần sớm đưa công trình vào khai thác, phục vụ hiệu quả nhu cầu phát triển của tỉnh Phú Yên.</p>\n<img class=\"alignnone wp-image-641 size-full\" src=\"/uploads/news/2023/08/Dong-Hoi-2.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-642 size-full\" src=\"/uploads/news/2023/08/Dong-Hoi-3.jpg\" alt=\"\" width=\"641\" height=\"855\" /> <img class=\"alignnone wp-image-643 size-full\" src=\"/uploads/news/2023/08/Dong-Hoi-4.jpg\" alt=\"\" width=\"854\" height=\"641\" /> <img class=\"alignnone wp-image-644 size-full\" src=\"/uploads/news/2023/08/Dong-Hoi-5.jpg\" alt=\"\" width=\"854\" height=\"641\" />', 291, '2023-10-25 10:34:22', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-thi-cong-xay-moi-cau-dong-hoi-xa-xuan-quang-1-huyen-dong-xuan-tinh-phu-yen/', 0, '2026-08-12 02:01:30', '2026-08-12 02:01:30', NULL);
INSERT INTO `pvn_news_posts` VALUES (16, 'du-an-trung-tam-dich-vu-thuong-mai-can-ho-va-van-phong-716', 11, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN ĐẦU TƯ DỰ ÁN CITY LIFE', NULL, '<p data-start=\"73\" data-end=\"189\"><strong data-start=\"73\" data-end=\"87\">Tên dự án:</strong> City Life<br data-start=\"97\" data-end=\"100\" /><strong data-start=\"100\" data-end=\"113\">Địa điểm:</strong> Khu hỗn hợp, Khu Công nghệ cao Hòa Lạc, huyện Thạch Thất, Thành phố Hà Nội.</p>\n<p data-start=\"191\" data-end=\"489\">Dự án City Life được định hướng phát triển thành tổ hợp trung tâm dịch vụ thương mại, căn hộ và văn phòng hiện đại, đáp ứng nhu cầu sinh sống, làm việc và kinh doanh trong khu vực Khu Công nghệ cao Hòa Lạc – một trong những trung tâm nghiên cứu, công nghệ và đổi mới sáng tạo trọng điểm của Thủ đô.</p>\n<p data-start=\"491\" data-end=\"914\">Với vị trí nằm trong khu hỗn hợp của Khu Công nghệ cao Hòa Lạc, dự án sở hữu lợi thế về hạ tầng đồng bộ, kết nối thuận tiện với trung tâm thành phố Hà Nội cũng như các khu vực lân cận. Đây là khu vực được quy hoạch bài bản, tập trung nhiều doanh nghiệp công nghệ, chuyên gia, kỹ sư và lực lượng lao động chất lượng cao, tạo tiền đề cho nhu cầu lớn về không gian làm việc chuyên nghiệp, dịch vụ thương mại và căn hộ lưu trú.</p>\n<p data-start=\"916\" data-end=\"1368\" data-is-last-node=\"\" data-is-only-node=\"\">City Life được kỳ vọng sẽ cung cấp hệ thống văn phòng hiện đại, không gian thương mại năng động cùng khu căn hộ tiện nghi, góp phần hình thành môi trường sống và làm việc khép kín, tiện ích, phù hợp với xu hướng phát triển đô thị thông minh. Dự án không chỉ mang ý nghĩa thương mại mà còn đóng vai trò bổ trợ hạ tầng dịch vụ cho toàn khu vực, góp phần nâng cao giá trị bất động sản và thúc đẩy phát triển kinh tế – xã hội tại Khu Công nghệ cao Hòa Lạc.</p>\n<img class=\"alignnone wp-image-718 size-full\" src=\"/uploads/news/2023/11/HL2.jpg\" alt=\"\" width=\"2560\" height=\"1834\" /><img class=\"alignnone wp-image-717 size-full\" src=\"/uploads/news/2023/11/HL1.jpg\" alt=\"\" width=\"2560\" height=\"1820\" />', 292, '2023-11-08 16:19:42', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/du-an-trung-tam-dich-vu-thuong-mai-can-ho-va-van-phong/', 0, '2026-08-12 02:01:31', '2026-08-12 02:01:31', NULL);
INSERT INTO `pvn_news_posts` VALUES (17, 'thi-cong-cao-toc-vinh-hao-phan-thiet-729', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN CAO TỐC VĨNH HẢO - PHAN THIẾT', NULL, '<p data-start=\"41\" data-end=\"386\">Dự án cao tốc Vĩnh Hảo – Phan Thiết thuộc tuyến cao tốc Bắc – Nam phía Đông, đi qua địa bàn tỉnh Bình Thuận, nằm trong tổng thể các đoạn tuyến Cam Lâm – Vĩnh Hảo, Vĩnh Hảo – Phan Thiết và Phan Thiết – Dầu Giây. Đây là dự án hạ tầng giao thông trọng điểm quốc gia, có ý nghĩa chiến lược trong việc hoàn thiện trục giao thông huyết mạch Bắc – Nam.</p>\n<p data-start=\"388\" data-end=\"721\">Trong giai đoạn 1, toàn tuyến được thiết kế với quy mô 4 làn xe, chiều rộng nền đường 17m, vận tốc khai thác tối đa 80km/h. Tuyến đường đi qua các huyện Tuy Phong, Bắc Bình, Hàm Thuận Bắc và Hàm Thuận Nam (tỉnh Bình Thuận), góp phần rút ngắn thời gian di chuyển, tăng cường kết nối liên vùng giữa khu vực Nam Trung Bộ và Đông Nam Bộ.</p>\n<p data-start=\"723\" data-end=\"1017\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn là một trong những đơn vị tham gia thi công dự án. Với kinh nghiệm triển khai các công trình hạ tầng quy mô lớn, yêu cầu kỹ thuật cao, Công ty đã tổ chức thi công đảm bảo tiến độ, chất lượng và an toàn lao động, đáp ứng các tiêu chuẩn kỹ thuật của dự án.</p>\n<p data-start=\"1019\" data-end=\"1279\" data-is-last-node=\"\" data-is-only-node=\"\">Việc hoàn thành và đưa vào khai thác tuyến cao tốc Vĩnh Hảo – Phan Thiết không chỉ góp phần giảm tải cho Quốc lộ 1, mà còn tạo động lực thúc đẩy phát triển kinh tế – xã hội, du lịch và thu hút đầu tư cho tỉnh Bình Thuận nói riêng và khu vực phía Nam nói chung.</p>\n<img class=\"alignnone wp-image-731 size-full\" src=\"/uploads/news/2023/11/anh.jpg\" alt=\"\" width=\"640\" height=\"324\" /> <img class=\"alignnone wp-image-732 size-full\" src=\"/uploads/news/2023/11/w-cao-toc-phan-thiet-vinh-hao-6-2-3-163.jpg\" alt=\"\" width=\"2000\" height=\"1333\" />', 293, '2023-10-09 10:44:07', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thi-cong-cao-toc-vinh-hao-phan-thiet/', 0, '2026-08-12 02:01:32', '2026-08-12 02:01:32', NULL);
INSERT INTO `pvn_news_posts` VALUES (18, 'du-an-harmonia-complex-747', 11, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN ĐẦU TƯ DỰ ÁN HARMONIA COMPLEX', NULL, '<p data-start=\"28\" data-end=\"157\"><strong data-start=\"28\" data-end=\"42\">Tên dự án:</strong> Harmonia Complex<br data-start=\"59\" data-end=\"62\" /><strong data-start=\"62\" data-end=\"75\">Địa điểm:</strong> Lô đất HH4 – Khu hỗn hợp, Khu Công nghệ cao Hòa Lạc, huyện Thạch Thất, TP Hà Nội.</p>\n<p data-start=\"159\" data-end=\"398\">Harmonia Complex được phát triển với định hướng trở thành một tổ hợp đa chức năng hiện đại, đáp ứng nhu cầu phát triển mạnh mẽ của khu vực Khu Công nghệ cao Hòa Lạc – trung tâm nghiên cứu, đào tạo và ứng dụng công nghệ trọng điểm quốc gia.</p>\n<p data-start=\"400\" data-end=\"816\">Tọa lạc tại lô đất HH4 thuộc khu hỗn hợp, dự án sở hữu vị trí chiến lược trong tổng thể quy hoạch đồng bộ của toàn khu, hưởng lợi từ hệ thống hạ tầng kỹ thuật và giao thông ngày càng hoàn thiện. Với lợi thế nằm trong khu vực tập trung nhiều doanh nghiệp công nghệ, viện nghiên cứu và trường đại học, Harmonia Complex được kỳ vọng sẽ đón đầu nhu cầu về không gian làm việc, lưu trú và dịch vụ tiện ích chất lượng cao.</p>\n<p data-start=\"818\" data-end=\"1186\" data-is-last-node=\"\" data-is-only-node=\"\">Dự án hướng tới việc kiến tạo một môi trường tích hợp hài hòa giữa không gian thương mại, văn phòng và các tiện ích phục vụ cộng đồng, góp phần hoàn thiện hệ sinh thái đô thị tại Hòa Lạc. Không chỉ đơn thuần là một công trình xây dựng, Harmonia Complex được định vị như một điểm nhấn kiến trúc và là động lực thúc đẩy giá trị gia tăng cho toàn khu vực trong tương lai.</p>\n<img class=\"alignnone wp-image-749 size-full\" src=\"/uploads/news/2023/11/z4860747121301_9f9d0f156067dad15518fa4c9b9c275a.jpg\" alt=\"\" width=\"2560\" height=\"1417\" /> <img class=\"alignnone wp-image-750 size-full\" src=\"/uploads/news/2023/11/z4860747139866_706fc77cdd41136fc6ce2fd45a6287ae.jpg\" alt=\"\" width=\"2560\" height=\"1394\" />', 294, '2023-11-09 09:06:19', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/du-an-harmonia-complex/', 0, '2026-08-12 02:01:34', '2026-08-12 02:01:34', NULL);
INSERT INTO `pvn_news_posts` VALUES (19, 'du-an-1f-complex-752', 11, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN ĐẦU TƯ DỰ ÁN 1F COMPLEX', NULL, '<p data-start=\"22\" data-end=\"160\"><strong data-start=\"22\" data-end=\"36\">Tên dự án:</strong> 1F Complex<br data-start=\"47\" data-end=\"50\" /><strong data-start=\"50\" data-end=\"62\">Địa chỉ:</strong> 1F Thái Hà, Phường Láng Hạ, Quận Đống Đa, TP Hà Nội.</p>\n<p data-start=\"162\" data-end=\"576\">1F Complex là tòa nhà văn phòng cho thuê tọa lạc tại vị trí trung tâm trên phố Thái Hà – khu vực tập trung nhiều doanh nghiệp, ngân hàng và tổ chức tài chính lớn của quận Đống Đa. Với lợi thế nằm trên trục giao thông thuận tiện, dự án dễ dàng kết nối tới các tuyến đường trọng điểm như Láng Hạ, Huỳnh Thúc Kháng, Tây Sơn, Nguyễn Chí Thanh…, tạo điều kiện thuận lợi cho hoạt động giao dịch và phát triển kinh doanh.</p>\n<p data-start=\"578\" data-end=\"925\">Dự án được định hướng khai thác chuyên biệt trong lĩnh vực cho thuê văn phòng, đáp ứng nhu cầu đa dạng của các doanh nghiệp vừa và nhỏ, công ty công nghệ, thương mại, dịch vụ và các tổ chức trong và ngoài nước. Không gian văn phòng được thiết kế linh hoạt, tối ưu công năng sử dụng, đảm bảo môi trường làm việc chuyên nghiệp, hiện đại và hiệu quả.</p>\n<p data-start=\"927\" data-end=\"1197\" data-is-last-node=\"\" data-is-only-node=\"\">Với vị trí trung tâm cùng hạ tầng kỹ thuật đồng bộ, 1F Complex mang đến giải pháp văn phòng ổn định, lâu dài cho doanh nghiệp, đồng thời góp phần nâng cao giá trị khai thác thương mại tại khu vực Thái Hà – Láng Hạ, một trong những khu vực kinh doanh sôi động của Thủ đô.</p>\n<img class=\"alignnone wp-image-753 size-full\" src=\"/uploads/news/2023/11/z4860710379644_611a6dcf61ba5f379fad7728210c90cc.jpg\" alt=\"\" width=\"1920\" height=\"2560\" />  <img class=\"alignnone wp-image-755 size-full\" src=\"/uploads/news/2023/11/z4860710753726_8392e5c1db899866b132773e8e332de9.jpg\" alt=\"\" width=\"1920\" height=\"2560\" />', 295, '2023-11-09 09:11:50', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/du-an-1f-complex/', 0, '2026-08-12 02:01:35', '2026-08-12 02:01:35', NULL);
INSERT INTO `pvn_news_posts` VALUES (20, 'dong-son-thi-cong-cong-trinh-cai-tao-nang-cap-quoc-lo-14b-tai-da-nang-764', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN CẢI TẠO, NÂNG CẤP QUỐC LỘ 14B (ĐÀ NẴNG)', NULL, '<p data-start=\"95\" data-end=\"420\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn, trong liên danh với Công ty Cổ phần Tập đoàn CIENCO4, là nhà thầu thi công dự án cải tạo, nâng cấp Quốc lộ 14B trên địa bàn thành phố Đà Nẵng. Dự án được đầu tư bằng nguồn vốn ngân sách Nhà nước với tổng mức đầu tư hơn 788 tỷ đồng, do Sở Giao thông Vận tải TP. Đà Nẵng làm chủ đầu tư.</p>\n<p data-start=\"422\" data-end=\"671\">Dự án có điểm đầu tại Km24+633 Quốc lộ 14B (xã Hòa Nhơn, huyện Hòa Vang), tiếp giáp khu vực nút giao cao tốc La Sơn – Túy Loan; điểm cuối tại Km32+185,09 (xã Hòa Khương, huyện Hòa Vang), giáp ranh tỉnh Quảng Nam. Tổng chiều dài tuyến khoảng 7,58 km.</p>\n<p data-start=\"673\" data-end=\"1114\">Tuyến đường được thiết kế với quy mô 4 làn xe cơ giới và 2 làn xe hỗn hợp, mặt cắt ngang rộng 34 m, vận tốc thiết kế 80 km/h. Trên tuyến có 4 cầu hiện hữu được mở rộng mặt cầu lên 28 m nhằm đồng bộ với quy mô nền, mặt đường. Bên cạnh đó, dự án được đầu tư hoàn chỉnh hệ thống thoát nước, các nút giao đảm bảo an toàn giao thông, đường gom – đường dân sinh, hệ thống điện chiếu sáng, biển báo và tín hiệu giao thông theo tiêu chuẩn hiện hành.</p>\n<p data-start=\"1116\" data-end=\"1418\">Việc cải tạo, nâng cấp Quốc lộ 14B có ý nghĩa quan trọng trong việc tăng cường kết nối giữa trung tâm TP. Đà Nẵng với khu vực phía Tây và các tỉnh lân cận, đặc biệt là kết nối với hệ thống cao tốc, góp phần giảm tải giao thông, nâng cao năng lực vận tải và thúc đẩy phát triển kinh tế – xã hội khu vực.</p>\n<p data-start=\"1420\" data-end=\"1638\" data-is-last-node=\"\" data-is-only-node=\"\">Với kinh nghiệm thi công nhiều công trình hạ tầng giao thông quy mô lớn, CTCP Đầu tư Hạ tầng Đông Sơn cam kết triển khai dự án đảm bảo chất lượng, tiến độ và an toàn, đáp ứng yêu cầu kỹ thuật và kỳ vọng của chủ đầu tư.</p>\n<img class=\"alignnone wp-image-1909 size-full\" src=\"/uploads/news/2023/11/1CAO.jpg\" alt=\"\" width=\"650\" height=\"417\" />', 296, '2023-11-25 09:27:45', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-thi-cong-cong-trinh-cai-tao-nang-cap-quoc-lo-14b-tai-da-nang/', 0, '2026-08-12 02:01:35', '2026-08-12 02:01:35', NULL);
INSERT INTO `pvn_news_posts` VALUES (21, 'cong-ty-dong-son-tang-qua-tet-cho-ho-gia-dinh-co-hoan-canh-kho-khan-o-cac-huyen-nam-truc-truc-ninh-hai-hau-nghia-hung-nam-dinh-772', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TRAO QUÀ TẾT CHO CÁC HỘ GIA ĐÌNH CÓ HOÀN CẢNH KHÓ KHĂN TẠI CÁC HUYỆN NAM TRỰC, TRỰC NINH, HẢI HẬU, NGHĨA HƯNG (NAM ĐỊNH)', NULL, '<p data-start=\"102\" data-end=\"558\">Nhân dịp Xuân Giáp Thìn 2024, ngày 12/01/2024, Đoàn đại biểu Quốc hội tỉnh Nam Định gồm các đồng chí: Nguyễn Hải Dũng – Tỉnh ủy viên, Phó Trưởng đoàn chuyên trách Đoàn ĐBQH tỉnh; Mai Thị Phương Hoa – Phó Chủ nhiệm Ủy ban Tư pháp của Quốc hội, cùng đại diện Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã tổ chức thăm hỏi, chúc Tết và trao quà cho các hộ gia đình có hoàn cảnh đặc biệt khó khăn trên địa bàn các huyện Nam Trực, Trực Ninh, Hải Hậu và Nghĩa Hưng.</p>\n<p data-start=\"560\" data-end=\"985\">Đoàn đã trao tặng 210 suất quà, mỗi suất trị giá 500.000 đồng, tới các hộ gia đình tại các xã: Nam Toàn, Nam Cường (huyện Nam Trực); Liêm Hải (huyện Trực Ninh); Hải Cường, Hải Sơn (huyện Hải Hậu); Nghĩa Trung, Nghĩa Sơn (huyện Nghĩa Hưng). Tại các điểm đến, Đoàn đã ân cần thăm hỏi, động viên và gửi lời chúc năm mới sức khỏe, an lành, mong các gia đình tiếp tục nỗ lực vượt qua khó khăn, ổn định và vươn lên trong cuộc sống.</p>\n<p data-start=\"987\" data-end=\"1519\">Cũng trong dịp này, Đoàn đã đến thăm, chúc Tết Giáo xứ Đại Đê (xã Nghĩa Sơn, huyện Nghĩa Hưng) và tặng quà Linh mục Lại Văn Quynh – Chánh xứ Quản hạt Liễu Đề, Chánh xứ Giáo xứ Đại Đê. Đoàn gửi lời chúc mừng năm mới tới các vị chức sắc tôn giáo và bà con giáo dân, mong tiếp tục phát huy tinh thần “kính Chúa yêu nước”, “sống Phúc âm trong lòng dân tộc”, tích cực tham gia các phong trào thi đua yêu nước, đặc biệt là phong trào xây dựng nông thôn mới, góp phần xây dựng quê hương ngày càng giàu đẹp, văn minh và phát triển bền vững.</p>\n<p data-start=\"1521\" data-end=\"1665\" data-is-last-node=\"\" data-is-only-node=\"\">Hoạt động thể hiện trách nhiệm xã hội, tinh thần sẻ chia của CTCP Đầu tư Hạ tầng Đông Sơn đối với cộng đồng, nhất là trong dịp Tết đến, Xuân về.</p>\n\n<div></div>\n<div><img class=\"alignnone wp-image-777 size-full\" src=\"/uploads/news/2024/01/Anh-5.jpg\" alt=\"\" width=\"1276\" height=\"956\" /> <img class=\"alignnone wp-image-778 size-full\" src=\"/uploads/news/2024/01/Anh-6.jpg\" alt=\"\" width=\"1276\" height=\"956\" /> <img class=\"alignnone wp-image-779 size-full\" src=\"/uploads/news/2024/01/Anh-7.jpg\" alt=\"\" width=\"1276\" height=\"956\" /></div>', 297, '2024-01-12 13:46:47', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/cong-ty-dong-son-tang-qua-tet-cho-ho-gia-dinh-co-hoan-canh-kho-khan-o-cac-huyen-nam-truc-truc-ninh-hai-hau-nghia-hung-nam-dinh/', 0, '2026-08-12 02:01:36', '2026-08-12 02:01:36', NULL);
INSERT INTO `pvn_news_posts` VALUES (22, 'cong-ty-dong-son-tang-qua-tet-tai-4-xa-giao-hai-giao-lac-giao-thuy-xuan-hoa-xuan-kien-xuan-truong-781', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TRAO QUÀ TẾT TẠI CÁC XÃ GIAO HẢI, GIAO LẠC (HUYỆN GIAO THỦY) VÀ XUÂN HÒA, XUÂN KIÊN (HUYỆN XUÂN TRƯỜNG)', NULL, '<p data-start=\"126\" data-end=\"416\">Ngày 19/01, Đoàn đại biểu Quốc hội (ĐBQH) tỉnh Nam Định đã phối hợp với Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn tổ chức chương trình trao tặng quà Tết cho các gia đình chính sách và các hộ có hoàn cảnh khó khăn tại một số địa phương trên địa bàn tỉnh nhân dịp Tết Nguyên đán Giáp Thìn 2024.</p>\n<p data-start=\"418\" data-end=\"628\">Tham dự chương trình có đồng chí Nguyễn Hải Dũng – Tỉnh ủy viên, Phó Trưởng đoàn chuyên trách Đoàn ĐBQH tỉnh; lãnh đạo các huyện Giao Thủy, Xuân Trường cùng đại diện chính quyền địa phương các xã được trao quà.</p>\n<p data-start=\"630\" data-end=\"920\">Trong khuôn khổ chương trình, Đoàn đã trao tặng 120 suất quà cho các gia đình chính sách, hộ nghèo tại 4 xã: Giao Hải, Giao Lạc (huyện Giao Thủy) và Xuân Hòa, Xuân Kiên (huyện Xuân Trường), mỗi xã 30 hộ. Mỗi suất quà trị giá 500.000 đồng, do Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn tài trợ.</p>\n<p data-start=\"922\" data-end=\"1354\">Tại các điểm trao quà, đại diện Đoàn ĐBQH tỉnh và Công ty đã ân cần thăm hỏi tình hình đời sống, gửi lời chúc mừng năm mới an khang, mạnh khỏe tới các gia đình; đồng thời bày tỏ mong muốn các hộ gia đình tiếp tục phát huy tinh thần vượt khó, nỗ lực vươn lên ổn định cuộc sống. Những phần quà tuy giá trị vật chất không lớn nhưng thể hiện sự quan tâm, sẻ chia kịp thời, góp phần giúp các gia đình đón Tết cổ truyền ấm áp, đủ đầy hơn.</p>\n<p data-start=\"1356\" data-end=\"1886\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn hiện đang thi công một số công trình giao thông trọng điểm trên địa bàn tỉnh Nam Định. Với tinh thần “tương thân, tương ái”, bên cạnh hoạt động sản xuất kinh doanh, Công ty luôn chú trọng thực hiện trách nhiệm xã hội đối với cộng đồng. Nhân dịp Tết Nguyên đán Giáp Thìn 2024, Công ty đã trích một phần quỹ phúc lợi, phối hợp với Đoàn ĐBQH tỉnh tổ chức trao tặng tổng cộng 260 suất quà cho các gia đình chính sách, hộ nghèo, hộ có hoàn cảnh đặc biệt khó khăn tại nhiều địa phương trong tỉnh.</p>\n<p data-start=\"1888\" data-end=\"2291\" data-is-last-node=\"\" data-is-only-node=\"\">Chương trình tặng quà Tết không chỉ mang ý nghĩa hỗ trợ vật chất mà còn lan tỏa giá trị nhân văn sâu sắc, thể hiện truyền thống tốt đẹp của dân tộc Việt Nam và tinh thần trách nhiệm của doanh nghiệp đối với xã hội. Đây cũng là nguồn động viên thiết thực, góp phần tạo thêm niềm tin, động lực để các gia đình vượt qua khó khăn, vươn lên trong cuộc sống, chung tay xây dựng quê hương ngày càng phát triển.</p>\n<img class=\"alignnone wp-image-782 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/01/Anh-dang-1.png\" alt=\"\" width=\"960\" height=\"540\" />', 298, '2024-01-20 09:00:29', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/cong-ty-dong-son-tang-qua-tet-tai-4-xa-giao-hai-giao-lac-giao-thuy-xuan-hoa-xuan-kien-xuan-truong/', 0, '2026-08-12 02:01:37', '2026-08-12 02:01:37', NULL);
INSERT INTO `pvn_news_posts` VALUES (23, 'chu-tich-ubnd-tinh-nam-dinh-kiem-tra-tien-do-du-an-tuyen-duong-bo-moi-nam-dinh-lac-quan-duong-bo-ven-bien-787', 5, 'CHỦ TỊCH UBND TỈNH NAM ĐỊNH KIỂM TRA TIẾN ĐỘ DỰ ÁN TUYẾN ĐƯỜNG BỘ MỚI NAM ĐỊNH - LẠC QUẦN - ĐƯỜNG BỘ VEN BIỂN', NULL, '<p data-start=\"110\" data-end=\"647\">Ngày 17/01, đồng chí Phạm Đình Nghị – Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh Nam Định đã đi kiểm tra tiến độ thi công dự án xây dựng tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển. Cùng tham gia đoàn công tác có đồng chí Hà Lan Anh – Tỉnh ủy viên, Phó Chủ tịch UBND tỉnh; lãnh đạo các sở, ngành: Kế hoạch và Đầu tư, Xây dựng, Giao thông Vận tải, Nông nghiệp và Phát triển nông thôn; Ban Quản lý dự án đầu tư xây dựng tỉnh; Văn phòng UBND tỉnh cùng lãnh đạo UBND các huyện Nam Trực, Trực Ninh, Hải Hậu, Xuân Trường, Giao Thủy.</p>\n<p data-start=\"649\" data-end=\"822\">Về tiến độ thi công, gói thầu số 3 (đoạn Km19+00 đến cuối tuyến) do Liên danh Công ty Đông Sơn – Hoàn Hảo – 479 Hòa Bình thực hiện hiện đạt giá trị khối lượng khoảng 23,52%.</p>\n<p data-start=\"824\" data-end=\"1325\">Đối với công tác giải phóng mặt bằng (GPMB), đến nay đã bàn giao được 21,92/24,66 km. Trong đó, phần đất nông nghiệp đã hoàn thành tạm bàn giao khoảng 21,65 km (đạt 100%), gồm: huyện Nam Trực 8,5 km; Trực Ninh 5,78 km; Xuân Trường 4,5 km; Hải Hậu 0,7 km; Giao Thủy 2,17 km. Đã bàn giao khoảng 0,27 km đất chuyển đổi trong khu dân cư xã Nam Thanh (Nam Trực). Phần còn lại 2,74 km thuộc các huyện: Nam Trực (0,46 km), Trực Ninh (1,32 km), Xuân Trường (0,46 km), Hải Hậu (0,13 km) và Giao Thủy (0,37 km).</p>\n<p data-start=\"1327\" data-end=\"1781\">Theo Thông báo số 246/TB-UBND ngày 06/10/2023 của UBND tỉnh, mặt bằng phần nền đường (rộng khoảng 50 m) phải hoàn thành bàn giao trước ngày 31/12/2023 và bàn giao toàn bộ mặt bằng trước ngày 30/6/2024. Đến nay, đối với đất trong khu dân cư, Hội đồng GPMB các huyện đã kết thúc thời gian công khai phương án; tỷ lệ hộ dân cơ bản đồng ý đạt 56%, cụ thể: Nam Trực 25/153 hộ; Trực Ninh 160/163 hộ; Xuân Trường 20/105 hộ; Hải Hậu 10/10 hộ; Giao Thủy 69/70 hộ.</p>\n<p data-start=\"1783\" data-end=\"2033\">Ban Quản lý dự án đầu tư xây dựng tỉnh cùng các nhà thầu đang phối hợp với Hội đồng GPMB các huyện Trực Ninh, Hải Hậu, Giao Thủy xác định phần lõi phạm vi công trình (khoảng 50 m) để tạm bàn giao mặt bằng đảm bảo thông tuyến thi công, đạt khoảng 95%.</p>\n<p data-start=\"2035\" data-end=\"2566\" data-is-last-node=\"\" data-is-only-node=\"\">Sau khi kiểm tra thực tế tại công trường và nghe báo cáo của các sở, ngành, địa phương, đồng chí Chủ tịch UBND tỉnh ghi nhận, biểu dương nỗ lực của các huyện trong công tác GPMB. Đồng chí yêu cầu các địa phương tiếp tục tập trung lãnh đạo, chỉ đạo quyết liệt nhằm hoàn thành công tác GPMB theo đúng kế hoạch; giao Sở Tài nguyên và Môi trường phối hợp với các sở, ngành liên quan hướng dẫn, hỗ trợ kịp thời tháo gỡ khó khăn, vướng mắc, tạo điều kiện thuận lợi để nhà thầu đẩy nhanh tiến độ, đảm bảo chất lượng và hiệu quả của dự án.</p>\n<img class=\"alignnone wp-image-790 size-full\" src=\"/uploads/news/2024/01/Anh-3-1.jpg\" alt=\"\" width=\"960\" height=\"540\" />\n\n<img class=\"alignnone wp-image-789 size-full\" src=\"/uploads/news/2024/01/Anh-2-1.jpg\" alt=\"\" width=\"960\" height=\"540\" />', 299, '2024-01-18 09:07:37', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/chu-tich-ubnd-tinh-nam-dinh-kiem-tra-tien-do-du-an-tuyen-duong-bo-moi-nam-dinh-lac-quan-duong-bo-ven-bien/', 0, '2026-08-12 02:01:37', '2026-08-12 02:01:37', NULL);
INSERT INTO `pvn_news_posts` VALUES (24, 'thuong-truc-tinh-uy-nam-dinh-kiem-tra-tien-do-mot-so-du-an-dau-tu-xay-dung-trong-diem-793', 5, 'THƯỜNG TRỰC TỈNH ỦY NAM ĐỊNH KIỂM TRA TIẾN ĐỘ CÁC DỰ ÁN ĐẦU TƯ XÂY DỰNG TRỌNG ĐIỂM TRÊN ĐỊA BÀN TỈNH', NULL, '<p data-start=\"82\" data-end=\"481\">Ngày 19/02, các đồng chí Thường trực Tỉnh ủy Nam Định gồm: đồng chí Phạm Gia Túc – Ủy viên Ban Chấp hành Trung ương Đảng, Bí thư Tỉnh ủy; đồng chí Lê Quốc Chỉnh – Phó Bí thư Thường trực Tỉnh ủy, Chủ tịch HĐND tỉnh, Trưởng Đoàn ĐBQH tỉnh; đồng chí Phạm Đình Nghị – Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh đã đi kiểm tra thực tế tiến độ triển khai một số dự án, công trình trọng điểm trên địa bàn tỉnh.</p>\n<p data-start=\"483\" data-end=\"867\">Đoàn đã kiểm tra các dự án: xây dựng tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển; dự án xây dựng cầu qua sông Đào nối đường Song Hào đến đường Vũ Hữu Lợi (thành phố Nam Định); và dự án Bệnh viện Đa khoa tỉnh. Trong đó, tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển là công trình trọng điểm mà Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đang tham gia thi công.</p>\n<p data-start=\"869\" data-end=\"1310\">Cùng đi kiểm tra có các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy: Nguyễn Phùng Hoan – Phó Chủ tịch Thường trực HĐND tỉnh; Trần Anh Dũng – Phó Chủ tịch Thường trực UBND tỉnh; Mai Văn Quyết – Giám đốc Sở Kế hoạch và Đầu tư; Nguyễn Anh Tuấn – Bí thư Thành ủy, Chủ tịch HĐND thành phố Nam Định; đồng chí Trần Lê Đoài – Tỉnh ủy viên, Phó Chủ tịch UBND tỉnh; cùng lãnh đạo các sở, ban, ngành liên quan, lãnh đạo thành phố Nam Định và huyện Nam Trực.</p>\n<p data-start=\"1312\" data-end=\"1683\">Tại các công trường, Đoàn công tác đã nghe báo cáo về tiến độ thi công, công tác giải phóng mặt bằng, những khó khăn, vướng mắc trong quá trình triển khai thực hiện dự án. Các đồng chí lãnh đạo tỉnh ghi nhận tinh thần chủ động, trách nhiệm của các chủ đầu tư, nhà thầu và chính quyền địa phương trong việc tập trung nguồn lực, đẩy nhanh tiến độ các công trình trọng điểm.</p>\n<p data-start=\"1685\" data-end=\"2221\">Đối với dự án tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển, các đồng chí Thường trực Tỉnh ủy yêu cầu các đơn vị liên quan tiếp tục phối hợp chặt chẽ, khẩn trương tháo gỡ những tồn tại trong công tác giải phóng mặt bằng, đồng thời tăng cường nhân lực, thiết bị để đẩy nhanh tiến độ thi công, bảo đảm chất lượng và an toàn lao động. Việc hoàn thành đúng tiến độ các công trình trọng điểm có ý nghĩa quan trọng trong việc thúc đẩy phát triển kinh tế – xã hội, mở rộng không gian phát triển đô thị, nâng cao đời sống nhân dân.</p>\n<p data-start=\"2223\" data-end=\"2478\" data-is-last-node=\"\" data-is-only-node=\"\">Chuyến kiểm tra thể hiện sự quan tâm, chỉ đạo sát sao của lãnh đạo tỉnh đối với các dự án trọng điểm, đồng thời tạo động lực để các chủ đầu tư, nhà thầu – trong đó có CTCP Đầu tư Hạ tầng Đông Sơn – tiếp tục nỗ lực, quyết tâm hoàn thành các mục tiêu đề ra.</p>\n<img class=\"alignnone wp-image-795 size-full\" src=\"/uploads/news/2024/02/anh-2.jpg\" alt=\"\" width=\"960\" height=\"540\" /><img class=\"alignnone wp-image-794 size-full\" src=\"/uploads/news/2024/02/Anh-1.jpg\" alt=\"\" width=\"960\" height=\"702\" />\n\nPhát biểu chỉ đạo tại buổi kiểm tra, đồng chí Bí thư Tỉnh ủy Phạm Gia Túc đã ghi nhận, biểu dương nỗ lực của các sở, ngành, địa phương trong thực hiện công tác giải phóng mặt bằng; nhà thầu thi công đã khắc phục khó khăn, tập trung tối đa nhân lực, máy móc để thực hiện các hạng mục công trình đảm bảo tiến độ, chất lượng. Đồng chí Bí thư Tỉnh ủy khẳng định, đây là các công trình trọng điểm, kiểu mẫu của tỉnh chào mừng Đại hội Đảng bộ tỉnh lần thứ XXI. Để các công trình sớm hoàn thành và đưa vào khai thác, đồng chí Bí thư Tỉnh ủy yêu cầu UBND tỉnh quyết liệt chỉ đạo các sở, ngành tạo điều kiện tối đa cho nhà thầu thực hiện các hạng mục đảm bảo tiến độ, chất lượng. Yêu cầu nhà thầu nghiên cứu, có giải pháp thi công hợp lý, hiệu quả; chủ động các nguồn vật liệu xây dựng (cát, đá...) để các hạng mục công trình đảm bảo tiến độ, chất lượng và tuyệt đối an toàn. Trong quá trình triển khai, nếu có khó khăn, vướng mắc phát sinh yêu cầu đơn vị giám sát, nhà thầu thi công báo cáo ngay với chủ đầu tư để có phương án xử lý, nếu vượt thẩm quyền kịp thời báo cáo UBND tỉnh để tháo gỡ ngay. Tỉnh cam kết tạo điều kiện tối đa cho các đơn vị giám sát, nhà thầu thi công dự án đảm bảo chất lượng, mỹ thuật và tiến độ theo kế hoạch, phục vụ phát triển kinh tế - xã hội của các địa phương và của tỉnh trong thời gian tới.', 300, '2024-02-20 09:09:09', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thuong-truc-tinh-uy-nam-dinh-kiem-tra-tien-do-mot-so-du-an-dau-tu-xay-dung-trong-diem/', 0, '2026-08-12 02:01:38', '2026-08-12 02:01:38', NULL);
INSERT INTO `pvn_news_posts` VALUES (25, 'le-ra-quan-dau-nam-tai-du-an-cai-tao-nang-cap-quoc-lo-14b-da-nang-800', 5, 'LỄ RA QUÂN ĐẦU NĂM TẠI DỰ ÁN CẢI TẠO, NÂNG CẤP QUỐC LỘ 14B (ĐÀ NẴNG)', NULL, '<p data-start=\"93\" data-end=\"394\">Sáng 19/02, ông Lê Trung Chinh – Chủ tịch UBND TP. Đà Nẵng đã tham dự lễ ra quân đầu năm tại hai dự án giao thông lớn trên địa bàn thành phố, trong đó có dự án cải tạo, nâng cấp Quốc lộ 14B – công trình do Liên danh Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn và Công ty Cổ phần Tập đoàn CIENCO4 thi công.</p>\n<p data-start=\"396\" data-end=\"800\">Phát biểu tại buổi lễ, Chủ tịch UBND TP. Đà Nẵng đánh giá dự án cải tạo, nâng cấp Quốc lộ 14B là công trình trọng điểm, mang tính động lực, có ý nghĩa quan trọng đối với phát triển hạ tầng giao thông và kinh tế – xã hội khu vực phía Nam thành phố. Đây là tuyến kết nối chiến lược giữa Đà Nẵng với các tỉnh khu vực Tây Nguyên và hệ thống cao tốc, góp phần giảm tải giao thông và nâng cao năng lực vận tải.</p>\n<p data-start=\"802\" data-end=\"1200\">Theo ông Lê Trung Chinh, do tuyến đường được cải tạo, mở rộng trên nền đường cũ, lưu lượng phương tiện qua lại lớn nên công tác đảm bảo an toàn giao thông trong quá trình thi công là yêu cầu đặc biệt quan trọng. Chủ tịch UBND thành phố đề nghị các đơn vị thi công thực hiện nghiêm các biện pháp tổ chức giao thông, đảm bảo an toàn cho người dân và phương tiện trong suốt thời gian triển khai dự án.</p>\n<p data-start=\"1202\" data-end=\"1472\">Đồng thời, ông yêu cầu huyện Hòa Vang tập trung đẩy nhanh công tác giải phóng mặt bằng, tạo điều kiện thuận lợi để nhà thầu tranh thủ thời tiết thuận lợi, huy động tối đa nhân lực, thiết bị, đẩy nhanh tiến độ thi công, phấn đấu hoàn thành dự án theo đúng kế hoạch đề ra.</p>\n<p data-start=\"1474\" data-end=\"1758\">Dự án cải tạo, nâng cấp Quốc lộ 14B có tổng mức đầu tư hơn 788 tỷ đồng từ nguồn ngân sách Trung ương và ngân sách TP. Đà Nẵng. Tuyến có điểm đầu tại Km24+633 (xã Hòa Nhơn) và điểm cuối tại Km32+185 (xã Hòa Khương, huyện Hòa Vang), giáp ranh tỉnh Quảng Nam, với tổng chiều dài 7,58 km.</p>\n<p data-start=\"1760\" data-end=\"2024\" data-is-last-node=\"\" data-is-only-node=\"\">Việc triển khai đồng bộ, quyết liệt dự án ngay từ đầu năm thể hiện quyết tâm của thành phố trong việc hoàn thiện hệ thống hạ tầng giao thông, đồng thời khẳng định năng lực và trách nhiệm của các nhà thầu tham gia thi công, trong đó có CTCP Đầu tư Hạ tầng Đông Sơn.</p>\n<img class=\"alignnone wp-image-802 size-full\" src=\"/uploads/news/2024/02/anh-4.webp\" alt=\"\" width=\"2000\" height=\"1126\" />\n\n<img class=\"alignnone wp-image-801 size-full\" src=\"/uploads/news/2024/02/Anh-3.webp\" alt=\"\" width=\"2000\" height=\"1126\" />', 301, '2024-02-20 09:30:12', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/le-ra-quan-dau-nam-tai-du-an-cai-tao-nang-cap-quoc-lo-14b-da-nang/', 0, '2026-08-12 02:01:38', '2026-08-12 02:01:38', NULL);
INSERT INTO `pvn_news_posts` VALUES (26, 'dong-son-to-chuc-hoi-nghi-tong-ket-hoat-dong-sxkd-nam-2023-804', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TỔ CHỨC HỘI NGHỊ TỔNG KẾT HOẠT ĐỘNG SẢN XUẤT KINH DOANH NĂM 2023', NULL, 'Ngày 01/02/2024, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã tổ chức Hội nghị tổng kết hoạt động sản xuất kinh doanh năm 2023 và đề ra phương hướng, nhiệm vụ năm 2024. Hội nghị có sự tham dự của các thành viên Hội đồng quản trị, Ban Kiểm soát, Ban Tổng Giám đốc cùng toàn thể cán bộ, nhân viên Công ty.\n\nTại Hội nghị, ông Đậu Hiếu Thắng – Phó Tổng Giám đốc Công ty, đại diện Ban Tổng Giám đốc – đã trình bày Báo cáo kết quả hoạt động sản xuất kinh doanh năm 2023 và phương hướng, nhiệm vụ trọng tâm năm 2024.\n\nBáo cáo nêu rõ, năm 2023 là một năm đầy thách thức khi nền kinh tế thế giới và trong nước tiếp tục đối mặt với nhiều khó khăn, biến động. Tuy nhiên, dưới sự chỉ đạo sát sao của Hội đồng quản trị, sự điều hành quyết liệt của Ban Tổng Giám đốc cùng tinh thần đoàn kết, nỗ lực của toàn thể cán bộ, nhân viên, Công ty Đông Sơn đã hoàn thành nhiều chỉ tiêu quan trọng.\n\nCụ thể, doanh thu năm 2023 đạt 405 tỷ đồng; giá trị hợp đồng ký mới trong năm đạt 1.214 tỷ đồng. Công ty đã triển khai thi công 10 công trình trọng điểm trên cả nước, tiêu biểu như: Đường bộ mới Nam Định; Cầu vượt sông Đáy; Quốc lộ 14B (Đà Nẵng); Cầu Đồng Hội; Sơn kẻ đường đoạn Bắc Ninh; Cầu Vàm Sát; Cao tốc Vĩnh Hảo – Phan Thiết; Kè Quan Chánh Bố; Mở rộng đường Nguyễn Hữu Cảnh; Kè Chợ Gạo. Các dự án đều được tổ chức thi công đảm bảo chất lượng, an toàn và tiến độ theo cam kết.\n\nTrong năm, Công ty đã đầu tư vào 01 công ty con và thành lập thêm 04 chi nhánh mới (Chi nhánh 1, Chi nhánh 2, Chi nhánh 3 và Chi nhánh 5), đồng thời thành lập 04 Ban chỉ huy công trường để trực tiếp điều hành thi công các dự án lớn gồm: Đường bộ mới Nam Định, Cầu Đồng Hội, Quốc lộ 14B (Đà Nẵng) và Cầu vượt sông Đáy. Đây là bước đi quan trọng nhằm kiện toàn tổ chức, nâng cao năng lực quản lý và điều hành thi công trong giai đoạn phát triển mới.\n\nVề công tác nhân sự, Công ty đã tuyển dụng 04 cán bộ vào làm việc tại trụ sở chính và 26 cán bộ, nhân sự cho các chi nhánh, đáp ứng yêu cầu mở rộng quy mô và triển khai đồng thời nhiều dự án trên các địa bàn khác nhau.\n\nỞ lĩnh vực thị trường, năm 2023 Công ty đã tích cực tham gia đấu thầu, chủ động mời gọi các đối tác cùng hợp tác, liên danh để nâng cao năng lực cạnh tranh. Kết quả, Công ty trúng 5/7 gói thầu với tổng giá trị 2.067,98 tỷ đồng; trong đó, phần giá trị công việc đứng danh Công ty là 1.214,234 tỷ đồng. Kết quả này cho thấy uy tín, năng lực và vị thế của Đông Sơn ngày càng được khẳng định trên thị trường xây dựng hạ tầng.\n\nPhát biểu tại Hội nghị, Ban Lãnh đạo Công ty ghi nhận, biểu dương tinh thần trách nhiệm, sự nỗ lực của toàn thể cán bộ, nhân viên trong năm qua; đồng thời nhấn mạnh nhiệm vụ trọng tâm năm 2024 là tiếp tục nâng cao năng lực quản trị, đẩy mạnh công tác thị trường, đảm bảo tiến độ – chất lượng các công trình, tăng cường quản lý tài chính và phát triển nguồn nhân lực chất lượng cao, hướng tới mục tiêu tăng trưởng bền vững.\n\nHội nghị tổng kết là dịp để toàn thể cán bộ, nhân viên nhìn lại chặng đường đã qua, rút ra bài học kinh nghiệm và thống nhất quyết tâm thực hiện thắng lợi kế hoạch năm 2024, góp phần xây dựng Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn ngày càng phát triển vững mạnh.\n\n<img class=\"alignnone size-medium wp-image-805\" src=\"/uploads/news/2024/02/anh-5-533x400.jpg\" alt=\"\" width=\"533\" height=\"400\" /><img class=\"alignnone size-medium wp-image-809\" src=\"/uploads/news/2024/02/anh-7-300x400.jpg\" alt=\"\" width=\"300\" height=\"400\" />\n\nVới nhận định năm 2024 vẫn tiếp tục còn nhiều khó khăn, thách thức, Công ty Đông Sơn xây dựng mục tiêu hoạt động ổn định, bền vững, tăng doanh thu và sản lượng. Một số nhiệm vụ trọng tâm được Công ty đề ra như sau:\n<ul>\n 	<li><em>Công ty tiếp tục nâng cao tính chủ động, tự chủ trong mọi hoạt động SXKD, tiếp tục thực hiện cơ cấu lại bộ máy tổ chức, nhân sự đi đôi với thay đổi phương thức quản trị, quản lý, điều hành sản xuất theo hướng khoa học, hiện đại, thực chất và hiệu quả, nâng cao tính chuyên nghiệp của từng bộ phận phòng ban, đơn vị.</em></li>\n 	<li><em>Tiếp tục ổn định công tác thị trường, tìm kiếm việc làm và giá trị sản xuất, doanh thu trong lĩnh vực hoạt động xây lắp. Tăng doanh thu và sản lượng lên hơn so với năm 2023.</em></li>\n 	<li><em>Từng bước ổn định khả năng tài chính, tăng cường năng lực quản lý, điều hành và thi công… để tham gia các công trình xây lắp có giá trị lớn, yêu cầu kỹ thuật cao, khẳng định vị thế và xây dựng thương hiệu cho Công ty.</em></li>\n 	<li><em>Tiếp tục bám nắm hồ sơ thiết kế và lập hồ sơ dự thầu các công trình công ty dự kiến thực hiện trong năm 2023.</em></li>\n 	<li><em>Công tác đấu thầu: Hoàn thiện các bộ hồ sơ mời thầu và hồ sơ dự thầu mẫu phân theo loại công trình phù hợp với năng lực của công ty. Hoàn thiện phương pháp tính giá dự thầu phù hợp với khối lượng mời thầu, khối lượng thiết kế bản vẽ thi công và khối lượng thực tế thi công dưới công trường.</em></li>\n 	<li><em>Sắp xếp lại bộ máy tổ chức Công ty theo hướng theo hướng tinh, gọn và chuyên môn hoá cao. Thành lập thêm hoặc sắp xếp lại các phòng ban tham mưu, đội thi công mới để đáp ứng yêu cầu công việc.</em></li>\n 	<li><em>Tái cơ cấu nhân sự các phòng ban, đơn vị. Rà soát các vị trí không đáp ứng được yêu cầu nhiệm vụ, thiếu ý thức, tư cách… để có hình thức xử lý kịp thời. Bố trí lại hoặc giải quyết các hình thức như: nghỉ chờ việc, chuyển công tác… cho các vị trí không thích hợp, không bố trí được việc làm. Đồng thời có hình thức động viên, khuyến khích kịp thời cho các vị trí có năng lực, hoàn thành tốt nhiệm vụ được giao. Tiếp tục có chính sách để thu hút nhân tài đảm nhận các vị trí chủ chốt của Công ty.</em></li>\n</ul>\nTại Hội nghị, các cán bộ nhân viên bày tỏ chia sẻ tin tưởng vào phương hướng, kế hoạch của Công ty trong tương lai. Kết thúc Hội nghị, bà Nguyễn Thị Minh Huệ - Chủ tịch Hội đồng quản trị Công ty phát biểu, tin tưởng rằng với sự đoàn kết, thống nhất và quyết tâm từ Hội đồng quản trị, Ban lãnh đạo đến toàn thể cán bộ nhân viên sẽ giúp Đông Sơn ngày càng phát triển bền vững trong các năm tiếp theo.', 302, '2024-02-01 09:43:50', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-to-chuc-hoi-nghi-tong-ket-hoat-dong-sxkd-nam-2023/', 0, '2026-08-12 02:01:39', '2026-08-12 02:01:39', NULL);
INSERT INTO `pvn_news_posts` VALUES (27, 'dong-chi-chu-tich-ubnd-tinh-nam-dinh-kiem-tra-tien-do-trien-khai-thuc-hien-du-an-duong-bo-moi-nam-dinh-lac-quan-duong-bo-ven-bien-836', 5, 'CHỦ TỊCH UBND TỈNH NAM ĐỊNH KIỂM TRA TIẾN ĐỘ THI CÔNG DỰ ÁN ĐƯỜNG BỘ MỚI NAM ĐỊNH - LẠC QUẦN - ĐƯỜNG BỘ VEN BIỂN', NULL, '<p data-start=\"82\" data-end=\"451\">Ngày 03/6, đồng chí Phạm Đình Nghị – Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh Nam Định đã đi kiểm tra thực tế và tổ chức kiểm điểm tiến độ triển khai các dự án giao thông trọng điểm trên địa bàn tỉnh, gồm: dự án xây dựng tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển và dự án cầu vượt sông Đào nối từ đường Song Hào đến đường Vũ Hữu Lợi (thành phố Nam Định).</p>\n<p data-start=\"453\" data-end=\"834\">Tham dự buổi kiểm tra có các đồng chí Ủy viên Ban Thường vụ Tỉnh ủy: Mai Văn Quyết – Giám đốc Sở Kế hoạch và Đầu tư; Nguyễn Anh Tuấn – Bí thư Thành ủy, Chủ tịch HĐND thành phố Nam Định; đồng chí Hà Lan Anh – Tỉnh ủy viên, Phó Chủ tịch UBND tỉnh; cùng lãnh đạo các sở, ngành liên quan và lãnh đạo các huyện Nam Trực, Trực Ninh, Hải Hậu, Xuân Trường, Giao Thủy và thành phố Nam Định.</p>\n<p data-start=\"836\" data-end=\"1097\">Đối với dự án tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển, công trình đi qua 5 huyện: Nam Trực, Trực Ninh, Hải Hậu, Xuân Trường và Giao Thủy, với tổng chiều dài khoảng 24,66 km. Đến nay, mặt bằng phục vụ thi công đã được bàn giao 24,585/24,66 km.</p>\n<p data-start=\"1099\" data-end=\"1265\">Cụ thể, phần đất nông nghiệp đã bàn giao khoảng 22,31 km, gồm: huyện Nam Trực 8,662 km; Trực Ninh 6,23 km; Xuân Trường 4,52 km; Hải Hậu 0,74 km; Giao Thủy 2,158 km.</p>\n<p data-start=\"1267\" data-end=\"1529\">Đối với đất dân cư vùng lõi (khoảng 50 m), đã bàn giao 2,275/2,35 km, trong đó: Nam Trực 0,568/0,568 km; Trực Ninh 0,87/0,87 km; Xuân Trường 0,365/0,44 km; Hải Hậu 0,09/0,09 km; Giao Thủy 0,382/0,382 km; còn lại 0,075 km thuộc xã Xuân Kiên (huyện Xuân Trường).</p>\n<p data-start=\"1531\" data-end=\"1766\">Phần đất dân cư ngoài vùng lõi đã bàn giao 0,838/2,142 km; trong đó huyện Hải Hậu và Giao Thủy đã hoàn thành bàn giao; Nam Trực đạt 0,248/1,017 km; Trực Ninh 0,11/0,31 km; Xuân Trường 0,05/0,385 km; còn lại khoảng 1,3 km chưa bàn giao.</p>\n<p data-start=\"1768\" data-end=\"1801\">Về tiến độ thi công các gói thầu:</p>\n\n<ul data-start=\"1803\" data-end=\"2362\">\n 	<li data-start=\"1803\" data-end=\"2015\">\n<p data-start=\"1805\" data-end=\"2015\"><strong data-start=\"1805\" data-end=\"1822\">Gói thầu số 1</strong> (Km0 – Km15+740 và nhánh kết nối Quốc lộ 21) do Liên danh Công ty Nasaco – Trung Nam thực hiện, chiều dài 15,74 km, đã nhận đủ mặt bằng 15,74 km; giá trị khối lượng thực hiện đạt khoảng 40%.</p>\n</li>\n 	<li data-start=\"2016\" data-end=\"2196\">\n<p data-start=\"2018\" data-end=\"2196\"><strong data-start=\"2018\" data-end=\"2035\">Gói thầu số 2</strong> (Km15+740 – Km19+00) do Công ty Cổ phần Xây dựng hạ tầng Đại Phong thi công, chiều dài 3,26 km, đã nhận 3,185 km mặt bằng; giá trị thực hiện đạt khoảng 52,4%.</p>\n</li>\n 	<li data-start=\"2197\" data-end=\"2362\">\n<p data-start=\"2199\" data-end=\"2362\"><strong data-start=\"2199\" data-end=\"2216\">Gói thầu số 3</strong> (Km19+00 đến cuối tuyến) dài 5,66 km do Liên danh Công ty Đông Sơn – Hoàn Hảo – 479 Hòa Bình thi công, đã nhận đủ 5,66 km mặt bằng để triển khai.</p>\n</li>\n</ul>\n<p data-start=\"2364\" data-end=\"2788\">Sau khi kiểm tra thực tế tại công trường và nghe báo cáo, đồng chí Chủ tịch UBND tỉnh yêu cầu các địa phương tiếp tục tập trung giải quyết dứt điểm những tồn tại trong công tác giải phóng mặt bằng, đặc biệt là phần đất dân cư ngoài vùng lõi; đồng thời đề nghị các nhà thầu tranh thủ điều kiện thời tiết thuận lợi, huy động tối đa nhân lực, máy móc, tổ chức thi công khoa học, đảm bảo tiến độ, chất lượng và an toàn lao động.</p>\n<p data-start=\"2790\" data-end=\"3005\" data-is-last-node=\"\" data-is-only-node=\"\">Việc đẩy nhanh tiến độ các dự án giao thông trọng điểm có ý nghĩa quan trọng trong việc hoàn thiện hạ tầng, tăng cường liên kết vùng và tạo động lực phát triển kinh tế – xã hội cho tỉnh Nam Định trong giai đoạn tới.</p>\n<img class=\"alignnone wp-image-1865 size-full\" src=\"/uploads/news/2024/06/a1_20240117164035.jpg\" alt=\"\" width=\"960\" height=\"540\" />\n\n<img class=\"alignnone wp-image-837 size-full\" src=\"/uploads/news/2024/06/Anh-dang-web-2.png\" alt=\"\" width=\"960\" height=\"540\" />', 303, '2024-06-03 13:49:31', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-chi-chu-tich-ubnd-tinh-nam-dinh-kiem-tra-tien-do-trien-khai-thuc-hien-du-an-duong-bo-moi-nam-dinh-lac-quan-duong-bo-ven-bien/', 0, '2026-08-12 02:01:40', '2026-08-12 02:01:40', NULL);
INSERT INTO `pvn_news_posts` VALUES (28, 'bien-ban-nghi-quyet-dhdcd-thuong-nien-nam-2024-841', 12, 'BIÊN BẢN & NGHỊ QUYẾT ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2024', NULL, '<p data-start=\"115\" data-end=\"324\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"174\" data-end=\"246\">Biên bản họp và Nghị quyết Đại hội đồng cổ đông thường niên năm 2024</strong> được thông qua hợp lệ theo quy định của Luật Doanh nghiệp và Điều lệ Công ty.</p>\n<p data-start=\"733\" data-end=\"910\">Biên bản và Nghị quyết Đại hội đồng cổ đông thường niên năm 2024 là căn cứ pháp lý quan trọng để Công ty triển khai các quyết nghị đã được cổ đông thông qua trong năm tài chính.</p>\n<p data-start=\"912\" data-end=\"986\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/03/2024-06-26-Bien-ban-hop-DHCDTN-2024.pdf\">Biên bản họp và Nghị quyết Đại hội đồng cổ đông thường niên năm 2024</a></span></p>', 304, '2024-06-26 10:50:58', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bien-ban-nghi-quyet-dhdcd-thuong-nien-nam-2024/', 0, '2026-08-12 02:01:40', '2026-08-12 02:01:40', NULL);
INSERT INTO `pvn_news_posts` VALUES (29, 'tai-lieu-hop-dhdcd-thuong-nien-nam-2024-844', 12, 'TÀI LIỆU HỌP ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2024', NULL, 'Toàn bộ nội dung chương trình, báo cáo và tờ trình trình Đại hội được cập nhật đầy đủ trong bộ Tài liệu họp Đại hội đồng cổ đông thường niên năm 2024 của CTCP Đầu tư Hạ tầng Đông Sơn.\n\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/06/Tai-lieu-dai-hoi-DHDCD-TN-2024.pdf\">Tài liệu họp Đại hội đồng Cổ đông thường niên năm 2024</a></span>', 305, '2024-06-03 10:55:34', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/tai-lieu-hop-dhdcd-thuong-nien-nam-2024/', 0, '2026-08-12 02:01:44', '2026-08-12 02:01:44', NULL);
INSERT INTO `pvn_news_posts` VALUES (30, 'dong-son-hinh-anh-thi-cong-tren-cac-cong-truong-850', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN CẬP NHẬT HÌNH ẢNH THI CÔNG TẠI CÁC CÔNG TRƯỜNG (THÁNG 7/2024)', NULL, '1. Hình ảnh tại công trường thi công dự án Đường bộ mới ven biển\n\n<img class=\"alignnone wp-image-851 size-full\" src=\"/uploads/news/2024/08/Anh-1.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-852 size-full\" src=\"/uploads/news/2024/08/Anh-3.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-853 size-full\" src=\"/uploads/news/2024/08/Anh-5.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-854 size-full\" src=\"/uploads/news/2024/08/Anh-6.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-855 size-full\" src=\"/uploads/news/2024/08/Anh-7.jpg\" alt=\"\" width=\"1280\" height=\"960\" /><img class=\"alignnone wp-image-857 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/08/Anh-10.jpg\" alt=\"\" width=\"1280\" height=\"960\" />\n\n2. Hình ảnh tại công trường thi công dự án cầu vượt Sông Đáy\n\n<img class=\"alignnone wp-image-861 size-full\" src=\"/uploads/news/2024/07/z5704611153540_f37e6906b9571569a1e961021d124a9b.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-862 size-full\" src=\"/uploads/news/2024/07/z5704611244528_a49bd86d6bd4d10039c504c3becbc99f-1.jpg\" alt=\"\" width=\"1280\" height=\"960\" />  <img class=\"alignnone wp-image-864 size-full\" src=\"/uploads/news/2024/07/z5704611301142_70313024b129eac2be91f72bdf7d85df.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-865 size-full\" src=\"/uploads/news/2024/07/z5704611380029_06a22b8a0f00ba6c4eb7db6f8b7cbb61.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-866 size-full\" src=\"/uploads/news/2024/07/z5704611399779_9ac9831a1bcc0287e35798e1fe04b885.jpg\" alt=\"\" width=\"1280\" height=\"960\" />\n\n3. Hình ảnh tại công trường thi công dự án cải tạo, nâng cấp Quốc lộ 14B (Đà Nẵng)<img class=\"alignnone wp-image-867 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/07/z5677864131188_7cf414d78dca1b0747966e64e828262e.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-868 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/07/z5677864142797_098a236629783da74489aa9ad5fd13d0.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-869 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/07/z5677864142924_7d9a274a272c62b1fbf839a92d2a8f45.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-870 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/07/z5677864154305_05cbea29e43b028aacfeb06cd69829cc.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-871 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/07/z5677864175905_5ff965b76d0e1c826e3640320abde69f.jpg\" alt=\"\" width=\"1280\" height=\"960\" /> <img class=\"alignnone wp-image-872 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/07/z5677864192438_d300b67dfecb9136b7f51b6a99d4e565.jpg\" alt=\"\" width=\"1280\" height=\"960\" />\n\n4. Hình ảnh tại công trường thi công dự án xây mới cầu Đồng Hội (Phú Yên)\n\n<img class=\"alignnone wp-image-873 size-full\" src=\"/uploads/news/2024/07/1.jpg\" alt=\"\" width=\"960\" height=\"1280\" /> <img class=\"alignnone wp-image-874 size-full\" src=\"/uploads/news/2024/07/2.jpg\" alt=\"\" width=\"960\" height=\"1280\" /> <img class=\"alignnone wp-image-875 size-full\" src=\"/uploads/news/2024/07/3.jpg\" alt=\"\" width=\"960\" height=\"1280\" /> <img class=\"alignnone wp-image-876 size-full\" src=\"/uploads/news/2024/07/4.jpg\" alt=\"\" width=\"960\" height=\"1280\" /> <img class=\"alignnone wp-image-877 size-full\" src=\"/uploads/news/2024/07/5.jpg\" alt=\"\" width=\"960\" height=\"1280\" />', 306, '2024-07-30 15:40:19', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-hinh-anh-thi-cong-tren-cac-cong-truong/', 0, '2026-08-12 02:01:50', '2026-08-12 02:01:50', NULL);
INSERT INTO `pvn_news_posts` VALUES (31, 'thuong-truc-tinh-uy-nam-dinh-kiem-tra-tien-do-du-an-xay-dung-cau-vuot-song-day-noi-tinh-ninh-binh-va-tinh-nam-dinh-880', 5, 'THƯỜNG TRỰC TỈNH ỦY NAM ĐỊNH KIỂM TRA TIẾN ĐỘ THI CÔNG DỰ ÁN CẦU VƯỢT SÔNG ĐÁY NỐI NINH BÌNH - NAM ĐỊNH', NULL, '<p data-start=\"75\" data-end=\"627\">Chiều 06/8, các đồng chí Thường trực Tỉnh ủy Nam Định gồm: đồng chí Phạm Gia Túc – Ủy viên Ban Chấp hành Trung ương Đảng, Bí thư Tỉnh ủy; đồng chí Lê Quốc Chỉnh – Phó Bí thư Thường trực Tỉnh ủy, Chủ tịch HĐND tỉnh, Trưởng Đoàn ĐBQH tỉnh; đồng chí Phạm Đình Nghị – Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh đã đi kiểm tra thực tế các dự án đầu tư xây dựng trọng điểm trên địa bàn tỉnh. Trong đó, Đoàn đã kiểm tra dự án xây dựng cầu vượt sông Đáy nối tỉnh Nam Định và tỉnh Ninh Bình thuộc tuyến đường bộ cao tốc Ninh Bình – Nam Định – Thái Bình – Hải Phòng.</p>\n<p data-start=\"629\" data-end=\"1052\">Dự án được khởi công từ tháng 8/2023, có tổng chiều dài tuyến chính khoảng 2 km, quy mô 4 làn xe. Phần cầu vượt sông dài khoảng 1,36 km, đường dẫn hai đầu cầu dài khoảng 0,64 km; tổng mức đầu tư 1.450 tỷ đồng. Đây là công trình có ý nghĩa đặc biệt quan trọng trong việc tăng cường kết nối liên vùng, hoàn thiện mạng lưới giao thông khu vực đồng bằng sông Hồng và tạo động lực phát triển kinh tế – xã hội cho các địa phương.</p>\n<p data-start=\"1054\" data-end=\"1272\">Về công tác giải phóng mặt bằng, đến nay cơ bản đã hoàn thành; hiện chỉ còn hạng mục di dời đường điện 0,4kV phía tỉnh Ninh Bình. UBND hai tỉnh Nam Định và Ninh Bình đã ban hành quyết định giao đất để triển khai dự án.</p>\n<p data-start=\"1274\" data-end=\"1726\">Về tiến độ thi công, giá trị khối lượng thực hiện đạt khoảng 70%. Trong đó, phần cầu đã hoàn thành 100% cọc khoan nhồi mố; hai trụ chính dưới sông (T12, T13) đã hoàn thành các khối K0, cơ bản hoàn tất lắp dựng xe đúc và thử tải; đã đổ bê tông khối K1 trụ T12, dự kiến hợp long cầu chính vào tháng 11/2024. Hai trụ chính trên cạn (T7, T8) vượt đê hữu Đáy đã hoàn thành dầm hộp đúc hẫng trụ T8 và hợp long biên với trụ T9; trụ T7 đã hoàn thành khối K0.</p>\n<p data-start=\"1728\" data-end=\"2136\">Đối với các nhịp dầm Super T, phía Ninh Bình đã lao lắp 6/8 nhịp; phía Nam Định đã hoàn thành 10/15 nhịp. Phần đường dẫn phía Nam Định đã hoàn thành đào hữu cơ, xử lý nền đất yếu; đoạn cắm bấc thấm đã hoàn thành đắp cát K95 và đắp gia tải; hiện đang tiếp tục đắp cát K95, thi công vật liệu hạt sau mố đoạn cọc xi măng đất đầu cầu, đồng thời triển khai các hạng mục thoát nước, công trình phòng hộ và phụ trợ.</p>\n<p data-start=\"2138\" data-end=\"2616\">Sau khi kiểm tra thực tế và nghe báo cáo, đồng chí Bí thư Tỉnh ủy yêu cầu các sở, ngành và địa phương liên quan tiếp tục phối hợp chặt chẽ, tạo điều kiện thuận lợi tối đa để các nhà thầu triển khai thi công đảm bảo tiến độ, chất lượng và an toàn. Đồng chí nhấn mạnh yêu cầu các đơn vị thi công huy động đầy đủ nhân lực, máy móc, tranh thủ điều kiện thời tiết thuận lợi để đẩy nhanh tiến độ, phấn đấu hoàn thành và đưa công trình vào khai thác trong năm 2024 theo kế hoạch đề ra.</p>\n<p data-start=\"2618\" data-end=\"2861\" data-is-last-node=\"\" data-is-only-node=\"\">Việc tập trung chỉ đạo quyết liệt, thường xuyên kiểm tra tiến độ thể hiện quyết tâm của tỉnh Nam Định trong việc hoàn thành các công trình hạ tầng trọng điểm, tạo nền tảng vững chắc cho phát triển kinh tế – xã hội bền vững trong giai đoạn tới.</p>\n<img class=\"alignnone wp-image-885 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/08/anh_Viber_2024-08-07_09-24-53-680.jpg\" alt=\"\" width=\"1600\" height=\"1200\" /> <img class=\"alignnone wp-image-881 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/08/Anh.png\" alt=\"\" width=\"960\" height=\"640\" />', 307, '2024-08-07 09:32:10', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thuong-truc-tinh-uy-nam-dinh-kiem-tra-tien-do-du-an-xay-dung-cau-vuot-song-day-noi-tinh-ninh-binh-va-tinh-nam-dinh/', 0, '2026-08-12 02:01:50', '2026-08-12 02:01:50', NULL);
INSERT INTO `pvn_news_posts` VALUES (32, 'dong-son-con-nguoi-la-nhan-to-trung-tam-quyet-dinh-su-phat-trien-on-dinh-ben-vung-cua-doanh-nghiep-888', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN XÁC ĐỊNH CON NGƯỜI LÀ NHÂN TỐ TRUNG TÂM, QUYẾT ĐỊNH SỰ PHÁT TRIỂN ỔN ĐỊNH VÀ BỀN VỮNG CỦA DOANH NGHIỆP', NULL, '<p data-start=\"0\" data-end=\"512\">Trong bối cảnh nền kinh tế còn nhiều biến động, cộng đồng doanh nghiệp nói chung phải đối mặt với không ít khó khăn, áp lực về chi phí, dòng tiền và thị trường; nhiều đơn vị buộc phải thực hiện cắt giảm chi phí, đặc biệt là chi phí quản lý để duy trì hoạt động ổn định. Tuy nhiên, song song với việc đảm bảo kế hoạch sản xuất kinh doanh và duy trì tăng trưởng bền vững, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn vẫn luôn xác định con người là yếu tố cốt lõi, là nền tảng cho sự phát triển lâu dài của doanh nghiệp.</p>\n<p data-start=\"514\" data-end=\"875\">Công ty đặc biệt chú trọng công tác chăm lo, bảo vệ quyền và lợi ích hợp pháp, chính đáng của người lao động. Bên cạnh việc đảm bảo việc làm ổn định, thu nhập phù hợp với năng lực và vị trí công tác, Đông Sơn còn quan tâm xây dựng môi trường làm việc chuyên nghiệp, đoàn kết, khuyến khích tinh thần sáng tạo và gắn bó lâu dài của cán bộ, công nhân viên (CBCNV).</p>\n<p data-start=\"877\" data-end=\"1201\">Các hoạt động đoàn thể được Công ty quan tâm, tạo điều kiện tổ chức thường xuyên, góp phần nâng cao đời sống tinh thần và tăng cường sự gắn kết nội bộ. Công ty luôn lắng nghe tâm tư, nguyện vọng của người lao động, từ đó xây dựng các chính sách phù hợp, hướng tới sự hài hòa giữa lợi ích doanh nghiệp và quyền lợi của CBCNV.</p>\n<p data-start=\"1203\" data-end=\"1564\">100% CBCNV của Công ty được ký kết hợp đồng lao động theo đúng quy định của pháp luật; được tham gia đầy đủ các chế độ bảo hiểm xã hội, bảo hiểm y tế, bảo hiểm thất nghiệp và bảo hiểm tai nạn. Đây không chỉ là trách nhiệm pháp lý mà còn thể hiện cam kết lâu dài của Công ty trong việc bảo đảm an sinh, tạo sự yên tâm để người lao động toàn tâm toàn ý cống hiến.</p>\n<p data-start=\"1566\" data-end=\"2058\">Song song đó, Đông Sơn luôn chú trọng công tác tuyển dụng, đào tạo và tái đào tạo nguồn nhân lực. Công ty chủ động nâng cao chất lượng đội ngũ thông qua các chương trình bồi dưỡng chuyên môn, kỹ năng quản lý, cập nhật quy định pháp luật và công nghệ mới trong lĩnh vực xây dựng – hạ tầng. Đối với các cán bộ chủ chốt, Công ty có chính sách đãi ngộ phù hợp nhằm thu hút, giữ chân và phát huy tối đa năng lực của đội ngũ nhân sự nòng cốt, từng bước nâng cao năng lực cạnh tranh trên thị trường.</p>\n<p data-start=\"2060\" data-end=\"2410\">Hàng năm, Công ty trích một phần lợi nhuận để xây dựng quỹ phúc lợi, phục vụ các hoạt động chăm lo đời sống cho người lao động như: tổ chức khám sức khỏe định kỳ, tham quan – du lịch, teambuilding và các chương trình gắn kết tập thể. Những hoạt động này không chỉ góp phần tái tạo sức lao động mà còn xây dựng văn hóa doanh nghiệp bền vững, nhân văn.</p>\n<p data-start=\"2412\" data-end=\"2653\" data-is-last-node=\"\" data-is-only-node=\"\">Với định hướng phát triển lấy con người làm trung tâm, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn tiếp tục khẳng định quan điểm: sự phát triển của doanh nghiệp phải gắn liền với sự ổn định, an tâm và trưởng thành của mỗi cán bộ, công nhân viên.</p>', 308, '2024-06-23 13:54:31', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-con-nguoi-la-nhan-to-trung-tam-quyet-dinh-su-phat-trien-on-dinh-ben-vung-cua-doanh-nghiep/', 0, '2026-08-12 02:01:51', '2026-08-12 02:01:51', NULL);
INSERT INTO `pvn_news_posts` VALUES (33, 'dong-son-to-chuc-kham-suc-khoe-dinh-ky-cho-nguoi-lao-dong-891', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TỔ CHỨC KHÁM SỨC KHỎE ĐỊNH KỲ CHO NGƯỜI LAO ĐỘNG', NULL, '<p data-start=\"80\" data-end=\"284\">Ngày 11/01/2024, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã phối hợp với Bệnh viện Mediplus tổ chức chương trình khám sức khỏe định kỳ năm 2024 cho toàn thể cán bộ, công nhân viên (CBCNV) trong Công ty.</p>\n<p data-start=\"286\" data-end=\"539\">Hoạt động khám sức khỏe thường niên nhằm giúp người lao động nắm bắt kịp thời tình trạng sức khỏe của bản thân, phát hiện sớm các nguy cơ bệnh lý để có biện pháp điều trị và phòng ngừa phù hợp, qua đó nâng cao chất lượng cuộc sống và hiệu quả công việc.</p>\n<p data-start=\"541\" data-end=\"918\">Chương trình khám được thực hiện đầy đủ theo đúng quy trình chuyên môn với sự tham gia của đội ngũ y, bác sĩ Bệnh viện Mediplus. Các nội dung khám bao gồm: khám tổng quát, siêu âm, đo điện tâm đồ, chụp X-quang tim phổi, siêu âm ổ bụng, xét nghiệm công thức máu, đường huyết, mỡ máu, chức năng gan, thận, tuyến giáp… đảm bảo đánh giá toàn diện tình trạng sức khỏe của mỗi CBCNV.</p>\n<p data-start=\"920\" data-end=\"1351\">Sau khi có kết quả, Công ty sẽ tổng hợp và phân loại sức khỏe theo kết luận chuyên môn; đồng thời cập nhật dữ liệu vào hệ thống Quản lý nguồn nhân lực, lập hồ sơ theo dõi đối với các trường hợp có bệnh lý mãn tính, thực hiện các khuyến nghị điều trị theo chỉ định của bác sĩ. Trên cơ sở đó, Công ty xem xét bố trí, sắp xếp công việc phù hợp với tình trạng sức khỏe của từng cá nhân, đảm bảo môi trường làm việc an toàn và hiệu quả.</p>\n<p data-start=\"1353\" data-end=\"1612\" data-is-last-node=\"\" data-is-only-node=\"\">Việc tổ chức khám sức khỏe định kỳ 01 lần/năm là hoạt động được Đông Sơn duy trì thường xuyên, thể hiện sự quan tâm thiết thực của Ban Lãnh đạo đối với đời sống và sức khỏe người lao động – nguồn lực quan trọng trong quá trình phát triển bền vững của Công ty.</p>', 309, '2024-01-12 16:44:24', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-to-chuc-kham-suc-khoe-dinh-ky-cho-nguoi-lao-dong/', 0, '2026-08-12 02:01:51', '2026-08-12 02:01:51', NULL);
INSERT INTO `pvn_news_posts` VALUES (34, 'ung-ho-895', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TRAO 400 TRIỆU ĐỒNG HỖ TRỢ CÁC ĐỊA PHƯƠNG TRÊN ĐỊA BÀN TỈNH NAM ĐỊNH KHẮC PHỤC HẬU QUẢ BÃO YAGI', NULL, '<p data-start=\"86\" data-end=\"318\">Sáng ngày 26/9, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã phối hợp cùng Ủy ban Mặt trận Tổ quốc Việt Nam tỉnh Nam Định tổ chức chương trình thăm hỏi và trao kinh phí hỗ trợ các địa phương bị ảnh hưởng bởi cơn bão số 3 (bão Yagi).</p>\n<p data-start=\"320\" data-end=\"525\">Theo đó, Công ty đã trao tặng 200 triệu đồng cho huyện Nam Trực và 200 triệu đồng cho huyện Trực Ninh, với mong muốn góp phần hỗ trợ hai địa phương khắc phục hậu quả sau bão, sớm ổn định đời sống Nhân dân.</p>\n<p data-start=\"527\" data-end=\"893\">Cơn bão Yagi vừa qua đã gây thiệt hại về tài sản, hoa màu và cơ sở hạ tầng tại nhiều khu vực trên địa bàn tỉnh Nam Định. Trước những khó khăn đó, sự chung tay, sẻ chia từ cộng đồng doanh nghiệp có ý nghĩa thiết thực, góp phần giúp chính quyền và người dân địa phương có thêm nguồn lực để khôi phục sản xuất, sửa chữa nhà cửa, công trình hư hỏng và ổn định cuộc sống.</p>\n<p data-start=\"895\" data-end=\"1310\">Phát biểu tại buổi trao tặng, đại diện Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn chia sẻ: bên cạnh hoạt động sản xuất kinh doanh, Công ty luôn xác định trách nhiệm xã hội là một trong những nhiệm vụ quan trọng. Với tinh thần “lá lành đùm lá rách”, “tương thân tương ái”, Đông Sơn mong muốn đóng góp một phần nhỏ bé, đồng hành cùng địa phương trong giai đoạn khó khăn, chung tay vì cộng đồng và sự phát triển bền vững.</p>\n<p data-start=\"1312\" data-end=\"1840\">Tại buổi tiếp nhận, lãnh đạo huyện Nam Trực và huyện Trực Ninh đã bày tỏ sự cảm ơn sâu sắc trước sự quan tâm, hỗ trợ kịp thời của Công ty. Đại diện hai địa phương cho biết, nguồn kinh phí này sẽ được sử dụng đúng mục đích, ưu tiên hỗ trợ các hộ gia đình bị thiệt hại nặng, sửa chữa cơ sở hạ tầng thiết yếu, góp phần nhanh chóng khắc phục hậu quả do bão lụt gây ra. Đồng thời, các địa phương cũng mong muốn trong thời gian tới tiếp tục nhận được sự quan tâm, đồng hành của Công ty trong các hoạt động an sinh xã hội trên địa bàn.</p>\n<p data-start=\"1842\" data-end=\"2210\" data-is-last-node=\"\" data-is-only-node=\"\">Hoạt động trao tặng lần này không chỉ mang giá trị vật chất mà còn lan tỏa tinh thần đoàn kết, trách nhiệm và nghĩa tình của doanh nghiệp đối với cộng đồng. Qua đó tiếp tục khẳng định vai trò, uy tín và hình ảnh của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn – một doanh nghiệp luôn gắn sự phát triển của mình với trách nhiệm xã hội và sự phát triển chung của địa phương.</p>\n<img class=\"alignnone wp-image-897 size-full\" style=\"font-size: 14.4px;\" src=\"/uploads/news/2024/09/z5868339457599_cee642bbe760f6b0349e520d5d535573.jpg\" alt=\"\" width=\"2560\" height=\"1707\" />\n\n&nbsp;', 310, '2024-09-27 10:36:22', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ung-ho/', 0, '2026-08-12 02:01:51', '2026-08-12 02:01:51', NULL);
INSERT INTO `pvn_news_posts` VALUES (35, 'dieu-le-cong-ty-902', 14, 'CÔNG TY CỔ PHẦN ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN – ĐIỀU LỆ CÔNG TY', NULL, '<p data-start=\"86\" data-end=\"214\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố các văn bản quản trị nội bộ đang áp dụng tại Công ty, cụ thể như sau:</p>\n\n<h3 data-start=\"216\" data-end=\"292\"><strong data-start=\"220\" data-end=\"290\">1. Điều lệ tổ chức và hoạt động Công ty (Điều lệ Công ty Đông Sơn)</strong></h3>\n<p data-start=\"293\" data-end=\"576\">Điều lệ quy định về tổ chức, quản trị và hoạt động của Công ty; quyền và nghĩa vụ của cổ đông; cơ cấu tổ chức quản lý; thẩm quyền và trách nhiệm của Đại hội đồng cổ đông, Hội đồng quản trị, Ban kiểm soát và Ban điều hành; cùng các nội dung khác theo quy định của pháp luật hiện hành.</p>\n<p data-start=\"293\" data-end=\"576\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/03/Dieu-le-cong-ty-Dong-Son.pdf\">Điều lệ công ty </a></span></p>\n\n<h3 data-start=\"578\" data-end=\"640\"><strong data-start=\"582\" data-end=\"638\">2. Quy chế quản trị nội bộ (QUY CHẾ QUẢN TRỊ NỘI BỘ)</strong></h3>\n<p data-start=\"641\" data-end=\"873\">Quy chế quản trị nội bộ quy định các nguyên tắc, quy trình và cơ chế quản trị nhằm đảm bảo hoạt động của Công ty minh bạch, hiệu quả, phù hợp với quy định của pháp luật và thông lệ quản trị công ty áp dụng đối với công ty đại chúng.</p>\n<p data-start=\"641\" data-end=\"873\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/09/2023.-QUY-CHE-QUAN-TRI-NOI-BO.pdf\">Quy chế quản trị nội bộ</a></span></p>\n\n<h3 data-start=\"875\" data-end=\"950\"><strong data-start=\"879\" data-end=\"948\">3. Quy chế hoạt động của Hội đồng quản trị (QUY CHẾ HOẠT ĐỘNG HĐQT 2023)</strong></h3>\n<p data-start=\"951\" data-end=\"1183\">Quy chế quy định cụ thể về chức năng, nhiệm vụ, quyền hạn, nguyên tắc hoạt động, chế độ họp và thông qua nghị quyết của Hội đồng quản trị; trách nhiệm của từng thành viên Hội đồng quản trị theo quy định pháp luật và Điều lệ Công ty.</p>\n<p data-start=\"951\" data-end=\"1183\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/09/2023.-QUY-CHE-HD-HDQT.pdf\">Quy chế hoạt động HĐQT</a> </span></p>\n\n<h3 data-start=\"1185\" data-end=\"1265\"><strong data-start=\"1189\" data-end=\"1263\">4. Quy chế hoạt động của Ban kiểm soát (QUY CHẾ HOẠT ĐỘNG BAN KIỂM SOÁT 2023)</strong></h3>\n<p data-start=\"1266\" data-end=\"1503\">Quy chế quy định về cơ cấu tổ chức, nhiệm vụ, quyền hạn, nguyên tắc hoạt động và chế độ làm việc của Ban kiểm soát; đảm bảo thực hiện chức năng giám sát hoạt động quản trị, điều hành và tình hình tài chính của Công ty theo đúng quy định.</p>\n<p data-start=\"1505\" data-end=\"1661\">Các tài liệu nêu trên được công bố nhằm đảm bảo tuân thủ quy định về công bố thông tin, đồng thời nâng cao tính minh bạch và chuẩn mực quản trị tại Công ty.</p>\n<p data-start=\"1663\" data-end=\"1727\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/09/2023.-QUY-CHE-HD-BAN-KIEM-SOAT.pdf\">Quy chế hoạt động Ban Kiểm soát</a> </span></p>\n&nbsp;\n\n&nbsp;\n\n&nbsp;', 311, '2024-03-27 10:46:59', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dieu-le-cong-ty/', 0, '2026-08-12 02:02:05', '2026-08-12 02:02:05', NULL);
INSERT INTO `pvn_news_posts` VALUES (36, 'dong-son-duoc-chap-thuan-tro-thanh-cong-ty-dai-chung-908', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN CHÍNH THỨC ĐƯỢC CHẤP THUẬN TRỞ THÀNH CÔNG TY ĐẠI CHÚNG', NULL, 'CTCP Đầu tư Hạ tầng Đông Sơn đã được cơ quan có thẩm quyền chấp thuận trở thành công ty đại chúng theo quy định của pháp luật chứng khoán. Sự kiện đánh dấu bước phát triển quan trọng trong quá trình nâng cao năng lực quản trị, minh bạch thông tin và mở rộng hoạt động của Công ty.\n\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/11/Cong-van-chap-thuan-dai-chung.pdf\">Công văn chấp thuận trở thành công ty đại chúng</a></span>', 312, '2024-11-25 16:56:54', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-duoc-chap-thuan-tro-thanh-cong-ty-dai-chung/', 0, '2026-08-12 02:02:06', '2026-08-12 02:02:06', NULL);
INSERT INTO `pvn_news_posts` VALUES (37, 'thong-bao-chot-danh-sach-co-dong-de-thuc-hien-dang-ky-luu-ky-va-dang-ky-giao-dich-co-phieu-911', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO CHỐT DANH SÁCH CỔ ĐÔNG ĐỂ THỰC HIỆN ĐĂNG KÝ LƯU KÝ VÀ ĐĂNG KÝ GIAO DỊCH CỔ PHIẾU', NULL, 'CTCP Đầu tư Hạ tầng Đông Sơn thông báo về việc chốt danh sách cổ đông nhằm thực hiện đăng ký lưu ký chứng khoán và đăng ký giao dịch cổ phiếu theo quy định hiện hành.\n\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/11/Chot-danh-sach.pdf\">Danh sách cổ đông</a></span>', 313, '2024-11-25 17:00:38', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-chot-danh-sach-co-dong-de-thuc-hien-dang-ky-luu-ky-va-dang-ky-giao-dich-co-phieu/', 0, '2026-08-12 02:02:06', '2026-08-12 02:02:06', NULL);
INSERT INTO `pvn_news_posts` VALUES (38, 'thong-bao-ky-hop-dong-kiem-toan-bctc-nam-2024-915', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO KÝ HỢP ĐỒNG KIỂM TOÁN BÁO CÁO TÀI CHÍNH NĂM 2024', NULL, '<p data-start=\"150\" data-end=\"378\"><strong data-start=\"150\" data-end=\"378\">Ngày 27/11/2024, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã ký kết Hợp đồng kiểm toán số 27116/2024/HĐTC/IAV với Công ty TNHH Kiểm toán và Định giá Quốc Tế (IAV) để thực hiện kiểm toán Báo cáo tài chính năm 2024 của Công ty.</strong></p>\n<p data-start=\"380\" data-end=\"871\">Việc ký kết hợp đồng kiểm toán được thực hiện theo quy định của pháp luật về kế toán, kiểm toán và chứng khoán, nhằm đảm bảo Báo cáo tài chính năm 2024 được kiểm toán độc lập, khách quan, trung thực và hợp lý trên các khía cạnh trọng yếu. Thông qua hoạt động kiểm toán, Công ty tiếp tục khẳng định cam kết tuân thủ các chuẩn mực kế toán hiện hành, nâng cao tính minh bạch trong công tác quản trị tài chính và cung cấp thông tin đầy đủ, chính xác tới cổ đông, nhà đầu tư và các bên liên quan.</p>\n<p data-start=\"873\" data-end=\"1099\">Đơn vị kiểm toán – Công ty TNHH Kiểm toán và Định giá Quốc Tế (IAV) – là tổ chức kiểm toán hoạt động theo quy định của pháp luật, đủ điều kiện thực hiện kiểm toán báo cáo tài chính cho các doanh nghiệp theo quy định hiện hành.</p>', 314, '2024-11-28 13:53:03', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ky-hop-dong-kiem-toan-bctc-nam-2024/', 0, '2026-08-12 02:02:07', '2026-08-12 02:02:07', NULL);
INSERT INTO `pvn_news_posts` VALUES (39, 'dong-son-ban-cong-bo-thong-tin-ve-cong-ty-dai-chung-918', 13, 'BẢN CÔNG BỐ THÔNG TIN CÔNG TY ĐẠI CHÚNG', NULL, 'Thông tin chi tiết về tình hình pháp lý, cơ cấu tổ chức, lĩnh vực hoạt động và các nội dung theo quy định đối với công ty đại chúng được cập nhật đầy đủ trong Bản công bố thông tin của CTCP Đầu tư Hạ tầng Đông Sơn.\n\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/11/Ban-Cong-bo-thong-tin.pdf\">Bản Công bố thông tin</a></span>', 315, '2024-11-25 16:34:56', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dong-son-ban-cong-bo-thong-tin-ve-cong-ty-dai-chung/', 0, '2026-08-12 02:02:16', '2026-08-12 02:02:16', NULL);
INSERT INTO `pvn_news_posts` VALUES (40, 'thong-bao-quyet-dinh-xu-phat-vi-pham-hanh-chinh-ve-thue-921', 13, 'QUYẾT ĐỊNH XỬ PHẠT VI PHẠM HÀNH CHÍNH VỀ THUẾ', NULL, '<p data-start=\"371\" data-end=\"656\">CTCP Đầu tư Hạ tầng Đông Sơn thông báo về việc nhận được Quyết định xử phạt vi phạm hành chính về thuế do cơ quan có thẩm quyền ban hành theo quy định của pháp luật hiện hành. Nội dung xử phạt liên quan đến các nghĩa vụ thuế của Công ty và được thực hiện theo quy định về quản lý thuế.</p>\n<p data-start=\"658\" data-end=\"873\">Công ty nghiêm túc chấp hành Quyết định xử phạt, đồng thời thực hiện đầy đủ các nghĩa vụ tài chính theo yêu cầu của cơ quan quản lý. Sự việc không làm ảnh hưởng đáng kể đến hoạt động sản xuất kinh doanh của Công ty.</p>\n<p data-start=\"658\" data-end=\"873\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/11/Quyet-dinh-63076.QD-CTHN.TTKT6_.XPVPHC-ngay-27.11.2024-1.pdf\">Quyết định 63076.QĐ-CTHN.TTKT6.XPVPHC ngày 27.11.2024 </a></span></p>', 316, '2024-11-29 08:39:19', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-quyet-dinh-xu-phat-vi-pham-hanh-chinh-ve-thue/', 0, '2026-08-12 02:02:17', '2026-08-12 02:02:17', NULL);
INSERT INTO `pvn_news_posts` VALUES (41, 'ban-hanh-quy-che-cong-bo-thong-tin-924', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN BAN HÀNH QUY CHẾ CÔNG BỐ THÔNG TIN', NULL, '<p data-start=\"485\" data-end=\"771\">Quy chế công bố thông tin là cơ sở để Công ty thực hiện trách nhiệm minh bạch hóa thông tin đối với cổ đông, nhà đầu tư và các bên liên quan, đồng thời nâng cao hiệu quả quản trị doanh nghiệp và tuân thủ các nghĩa vụ theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n<p data-start=\"485\" data-end=\"771\">CTCP Đầu tư Hạ tầng Đông Sơn thông báo về việc ban hành Quy chế công bố thông tin nhằm đảm bảo việc cung cấp thông tin được thực hiện kịp thời, đầy đủ, chính xác và tuân thủ quy định của pháp luật hiện hành.</p>\n<p data-start=\"485\" data-end=\"771\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/11/291124_CBTT.DS_.pdf\">Quy chế Công bố thông tin</a></span></p>', 317, '2024-11-29 10:58:12', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ban-hanh-quy-che-cong-bo-thong-tin/', 0, '2026-08-12 02:02:19', '2026-08-12 02:02:19', NULL);
INSERT INTO `pvn_news_posts` VALUES (42, 'hop-long-cau-vuot-song-day-noi-tinh-ninh-binh-va-tinh-nam-dinh-thuoc-tuyen-duong-bo-cao-toc-ninh-binh-nam-dinh-thai-binh-hai-phong-930', 5, 'LỄ HỢP LONG CẦU VƯỢT SÔNG ĐÁY NỐI NINH BÌNH - NAM ĐỊNH THUỘC TUYẾN CAO TỐC NINH BÌNH - NAM ĐỊNH - THÁI BÌNH - HẢI PHÒNG', NULL, 'Ngày 2/12, UBND tỉnh đã tổ chức lễ hợp long Dự án xây dựng cầu vượt sông Đáy nối tỉnh Ninh Bình và tỉnh Nam Định thuộc tuyến đường bộ cao tốc Ninh Bình - Nam Định - Thái Bình - Hải Phòng. Dự buổi lễ, có các đồng chí: Đặng Khánh Toàn, Bí thư Tỉnh ủy; Phạm Đình Nghị, Phó Bí thư Tỉnh ủy, Chủ tịch UBND tỉnh; Hà Lan Anh, TUV, Phó Chủ tịch UBND tỉnh.\n\n<img class=\"alignnone wp-image-931 size-full\" src=\"/uploads/news/2024/12/Anh-2.png\" alt=\"\" width=\"960\" height=\"540\" />\n\n<img class=\"alignnone wp-image-932 size-full\" src=\"/uploads/news/2024/12/anh-3.png\" alt=\"\" width=\"960\" height=\"540\" />\n\nDự án xây dựng cầu vượt sông Đáy nối tỉnh Ninh Bình và tỉnh Nam Định là dự án thành phần thuộc tuyến đường bộ cao tốc Ninh Bình - Nam Định - Thái Bình - Hải Phòng (tuyến CT.08) được thực hiện theo Quyết định số 17/2022/QĐ-TTg ngày 28/7/2022 của Thủ tướng Chính phủ. Dự án được HĐND tỉnh Nam Định quyết nghị chủ trương đầu tư tại Nghị quyết số 91/NQ-HĐND ngày 26/8/2022, số 128/NQ-HĐND ngày 09/12/2022; UBND tỉnh Nam Định phê duyệt dự án đầu tư tại Quyết định số 350/QĐ-UBND ngày 23/02/2023 với tổng mức đầu tư 1.450 tỷ đồng.\n\nDự án có tổng chiều dài tuyến 2km đi qua 2 xã Khánh Cường, Khánh Trung thuộc địa phận huyện Yên Khánh tỉnh Ninh Bình và 3 xã: Nghĩa Châu, Nghĩa Trung, Nghĩa Thái thuộc huyện Nghĩa Hưng tỉnh Nam Định. Điểm đầu dự án tại Km17+300 trên tuyến đường cao tốc Ninh Bình - Hải Phòng, thuộc xã Khánh Cường, huyện Yên Khánh, tỉnh Ninh Bình; điểm cuối dự án tại Km19+300 trên tuyến đường cao tốc Ninh Bình - Hải Phòng, thuộc xã Nghĩa Thái, huyện Nghĩa Hưng, tỉnh Nam Định.\n\n<img class=\"alignnone wp-image-933 size-full\" src=\"/uploads/news/2024/12/anh-4.png\" alt=\"\" width=\"960\" height=\"540\" />\n\nCông trình có quy mô 4 làn xe, vận tốc thiết kế 100km/giờ, gồm: Phần cầu vượt sông chiều dài khoảng 1,36km; mặt cắt ngang cầu rộng 19,5m; Đường dẫn chiều dài khoảng 0,64km với bề rộng nền đường 19m. Xây dựng các tuyến đường nhánh, nút giao và các công trình phụ trợ theo quy hoạch, quy chuẩn, tiêu chuẩn hiện hành.\n\nCầu vượt sông Đáy khoảng Km18+116/lý trình đường cao tốc Ninh Bình - Nam Định - Thái Bình - Hải Phòng; Vị trí vượt sông nằm ở phía thượng lưu bến phà Tam Tòa; Khổ thông thuyền 85mx15m; giao khác mức với đê Tả và đê Hữu sông Đáy, tĩnh không đường/đê 4,75m. Cầu gồm 29 nhịp, phần cầu chính gồm 3 nhịp liên tục dầm hộp bê tông cốt thép dự ứng lực đúc hẫng cân bằng, sơ đồ (80+130+80)m; phần cầu dẫn vượt đê Hữu sông Đáy phía tỉnh Ninh Bình gồm 3 nhịp liên tục dầm hộp bê tông cốt thép dự ứng lực sơ đồ (46+70+46)m, các nhịp dẫn còn lại dùng kết cấu dầm Super-T bê tông cốt thép dự ứng lực.', 318, '2024-12-02 15:11:04', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/hop-long-cau-vuot-song-day-noi-tinh-ninh-binh-va-tinh-nam-dinh-thuoc-tuyen-duong-bo-cao-toc-ninh-binh-nam-dinh-thai-binh-hai-phong/', 0, '2026-08-12 02:02:21', '2026-08-12 02:02:21', NULL);
INSERT INTO `pvn_news_posts` VALUES (43, 'thong-bao-ve-viec-co-phieu-dong-son-duoc-chap-thuan-dang-ky-luu-ky-tai-vsdc-939', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO VỀ VIỆC CỔ PHIẾU ĐƯỢC CHẤP THUẬN ĐĂNG KÝ, LƯU KÝ TẠI VSDC', NULL, 'Ngày 16/12/2024, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn nhận được công văn số 16106/VSDC-ĐKCP.NV của Tổng công ty lưu ký và bù trừ chứng khoán Việt Nam về việc chứng nhận đăng ký cổ phiếu, theo đó cổ phiếu Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn được đăng ký, lưu ký tại Tổng công ty lưu ký và bù trừ chứng khoán Việt Nam với mã chứng khoán DSH.\n\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2024/12/CV-xac-nhan-dang-ky-CK.pdf\">Công văn xác nhận đăng ký Chứng khoán</a></span>', 319, '2024-12-16 16:10:20', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ve-viec-co-phieu-dong-son-duoc-chap-thuan-dang-ky-luu-ky-tai-vsdc/', 0, '2026-08-12 02:02:21', '2026-08-12 02:02:21', NULL);
INSERT INTO `pvn_news_posts` VALUES (44, 'thong-bao-ty-le-so-huu-nuoc-ngoai-toi-da-tai-dong-son-942', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO TỶ LỆ SỞ HỮU NƯỚC NGOÀI TỐI ĐA', NULL, 'Ngày 16/12/2024, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn nhận được công văn số 8456/UBCK-PTTT của Ủy ban Chứng khoán Nhà nước về việc thông báo tỷ lệ sở hữu nước ngoài tối đa của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn tại mức 0%.\n\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/wp-content/uploads/2024/12/TB-ty-le-so-huu-nuoc-ngoai-toi-da.pdf\">Thông báo tỷ lệ sở hữu nước ngoài tối đa</a></span>', 320, '2024-12-16 16:11:37', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ty-le-so-huu-nuoc-ngoai-toi-da-tai-dong-son/', 0, '2026-08-12 02:02:52', '2026-08-12 02:02:52', NULL);
INSERT INTO `pvn_news_posts` VALUES (45, 'nghi-quyet-so-02-01-2024-nq-hdqt-dsh-ve-thong-qua-chu-truong-ky-ket-thuc-hien-cac-hop-dong-giao-dich-thoa-thuan-giua-cong-ty-cp-dau-tu-ha-tang-dong-son-voi-cac-cong-ty-con-cong-ty-lien-ket-nguoi-co-953', 13, 'NGHỊ QUYẾT SỐ 02.01.2025/NQ-HĐQT/DSH VỀ VIỆC THÔNG QUA CHỦ TRƯƠNG KÝ KẾT, THỰC HIỆN CÁC HỢP ĐỒNG, GIAO DỊCH VỚI CÔNG TY CON, CÔNG TY LIÊN KẾT, NGƯỜI CÓ LIÊN QUAN VÀ THÔNG QUA PHƯƠNG ÁN MUA TIẾP CỔ PHẦN TẠI CTCP CÔNG NGHỆ ĐÔNG QUANG INVESTMENT', NULL, '<p data-start=\"129\" data-end=\"422\">Hội đồng quản trị CTCP Đầu tư Hạ tầng Đông Sơn đã ban hành Nghị quyết số 02.01.2025/NQ-HĐQT/DSH về việc thông qua chủ trương ký kết và thực hiện các Hợp đồng/Giao dịch/Thỏa thuận giữa Công ty với các công ty con, công ty liên kết và người có liên quan theo quy định tại Luật Doanh nghiệp 2020.</p>\n<p data-start=\"424\" data-end=\"695\">Đồng thời, Nghị quyết cũng thông qua phương án mua tiếp cổ phần tại Công ty Cổ phần Công nghệ Đông Quang Investment nhằm phục vụ định hướng đầu tư và chiến lược phát triển của Công ty trong thời gian tới. Nội dung được thực hiện theo Nghị quyết đã được ban hành.</p>\n<p data-start=\"424\" data-end=\"695\">Chi tiết: <a style=\"font-size: 14.4px;\" href=\"https://htds.vn/wp-content/uploads/2025/01/NQ-HDQT-ngay-02.01.2025.pdf\"><span style=\"color: #0000ff;\">NQ HĐQT ngày 02.01.2025</span></a></p>', NULL, '2025-01-03 11:29:31', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-so-02-01-2024-nq-hdqt-dsh-ve-thong-qua-chu-truong-ky-ket-thuc-hien-cac-hop-dong-giao-dich-thoa-thuan-giua-cong-ty-cp-dau-tu-ha-tang-dong-son-voi-cac-cong-ty-con-cong-ty-lien-ket-nguoi-co/', 0, '2026-08-12 02:03:34', '2026-08-12 02:03:34', NULL);
INSERT INTO `pvn_news_posts` VALUES (46, 'bao-cao-tinh-hinh-quan-tri-cong-ty-nam-2024-960', 13, 'BÁO CÁO TÌNH HÌNH QUẢN TRỊ CÔNG TY NĂM 2024', NULL, '<p data-start=\"315\" data-end=\"455\">CTCP Đầu tư Hạ tầng Đông Sơn công bố Báo cáo tình hình quản trị công ty năm 2024 theo quy định của pháp luật về doanh nghiệp và chứng khoán.</p>\n<p data-start=\"457\" data-end=\"766\">Báo cáo phản ánh hoạt động của Hội đồng quản trị, Ban Kiểm soát, Ban Điều hành và các nội dung liên quan đến công tác quản trị doanh nghiệp trong năm, bao gồm việc thực hiện quyền và nghĩa vụ của các thành viên, tình hình giao dịch với người có liên quan và các nội dung khác theo quy định hiện hành.</p>\n<p data-start=\"457\" data-end=\"766\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/02/Bao-cao-quan-tri-ban-cong-bo.pdf\">Báo cáo quản trị 2024</a></span></p>', 321, '2025-01-16 16:49:38', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tinh-hinh-quan-tri-cong-ty-nam-2024/', 0, '2026-08-12 02:03:37', '2026-08-12 02:03:37', NULL);
INSERT INTO `pvn_news_posts` VALUES (47, 'thong-bao-giay-chung-nhan-dang-ky-dia-diem-kinh-doanh-963', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO VỀ VIỆC ĐƯỢC CẤP GIẤY CHỨNG NHẬN ĐĂNG KÝ ĐỊA ĐIỂM KINH DOANH', NULL, 'Ngày 10/02/2025, Công ty CP Đầu tư Hạ tầng Đông Sơn nhận được Giấy chứng nhận đăng ký địa điểm kinh doanh với các thông tin như sau:\n<ul>\n 	<li>Mã số địa điểm kinh doanh: 00001</li>\n 	<li>Đăng ký lần đầu, ngày 04 tháng 02 năm 2025</li>\n 	<li>Địa chỉ: Khu B53, đường Anh Dũng, thôn Cầu, xã Kim Nỗ, huyện Đông Anh, TP Hà Nội</li>\n 	<li>Thông tin về người đứng đầu:</li>\n 	<li>Họ và tên: Nguyễn Tiến Hưng Giới tính: Nam</li>\n 	<li>Sinh ngày: 25/08/1977 Dân tộc: Kinh  Quốc tịch: Nam</li>\n 	<li>Số giấy tờ pháp lý của cá nhân: 026077000501</li>\n 	<li>Ngày cấp: 18/08/2022 Nơi cấp: Cục cảnh sát Quản lý hành chính về trật tự xã hội</li>\n 	<li>Địa chỉ thường trú: CH12A06, CT3C, Khu ĐTM Hoàng 7, phường Cổ Nhuế 1, quận Bắc Từ Liêm, TP Hà Nội</li>\n</ul>\nĐịa chỉ liên lạc: CH12A06, CT3C, Khu ĐTM Hoàng 7, phường Cổ Nhuế 1, quận Bắc Từ Liêm, TP Hà Nội\n\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/02/DKDDKD-04.02.2025.pdf\">Giấy chứng nhận đăng ký địa điểm kinh doanh</a></span>', 322, '2025-02-10 16:59:56', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-giay-chung-nhan-dang-ky-dia-diem-kinh-doanh/', 0, '2026-08-12 02:03:38', '2026-08-12 02:03:38', NULL);
INSERT INTO `pvn_news_posts` VALUES (48, 'le-ky-niem-15-nam-thanh-lap-cong-ty-va-tiec-tat-nien-967', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN KỶ NIỆM 15 NĂM THÀNH LẬP VÀ TỔ CHỨC TIỆC TẤT NIÊN', NULL, 'Ngày 10/01/2025, Công ty Cổ phần Đầu tư hạ tầng Đông Sơn (mã chứng khoán: DSH) long trọng tổ chức lễ kỷ niệm 15 năm thành lập Công ty và cũng là tiệc tất niên để cùng nhìn lại một năm qua. Đây là sự kiện đánh dấu 1 cột mốc quan trọng <strong>\"15 năm vững bước để vươn xa\"</strong>, tạo nền tảng vững chắc, chỗ đứng trên thị trường của Công ty Cổ phần Đầu tư hạ tầng Đông Sơn.\n\nSự kiện diễn ra tại khách sạn Daewoo, Công ty Cổ phần Đầu tư hạ tầng Đông Sơn đã vinh hạnh được đón tiếp các khách mời là đối tác, khách hàng, cán bộ nhân viên đến dự buổi lễ kỷ niệm 15 năm thành lập công ty.\n\n<img class=\"alignnone wp-image-978 size-full\" src=\"/uploads/news/2025/01/Untitled-design.png\" alt=\"\" width=\"800\" height=\"600\" />\n\nBuổi lễ đánh dấu chặng đường 15 năm (09/12/2009 - 09/12/2024) nỗ lực xây dựng và phát triển của toàn thể cán bộ nhân viên Công ty. 15 năm là một chằng đường dài đối với một doanh nghiệp, một chặng đường có nhiều gian nan, thử thách nhưng cũng ghi nhận sự phát triển và khẳng định thương hiệu, vị thế của Đông Sơn trong lĩnh vực xây lắp.\n\nNăm 2024, Công ty Cổ phần Đầu tư hạ tầng Đông Sơn đã hoàn thành đăng ký trở thành công ty đại chúng và được cấp mã chứng khoán DSH. Việc trở thành công ty đại chúng cũng là cột mốc đánh dấu một giai đoạn mới của Công ty, là bước phát triển quan trọng trong hoạt động của doanh nghiệp. Bằng việc trở thành công ty đại chúng, Công ty sẽ tạo được uy tín thương hiệu tốt hơn, tạo được niềm tin vững chắc nơi nhà đầu tư nhưng đồng thời Công ty cũng sẽ phải công khai mọi hoạt động của mình và chịu sự giám sát của công chúng.\n\nBuổi lễ cũng là dịp để Đông Sơn gửi lời cảm ơn chân thành đến những cán bộ nhân viên - những người đã xây dựng, cống hiến cho doanh nghiệp. Bên cạnh đó còn là lời tri ân sâu sắc đến những khách hàng, đối tác đã đồng hành cùng doanh nghiệp suốt chặng đường từ lúc hình thành đến khi phát triển vững chắc như hiện nay.\n\n<img class=\"alignnone wp-image-980 size-full\" src=\"/uploads/news/2025/01/Anh-hoa-1.jpg\" alt=\"\" width=\"2000\" height=\"2000\" /><img class=\"alignnone wp-image-981 size-full\" src=\"/uploads/news/2025/01/Anh-hoa-2.jpg\" alt=\"\" width=\"2000\" height=\"2000\" /> <img class=\"alignnone wp-image-982 size-full\" src=\"/uploads/news/2025/01/anh-hoa-3.jpg\" alt=\"\" width=\"2000\" height=\"2000\" />\n\n&nbsp;', 323, '2025-01-11 09:52:07', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/le-ky-niem-15-nam-thanh-lap-cong-ty-va-tiec-tat-nien/', 0, '2026-08-12 02:03:40', '2026-08-12 02:03:40', NULL);
INSERT INTO `pvn_news_posts` VALUES (49, 'bo-nhiem-nguoi-phu-trach-quan-tri-cong-ty-va-nguoi-uy-quyen-thuc-hien-cong-bo-thong-tin-987', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN BỔ NHIỆM NGƯỜI PHỤ TRÁCH QUẢN TRỊ CÔNG TY VÀ NGƯỜI ĐƯỢC ỦY QUYỀN THỰC HIỆN CÔNG BỐ THÔNG TIN', NULL, '<p data-start=\"106\" data-end=\"360\">Hội đồng quản trị CTCP Đầu tư Hạ tầng Đông Sơn đã ban hành Nghị quyết số 17.02/2025/QĐ-HĐQT/DSH về việc bổ nhiệm Người phụ trách quản trị công ty. Theo đó, bà <strong data-start=\"265\" data-end=\"288\">Nguyễn Thị Thu Thùy</strong> được bổ nhiệm giữ chức vụ Người phụ trách quản trị công ty của Công ty.</p>\n<p data-start=\"362\" data-end=\"630\">Đồng thời, Công ty đã ban hành Văn bản ủy quyền số 01/2025/GUQ-DSH về việc ủy quyền bà <strong data-start=\"449\" data-end=\"472\">Nguyễn Thị Thu Thùy</strong> – Người phụ trách quản trị công ty – là Người được ủy quyền thực hiện công bố thông tin theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n<p data-start=\"632\" data-end=\"858\">Việc bổ nhiệm và ủy quyền được thực hiện theo đúng thẩm quyền và quy định pháp luật hiện hành, nhằm đảm bảo công tác quản trị doanh nghiệp và nghĩa vụ công bố thông tin của Công ty được thực hiện đầy đủ, kịp thời và minh bạch.</p>\n<p data-start=\"632\" data-end=\"858\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/02/CBTT-ngay-18.02.2025.pdf\">Bổ nhiệm Người phụ trách quản trị công ty và Người ủy quyền thực hiện công bố thông tin</a></span></p>', 324, '2025-02-18 09:36:03', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bo-nhiem-nguoi-phu-trach-quan-tri-cong-ty-va-nguoi-uy-quyen-thuc-hien-cong-bo-thong-tin/', 0, '2026-08-12 02:03:40', '2026-08-12 02:03:40', NULL);
INSERT INTO `pvn_news_posts` VALUES (50, 'thong-bao-ngay-chot-danh-sach-co-dong-co-quyen-tham-du-dai-hoi-dong-co-dong-thuong-nien-nam-2025-994', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO NGÀY CHỐT DANH SÁCH CỔ ĐÔNG CÓ QUYỀN THAM DỰ ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2025', NULL, '<p data-start=\"433\" data-end=\"609\">CTCP Đầu tư Hạ tầng Đông Sơn thông báo về ngày chốt danh sách cổ đông có quyền tham dự Đại hội đồng cổ đông thường niên năm 2025 theo quy định của pháp luật và Điều lệ Công ty.</p>\n<p data-start=\"611\" data-end=\"895\">Danh sách cổ đông được lập căn cứ trên dữ liệu đăng ký, lưu ký cổ phiếu tại ngày chốt quyền nhằm xác định các cổ đông đủ điều kiện tham dự và thực hiện quyền biểu quyết tại Đại hội. Thông tin chi tiết về thời gian, địa điểm và nội dung Đại hội sẽ được Công ty thông báo theo quy định.</p>\n\n<table width=\"651\">\n<tbody>\n<tr>\n<td width=\"210\">Tên chứng khoán</td>\n<td width=\"441\">: Cổ phiếu Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</td>\n</tr>\n<tr>\n<td width=\"210\">Mã chứng khoán</td>\n<td width=\"441\">: DSH</td>\n</tr>\n<tr>\n<td width=\"210\">Loại chứng khoán</td>\n<td width=\"441\">: Cổ phiếu phổ thông</td>\n</tr>\n<tr>\n<td width=\"210\">Mệnh giá giao dịch</td>\n<td width=\"441\">: 10.000 đồng</td>\n</tr>\n<tr>\n<td width=\"210\">Sàn giao dịch</td>\n<td width=\"441\">: sàn đại chúng chưa niêm yết</td>\n</tr>\n<tr>\n<td width=\"210\">Ngày đăng ký cuối cùng</td>\n<td width=\"441\">: 01/04/2025</td>\n</tr>\n<tr>\n<td width=\"210\"><strong>1.   </strong><strong>Lý do và mục đích</strong></td>\n<td width=\"441\">: Tham dự Đại hội đồng cổ đông thường niên năm 2025</td>\n</tr>\n<tr>\n<td width=\"210\"><strong>2.   </strong><strong>Nội dung cụ thể</strong></td>\n<td width=\"441\"></td>\n</tr>\n<tr>\n<td width=\"210\">Tỷ lệ thực hiện</td>\n<td width=\"441\">: 01 cổ phần – 1 quyền biểu quyết</td>\n</tr>\n<tr>\n<td width=\"210\">Thời gian thực hiện</td>\n<td width=\"441\">: Công ty sẽ thông báo sau</td>\n</tr>\n<tr>\n<td width=\"210\">Địa điểm thực hiện</td>\n<td width=\"441\">: Công ty sẽ thông báo sau</td>\n</tr>\n<tr>\n<td width=\"210\">Nội dung họp:</td>\n<td width=\"441\">: Các nội dung thuộc thẩm quyền đại hội đồng cổ đông.</td>\n</tr>\n</tbody>\n</table>', 325, '2025-03-11 11:31:23', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ngay-chot-danh-sach-co-dong-co-quyen-tham-du-dai-hoi-dong-co-dong-thuong-nien-nam-2025/', 0, '2026-08-12 02:03:41', '2026-08-12 02:03:41', NULL);
INSERT INTO `pvn_news_posts` VALUES (51, 'bao-cao-tai-chinh-rieng-nam-2024-da-duoc-kiem-toan-999', 15, 'BÁO CÁO TÀI CHÍNH RIÊNG NĂM 2024 (ĐÃ ĐƯỢC KIỂM TOÁN)', NULL, '<p data-start=\"101\" data-end=\"253\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"160\" data-end=\"214\">Báo cáo tài chính riêng năm 2024 đã được kiểm toán</strong> theo quy định của pháp luật hiện hành.</p>\n<p data-start=\"531\" data-end=\"698\">Báo cáo đã được kiểm toán bởi đơn vị kiểm toán độc lập theo đúng chuẩn mực và quy định về kiểm toán, với ý kiến kiểm toán được thể hiện tại Báo cáo kiểm toán kèm theo.</p>\n<p data-start=\"700\" data-end=\"890\">Việc công bố thông tin nhằm đảm bảo tính minh bạch, tuân thủ quy định về công bố thông tin đối với công ty đại chúng và cung cấp cơ sở tham khảo cho cổ đông, nhà đầu tư và các bên liên quan.</p>\n<p data-start=\"892\" data-end=\"985\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/03/BCTC-rieng-CTCP-Dau-tu-Ha-tang-Dong-Son-Nam-2024.pdf\">Báo cáo tài chính riêng năm 2024</a></span></p>', 326, '2025-03-17 14:40:14', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-rieng-nam-2024-da-duoc-kiem-toan/', 0, '2026-08-12 02:03:47', '2026-08-12 02:03:47', NULL);
INSERT INTO `pvn_news_posts` VALUES (52, 'bao-cao-tai-chinh-hop-nhat-nam-2024-da-duoc-kiem-toan-1003', 15, 'BÁO CÁO TÀI CHÍNH HỢP NHẤT NĂM 2024 (ĐÃ ĐƯỢC KIỂM TOÁN)', NULL, '<span style=\"font-size: 14.4px;\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố </span><strong style=\"font-size: 14.4px;\" data-start=\"163\" data-end=\"220\">Báo cáo tài chính hợp nhất năm 2024 đã được kiểm toán</strong><span style=\"font-size: 14.4px;\"> theo quy định của pháp luật về kế toán, kiểm toán và công bố thông tin trên thị trường chứng khoán.</span>\n<p data-start=\"676\" data-end=\"839\">Báo cáo đã được kiểm toán bởi đơn vị kiểm toán độc lập theo các chuẩn mực và quy định hiện hành, với ý kiến kiểm toán được thể hiện tại Báo cáo kiểm toán đính kèm.</p>\n<p data-start=\"841\" data-end=\"1022\">Việc công bố Báo cáo tài chính hợp nhất đã được kiểm toán nhằm đảm bảo tính minh bạch, cung cấp thông tin đầy đủ, kịp thời và chính xác tới cổ đông, nhà đầu tư và các bên liên quan.</p>\n<p data-start=\"1024\" data-end=\"1129\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/03/BCTC-hop-nhat-CTCP-Dau-tu-Ha-tang-Dong-Son-Nam-2024.pdf\">Báo cáo tài chính hợp nhất năm 2024</a></span></p>', 327, '2025-03-17 14:42:52', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-hop-nhat-nam-2024-da-duoc-kiem-toan/', 0, '2026-08-12 02:03:53', '2026-08-12 02:03:53', NULL);
INSERT INTO `pvn_news_posts` VALUES (53, 'cong-van-giai-trinh-chenh-lech-loi-nhuan-tren-10-tren-bctc-voi-bao-cao-cung-ky-nam-truoc-1006', 15, 'CÔNG VĂN GIẢI TRÌNH CHÊNH LỆCH LỢI NHUẬN TRÊN 10% SO VỚI CÙNG KỲ NĂM TRƯỚC', NULL, '<p data-start=\"125\" data-end=\"344\">Thực hiện quy định về công bố thông tin trên thị trường chứng khoán, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố <strong data-start=\"242\" data-end=\"343\">Công văn giải trình chênh lệch lợi nhuận trên 10% trên Báo cáo tài chính so với cùng kỳ năm trước</strong>.</p>\n<p data-start=\"346\" data-end=\"804\">Theo đó, căn cứ số liệu tại Báo cáo tài chính đã công bố, lợi nhuận của Công ty trong kỳ báo cáo có sự biến động trên 10% so với cùng kỳ năm trước. Công ty đã thực hiện lập Công văn giải trình, phân tích nguyên nhân chủ yếu dẫn đến sự thay đổi này.</p>\n<p data-start=\"806\" data-end=\"986\">Việc giải trình được thực hiện nhằm đảm bảo tuân thủ đầy đủ quy định của pháp luật, đồng thời cung cấp thông tin minh bạch, kịp thời tới cổ đông, nhà đầu tư và các cơ quan quản lý.</p>\n<p data-start=\"806\" data-end=\"986\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/03/CBTT-giai-trinh-BCTC.pdf\">Công văn giải trình</a></span></p>', 328, '2025-03-17 14:44:16', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/cong-van-giai-trinh-chenh-lech-loi-nhuan-tren-10-tren-bctc-voi-bao-cao-cung-ky-nam-truoc/', 0, '2026-08-12 02:03:54', '2026-08-12 02:03:54', NULL);
INSERT INTO `pvn_news_posts` VALUES (54, 'thong-bao-quyet-dinh-chap-thuan-dang-ky-giao-dich-co-phieu-tai-san-upcom-1010', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO QUYẾT ĐỊNH CHẤP THUẬN ĐĂNG KÝ GIAO DỊCH CỔ PHIẾU TẠI SÀN UPCOM', NULL, '<p data-start=\"383\" data-end=\"555\">CTCP Đầu tư Hạ tầng Đông Sơn thông báo về việc nhận được Quyết định chấp thuận đăng ký giao dịch cổ phiếu của Công ty trên hệ thống giao dịch UPCoM theo quy định hiện hành.</p>\n<p data-start=\"557\" data-end=\"864\">Việc được chấp thuận đăng ký giao dịch cổ phiếu tại UPCoM là bước quan trọng trong quá trình tham gia thị trường chứng khoán, góp phần nâng cao tính minh bạch, tăng cường năng lực quản trị và mở rộng cơ hội tiếp cận nhà đầu tư của Công ty. Thông tin chi tiết được thực hiện theo Quyết định đã được ban hành.</p>\n<p data-start=\"557\" data-end=\"864\">Chi tiết:<span style=\"color: #0000ff;\"> <a style=\"color: #0000ff;\" href=\"/uploads/news/2025/04/DSH-QD-so-300.QD_.HNX-ngay-03.04.2025-vv-DKGD-Upcom.pdf\">Quyết định chấp thuận đăng ký giao dịch cổ phiếu trên sàn UPCoM</a></span></p>', 329, '2025-04-03 16:22:16', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-quyet-dinh-chap-thuan-dang-ky-giao-dich-co-phieu-tai-san-upcom/', 0, '2026-08-12 02:03:54', '2026-08-12 02:03:54', NULL);
INSERT INTO `pvn_news_posts` VALUES (55, 'ban-cong-bo-thong-tin-dang-ky-giao-dich-upcom-1013', 13, 'THÔNG TIN ĐĂNG KÝ GIAO DỊCH UPCOM', NULL, '<p data-start=\"340\" data-end=\"550\">CTCP Đầu tư Hạ tầng Đông Sơn công bố Bản công bố thông tin phục vụ việc đăng ký giao dịch cổ phiếu của Công ty trên hệ thống giao dịch UPCoM theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n<p data-start=\"552\" data-end=\"851\">Bản công bố thông tin cung cấp các nội dung liên quan đến tình hình hoạt động sản xuất kinh doanh, cơ cấu tổ chức, quản trị doanh nghiệp, tình hình tài chính và các thông tin quan trọng khác nhằm đảm bảo tính minh bạch, đầy đủ và chính xác trước khi cổ phiếu chính thức đăng ký giao dịch trên UPCoM.</p>\n<p data-start=\"552\" data-end=\"851\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/04/Ban-CBTT-ban-scan.pdf\">Bản công bố thông tin đăng ký giao dịch UPCoM</a></span></p>', 330, '2025-04-03 16:23:40', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ban-cong-bo-thong-tin-dang-ky-giao-dich-upcom/', 0, '2026-08-12 02:03:59', '2026-08-12 02:03:59', NULL);
INSERT INTO `pvn_news_posts` VALUES (56, 'bao-cao-thuong-nien-nam-2024-1024', 16, 'BÁO CÁO THƯỜNG NIÊN NĂM 2024', NULL, NULL, 331, '2025-04-04 21:29:54', 'd/m/Y', NULL, 'sm', 0, 0, 1, 2, 'published', 'https://pvnsoft.cloud/bao-cao-thuong-nien-nam-2024/', 0, '2026-08-12 02:03:59', '2026-08-12 02:03:59', NULL);
INSERT INTO `pvn_news_posts` VALUES (57, 'thong-bao-ngay-giao-dich-dau-tien-cua-co-phieu-dsh-1027', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO NGÀY GIAO DỊCH ĐẦU TIÊN CỦA CỔ PHIẾU DSH', NULL, '- Ngày 10/04/2025, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn nhận được Thông báo số 1570/TB-SGDHN ngày 10/04/2025 của Sở Giao dịch chứng khoán Hà Nội về ngày giao dịch đầu tiên cổ phiếu đăng ký giao dịch của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn với những nội dung sau:\n\n- Tên tổ chức đăng ký giao dịch: Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn\n\n- Loại chứng khoán: Cổ phiếu phổ thông\n\n- Mã chứng khoán: DSH\n\n- Mệnh giá: 10.000 đồng/cổ phiếu\n\n- Số lượng chứng khoán đăng ký giao dịch: 10.000.000 cổ phiếu <em>(Mười triệu cổ phiếu)</em>\n\n- Giá trị chứng khoán đăng ký giao dịch: 100.000.000.000 đồng <em>(Một trăm tỷ đồng)</em>\n\n- Ngày giao dịch đầu tiên: Thứ Ba, ngày 22/04/2025\n\n- Giá tham chiếu trong ngày giao dịch đầu tiên: 18.000 đồng/cổ phiếu\n\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/04/10.04.2025-TB-ngay-giao-dich-dau-tien.pdf\">10.04.2025 - Thông báo ngày giao dịch đầu tiên</a></span>', 332, '2025-04-10 16:55:30', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ngay-giao-dich-dau-tien-cua-co-phieu-dsh/', 0, '2026-08-12 02:04:00', '2026-08-12 02:04:00', NULL);
INSERT INTO `pvn_news_posts` VALUES (58, 'dau-tu-ha-tang-dong-son-chinh-thuc-giao-dich-tren-upcom-voi-ma-dsh-gia-chao-san-18-000-dong-cp-1031', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN CHÍNH THỨC GIAO DỊCH TRÊN UPCOM VỚI MÃ CHỨNG KHOÁN DSH, GIÁ CHÀO SÀN 18.000 ĐỒNG/CỔ PHIẾU', NULL, 'Ngày 22/04/2025, 10 triệu cổ phiếu DSH của CTCP Đầu tư Hạ tầng Đông Sơn chính thức được giao dịch trên sàn UPCoM. Giá tham chiếu trong ngày giao dịch đầu tiên là 18.000 đồng/cổ phiếu, tương ứng với mức định giá doanh nghiệp khi chào sàn là 180 tỷ đồng.\n\nTrước đó, ngày 03/04/2025, Sở Giao dịch Chứng khoán Hà Nội (HNX) đã chấp thuận cho Đầu tư Hạ tầng Đông Sơn đăng ký giao dịch 10 triệu cổ phiếu DSH trên UPCoM.\n\n<img class=\"alignnone wp-image-1037 size-full\" src=\"/uploads/news/2025/04/KTT00491-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1716\" /> <img class=\"alignnone wp-image-1038 size-full\" src=\"/uploads/news/2025/04/KTT00542-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1712\" />\n\nTiền thân của Đầu tư Hạ tầng Đông Sơn là CTCP Đầu tư và Thương mại 319, được thành lập vào năm 2009 với vốn điều lệ 100 tỷ đồng. Đến năm 2017, cổ đông sáng lập là Tổng công ty 319 (Bộ Quốc Phòng) đã thực hiện thoái vốn, giảm tỷ lệ sở hữu từ 51% xuống còn 15%, thông qua việc chào bán thành công 3,6 triệu cổ phần với giá 11.900 đồng/cổ phiếu. Tháng 10/2019, công ty chính thức đổi tên thành CTCP Đầu tư Hạ tầng Đông Sơn.\n\nĐầu tư Hạ tầng Đông Sơn vừa kỷ niệm 15 năm thành lập, với 1 doanh nghiệp xây dựng thì 15 năm không phải là quá dài nhưng cũng đủ để công ty kịp ghi dấu ấn đậm nét tại các công trình trọng điểm có quy mô lớn như Sửa chữa đường Nguyễn Hữu Cảnh, TP Hồ Chí Minh; Xây dựng Cầu Rạch Rộp 1, huyện Nhà Bè; Xây dựng đường trục chính vào khu liên hợp thể dục thể thao Rạch Chiếc; Dự án đầu tư xây dựng công trình cải tạo nền, mặt đường quốc lộ 1 đoạn Phan Thiết - Đồng Nai theo hình thức Hợp đồng BOT; Nhà văn hóa sinh viên thành phố tại Đại học Quốc gia Thành phố Hồ Chí Minh, …\n\nĐáng chú ý, Đầu tư Hạ tầng Đông Sơn cùng với Vinaconex (mã: VCG), Ocean Group (mã: OGC), Văn Phú Invest (mã: VPI) là chủ đầu tư của dự án BOT Hà Nội – Bắc Giang. Đây là dự án cải tạo, nâng cấp Quốc lộ 1 đoạn Hà Nội – Bắc Giang dài 45,8 km, đi qua TP Hà Nội, tỉnh Bắc Ninh và tỉnh Bắc Giang. Dự án có điểm đầu tại nút giao với Quốc lộ 31 và điểm cuối tại trạm thu phí Phù Đổng cũ (Hà Nội), đã đưa vào sử dụng từ tháng 5/2016. Dự án này được đánh giá là một trong những dự án BOT hiệu quả nhất cả nước. Khoản đầu tư này mang lại lợi nhuận khá ổn định cho công ty, dao động từ 20 - 42 tỷ đồng mỗi năm.\n\n<b>Về tình hình kinh doanh </b>, năm 2024 được đánh giá là một năm nhiều thách thức đối với ngành xây dựng, với bối cảnh thị trường bất động sản trầm lắng, dòng vốn bế tắc, công nợ khó thu hồi, và lãi suất cho vay cao hơn so với năm 2023 khiến chi phí tài chính gia tăng. Dù vậy, công ty vẫn ghi nhận đà tăng trưởng tích cực. Doanh thu thuần cả năm đạt hơn 629 tỷ đồng, tăng hơn 57% so với năm trước. Trong đó, hơn 78% đến từ các hợp đồng xây dựng.\n\nKết quả này chủ yếu nhờ công ty đồng loạt triển khai các dự án quy mô lớn như Đường bộ mới Nam Định, Cầu vượt sông Đáy, mở rộng Quốc lộ 14B tại TP Đà Nẵng, Cầu Đồng Hội,… đồng thời ký thêm nhiều hợp đồng cung cấp hàng hóa với các đối tác mới.\n\nLợi nhuận trước thuế năm 2024 đạt hơn 57 tỷ đồng, tăng 45%; lợi nhuận sau thuế đạt hơn 53 tỷ đồng. Lợi nhuận cơ bản trên mỗi cổ phiếu (EPS) tăng từ 3.783 đồng/cổ phiếu (năm 2023) lên 5.299 đồng/cổ phiếu (năm 2024). Tính đến ngày 31/12/2024, tổng tài sản của công ty đạt hơn 695 tỷ đồng.\n\n<b>Kế hoạch năm 2025 </b>, Đông Sơn đặt mục tiêu doanh thu thuần tăng 10% lên mức 692 tỷ đồng, lợi nhuận trước thuế xấp xỉ 51 tỷ đồng. Công ty dự kiến tiếp tục triển khai 5 dự án trọng điểm gồm: mở rộng đường Hoàng Hoa Thám đến đường Cộng Hòa (TP.HCM), cải tạo Quốc lộ 14B (Đà Nẵng), xây dựng cầu Đồng Hội (Phú Yên), cầu vượt sông Đáy nối Ninh Bình và Nam Định, cùng tuyến đường bộ Nam Định – Lạc Quần – đường ven biển.\n\nNgoài ra, công ty định hướng tích cực tham gia các gói thầu xây dựng thuộc các dự án công mà Chính phủ ưu tiên phân bổ vốn, đồng thời tập trung vào các gói thầu có tính cạnh tranh cao về giá và năng lực thi công.\n\nBên cạnh việc ưu tiên phát triển lĩnh vực xây dựng, Đông Sơn cũng sẽ tăng cường tìm kiếm cơ hội đầu tư vào các dự án bất động sản khu công nghiệp (BĐS KCN), nhà ở xã hội (NƠXH),…\n\n<span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://cafef.vn/dau-tu-ha-tang-dong-son-chinh-thuc-giao-dich-tren-upcom-voi-ma-dsh-gia-chao-san-18000-dong-cp-188250421224326552.chn\">CTCP Đầu tư Hạ tầng Đông Sơn chính thức giao dịch trên UPCoM với mã chứng khoán DSH, giá chào sàn 18.000 đồng/cổ phiếu</a></span>', 333, '2025-04-22 15:10:25', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dau-tu-ha-tang-dong-son-chinh-thuc-giao-dich-tren-upcom-voi-ma-dsh-gia-chao-san-18-000-dong-cp/', 0, '2026-08-12 02:04:01', '2026-08-12 02:04:01', NULL);
INSERT INTO `pvn_news_posts` VALUES (59, 'thu-moi-hop-va-tai-lieu-hop-dai-hoi-dong-thuong-nien-nam-2025-1045', 12, 'TÀI LIỆU HỌP ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2025', NULL, '<p data-start=\"187\" data-end=\"332\">CTCP Đầu tư Hạ tầng Đông Sơn công bố bộ <strong data-start=\"227\" data-end=\"285\">Tài liệu họp Đại hội đồng cổ đông thường niên năm 2025</strong> phục vụ cổ đông nghiên cứu và tham dự Đại hội.</p>\n\n<ol>\n 	<li data-start=\"358\" data-end=\"413\">Thư mời họp Đại hội đồng cổ đông thường niên năm 2025</li>\n 	<li data-start=\"358\" data-end=\"413\">Chương trình họp Đại hội đồng cổ đông thường niên năm 2025</li>\n 	<li data-start=\"358\" data-end=\"413\">Báo cáo số 01/BC/ĐHĐCĐ/2025 của Hội đồng quản trị về công tác quản trị và kết quả hoạt động của HĐQT và từng thành viên HĐQT; phương hướng hoạt động năm 2025</li>\n 	<li data-start=\"358\" data-end=\"413\">Báo cáo số 02/BC/ĐHĐCĐ/2025 của Hội đồng quản trị về kết quả hoạt động sản xuất kinh doanh năm 2024 và kế hoạch sản xuất kinh doanh năm 2025</li>\n 	<li data-start=\"358\" data-end=\"413\">Báo cáo số 03/BC/ĐHĐCĐ/2025 của Ban Kiểm soát về kết quả kinh doanh của Công ty, kết quả hoạt động của Hội đồng quản trị, Tổng Giám đốc; báo cáo tự đánh giá kết quả hoạt động của Ban Kiểm soát và từng thành viên</li>\n 	<li data-start=\"358\" data-end=\"413\">Tờ trình số 01/TTr/ĐHĐCĐ/2025 về việc thông qua Báo cáo tài chính kiểm toán năm 2024</li>\n 	<li data-start=\"358\" data-end=\"413\">Tờ trình số 02/TTr/ĐHĐCĐ/2025 về việc phân phối lợi nhuận năm 2024</li>\n 	<li data-start=\"358\" data-end=\"413\">Tờ trình số 03/TTr/ĐHĐCĐ/2025 về quyết toán thù lao HĐQT và Ban Kiểm soát năm 2024, và đề xuất chi trả thù lao năm 2025</li>\n 	<li data-start=\"358\" data-end=\"413\">Tờ trình số 04/TTr/ĐHĐCĐ/2025 về việc lựa chọn đơn vị kiểm toán Báo cáo tài chính năm 2025</li>\n 	<li data-start=\"358\" data-end=\"413\">Dự thảo Nghị quyết Đại hội đồng cổ đông thường niên năm 2025</li>\n 	<li data-start=\"358\" data-end=\"413\">Mẫu Phiếu biểu quyết</li>\n</ol>\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/04/Tai-lieu-hop-DHDCD-2025.pdf\">Tài liệu họp ĐHĐCĐ 2025</a></span>\n<p data-start=\"1470\" data-end=\"1648\">Các tài liệu được công bố nhằm đảm bảo cổ đông có đầy đủ thông tin để xem xét, thảo luận và thực hiện quyền biểu quyết tại Đại hội theo quy định của pháp luật và Điều lệ Công ty.</p>', 334, '2025-04-25 15:06:05', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thu-moi-hop-va-tai-lieu-hop-dai-hoi-dong-thuong-nien-nam-2025/', 0, '2026-08-12 02:04:05', '2026-08-12 02:04:05', NULL);
INSERT INTO `pvn_news_posts` VALUES (60, 'thu-moi-hop-dhdcd-thuong-nien-nam-2025-1051', 12, 'THƯ MỜI HỌP ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2025', NULL, '<p data-start=\"355\" data-end=\"501\">CTCP Đầu tư Hạ tầng Đông Sơn công bố Thư mời họp Đại hội đồng cổ đông thường niên năm 2025 theo quy định của Luật Doanh nghiệp và Điều lệ Công ty.</p>\n<p data-start=\"503\" data-end=\"823\">Thư mời họp gửi tới các cổ đông có quyền tham dự Đại hội, bao gồm thông tin về thời gian, địa điểm, chương trình họp và các nội dung dự kiến trình Đại hội xem xét, thông qua. Việc tổ chức Đại hội đồng cổ đông thường niên nhằm tổng kết hoạt động năm 2024 và thông qua kế hoạch, định hướng phát triển năm 2025 của Công ty.</p>\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/04/Thu-moi-hop-DHDCD-2025.pdf\">Thư mời họp ĐHĐCĐ 2025</a></span>', 335, '2025-04-08 16:31:03', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thu-moi-hop-dhdcd-thuong-nien-nam-2025/', 0, '2026-08-12 02:04:06', '2026-08-12 02:04:06', NULL);
INSERT INTO `pvn_news_posts` VALUES (61, 'nghi-quyet-so-06-05-2025-nq-hdqt-dsh-1055', 13, 'NGHỊ QUYẾT SỐ 06.05.2025/NQ-HĐQT/DSH', NULL, '<p data-start=\"512\" data-end=\"789\">Hội đồng quản trị CTCP Đầu tư Hạ tầng Đông Sơn đã ban hành Nghị quyết số 06.05.2025/NQ-HĐQT/DSH về việc thông qua chủ trương sử dụng tài sản/quyền tài sản của Bên thứ ba để thế chấp nhằm đảm bảo cho nghĩa vụ vay vốn của Công ty tại Ngân hàng theo thỏa thuận tín dụng đã ký kết.</p>\n<p data-start=\"791\" data-end=\"1028\">Việc thông qua nội dung nêu trên được thực hiện theo đúng thẩm quyền của Hội đồng quản trị và phù hợp với quy định của pháp luật hiện hành, nhằm đảm bảo nguồn vốn phục vụ hoạt động sản xuất kinh doanh và triển khai các dự án của Công ty.</p>\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/05/03.01.2025-CBTT-NQ-HDQT.pdf\">Nghị quyết 06.05.2025/NQ-HĐQT/DSH</a></span>', 324, '2025-05-07 14:06:38', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-so-06-05-2025-nq-hdqt-dsh/', 0, '2026-08-12 02:04:06', '2026-08-12 02:04:06', NULL);
INSERT INTO `pvn_news_posts` VALUES (62, 'cong-ty-dong-son-trung-goi-thau-tuyen-duong-my-dinh-ba-sao-bai-dinh-1060', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TRÚNG THẦU DỰ ÁN TUYẾN ĐƯỜNG MỸ ĐÌNH - BA SAO - BÁI ĐÍNH', NULL, '<p data-start=\"98\" data-end=\"300\">Gói thầu thuộc Dự án thành phần 2: Đầu tư xây dựng tuyến đường Mỹ Đình – Ba Sao – Bái Đính (đoạn nối từ đường trục phía Nam đến đường Hương Sơn – Tam Chúc), đi qua địa bàn huyện Mỹ Đức và huyện Ứng Hòa.</p>\n<p data-start=\"302\" data-end=\"757\">Nhà thầu trúng thầu là Liên danh gồm: Tổng công ty Đầu tư phát triển hạ tầng đô thị UDIC – Công ty CP Đầu tư Hạ tầng Đông Sơn – Công ty CP Xây dựng và Dịch vụ kỹ thuật Việt Hưng – Công ty CP Tập đoàn Đông Đô – Công ty CP 471 – Công ty CP Sông Đà Hà Nội – Công ty CP Xây dựng Đồng Tiến – Tổng công ty Thăng Long – Công ty CP Xây dựng đô thị Hòa Phú – Công ty CP Tập đoàn Tư vấn đầu tư xây dựng Hải Lý – Công ty CP Cầu 14 – Công ty TNHH Xây dựng Thành Phát.</p>\n<p data-start=\"759\" data-end=\"878\">Giá trúng thầu là 1.338,035 tỷ đồng; thời gian thực hiện hợp đồng 690 ngày, theo hình thức hợp đồng đơn giá điều chỉnh.</p>\n<p data-start=\"880\" data-end=\"1131\" data-is-last-node=\"\" data-is-only-node=\"\">Theo kế hoạch, công trình dự kiến khởi công trong tháng 5/2025. Dự án sau khi hoàn thành sẽ góp phần tăng cường kết nối hạ tầng giao thông khu vực phía Tây và Tây Nam Hà Nội, tạo động lực thúc đẩy phát triển kinh tế – xã hội, du lịch và liên kết vùng.</p>\n<a href=\"/uploads/news/2025/05/Lien-danh-12-thanh-vien-trung-goi-thau-giao-thong-1.338-ty-tai-Ha-Noi.pdf\">Liên danh 12 thành viên trúng gói thầu giao thông 1.338 tỷ tại Hà Nội</a>', 324, '2025-05-15 11:33:38', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/cong-ty-dong-son-trung-goi-thau-tuyen-duong-my-dinh-ba-sao-bai-dinh/', 0, '2026-08-12 02:04:06', '2026-08-12 02:04:06', NULL);
INSERT INTO `pvn_news_posts` VALUES (63, 'bien-ban-nghi-quyet-dai-hoi-dong-co-dong-thuong-nien-nam-2025-1063', 12, 'BIÊN BẢN & NGHỊ QUYẾT ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2025', NULL, '<p data-start=\"381\" data-end=\"542\">CTCP Đầu tư Hạ tầng Đông Sơn công bố Biên bản họp và Nghị quyết Đại hội đồng cổ đông thường niên năm 2025 theo quy định của Luật Doanh nghiệp và Điều lệ Công ty.</p>\n<p data-start=\"544\" data-end=\"806\">Biên bản và Nghị quyết ghi nhận toàn bộ nội dung đã được Đại hội thảo luận và thông qua, bao gồm các vấn đề liên quan đến kết quả hoạt động năm 2024, kế hoạch sản xuất kinh doanh năm 2025 và các nội dung quan trọng khác thuộc thẩm quyền của Đại hội đồng cổ đông.</p>\n<p data-start=\"808\" data-end=\"929\">Việc công bố được thực hiện nhằm đảm bảo tính minh bạch và cung cấp thông tin đầy đủ, kịp thời tới cổ đông và nhà đầu tư.</p>\n<p data-start=\"808\" data-end=\"929\">Chi tiết:</p>\n<a href=\"/uploads/news/2025/05/NQ-BB-hop-DHDCD-TN-2025.pdf\"><span style=\"color: #0000ff;\">NQ, BB họp ĐHĐCĐ TN 2025</span></a>\n\n<span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/05/Tai-lieu-hop-DHDCD-TN-2025.pdf\">Tài liệu họp ĐHĐCĐ TN 2025</a></span>', 336, '2025-05-16 12:45:48', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bien-ban-nghi-quyet-dai-hoi-dong-co-dong-thuong-nien-nam-2025/', 0, '2026-08-12 02:04:12', '2026-08-12 02:04:12', NULL);
INSERT INTO `pvn_news_posts` VALUES (64, 'dau-tu-ha-tang-dong-son-len-ke-hoach-doanh-thu-2025-xap-xi-700-ty-dong-trung-goi-thau-giao-thong-nghin-ty-tai-ha-noi-1067', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN ĐẶT KẾ HOẠCH DOẠNH THU NĂM 2025 KHOẢNG 700 TỶ ĐỒNG VÀ TRÚNG GÓI THẦU GIAO THÔNG QUY MÔ NGHÌN TỶ TẠI HÀ NỘI', NULL, '<h2 class=\"sapo\" data-role=\"sapo\"><span style=\"font-size: 75%;\">Năm 2025, Đầu tư Hạ tầng Đông Sơn tiếp tục thực hiện 5 dự án đang triển khai theo đúng tiến độ cam kết với chủ đầu tư; đồng thời tăng cường tìm kiếm các cơ hội đầu tư vào các dự án bất động sản khu công nghiệp, nhà ở xã hội.</span></h2>\n<div class=\"contentdetail\">\n<div id=\"mainContent\" class=\"detail-cmain ss\">\n<div class=\"detail-content afcbc-body\" data-role=\"content\">\n<div class=\"tindnd clearfix\" data-marked-zoneid=\"cafef_detail_relatednewsbox\">\n<div id=\"listNewsInContent\" class=\"clearfix\">\n<div class=\"knswli-right\"><span style=\"font-size: 14.4px;\">Ngày 16/5/2025, </span><b style=\"color: #555555; font-size: 14.4px;\">CTCP Đầu tư Hạ tầng Đông Sơn (mã DSH) </b><span style=\"font-size: 14.4px;\">đã tổ chức thành công ĐHĐCĐ thường niên 2025. Cổ </span><span style=\"font-size: 14.4px;\">đông đã thông qua kế hoạch kinh doanh năm 2025 với mục tiêu doanh thu thuần tăng 10% lên mức 692 tỷ đồng. Lợi nhuận trước thuế xấp xỉ 51 tỷ đồng. Tỷ lệ cổ tức năm nay dự kiến đạt 20%.</span></div>\n</div>\n</div>\nTheo ban lãnh đạo công ty, kế hoạch kinh doanh được xây dựng trên cơ sở các giả định thận trọng về tình trạng hoạt động kinh doanh hiện tại, sự ảnh hưởng của các yếu tố vĩ mô về kinh tế, chính trị, xã hội và vẫn bám sát định hướng chiến lược của Công ty trong trung hạn và dài hạn.\n\n<img class=\"alignnone wp-image-1069 size-full\" src=\"/uploads/news/2025/05/Anh.jpg\" alt=\"\" width=\"1276\" height=\"956\" /> <img class=\"alignnone wp-image-1070 size-full\" src=\"/uploads/news/2025/05/Anh-2.jpg\" alt=\"\" width=\"1276\" height=\"956\" />\n\nCụ thể hơn, tại mảng hoạt động xây dựng, Đầu tư Hạ tầng Đông Sơn tiếp tục thực hiện 5 dự án đang triển khai theo đúng tiến độ cam kết với chủ đầu tư gồm Mở rộng đường Hoàng Hoa Thám đến đường Cộng Hòa, TP Hồ Chí Minh; Dự án cải tạo, nâng cấp Quốc lộ 14B, thành phố Đà Nẵng; Dự án Xây mới cầu Đồng Hội, xã Xuân Quang 1, huyện Đồng Xuân, tỉnh Phú Yên; Dự án xây dựng cầu vượt Sông Đáy nối tỉnh Ninh Bình và tỉnh Nam Định thuộc tuyến đường bộ cao tốc Ninh Bình – Nam Định – Thái Bình – Hải Phòng; Dự án xây dựng tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển. Ngoài ra, trong năm 2025, Công ty chủ trương tiếp cận, tham dự các gói thầu xây dựng dự án công được Chính phủ ưu tiên phân bổ nguồn vốn và các gói thầu Công ty có khả năng cạnh tranh cao về giá và năng lực thi công.\n\nBên cạnh việc ưu tiên phát triển lĩnh vực xây dựng, công ty cũng sẽ tăng cường tìm kiếm các cơ hội đầu tư vào các dự án bất động sản khu công nghiệp, bất động sản nhà ở xã hội,...\n<figure class=\"VCSortableInPreviewMode noCaption\">\n<div><a class=\"detail-img-lightbox\" title=\"\" href=\"https://cafefcdn.com/203337114487263232/2025/5/20/image1-1747763464230-17477634645891094520599.png\" target=\"_blank\" rel=\"noopener\" data-fancybox=\"img-lightbox\"><img class=\"lightbox-content aligncenter\" title=\"Đầu tư Hạ tầng Đông Sơn lên kế hoạch doanh thu 2025 xấp xỉ 700 tỷ đồng, trúng gói thầu giao thông nghìn tỷ tại Hà Nội- Ảnh 1.\" src=\"https://cafefcdn.com/203337114487263232/2025/5/20/image1-1747763464230-17477634645891094520599.png\" alt=\"Đầu tư Hạ tầng Đông Sơn lên kế hoạch doanh thu 2025 xấp xỉ 700 tỷ đồng, trúng gói thầu giao thông nghìn tỷ tại Hà Nội- Ảnh 1.\" width=\"936\" height=\"744\" data-original=\"https://cafefcdn.com/203337114487263232/2025/5/20/image1-1747763464230-17477634645891094520599.png\" /></a></div></figure>\nTrước đó trong năm 2024, Đầu tư Hạ tầng Đông Sơn ghi nhận đà tăng trưởng tích cực. Doanh thu thuần cả năm đạt hơn 629 tỷ đồng, tăng hơn 57% so với năm trước. Trong đó, hơn 78% đến từ các hợp đồng xây dựng. Lợi nhuận trước thuế năm 2024 đạt hơn 57 tỷ đồng, tăng 45%. Lợi nhuận cơ bản trên mỗi cổ phiếu (EPS) tăng từ 3.783 đồng/cổ phiếu (năm 2023) lên 5.299 đồng/cổ phiếu.\n<div class=\"h-show-pc\">\n<div class=\"c-banner\">\n<div class=\"c-banner-item is-custom-size\">\n<div class=\"c-banner-item__inner\">\n<div class=\"c-banner-item__box\"><span style=\"font-size: 14.4px;\">Tại thời điểm 31/12/2024, tổng tài sản của công ty đạt 695 tỷ đồng, LNST chưa phân phối đạt hơn 125 tỷ. Ngoài thi công xây lắp, DSH còn tham gia đầu tư 1 dự án giao thông theo hình thức BOT là dự án đầu tư xây dựng công trình cải tạo, nâng cấp Quốc lộ 1 đoạn Hà Nội - Bắc Giang. Dự án có tổng mức đầu tư gần 4,2 nghìn tỷ đồng, trong đó DSH góp 25% vốn, lợi nhuận từ dự án đầu tư này ổn định từ 20-42 tỷ đồng/năm, được ghi nhận là khoản lợi nhuận trong công ty liên kết.</span></div>\n</div>\n</div>\n</div>\n</div>\nVừa qua, <b>DSH đã công bố trúng gói thầu tuyến đường Mỹ Đình – Ba Sao – Bái Đính. </b>Cụ thể, Ban Quản lý dự án đầu tư xây dựng công trình giao thông TP. Hà Nội đã công bố kết quả lựa chọn nhà thầu Gói XL Thi công xây dựng và đảm bảo an toàn giao thông tuyến đường từ Km35+870 ÷ Km49+095 (bao gồm cầu vượt sông Đáy, cầu kênh Ngoại Độ, hệ thống chiếu sáng, tổ chức giao thông, đèn tín hiệu giao thông). Gói thầu thuộc Dự án thành phần 2 Đầu tư xây dựng tuyến đường Mỹ Đình - Ba Sao - Bái Đính (đoạn nối từ đường trục phía Nam đến đường Hương Sơn - Tam Chúc), huyện Mỹ Đức, huyện Ứng Hòa thuộc dự án cùng tên (tổng mức đầu tư 2.080 tỷ đồng).\n<figure class=\"VCSortableInPreviewMode\">\n<div><a class=\"detail-img-lightbox\" title=\" Bản đồ hướng tuyến 12,5 km (ảnh được vẽ theo quy hoạch chỉ mang tính tham khảo). \" href=\"https://cafefcdn.com/203337114487263232/2025/5/20/image2-1747763465548-17477634660442124155466.png\" target=\"_blank\" rel=\"noopener\" data-fancybox=\"img-lightbox\"><img class=\"lightbox-content aligncenter\" title=\"Đầu tư Hạ tầng Đông Sơn lên kế hoạch doanh thu 2025 xấp xỉ 700 tỷ đồng, trúng gói thầu giao thông nghìn tỷ tại Hà Nội- Ảnh 2.\" src=\"https://cafefcdn.com/203337114487263232/2025/5/20/image2-1747763465548-17477634660442124155466.png\" alt=\"Đầu tư Hạ tầng Đông Sơn lên kế hoạch doanh thu 2025 xấp xỉ 700 tỷ đồng, trúng gói thầu giao thông nghìn tỷ tại Hà Nội- Ảnh 2.\" width=\"936\" height=\"418\" data-original=\"https://cafefcdn.com/203337114487263232/2025/5/20/image2-1747763465548-17477634660442124155466.png\" /></a></div>\n<figcaption class=\"PhotoCMS_Caption\">\n<p class=\"\" style=\"text-align: center;\" data-placeholder=\"Nhập chú thích ảnh\">Bản đồ hướng tuyến 12,5 km (ảnh được vẽ theo quy hoạch chỉ mang tính tham khảo).</p>\n\n</figcaption></figure>\nVượt qua bước đánh giá về kỹ thuật, nhà thầu trúng thầu dự án trên là Liên danh gồm 12 thành viên gồm Tổng công ty Đầu tư phát triển hạ tầng đô thị UDIC – Công ty CP Đầu tư Hạ tầng Đông Sơn – Công ty CP xây dựng và Dịch vụ kỹ thuật Việt Hưng – Công ty CP Tập đoàn Đông Đô – Công ty CP 471 – Công ty CP Sông Đà Hà Nội – Công ty CP xây dựng Đồng Tiến – Tổng công ty Thăng Long – Công ty CP xây dựng đô thị Hòa Phú – Công ty CP Tập đoàn tư vấn đầu tư xây dựng Hải Lý – Công ty CP Cầu 14 – Công ty TNHH Xây dựng Thành Phát.\n\nGiá trúng thầu 1.338,035 tỷ đồng (giá dự toán 1.352,468 tỷ đồng); thời gian thực hiện hợp đồng 690 ngày, hợp đồng theo đơn giá điều chỉnh.\n\nĐầu tư Hạ tầng Đông Sơn được thành lập năm 2009 với tên ban đầu là CTCP Đầu tư và Thương mại 319, trên cơ sở góp vốn giữa 3 doanh nghiệp: Tổng công ty 319 – Bộ Quốc phòng, CTCP Vina Invest và CTCP Thép Châu Âu, sau khi thành lập hoạt động theo hình thức là công ty con của Tổng công ty 319. Hiện vốn điều lệ đạt 100 tỷ.\n\nNgày 22/4 vừa qua, 10 triệu cổ phiếu DSH đã chính thức giao dịch trên sàn UPCoM. Chốt phiên 20/5, thị giá DSH đạt 14.000 đồng/cp.\n\n<span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://cafef.vn/dau-tu-ha-tang-dong-son-len-ke-hoach-doanh-thu-2025-xap-xi-700-ty-dong-trung-goi-thau-giao-thong-nghin-ty-tai-ha-noi-188250521005147737.chn\">CTCP Đầu tư Hạ tầng Đông Sơn đặt kế hoạch doanh thu năm 2025 khoảng 700 tỷ đồng và trúng gói thầu giao thông quy mô nghìn tỷ tại Hà Nội</a></span>\n\n</div>\n</div>\n</div>', 337, '2025-05-21 10:16:30', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dau-tu-ha-tang-dong-son-len-ke-hoach-doanh-thu-2025-xap-xi-700-ty-dong-trung-goi-thau-giao-thong-nghin-ty-tai-ha-noi/', 0, '2026-08-12 02:04:13', '2026-08-12 02:04:13', NULL);
INSERT INTO `pvn_news_posts` VALUES (65, 'thong-bao-ngay-chot-danh-sach-tham-du-dhdcd-bat-thuong-nam-2025-1076', 12, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO NGÀY CHỐT DANH SÁCH CỔ ĐÔNG THAM DỰ ĐẠI HỘI ĐỒNG CỔ ĐÔNG BẤT THƯỜNG NĂM 2025', NULL, '<p data-start=\"413\" data-end=\"588\">CTCP Đầu tư Hạ tầng Đông Sơn thông báo về ngày chốt danh sách cổ đông có quyền tham dự Đại hội đồng cổ đông bất thường năm 2025 theo quy định của pháp luật và Điều lệ Công ty.</p>\n<p data-start=\"590\" data-end=\"874\">Danh sách cổ đông được lập căn cứ trên dữ liệu đăng ký, lưu ký cổ phiếu tại ngày chốt quyền nhằm xác định các cổ đông đủ điều kiện tham dự và thực hiện quyền biểu quyết tại Đại hội. Thông tin chi tiết về thời gian, địa điểm và nội dung Đại hội sẽ được Công ty thông báo theo quy định.</p>\nChi tiết: <a href=\"/uploads/news/2025/06/09.06.2025-CBTT-ngay-chot-danh-sach.pdf\">Danh sách cổ đông</a>\n\n&nbsp;', 338, '2025-06-09 14:59:14', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ngay-chot-danh-sach-tham-du-dhdcd-bat-thuong-nam-2025/', 0, '2026-08-12 02:04:13', '2026-08-12 02:04:13', NULL);
INSERT INTO `pvn_news_posts` VALUES (66, 'nghi-quyet-hdqt-ve-viec-ky-ket-hop-dong-voi-cong-ty-lien-ket-1085', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC KÝ KẾT HỢP ĐỒNG VỚI CÔNG TY LIÊN KẾT', NULL, '<p data-start=\"108\" data-end=\"305\">Ngày 01/07/2025, Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã họp và ban hành Nghị quyết số 01.07/2025/NQ-HĐQT/DSH về việc thông qua chủ trương ký kết hợp đồng với công ty liên kết.</p>\n<p data-start=\"307\" data-end=\"623\">Theo đó, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn và Công ty Cổ phần Đầu tư BOT Hà Nội – Bắc Giang (công ty liên kết) đã ký kết Hợp đồng thi công xây dựng công trình sửa chữa định kỳ lần 1 đường bộ thuộc Dự án đầu tư xây dựng công trình cải tạo, nâng cấp Quốc lộ 1 đoạn Hà Nội – Bắc Giang theo hình thức hợp đồng BOT.</p>\n<p data-start=\"625\" data-end=\"886\">Tổng giá trị hợp đồng là <strong data-start=\"650\" data-end=\"673\">84.522.616.012 đồng</strong> (chưa bao gồm điều chỉnh giá theo quy định của hợp đồng, nếu có). Việc ký kết hợp đồng được thực hiện theo đúng thẩm quyền của Hội đồng quản trị và quy định của pháp luật hiện hành về giao dịch với bên liên quan.</p>\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/07/Nghi-quyet-HDQT-01.07.2025.pdf\">Nghị quyết HĐQT 01.07.2025</a></span>\n\n&nbsp;', 339, '2025-07-01 11:19:05', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-ky-ket-hop-dong-voi-cong-ty-lien-ket/', 0, '2026-08-12 02:04:14', '2026-08-12 02:04:14', NULL);
INSERT INTO `pvn_news_posts` VALUES (67, 'thu-moi-hop-va-cac-tai-lieu-hop-dhdcd-bat-thuong-nam-2025-1090', 12, 'THƯ MỜI HỌP VÀ CÁC TÀI LIỆU HỌP ĐẠI HỘI ĐỒNG CỔ ĐÔNG BẤT THƯỜNG NĂM 2025', NULL, 'Công bố thông tin thời gian, địa điểm và tài liệu họp ĐHĐCĐ bất thường năm 2025 như sau:\n\n-     Thời gian tổ chức họp: 09 giờ 00 phút, Thứ Năm, ngày 24 tháng 07 năm 2025\n\n-     Địa điểm họp: Hội trường Vplace 10, tầng 3, tòa nhà 25T2-N05, KĐT Trung Hòa Nhân Chính, phố Nguyễn Thị Thập, Cầu Giấy, thành phố Hà Nội.\n\n-     Nội dung họp:\n<ul>\n 	<li>Tờ trình số 05/2025/TTr/DSH của HĐQT về việc tăng tỷ lệ sở hữu công ty liên kết;</li>\n 	<li>Tờ trình số 06/2025/TTr/DSH của HĐQT về phương án chào bán cổ phiếu ra công chúng cho cổ đông hiện hữu;</li>\n 	<li>Các nội dung khác thuộc thẩm quyền của ĐHĐCĐ (nếu có).</li>\n 	<li><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/07/Tai-lieu-DHDCD-BT-2025.pdf\">Tài liệu ĐHĐCĐ BT 2025  </a></span></li>\n 	<li><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/07/Mau-Giay-UQ-DHDCD-BT-2025.pdf\">Mau Giay UQ ĐHĐCĐ BT 2025</a></span></li>\n</ul>', 340, '2025-07-03 15:15:27', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thu-moi-hop-va-cac-tai-lieu-hop-dhdcd-bat-thuong-nam-2025/', 0, '2026-08-12 02:04:17', '2026-08-12 02:04:17', NULL);
INSERT INTO `pvn_news_posts` VALUES (68, 'bo-sung-dieu-chinh-tai-lieu-hop-dhdcd-bat-thuong-nam-2025-1095', 12, 'BỔ SUNG, ĐIỀU CHỈNH TÀI LIỆU HỌP ĐẠI HỘI ĐỒNG CỔ ĐÔNG BẤT THƯỜNG NĂM 2025', NULL, '<p style=\"text-align: left;\"><strong>Nghị quyết HĐQT về việc bổ sung, điều chỉnh tài liệu họp ĐHĐCĐ bất thường năm 2025 như sau:</strong></p>\n<p style=\"text-align: left;\">2.1 Bổ sung chương trình họp: Bổ sung Tờ trình số 07/2025/TTr/DSH về sửa đổi, bổ sung Điều lệ Công ty <em>(Tờ trình đính kèm)</em>.</p>\n<p style=\"text-align: left;\">2.2 Sửa Tờ trình số 06/2025/TTr/DSH về mục đích sử dụng vốn của đợt chào bán cổ phiếu ra công chúng cho cổ đông hiện hữu:</p>\n\n<table class=\" aligncenter\" width=\"105%\">\n<thead>\n<tr>\n<td rowspan=\"2\" width=\"11%\"><strong>Thứ tự ưu tiên (*)</strong></td>\n<td colspan=\"3\" width=\"55%\"><strong>Mục đích sử dụng vốn</strong></td>\n<td width=\"18%\"><strong>Số tiền (đồng)</strong></td>\n<td width=\"14%\"><strong>Thời gian giải ngân dự kiến</strong></td>\n</tr>\n<tr>\n<td width=\"27%\"><strong>Đã công bố</strong></td>\n<td colspan=\"2\" width=\"27%\"><strong>Điều chỉnh</strong></td>\n<td width=\"18%\"><strong> </strong></td>\n<td width=\"14%\"><strong> </strong></td>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td width=\"11%\">Ưu tiên 1</td>\n<td width=\"27%\">Mua 16.378.640 cổ phần, tương đương 33% vốn điều lệ của Công ty cổ phần Đầu tư BOT Hà Nội – Bắc Giang (<em>Mệnh giá: 10.000 đồng/cổ phần)</em> bằng hình thức mua lại cổ phần của cổ đông Công ty cổ phần Đầu tư BOT Hà Nội – Bắc Giang (**)</td>\n<td colspan=\"2\" width=\"27%\">Mua 16.378.640 cổ phần, tương đương 33% vốn điều lệ của Công ty cổ phần Đầu tư BOT Hà Nội – Bắc Giang (Mệnh giá: 10.000 đồng/cổ phần) bằng hình thức mua lại cổ phần của cổ đông Công ty cổ phần Đầu tư BOT Hà Nội – Bắc Giang (**)</td>\n<td width=\"18%\">184.750.960.000</td>\n<td width=\"14%\">Quý IV/2025 – Quý I/2026</td>\n</tr>\n<tr>\n<td width=\"11%\">Ưu tiên 2</td>\n<td width=\"27%\">Bổ sung vốn cho hoạt động mua sắm nguyên vật liệu, vật tư, thanh toán tiền nhân công, chi phí thuê máy thi công và/hoặc bù đắp thanh toán gốc, lãi vay ngân hàng của hợp đồng tín dụng phục vụ cho việc thực hiện Hợp đồng thi công xây dựng công trình:\n\n-   Dự án “Xây dựng tuyến đường bộ mới Nam Định – Lạc Quần – Đường bộ ven biển”\n\nvà/hoặc:\n\nDự án “cải tạo, nâng cấp Quốc lộ 14B thành phố Đà Nẵng).</td>\n<td colspan=\"2\" width=\"27%\">Bổ sung vốn cho hoạt động mua sắm nguyên vật liệu, vật tư, thanh toán tiền nhân công, chi phí thuê máy thi công, thanh toán công nợ cho các đối tác và/hoặc bù đắp thanh toán gốc, lãi vay ngân hàng của hợp đồng tín dụng, khế ước nhận nợ phục vụ cho các hoạt động thi công xây lắp, hoạt động sản xuất kinh doanh của Công ty.</td>\n<td width=\"18%\">65.249.040.000</td>\n<td width=\"14%\">Quý IV/2025 -  Quý I/2026</td>\n</tr>\n<tr>\n<td colspan=\"3\" width=\"39%\"><strong>Tổng cộng</strong></td>\n<td width=\"27%\"><strong> </strong></td>\n<td width=\"18%\"><strong>250.000.000.000</strong></td>\n<td width=\"14%\"></td>\n</tr>\n<tr>\n<td width=\"85\"></td>\n<td width=\"209\"></td>\n<td width=\"1\"></td>\n<td width=\"207\"></td>\n<td width=\"135\"></td>\n<td width=\"112\"></td>\n</tr>\n</tbody>\n</table>\n<p style=\"text-align: left;\"><em>(Tờ trình số 06/2025/TTr/DSH kèm theo)</em></p>\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/07/Bo-sung-tai-lieu-hop-DHDCD-BT-2025.pdf\">Bổ sung tài liệu họp ĐHĐCĐ BT 2025</a></span>', 341, '2025-07-09 14:08:14', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bo-sung-dieu-chinh-tai-lieu-hop-dhdcd-bat-thuong-nam-2025/', 0, '2026-08-12 02:04:19', '2026-08-12 02:04:19', NULL);
INSERT INTO `pvn_news_posts` VALUES (69, 'ky-hop-dong-kiem-toan-bao-cao-tai-chinh-nam-2025-1099', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO KÝ HỢP ĐỒNG KIỂM TOÁN BÁO CÁO TÀI CHÍNH NĂM 2025', NULL, '<p data-start=\"203\" data-end=\"371\">Ngày 18/07/2025, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã chính thức ký Hợp đồng kiểm toán số 1807/2025/HĐTC/IAV với Công ty TNHH Kiểm toán và Định giá Quốc Tế (IAV).</p>\n<p data-start=\"373\" data-end=\"414\">Theo nội dung hợp đồng, IAV sẽ thực hiện:</p>\n\n<ul data-start=\"416\" data-end=\"627\">\n 	<li data-start=\"416\" data-end=\"509\">\n<p data-start=\"418\" data-end=\"509\">Soát xét Báo cáo tài chính giữa niên độ cho kỳ kế toán 06 tháng kết thúc ngày 30/06/2025;</p>\n</li>\n 	<li data-start=\"510\" data-end=\"627\">\n<p data-start=\"512\" data-end=\"627\">Kiểm toán Báo cáo tài chính cho năm tài chính kết thúc ngày 31/12/2025 của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn.</p>\n</li>\n</ul>\n<p data-start=\"629\" data-end=\"1070\">Việc ký kết hợp đồng kiểm toán và soát xét Báo cáo tài chính nhằm đảm bảo các thông tin tài chính của Công ty được kiểm tra, đánh giá một cách độc lập, khách quan và tuân thủ đầy đủ các chuẩn mực kế toán, kiểm toán cũng như quy định pháp luật hiện hành. Đây là bước quan trọng trong việc nâng cao tính minh bạch, độ tin cậy của Báo cáo tài chính, đồng thời cung cấp thông tin chính xác, kịp thời tới cổ đông, nhà đầu tư và các bên liên quan.</p>\n<p data-start=\"1072\" data-end=\"1362\">Thông qua hoạt động soát xét giữa niên độ và kiểm toán cuối năm, Công ty tiếp tục khẳng định cam kết duy trì hệ thống quản trị tài chính chặt chẽ, chuyên nghiệp, phù hợp với định hướng phát triển bền vững và yêu cầu đối với doanh nghiệp đại chúng đang giao dịch trên thị trường chứng khoán.</p>\n<p data-start=\"1364\" data-end=\"1465\" data-is-last-node=\"\" data-is-only-node=\"\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng thông báo tới Quý cổ đông và nhà đầu tư được biết.</p>', 342, '2025-07-18 14:47:15', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ky-hop-dong-kiem-toan-bao-cao-tai-chinh-nam-2025/', 0, '2026-08-12 02:04:19', '2026-08-12 02:04:19', NULL);
INSERT INTO `pvn_news_posts` VALUES (70, 'thong-qua-chu-truong-ky-ket-hop-dong-giua-cong-ty-cp-dau-tu-ha-tang-dong-son-voi-tong-cong-ty-319-bo-quoc-phong-1101', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC THÔNG QUA CHỦ TRƯƠNG KÝ KẾT HỢP ĐỒNG GIỮA CÔNG TY CỔ PHẦN ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN VÀ TỔNG CÔNG TY 319 BỘ QUỐC PHÒNG', NULL, '<p data-start=\"207\" data-end=\"517\"><strong><span style=\"font-size: 110%;\">Nghị quyết Hội đồng quản trị về việc Ký kết hợp đồng với Cổ đông lớn - Tổng công ty 319 Bộ Quốc phòng</span></strong></p>\n<p data-start=\"207\" data-end=\"517\">Ngày 23/07/2025, Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã họp và ban hành Nghị quyết số 23.07/2025/NQ-HĐQT/DSH về việc thông qua chủ trương ký kết Hợp đồng với cổ đông lớn là Tổng Công ty 319 Bộ Quốc Phòng theo quy định của Luật Doanh nghiệp năm 2020 và các quy định pháp luật có liên quan.</p>\n<p data-start=\"519\" data-end=\"765\">Theo nội dung Nghị quyết, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn và Tổng Công ty 319 Bộ Quốc Phòng sẽ ký kết Hợp đồng về việc cho thuê thiết bị thi công, nhân công và cung cấp vật liệu phụ phục vụ thi công Dự án xây dựng nút giao thông Mỹ Thủy.</p>\n<p data-start=\"767\" data-end=\"948\">Giá trị hợp đồng dự kiến là 42.631.922.606 đồng (Bốn mươi hai tỷ sáu trăm ba mươi mốt triệu chín trăm hai mươi hai nghìn sáu trăm lẻ sáu đồng), chưa bao gồm điều chỉnh giá (nếu có).</p>\n<p data-start=\"950\" data-end=\"1225\" data-is-last-node=\"\" data-is-only-node=\"\">Việc ký kết hợp đồng nhằm đảm bảo nguồn lực thi công, đáp ứng tiến độ và yêu cầu kỹ thuật của dự án, đồng thời thực hiện đúng quy trình phê duyệt giao dịch với bên có liên quan theo quy định hiện hành, đảm bảo tính minh bạch và tuân thủ pháp luật trong hoạt động của Công ty.</p>\n<p data-start=\"950\" data-end=\"1225\" data-is-last-node=\"\" data-is-only-node=\"\"><strong>Chi tiết xem tại: <a href=\"/uploads/news/2025/07/000000015198609_23.07.2025_CBTT_ky_HD_voi_co_dong_lon.pdf\">Nghị quyết HĐQT</a></strong></p>', 343, '2025-07-23 10:18:27', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-qua-chu-truong-ky-ket-hop-dong-giua-cong-ty-cp-dau-tu-ha-tang-dong-son-voi-tong-cong-ty-319-bo-quoc-phong/', 0, '2026-08-12 02:04:19', '2026-08-12 02:04:19', NULL);
INSERT INTO `pvn_news_posts` VALUES (71, 'thong-bao-thay-doi-noi-dung-dang-ky-doanh-nghiep-1103', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO VỀ VIỆC THAY ĐỔI NỘI DUNG ĐĂNG KÝ DOANH NGHIỆP', NULL, 'Căn cứ theo Giấy xác nhận về việc thay đổi nội dung đăng ký doanh nghiệp số 0104291191 ngày 21/07/2025, do Sở kế hoạch và đầu tư thành phố Hà Nội cấp, chúng tôi trân trọng thông báo việc thay đổi Giấy chứng nhận đăng ký doanh nghiệp của Công ty chúng tôi như sau:\n\n- Tên tổ chức: Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn\n\n- Mã chứng khoán: DSH\n\n- Địa chỉ: Số 2, phố Nguyễn Thị Duệ, Phường Yên Hòa, TP Hà Nội\n\n- Điện thoại liên hệ: 024 3556 7799                                           Fax:\n\n- E-mail: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"mailto:hatangdongson@htds.vn\">hatangdongson@htds.vn</a></span>\n\n- Website: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/\">https://htds.vn/</a></span>\n\n<strong style=\"color: #333333; font-size: 14.4px;\"> 1. Thay đổi địa chỉ trụ sở chính</strong>\n\n<strong><em>1.1 Thông tin trước khi thay đổi</em></strong>\n\nSố 2, Phố Nguyễn Thị Duệ, Phường Yên Hòa, Quận Cầu Giấy, Thành phố Hà Nội, Việt Nam\n\n<strong><em>1.2 Thông tin sau khi thay đổi</em></strong>\n\nSố 2, Phố Nguyễn Thị Duệ, Phường Yên Hòa, Thành phố Hà Nội, Việt Nam\n\n<strong style=\"color: #333333; font-size: 14.4px;\">2. Thay đổi địa chỉ trụ sở chính</strong>\n\n2.  Lý do thay đổi: Cập nhập thay đổi theo địa giới hành chính.\n\n3. Ngày có hiệu lực: 21/07/2025\n\n4. Ngày Công ty nhận được Giấy xác nhận về việc thay đổi nội dung đăng ký doanh nghiệp từ Sở Kế hoạch &amp; Đầu tư: 23/07/2025.\n\nChi tiết:  <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/07/DKKD-lan-17.pdf\">Đăng ký doanh nghiệp lần 17</a></span>', 344, '2025-07-23 14:42:03', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-thay-doi-noi-dung-dang-ky-doanh-nghiep/', 0, '2026-08-12 02:04:20', '2026-08-12 02:04:20', NULL);
INSERT INTO `pvn_news_posts` VALUES (72, 'bien-ban-nghi-quyet-dhdcd-bat-thuong-nam-2025-1109', 12, 'BIÊN BẢN & NGHỊ QUYẾT ĐẠI HỘI ĐỒNG CỔ ĐÔNG BẤT THƯỜNG NĂM 2025', NULL, '<p data-start=\"69\" data-end=\"471\">Đại hội đồng cổ đông bất thường năm 2025 của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã được tổ chức theo đúng quy định của Luật Doanh nghiệp và Điều lệ Công ty. Đại hội đã tiến hành thảo luận và biểu quyết thông qua các nội dung thuộc thẩm quyền, bao gồm các vấn đề quan trọng liên quan đến định hướng hoạt động, kế hoạch triển khai và các quyết sách phục vụ hoạt động sản xuất kinh doanh của Công ty.</p>\n<p data-start=\"473\" data-end=\"704\" data-is-last-node=\"\" data-is-only-node=\"\">Biên bản họp và Nghị quyết Đại hội đồng cổ đông bất thường năm 2025 ghi nhận đầy đủ diễn biến, ý kiến thảo luận và kết quả biểu quyết đối với từng nội dung được trình tại Đại hội, làm cơ sở triển khai thực hiện trong thời gian tới.</p>\n<p data-start=\"473\" data-end=\"704\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/07/CV-75.pdf\">Biên bản &amp; Nghị quyết ĐHĐCĐ bất thường 2025</a></span></p>', 345, '2025-07-25 09:02:54', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bien-ban-nghi-quyet-dhdcd-bat-thuong-nam-2025/', 0, '2026-08-12 02:04:24', '2026-08-12 02:04:24', NULL);
INSERT INTO `pvn_news_posts` VALUES (73, 'dieu-le-cong-ty-sua-doi-bo-sung-nam-2025-1112', 14, 'CÔNG TY CỔ PHẦN ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN – ĐIỀU LỆ CÔNG TY SỬA ĐỔI, BỔ SUNG NĂM 2025', NULL, '<p data-start=\"92\" data-end=\"283\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"151\" data-end=\"196\">Điều lệ Công ty sửa đổi, bổ sung năm 2025</strong> đã được Đại hội đồng cổ đông thông qua theo đúng thẩm quyền và quy định của pháp luật.</p>\n<p data-start=\"285\" data-end=\"587\">Việc sửa đổi, bổ sung Điều lệ được thực hiện nhằm cập nhật các nội dung liên quan đến vốn điều lệ, cơ cấu tổ chức quản lý, quyền và nghĩa vụ của cổ đông, thẩm quyền của các cơ quan quản lý trong Công ty cũng như các nội dung khác phù hợp với tình hình hoạt động thực tế và quy định pháp luật hiện hành.</p>\n<p data-start=\"589\" data-end=\"872\">Điều lệ sửa đổi, bổ sung năm 2025 là căn cứ pháp lý quan trọng điều chỉnh toàn bộ hoạt động tổ chức và quản trị của Công ty trong giai đoạn tiếp theo, đảm bảo tính minh bạch, hiệu quả và tuân thủ quy định của Luật Doanh nghiệp, Luật Chứng khoán và các văn bản pháp luật có liên quan.</p>\n<p data-start=\"874\" data-end=\"967\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/07/Dieu-le-Cong-ty-2025-da-nen.pdf\">Điều lệ Công ty 2025</a></span></p>', 311, '2025-07-25 09:04:35', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dieu-le-cong-ty-sua-doi-bo-sung-nam-2025/', 0, '2026-08-12 02:04:27', '2026-08-12 02:04:27', NULL);
INSERT INTO `pvn_news_posts` VALUES (74, 'bao-cao-tro-thanh-co-dong-lon-vu-hoang-viet-1115', 13, 'BÁO CÁO VỀ VIỆC TRỞ THÀNH CỔ ĐÔNG LỚN – ÔNG VŨ HOÀNG VIỆT', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-6\" data-testid=\"conversation-turn-184\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"7bcac159-5df6-49f9-87df-7339bd3a8d5a\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"151\" data-end=\"282\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn nhận được báo cáo về việc trở thành cổ đông lớn của ông Vũ Hoàng Việt đối với cổ phiếu DSH.</p>\n<p data-start=\"284\" data-end=\"682\">Cụ thể:\n– Tên cá nhân thực hiện giao dịch: Vũ Hoàng Việt<br data-start=\"340\" data-end=\"343\" />– Mã chứng khoán: DSH<br data-start=\"364\" data-end=\"367\" />– Số lượng cổ phiếu nắm giữ trước khi trở thành cổ đông lớn: 0 cổ phiếu (tỷ lệ 0%)<br data-start=\"449\" data-end=\"452\" />– Số lượng cổ phiếu đã mua: 937.500 cổ phiếu<br data-start=\"496\" data-end=\"499\" />– Số lượng cổ phiếu nắm giữ sau khi thực hiện giao dịch: 937.500 cổ phiếu<br data-start=\"572\" data-end=\"575\" />– Tỷ lệ sở hữu sau khi thực hiện giao dịch: 9,375% vốn điều lệ<br data-start=\"637\" data-end=\"640\" />– Ngày trở thành cổ đông lớn: 23/07/2025</p>\n<p data-start=\"684\" data-end=\"791\" data-is-last-node=\"\" data-is-only-node=\"\">Việc công bố thông tin được thực hiện theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n\n</div>\n</div>\n</div>\n</div>\n<div class=\"z-0 flex min-h-[46px] justify-start\"></div>\n<div class=\"mt-3 w-full empty:hidden\">\n<div class=\"text-center\"></div>\n</div>\n</div>\n</div>\n</article></div>', 346, '2025-07-28 17:06:20', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tro-thanh-co-dong-lon-vu-hoang-viet/', 0, '2026-08-12 02:04:27', '2026-08-12 02:04:27', NULL);
INSERT INTO `pvn_news_posts` VALUES (75, 'bao-cao-tro-thanh-co-dong-lon-khuat-thao-linh-1117', 13, 'BÁO CÁO VỀ VIỆC TRỞ THÀNH CỔ ĐÔNG LỚN – BÀ KHUẤT THẢO LINH', NULL, '<p data-start=\"133\" data-end=\"265\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn nhận được báo cáo về việc trở thành cổ đông lớn của bà Khuất Thảo Linh đối với cổ phiếu DSH.</p>\n<p data-start=\"267\" data-end=\"672\">Cụ thể:<br data-start=\"274\" data-end=\"277\" />– Tên cá nhân thực hiện giao dịch: Khuất Thảo Linh<br data-start=\"327\" data-end=\"330\" />– Mã chứng khoán: DSH<br data-start=\"351\" data-end=\"354\" />– Số lượng cổ phiếu nắm giữ trước khi trở thành cổ đông lớn: 0 cổ phiếu (tỷ lệ 0%)<br data-start=\"436\" data-end=\"439\" />– Số lượng cổ phiếu đã mua: 1.250.000 cổ phiếu<br data-start=\"485\" data-end=\"488\" />– Số lượng cổ phiếu nắm giữ sau khi thực hiện giao dịch: 1.250.000 cổ phiếu<br data-start=\"563\" data-end=\"566\" />– Tỷ lệ sở hữu sau khi thực hiện giao dịch: 12,5% vốn điều lệ<br data-start=\"627\" data-end=\"630\" />– Ngày trở thành cổ đông lớn: 23/07/2025</p>\n<p data-start=\"674\" data-end=\"781\" data-is-last-node=\"\" data-is-only-node=\"\">Việc công bố thông tin được thực hiện theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>', 347, '2025-07-28 17:07:34', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tro-thanh-co-dong-lon-khuat-thao-linh/', 0, '2026-08-12 02:04:28', '2026-08-12 02:04:28', NULL);
INSERT INTO `pvn_news_posts` VALUES (76, 'nghi-quyet-hdqt-ve-viec-trien-khai-phuong-an-chao-ban-cho-co-phieu-cho-co-dong-hien-huu-1119', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC TRIỂN KHAI PHƯƠNG ÁN CHÀO BÁN CỔ PHIẾU CHO CỔ ĐÔNG HIỆN HỮU', NULL, '<p data-start=\"125\" data-end=\"380\">Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã ban hành Nghị quyết về việc triển khai phương án chào bán cổ phiếu cho cổ đông hiện hữu theo đúng nội dung đã được Đại hội đồng cổ đông thông qua và phù hợp với quy định của pháp luật hiện hành.</p>\n<p data-start=\"382\" data-end=\"692\" data-is-last-node=\"\" data-is-only-node=\"\">Phương án chào bán nhằm mục đích tăng vốn điều lệ, nâng cao năng lực tài chính và bổ sung nguồn vốn phục vụ hoạt động sản xuất kinh doanh, đầu tư các dự án của Công ty trong thời gian tới. Nghị quyết nêu rõ các nội dung triển khai, nguyên tắc thực hiện và phân công trách nhiệm tổ chức thực hiện theo quy định.</p>\n<p data-start=\"382\" data-end=\"692\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/07/Nghi-quyet-28.07.2025.pdf\">Nghị quyết về việc triển khai phương án chào bán cổ phiếu cho cổ đông hiện hữu</a></span></p>', 348, '2025-07-28 16:53:03', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-trien-khai-phuong-an-chao-ban-cho-co-phieu-cho-co-dong-hien-huu/', 0, '2026-08-12 02:04:28', '2026-08-12 02:04:28', NULL);
INSERT INTO `pvn_news_posts` VALUES (77, 'thong-bao-thay-doi-mau-dau-1123', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO THAY ĐỔI MẪU DẤU', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-9\" data-testid=\"conversation-turn-190\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"65b474d0-5899-4b6c-b8a1-07dd9b09e897\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"144\" data-end=\"280\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng thông báo về việc thay đổi mẫu dấu của Công ty theo quy định của pháp luật hiện hành.</p>\n<p data-start=\"282\" data-end=\"531\" data-is-last-node=\"\" data-is-only-node=\"\">Mẫu dấu mới được sử dụng kể từ ngày có hiệu lực theo quyết định của Công ty và thay thế cho mẫu dấu trước đây. Việc thay đổi mẫu dấu không làm ảnh hưởng đến quyền và nghĩa vụ của Công ty đối với các hợp đồng, giao dịch và văn bản đã ký kết trước đó.</p>\n<p data-start=\"282\" data-end=\"531\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"font-size: 14.4px; color: #0000ff;\" href=\"https://htds.vn/wp-content/uploads/2025/07/Thong-bao-mau-dau.pdf\">Thông báo thay đổi mẫu dấu</a></span></p>\n\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</article></div>', 349, '2025-07-29 16:57:15', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-thay-doi-mau-dau/', 0, '2026-08-12 02:04:59', '2026-08-12 02:04:59', NULL);
INSERT INTO `pvn_news_posts` VALUES (78, 'bao-cao-quan-tri-6-thang-dau-nam-2025-1126', 13, 'BÁO CÁO TÌNH HÌNH QUẢN TRỊ CÔNG TY 6 THÁNG ĐẦU NĂM 2025', NULL, '<p data-start=\"155\" data-end=\"328\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Báo cáo tình hình quản trị công ty 6 tháng đầu năm 2025 theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n<p data-start=\"330\" data-end=\"623\" data-is-last-node=\"\" data-is-only-node=\"\">Báo cáo cung cấp thông tin về hoạt động của Hội đồng quản trị, Ban kiểm soát và Ban điều hành; việc thực hiện các nghị quyết của Đại hội đồng cổ đông; tình hình giao dịch với cổ đông, người nội bộ và người có liên quan; cũng như việc tuân thủ các quy định về quản trị công ty trong kỳ báo cáo.</p>\n<p data-start=\"330\" data-end=\"623\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <a href=\"/uploads/news/2025/07/Bao-cao-quan-tri-Ban-cong-bo.pdf\"><span style=\"color: #0000ff;\">Báo cáo quản trị 6 tháng đầu năm 2025</span></a></p>', NULL, '2025-07-29 17:46:09', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-quan-tri-6-thang-dau-nam-2025/', 0, '2026-08-12 02:05:39', '2026-08-12 02:05:39', NULL);
INSERT INTO `pvn_news_posts` VALUES (79, 'bao-cao-quan-tri-cong-ty-6-thang-dau-nam-2025-1129', 13, 'BÁO CÁO TÌNH HÌNH QUẢN TRỊ CÔNG TY 6 THÁNG ĐẦU NĂM 2025', NULL, '<p data-start=\"129\" data-end=\"302\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Báo cáo tình hình quản trị công ty 6 tháng đầu năm 2025 theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n<p data-start=\"304\" data-end=\"574\" data-is-last-node=\"\" data-is-only-node=\"\">Báo cáo phản ánh tình hình hoạt động của Hội đồng quản trị, Ban kiểm soát, Ban điều hành; việc tuân thủ các quy định về quản trị công ty; giao dịch với cổ đông, người nội bộ và người có liên quan; cùng các nội dung quản trị khác theo quy định hiện hành trong kỳ báo cáo.</p>\n<p data-start=\"304\" data-end=\"574\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/07/BC-quan-tri-6-thang-dau-nam-2025-ban-cong-bo.pdf\">Báo cáo quản trị 6 tháng đầu năm 2025</a></span></p>', 350, '2025-07-29 14:46:30', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-quan-tri-cong-ty-6-thang-dau-nam-2025/', 0, '2026-08-12 02:05:45', '2026-08-12 02:05:45', NULL);
INSERT INTO `pvn_news_posts` VALUES (80, 'nghi-quyet-hdqt-ve-viec-thong-qua-bo-ho-so-dang-ky-chao-ban-cho-co-dong-hien-huu-de-tang-von-dieu-le-1134', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC THÔNG QUA BỘ HỒ SƠ ĐĂNG KÝ CHÀO BÁN CỔ PHIẾU CHO CỔ ĐÔNG HIỆN HỮU ĐỂ TĂNG VỐN ĐIỀU LỆ', NULL, '<p data-start=\"236\" data-end=\"486\">Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã họp và ban hành Nghị quyết về việc thông qua bộ hồ sơ đăng ký chào bán cổ phiếu cho cổ đông hiện hữu nhằm tăng vốn điều lệ của Công ty theo phương án đã được Đại hội đồng cổ đông thông qua.</p>\n<p data-start=\"488\" data-end=\"744\" data-is-last-node=\"\" data-is-only-node=\"\">Bộ hồ sơ đăng ký chào bán được xây dựng theo đúng quy định của pháp luật về chứng khoán và thị trường chứng khoán, làm cơ sở để Công ty thực hiện các thủ tục đăng ký với cơ quan quản lý nhà nước có thẩm quyền và triển khai phương án tăng vốn theo kế hoạch.</p>\n<p data-start=\"488\" data-end=\"744\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <a href=\"/uploads/news/2025/08/Nghi-quyet-01.08.2025.pdf\"><span style=\"color: #0000ff;\">Nghị quyết về việc thông qua bộ hồ sơ đăng ký chào bán cổ phiếu cho cổ đông hiện hữu</span></a></p>', 351, '2025-08-01 17:49:15', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-thong-qua-bo-ho-so-dang-ky-chao-ban-cho-co-dong-hien-huu-de-tang-von-dieu-le/', 0, '2026-08-12 02:05:45', '2026-08-12 02:05:45', NULL);
INSERT INTO `pvn_news_posts` VALUES (81, 'nghi-quyet-hdqt-thong-qua-ky-hop-dong-bao-lanh-phat-hanh-co-phieu-1137', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ THÔNG QUA VIỆC KÝ HỢP ĐỒNG BẢO LÃNH PHÁT HÀNH CỔ PHIẾU', NULL, 'Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã họp và ban hành Nghị quyết thông qua việc ký Hợp đồng bảo lãnh phát hành cổ phiếu nhằm triển khai phương án chào bán cổ phiếu theo nội dung đã được Đại hội đồng cổ đông thông qua và phù hợp với quy định của pháp luật hiện hành.\n\nViệc ký kết Hợp đồng bảo lãnh phát hành nhằm đảm bảo quá trình chào bán cổ phiếu được thực hiện đúng quy định, minh bạch và hiệu quả, đồng thời hỗ trợ Công ty trong việc huy động vốn phục vụ hoạt động sản xuất kinh doanh và đầu tư trong thời gian tới.\n\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/08/Nghi-quyet-31.07.2025.pdf\">Nghị quyết thông qua việc ký Hợp đồng bảo lãnh phát hành cổ phiếu</a></span>', 352, '2025-07-31 16:05:56', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-thong-qua-ky-hop-dong-bao-lanh-phat-hanh-co-phieu/', 0, '2026-08-12 02:05:46', '2026-08-12 02:05:46', NULL);
INSERT INTO `pvn_news_posts` VALUES (82, 'nghi-quyet-hdqt-ve-viec-ky-hop-dong-voi-ben-lien-quan-1141', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC KÝ KẾT HỢP ĐỒNG VỚI BÊN LIÊN QUAN', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-7\" data-testid=\"conversation-turn-206\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"04f45ba8-2949-4f67-b676-746fb3514776\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"230\" data-end=\"446\">Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã họp và ban hành Nghị quyết thông qua việc ký kết Hợp đồng với bên liên quan theo quy định tại Luật Doanh nghiệp 2020 và các văn bản pháp luật có liên quan.</p>\n<p data-start=\"448\" data-end=\"678\" data-is-last-node=\"\" data-is-only-node=\"\">Việc ký kết Hợp đồng được xem xét, đánh giá trên cơ sở đảm bảo nguyên tắc công khai, minh bạch, phù hợp với lợi ích của Công ty và cổ đông, đồng thời tuân thủ đầy đủ quy định về giao dịch với bên liên quan trong công ty đại chúng.</p>\n<p data-start=\"448\" data-end=\"678\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"font-size: 14.4px; color: #0000ff;\" href=\"/uploads/news/2025/08/Nghi-quyet-04.08.2025.pdf\">Nghị quyết thông qua việc ký kết Hợp đồng với bên liên quan</a></span></p>\n\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</article></div>', 353, '2025-08-04 15:41:23', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-ky-hop-dong-voi-ben-lien-quan/', 0, '2026-08-12 02:05:46', '2026-08-12 02:05:46', NULL);
INSERT INTO `pvn_news_posts` VALUES (83, 'nghi-quyet-hdqt-ve-viec-thanh-lap-chi-nhanh-so-6-1145', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC THÀNH LẬP CHI NHÁNH SỐ 6', NULL, '<p data-start=\"125\" data-end=\"387\">Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã họp và ban hành Nghị quyết thông qua việc thành lập Chi nhánh số 6 nhằm mở rộng mạng lưới hoạt động, tăng cường năng lực tổ chức thi công và triển khai các dự án theo định hướng phát triển của Công ty.</p>\n<p data-start=\"389\" data-end=\"678\" data-is-last-node=\"\" data-is-only-node=\"\">Việc thành lập Chi nhánh số 6 được thực hiện theo đúng quy định của Luật Doanh nghiệp và các quy định pháp luật có liên quan, góp phần nâng cao hiệu quả quản lý, chủ động trong điều hành hoạt động sản xuất kinh doanh và đáp ứng yêu cầu triển khai các công trình, dự án trong thời gian tới.</p>\n<p data-start=\"389\" data-end=\"678\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <a href=\"/uploads/news/2025/08/Nghi-quyet-HDQT-11.08.2025.pdf\"><span style=\"color: #0000ff;\">Nghị quyết thông qua việc thành lập Chi nhánh số 6</span></a></p>', 354, '2025-08-11 14:06:53', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-thanh-lap-chi-nhanh-so-6/', 0, '2026-08-12 02:05:47', '2026-08-12 02:05:47', NULL);
INSERT INTO `pvn_news_posts` VALUES (84, 'nghi-quyet-hdqt-thong-qua-han-muc-tin-dung-tai-vpbank-1151', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ THÔNG QUA HẠN MỨC TÍN DỤNG TẠI VPBANK', NULL, '<strong>NGHỊ </strong><strong>QUYẾT CỦA </strong><strong>HỘI ĐỒNG QUẢN TRỊ</strong>\n<h6>CÔNG TY CỔ PHẦN ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN</h6>\n<strong>QUYẾT NGHỊ</strong>\n\n<strong>Điều 1: </strong>Nhận cấp tín dụng từ Ngân hàng TMCP Việt Nam Thịnh Vượng (VPBank) dưới các hình thức sau:\n\nCho vay        Cấp bảo lãnh          Phát hành LC\n\nChiết khấu Hối phiếu đòi nợ kèm Bộ chứng từ xuất khẩu  Chiết khấu Bộ chứng từ xuất khẩu\n\nGia hạn thời hạn duy trì hạn mức cấp tín dụng 14 tháng kể từ ngày ký kết  Hợp đồng cấp hạn mức tín dụng số CLC-16516-01 ngày 24/04/2024.\n\nMục đích vay vốn/nhận cấp tín dụng:  Bổ sung VLĐ/ phát hành bảo lãnh phục vụ hoạt động thi công xây dựng công trình.\n\n<strong>Điều 2:</strong> Nhận cấp tín dụng từ Ngân hàng TMCP Việt Nam Thịnh Vượng (VPBank) dưới các hình thức sau:\n\nCho vay        Cấp bảo lãnh          Phát hành LC\n\nChiết khấu Hối phiếu đòi nợ kèm Bộ chứng từ xuất khẩu  Chiết khấu Bộ chứng từ xuất khẩu\n\nHạn mức: 180 tỷ đồng, trong đó:\n\n- Hạn mức vay vốn: 70 tỷ đồng, trong đó hạn mức vay không TSBĐ: 5 tỷ đồng\n\n- Hạn mức Bảo Lãnh: 180 tỷ đồng\n\n- Hạn mức LC: 180 tỷ đồng\n\nMục đích vay vốn/nhận cấp tín dụng: Bổ sung VLĐ/ phát hành bảo lãnh/ LC phục vụ hoạt động thi công xây dựng công trình.\n\n<strong>Điều 3</strong>: Dùng tài sản là: Quyền đòi nợ, Tiền, giấy tờ có giá do Vpbank phát hành chứng chỉ tiền gửi do VPBFC phát hành, trái phiếu do VPBankS phân phối thuộc sở hữu của công ty hoặc các thành viên góp vốn vào công ty; các tài sản là phương tiện vận tải; bất động sản của công ty hoặc cổ đông công ty để thế chấp/cầm cố bảo đảm cho nghĩa vụ trả nợ của Công ty tại VPBank.\n\n<strong>Điều</strong> <strong>4: </strong>Giao <strong>Ông Nguyễn Tiến Hưng</strong><strong>  </strong><strong>- Chức vụ: Tổng giám đốc,</strong> là người đại diện theo pháp luật của Công ty thực hiện việc trao đổi, làm việc với VPBank để nhận cấp tín dụng từ VPBank.<strong>   </strong>\n\n<strong>Điều</strong> <strong>5</strong><strong>. Hiệu lực</strong>\n\nQuyết định này có hiệu lực kể từ ngày ký.', 355, '2025-04-25 15:52:20', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-thong-qua-han-muc-tin-dung-tai-vpbank/', 0, '2026-08-12 02:05:47', '2026-08-12 02:05:47', NULL);
INSERT INTO `pvn_news_posts` VALUES (85, 'nghi-quyet-hdqt-ve-thong-qua-han-muc-tin-dung-tai-bidv-1154', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ THÔNG QUA HẠN MỨC TÍN DỤNG TẠI BIDV', NULL, '<strong>NGHỊ </strong><strong>QUYẾT CỦA </strong><strong>HỘI ĐỒNG QUẢN TRỊ</strong>\n<h6>CÔNG TY CỔ PHẦN ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN</h6>\n<h6></h6>\n<strong>QUYẾT NGHỊ</strong>\n\n<strong> </strong>\n\n<strong>Điều 1. Thông qua phương án đề nghị cấp tín dụng tại Ngân hàng TMCP Đầu tư và Phát triển Việt Nam – chi nhánh Mỹ Đình (BIDV Mỹ Đình), cụ thể:</strong>\n\n<strong><em>Hạn mức tín dụng năm 2025-2026</em></strong>\n\n- Hạn mức tín dụng: <strong>250.000.000.000 VNĐ (Hai trăm năm mươi tỷ đồng),</strong> trong đó:\n\n+ Hạn mức cho vay tối đa (bao gồm cả bảo lãnh thanh toán, mở L/C) đối với lĩnh vực xây lắp: 50.000.000.000VNĐ\n\n+ Hạn mức cho vay tối đa (bao gồm cả bảo lãnh thanh toán, mở L/C) đối với lĩnh vực thương mại: 50.000.000.000VNĐ\n\n- Hạn mức tín dụng này đã bao gồm cả số dư nợ, dư bảo lãnh theo hạn mức tại thời điểm hiện tại.\n\n- Mục đích: Bổ sung vốn lưu động, phát hành bảo lãnh, mở LC và các nghiệp vụ khác phục vụ hoạt động kinh doanh của doanh nghiệp.\n\n- Thời hạn của hạn mức: 12 tháng kể từ ngày ký hợp đồng tín dụng hạn mức.\n\n<strong>Điều 2</strong>: <strong>Thông qua việc dùng tài sản bảo đảm của công ty/bên thứ ba để đảm bảo cho nghĩa vụ của công ty tại BIDV Mỹ Đình, cụ thể:</strong>\n\n- Các tài sản bảo đảm hiện tại đang thế chấp/cầm cố/ký quỹ tại Ngân hàng;\n\n- Các tài sản bảo đảm khác theo quy định của ngân hàng.\n\n<strong>Điều</strong><strong> 3:      </strong>\n<ul>\n 	<li>Giao <strong>Ông Nguyễn Tiến Hưng</strong> <strong>- Chức vụ: Tổng giám đốc,</strong> là người đại diện theo pháp luật của Công ty, thay mặt cho Công ty thực hiện, trao đổi, đàm phán, quyết định các vấn đề liên quan đến việc nhận cấp tín dụng tại BIDV, bao gồm nhưng không giới hạn các vấn đề sau:\n<ol>\n 	<li>Các vấn đề liên quan đến lãi suất vay vốn, phí, điều kiện giải ngân, nhận nợ, kỳ hạn trả nợ, quyền và nghĩa vụ và tất cả các điều kiện, điều khoản khác có liên quan.</li>\n 	<li>Các vấn đề liên quan đến tài sản bảo đảm như quyền và nghĩa vụ của các bên, số tiền bảo đảm, phạm vi bảo đảm, thời hạn bảo đảm, trường hợp và phương thức xử lý tài sản thế chấp, phương thức giải quyết tranh chấp v.v….., thực hiện các thủ tục công chứng, đăng ký giao dịch bảo đảm.</li>\n 	<li>Ký kết Hợp đồng cho vay, Hợp đồng cấp hạn mức tín dụng, Hợp đồng, các tài liệu liên quan tới việc nhận cấp tín dụng, Hợp đồng thế chấp/cầm cố và tất cả các hợp đồng, thỏa thuận, văn bản phát sinh từ hoặc liên quan đến các Hợp đồng này với BIDV.</li>\n</ol>\n</li>\n</ul>\n3.2 Đại diện theo pháp luật của Công ty là <strong>Ông </strong><strong>Nguyễn Tiến Hưng  - Chức vụ: Tổng Giám Đốc,</strong> được ủy quyền lại cho người khác để thực hiện các công việc nêu tại mục 3.1 của Nội dung này.\n\n<strong>Điều</strong><strong> 4</strong><strong>. Hiệu lực</strong>\n\nQuyết định này có hiệu lực kể từ ngày ký.\n\nHội đồng quản trị, Ban Tổng Giám đốc và các phòng ban trong Công ty và các thành viên có liên quan chịu trách nhiệm thi hành quyết định này./.', 356, '2025-06-26 10:54:40', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-thong-qua-han-muc-tin-dung-tai-bidv/', 0, '2026-08-12 02:05:48', '2026-08-12 02:05:48', NULL);
INSERT INTO `pvn_news_posts` VALUES (86, 'bao-cao-tai-chinh-rieng-soat-xet-ban-nien-nam-2025-1157', 15, 'BÁO CÁO TÀI CHÍNH RIÊNG SOÁT XÉT BÁN NIÊN NĂM 2025', NULL, '<p data-start=\"101\" data-end=\"312\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"160\" data-end=\"214\">Báo cáo tài chính riêng soát xét bán niên năm 2025</strong> theo quy định của pháp luật về kế toán, kiểm toán và công bố thông tin đối với công ty đại chúng.</p>\n<p data-start=\"314\" data-end=\"605\">Báo cáo tài chính riêng bán niên cho kỳ kế toán 06 tháng đầu năm 2025 bao gồm: Bảng cân đối kế toán tại ngày kết thúc kỳ báo cáo, Báo cáo kết quả hoạt động kinh doanh, Báo cáo lưu chuyển tiền tệ và Bản thuyết minh Báo cáo tài chính, được lập theo các chuẩn mực kế toán và quy định hiện hành.</p>\n<p data-start=\"607\" data-end=\"754\">Báo cáo đã được đơn vị kiểm toán độc lập thực hiện soát xét theo đúng quy định, với kết luận soát xét được trình bày tại Báo cáo soát xét đính kèm.</p>\n<p data-start=\"756\" data-end=\"932\">Việc công bố Báo cáo tài chính riêng soát xét bán niên năm 2025 nhằm đảm bảo tính minh bạch, cung cấp thông tin đầy đủ và kịp thời tới cổ đông, nhà đầu tư và các bên liên quan.</p>\n<p data-start=\"934\" data-end=\"1036\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/08/Bao-cao-tai-chinh-rieng-soat-xet-ban-nien-2025-Cong-ty-Dong-Son.pdf\">Báo cáo tài chính riêng soát xét bán niên 2025</a></span></p>', 357, '2025-08-19 08:27:27', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-rieng-soat-xet-ban-nien-nam-2025/', 0, '2026-08-12 02:05:53', '2026-08-12 02:05:53', NULL);
INSERT INTO `pvn_news_posts` VALUES (87, 'bao-cao-tai-chinh-hop-nhat-soat-xet-ban-nien-nam-2025-1160', 15, 'BÁO CÁO TÀI CHÍNH HỢP NHẤT SOÁT XÉT BÁN NIÊN NĂM 2025', NULL, '<p data-start=\"104\" data-end=\"320\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"163\" data-end=\"220\">Báo cáo tài chính hợp nhất soát xét bán niên năm 2025</strong> theo quy định của pháp luật về kế toán, kiểm toán và công bố thông tin trên thị trường chứng khoán.</p>\n<p data-start=\"693\" data-end=\"862\">Báo cáo đã được đơn vị kiểm toán độc lập thực hiện soát xét theo các chuẩn mực và quy định hiện hành, với kết luận soát xét được trình bày tại Báo cáo soát xét đính kèm.</p>\n<p data-start=\"864\" data-end=\"1024\">Việc công bố thông tin nhằm đảm bảo tính minh bạch, cung cấp đầy đủ và kịp thời các thông tin tài chính quan trọng tới cổ đông, nhà đầu tư và các bên liên quan.</p>\n<p data-start=\"1026\" data-end=\"1122\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết:</p>\n\n<ul>\n 	<li data-start=\"1026\" data-end=\"1122\"><strong>Báo cáo:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/08/Bao-cao-tai-chinh-hop-nhat-soat-xet-ban-nien-2025-Cong-ty-Dong-Son.pdf\">Báo cáo tài chính hợp nhất soát xét bán niên 2025</a></span></li>\n 	<li data-start=\"1026\" data-end=\"1122\"><strong>Công văn:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/08/CV-CBTT-ban-nien-2025.pdf\">Công văn công bố thông tin bán niên 2025</a></span></li>\n</ul>', 358, '2025-08-19 08:29:01', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-hop-nhat-soat-xet-ban-nien-nam-2025/', 0, '2026-08-12 02:06:00', '2026-08-12 02:06:00', NULL);
INSERT INTO `pvn_news_posts` VALUES (88, 'thong-bao-giay-chung-nhan-dang-ky-hoat-dong-chi-nhanh-6-1165', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO GIẤY CHỨNG NHẬN ĐĂNG KÝ HOẠT ĐỘNG CHI NHÁNH SỐ 6', NULL, '<p data-start=\"122\" data-end=\"290\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng thông báo về việc Chi nhánh số 6 đã được cấp Giấy chứng nhận đăng ký hoạt động chi nhánh theo quy định của pháp luật.</p>\n<p data-start=\"292\" data-end=\"606\" data-is-last-node=\"\" data-is-only-node=\"\">Việc được cấp Giấy chứng nhận đăng ký hoạt động đánh dấu bước hoàn tất thủ tục pháp lý cần thiết để Chi nhánh số 6 chính thức đi vào hoạt động, góp phần mở rộng phạm vi triển khai dự án, nâng cao năng lực thi công và tăng cường hiệu quả tổ chức sản xuất kinh doanh của Công ty trong giai đoạn phát triển tiếp theo.</p>\n<p data-start=\"292\" data-end=\"606\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/09/DKKD-Chi-nhanh-6.pdf\">Giấy chứng nhận đăng ký hoạt động chi nhánh 6</a></span></p>', 359, '2025-09-03 16:39:04', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-giay-chung-nhan-dang-ky-hoat-dong-chi-nhanh-6/', 0, '2026-08-12 02:06:01', '2026-08-12 02:06:01', NULL);
INSERT INTO `pvn_news_posts` VALUES (89, 'nghi-quyet-hoi-dong-quan-tri-1168', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ TRIỂN KHAI PHƯƠNG ÁN VÀ THÔNG QUA HỒ SƠ ĐĂNG KÝ CHÀO BÁN CỔ PHIẾU CHO CỔ ĐÔNG HIỆN HỮU ĐỂ TĂNG VỐN ĐIỀU LỆ', NULL, '<p data-start=\"207\" data-end=\"467\">Ngày 09/09/2025, Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã họp và ban hành Nghị quyết số 09.09/2025/NQ-HĐQT/DSH về việc triển khai phương án chào bán cổ phiếu cho cổ đông hiện hữu nhằm tăng vốn điều lệ theo đúng chủ trương đã được thông qua.</p>\n<p data-start=\"469\" data-end=\"736\">Tiếp đó, ngày 10/09/2025, Hội đồng quản trị đã ban hành Nghị quyết số 10.09/2025/NQ-HĐQT/DSH về việc thông qua bộ hồ sơ đăng ký chào bán cổ phiếu cho cổ đông hiện hữu để thực hiện thủ tục đăng ký với cơ quan quản lý nhà nước có thẩm quyền theo quy định của pháp luật.</p>\n<p data-start=\"738\" data-end=\"989\" data-is-last-node=\"\" data-is-only-node=\"\">Việc triển khai phương án chào bán và hoàn thiện hồ sơ đăng ký thể hiện bước đi quan trọng trong kế hoạch tăng cường năng lực tài chính, bổ sung nguồn vốn phục vụ hoạt động sản xuất kinh doanh và các dự án đầu tư của Công ty trong giai đoạn tiếp theo.</p>\n<span style=\"font-size: 14.4px;\">Chi tiết: </span><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/09/10.09.2025-Nghi-quyet-HDQT.pdf\">Nghị quyết triển khai phương án chào bán cổ phiếu cho cổ đông hiện hữu nhằm tăng vốn điều lệ</a></span>', 324, '2025-09-10 15:33:18', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hoi-dong-quan-tri/', 0, '2026-08-12 02:06:01', '2026-08-12 02:06:01', NULL);
INSERT INTO `pvn_news_posts` VALUES (90, 'nghi-quyet-hdqt-ve-nhan-cap-tin-dung-tu-ngan-hang-1176', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC NHẬN CẤP TÍN DỤNG TỪ NGÂN HÀNG', NULL, '<p data-start=\"131\" data-end=\"362\">Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã họp và ban hành Nghị quyết thông qua việc nhận cấp tín dụng từ ngân hàng nhằm bổ sung nguồn vốn phục vụ hoạt động sản xuất kinh doanh và triển khai các dự án của Công ty.</p>\n<p data-start=\"364\" data-end=\"631\">Theo nội dung Nghị quyết, Hội đồng quản trị chấp thuận các điều khoản liên quan đến hạn mức tín dụng, mục đích sử dụng vốn, tài sản bảo đảm (nếu có) và giao Ban điều hành tổ chức thực hiện các thủ tục cần thiết theo quy định của pháp luật và thỏa thuận với ngân hàng.</p>\n<p data-start=\"633\" data-end=\"813\" data-is-last-node=\"\" data-is-only-node=\"\">Việc nhận cấp tín dụng góp phần tăng cường năng lực tài chính, đảm bảo nguồn vốn kịp thời phục vụ hoạt động thi công, đầu tư và phát triển bền vững của Công ty trong thời gian tới.</p>\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/09/CBTT-24.09.2025.pdf\">Nghị quyết nhận cấp tín dụng từ ngân hàng</a></span>', 360, '2025-09-24 16:29:33', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-nhan-cap-tin-dung-tu-ngan-hang/', 0, '2026-08-12 02:06:03', '2026-08-12 02:06:03', NULL);
INSERT INTO `pvn_news_posts` VALUES (91, 'thong-bao-ngay-dang-ky-cuoi-cung-de-thuc-hien-quyen-mua-co-phieu-chao-ban-cho-co-dong-hien-huu-1180', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO NGÀY ĐĂNG KÝ CUỐI CÙNG ĐỂ THỰC HIỆN QUYỀN MUA CỔ PHIẾU CHÀO BÁN CHO CỔ ĐÔNG HIỆN HỮU', NULL, '<p data-start=\"133\" data-end=\"320\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn thông báo về việc thông qua thời gian triển khai đợt chào bán cổ phiếu cho cổ đông hiện hữu nhằm tăng vốn điều lệ theo phương án đã được phê duyệt.</p>\n<p data-start=\"322\" data-end=\"364\">Theo đó, các mốc thời gian cụ thể như sau:</p>\n\n<ul data-start=\"366\" data-end=\"654\">\n 	<li data-start=\"366\" data-end=\"466\">\n<p data-start=\"368\" data-end=\"466\"><strong data-start=\"368\" data-end=\"394\">Ngày đăng ký cuối cùng</strong> để thực hiện quyền mua cổ phiếu của cổ đông hiện hữu: <strong data-start=\"449\" data-end=\"463\">17/10/2025</strong>.</p>\n</li>\n 	<li data-start=\"467\" data-end=\"561\">\n<p data-start=\"469\" data-end=\"561\"><strong data-start=\"469\" data-end=\"515\">Thời gian đăng ký và nộp tiền mua cổ phần:</strong> Từ ngày <strong data-start=\"524\" data-end=\"558\">24/10/2025 đến ngày 17/11/2025</strong>.</p>\n</li>\n 	<li data-start=\"562\" data-end=\"654\">\n<p data-start=\"564\" data-end=\"654\"><strong data-start=\"564\" data-end=\"610\">Thời gian chuyển nhượng quyền mua cổ phần:</strong> Từ ngày <strong data-start=\"619\" data-end=\"653\">24/10/2025 đến ngày 12/11/2025</strong>.</p>\n</li>\n</ul>\n<p data-start=\"656\" data-end=\"801\" data-is-last-node=\"\" data-is-only-node=\"\">Công ty đề nghị các cổ đông theo dõi và thực hiện quyền mua cổ phiếu theo đúng thời hạn quy định nhằm đảm bảo quyền và lợi ích hợp pháp của mình.</p>\n<p data-start=\"656\" data-end=\"801\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết:</p>\n<p data-start=\"656\" data-end=\"801\" data-is-last-node=\"\" data-is-only-node=\"\"><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/10/TB-VSD.pdf\">Thông báo ngày đăng ký cuối cùng để thực hiện quyền mua cổ phiếu</a></span></p>\n<p data-start=\"656\" data-end=\"801\" data-is-last-node=\"\" data-is-only-node=\"\"><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/10/NQ-HDQT-ve-viec-chot-danh-sach-co-dong-thuc-hien-quyen-mua.pdf\">Nghị quyết về việc chốt danh sách cổ đông thực hiện quyền mua</a></span></p>\n&nbsp;', 361, '2025-10-06 15:22:54', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ngay-dang-ky-cuoi-cung-de-thuc-hien-quyen-mua-co-phieu-chao-ban-cho-co-dong-hien-huu/', 0, '2026-08-12 02:06:04', '2026-08-12 02:06:04', NULL);
INSERT INTO `pvn_news_posts` VALUES (92, 'giay-chung-nhan-dang-ky-chao-ban-them-co-phieu-ra-cong-chung-va-ban-cao-bach-1186', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO CHÀO BÁN CỔ PHIẾU RA CÔNG CHÚNG, GIẤY CHỨNG NHẬN ĐĂNG KÝ CHÀO BÁN THÊM CỔ PHIẾU RA CÔNG CHÚNG VÀ BẢN CÁO BẠCH', NULL, '<p data-start=\"183\" data-end=\"382\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng thông báo về việc chào bán cổ phiếu ra công chúng theo Giấy chứng nhận đăng ký chào bán thêm cổ phiếu do cơ quan quản lý nhà nước có thẩm quyền cấp.</p>\n<p data-start=\"384\" data-end=\"569\">Đợt chào bán được thực hiện nhằm tăng vốn điều lệ, bổ sung nguồn lực tài chính phục vụ hoạt động sản xuất kinh doanh, đầu tư và mở rộng quy mô hoạt động của Công ty trong giai đoạn tới.</p>\n<p data-start=\"571\" data-end=\"597\">Kèm theo thông báo này là:</p>\n\n<ul data-start=\"599\" data-end=\"819\">\n 	<li data-start=\"599\" data-end=\"664\">\n<p data-start=\"601\" data-end=\"664\">Giấy chứng nhận đăng ký chào bán thêm cổ phiếu ra công chúng;</p>\n</li>\n 	<li data-start=\"665\" data-end=\"819\">\n<p data-start=\"667\" data-end=\"819\">Bản cáo bạch cung cấp đầy đủ thông tin về tình hình hoạt động, tài chính, phương án sử dụng vốn thu được từ đợt chào bán và các yếu tố rủi ro liên quan.</p>\n</li>\n</ul>\n<p data-start=\"821\" data-end=\"985\" data-is-last-node=\"\" data-is-only-node=\"\">Công ty kính đề nghị Quý cổ đông và nhà đầu tư nghiên cứu kỹ nội dung Bản cáo bạch và các tài liệu liên quan để nắm rõ thông tin trước khi đưa ra quyết định đầu tư.</p>\n<p data-start=\"821\" data-end=\"985\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết:</p>\n<p data-start=\"821\" data-end=\"985\" data-is-last-node=\"\" data-is-only-node=\"\"><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/10/Ban-thong-bao-ko-ky-so.pdf\">Thông báo chào bán cổ phiếu ra công chúng</a></span></p>\n<p data-start=\"821\" data-end=\"985\" data-is-last-node=\"\" data-is-only-node=\"\"><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/10/Giay-chung-nhan-dang-ky-chao-ban-them-CP-RCC-DSH.pdf\">Giấy chứng nhận đăng ký chào bán thêm cổ phiếu ra công chúng</a></span></p>\n<span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/10/Ban-cao-bach-phan-1.pdf\">Bản cáo bạch (phần 1)</a></span>\n\n<span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/10/Ban-cao-bach-phan-2.pdf\">Bản cáo bạch (phần 2)</a></span>', 324, '2025-10-06 16:21:57', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/giay-chung-nhan-dang-ky-chao-ban-them-co-phieu-ra-cong-chung-va-ban-cao-bach/', 0, '2026-08-12 02:06:20', '2026-08-12 02:06:20', NULL);
INSERT INTO `pvn_news_posts` VALUES (93, 'cong-bo-ban-thong-bao-phat-hanh-co-phieu-tren-3-so-bao-1196', 13, 'BẢN THÔNG BÁO PHÁT HÀNH CỔ PHIẾU TRÊN 03 SỐ BÁO', NULL, '<p data-start=\"84\" data-end=\"396\">Thực hiện theo quy định tại Khoản 5 Điều 41 Nghị định số 155/2020/NĐ-CP của Chính phủ hướng dẫn thi hành một số điều của Luật Chứng khoán, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã hoàn tất việc công bố Bản thông báo phát hành cổ phiếu ra công chúng trên 01 tờ báo điện tử trong 03 số liên tiếp, cụ thể như sau:</p>\n<p data-start=\"398\" data-end=\"575\"><strong data-start=\"398\" data-end=\"430\">Kỳ 1 – Ngày đăng 07/10/2025:</strong><br data-start=\"430\" data-end=\"433\" /><span style=\"color: #0000ff;\"><a class=\"decorated-link\" style=\"color: #0000ff;\" href=\"https://www.tinnhanhchungkhoan.vn/cong-ty-co-phan-dau-tu-ha-tang-dong-son-dsh-thong-bao-chao-ban-co-phieu-ra-cong-chung-ky-1-post377990.html\" target=\"_new\" rel=\"noopener\" data-start=\"433\" data-end=\"573\">https://www.tinnhanhchungkhoan.vn/cong-ty-co-phan-dau-tu-ha-tang-dong-son-dsh-thong-bao-chao-ban-co-phieu-ra-cong-chung-ky-1-post377990.html</a></span></p>\n<p data-start=\"577\" data-end=\"754\"><strong data-start=\"577\" data-end=\"609\">Kỳ 2 – Ngày đăng 08/10/2025:</strong><br data-start=\"609\" data-end=\"612\" /><span style=\"color: #0000ff;\"><a class=\"decorated-link\" style=\"color: #0000ff;\" href=\"https://www.tinnhanhchungkhoan.vn/cong-ty-co-phan-dau-tu-ha-tang-dong-son-dsh-thong-bao-chao-ban-co-phieu-ra-cong-chung-ky-2-post377992.html\" target=\"_new\" rel=\"noopener\" data-start=\"612\" data-end=\"752\">https://www.tinnhanhchungkhoan.vn/cong-ty-co-phan-dau-tu-ha-tang-dong-son-dsh-thong-bao-chao-ban-co-phieu-ra-cong-chung-ky-2-post377992.html</a></span></p>\n<p data-start=\"756\" data-end=\"933\"><strong data-start=\"756\" data-end=\"788\">Kỳ 3 – Ngày đăng 09/10/2025:</strong><br data-start=\"788\" data-end=\"791\" /><span style=\"color: #0000ff;\"><a class=\"decorated-link\" style=\"color: #0000ff;\" href=\"https://www.tinnhanhchungkhoan.vn/cong-ty-co-phan-dau-tu-ha-tang-dong-son-dsh-thong-bao-chao-ban-co-phieu-ra-cong-chung-ky-3-post377993.html\" target=\"_new\" rel=\"noopener\" data-start=\"791\" data-end=\"931\">https://www.tinnhanhchungkhoan.vn/cong-ty-co-phan-dau-tu-ha-tang-dong-son-dsh-thong-bao-chao-ban-co-phieu-ra-cong-chung-ky-3-post377993.html</a></span></p>\n<p data-start=\"935\" data-end=\"1086\" data-is-last-node=\"\" data-is-only-node=\"\">Việc công bố được thực hiện đầy đủ, đúng quy định pháp luật hiện hành nhằm đảm bảo tính minh bạch thông tin và quyền tiếp cận thông tin của nhà đầu tư.</p>', 362, '2025-10-09 09:35:50', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/cong-bo-ban-thong-bao-phat-hanh-co-phieu-tren-3-so-bao/', 0, '2026-08-12 02:06:20', '2026-08-12 02:06:20', NULL);
INSERT INTO `pvn_news_posts` VALUES (94, 'nghi-quyet-hdqt-ve-viec-dieu-chinh-han-muc-tin-dung-tai-ngan-hang-1199', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC ĐIỀU CHỈNH HẠN MỨC TÍN DỤNG TẠI NGÂN HÀNG', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-18\" data-testid=\"conversation-turn-228\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"69cfeb16-68bc-4f56-994c-8c0111fda6d6\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"126\" data-end=\"377\">Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã ban hành Nghị quyết về việc điều chỉnh hạn mức tín dụng tại Ngân hàng nhằm đáp ứng nhu cầu vốn phục vụ hoạt động sản xuất kinh doanh và triển khai các dự án của Công ty trong từng giai đoạn.</p>\n<p data-start=\"379\" data-end=\"637\">Việc điều chỉnh hạn mức tín dụng được thực hiện trên cơ sở đánh giá tình hình tài chính, kế hoạch dòng tiền và nhu cầu sử dụng vốn thực tế, đảm bảo tuân thủ các quy định của pháp luật, Điều lệ Công ty cũng như các thỏa thuận với tổ chức tín dụng liên quan.</p>\n<p data-start=\"639\" data-end=\"863\" data-is-last-node=\"\" data-is-only-node=\"\">Nghị quyết cũng giao Ban Điều hành tổ chức triển khai các thủ tục cần thiết, làm việc với Ngân hàng để hoàn thiện hồ sơ, ký kết các văn bản liên quan và thực hiện nghĩa vụ theo đúng nội dung được Hội đồng quản trị thông qua.</p>\n\n</div>\n</div>\n</div>\n</div>\n<div class=\"z-0 flex min-h-[46px] justify-start\">Chi tiết:<span style=\"color: #0000ff;\"> <a style=\"font-size: 14.4px; color: #0000ff;\" href=\"/uploads/news/2025/10/2025-10-17-CBTT-Nghi-quyet-HDQT.pdf\">Nghị quyết về việc điều chỉnh hạn mức tín dụng tại Ngân hàng</a></span></div>\n</div>\n</div>\n</article></div>', 363, '2025-10-17 14:47:09', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-dieu-chinh-han-muc-tin-dung-tai-ngan-hang/', 0, '2026-08-12 02:06:21', '2026-08-12 02:06:21', NULL);
INSERT INTO `pvn_news_posts` VALUES (95, 'thong-bao-ve-viec-thuc-hien-quyen-mua-va-chuyen-nhuong-quyen-mua-co-phieu-doi-voi-co-dong-chua-luu-ky-co-phieu-1202', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO VỀ VIỆC THỰC HIỆN QUYỀN MUA VÀ CHUYỂN NHƯỢNG QUYỀN MUA CỔ PHIẾU ĐỐI VỚI CỔ ĐÔNG CHƯA LƯU KÝ CỔ PHIẾU', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-19\" data-testid=\"conversation-turn-230\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"ba25895b-2ad9-4b5b-81c6-1e2eaf232544\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"158\" data-end=\"399\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng thông báo đến các cổ đông chưa thực hiện lưu ký cổ phiếu về việc thực hiện quyền mua và chuyển nhượng quyền mua cổ phiếu trong đợt chào bán cổ phiếu cho cổ đông hiện hữu để tăng vốn điều lệ.</p>\n<p data-start=\"401\" data-end=\"828\">Theo đó, cổ đông chưa lưu ký cổ phiếu có trách nhiệm thực hiện quyền mua cổ phiếu và/hoặc chuyển nhượng quyền mua trong thời hạn quy định theo phương án chào bán đã được cấp có thẩm quyền phê duyệt. Việc thực hiện quyền mua và chuyển nhượng quyền mua được thực hiện trực tiếp tại trụ sở Công ty (hoặc địa điểm do Công ty thông báo), trên cơ sở xuất trình đầy đủ giấy tờ tùy thân hợp lệ và các tài liệu liên quan theo hướng dẫn.</p>\n<p data-start=\"830\" data-end=\"1115\" data-is-last-node=\"\" data-is-only-node=\"\">Công ty đề nghị các cổ đông chưa lưu ký chủ động liên hệ để được hướng dẫn chi tiết về thủ tục, thời gian, địa điểm đăng ký thực hiện quyền, nộp tiền mua cổ phần cũng như thủ tục chuyển nhượng quyền mua (nếu có), đảm bảo quyền và lợi ích hợp pháp của mình theo đúng quy định hiện hành.</p>\n<p data-start=\"830\" data-end=\"1115\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"font-size: 14.4px; color: #0000ff;\" href=\"/uploads/news/2025/10/TB-vv-thuc-hien-quyen-mua-va-chuyen-nhuong-CKchua-luu-ky.pdf\">Thông báo thực hiện quyền mua và chuyển nhượng quyền mua cổ phiếu</a></span></p>\n\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</article></div>', 324, '2025-10-22 15:04:44', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ve-viec-thuc-hien-quyen-mua-va-chuyen-nhuong-quyen-mua-co-phieu-doi-voi-co-dong-chua-luu-ky-co-phieu/', 0, '2026-08-12 02:06:22', '2026-08-12 02:06:22', NULL);
INSERT INTO `pvn_news_posts` VALUES (96, 'nghi-quyet-hdqt-ve-viec-thong-qua-bien-phap-bao-dam-tien-vay-bao-lanh-tai-ngan-hang-1206', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC THÔNG QUA BIỆN PHÁP BẢO ĐẢM TIỀN VAY/BẢO LÃNH TẠI NGÂN HÀNG', NULL, '<p data-start=\"144\" data-end=\"463\">Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã ban hành Nghị quyết về việc thông qua chủ trương áp dụng các biện pháp bảo đảm tiền vay và/hoặc bảo lãnh tại Ngân hàng nhằm phục vụ nhu cầu cấp tín dụng, bảo lãnh và các nghĩa vụ tài chính của Công ty theo các hợp đồng tín dụng đã ký kết hoặc dự kiến ký kết.</p>\n<p data-start=\"465\" data-end=\"926\">Theo Nghị quyết, Hội đồng quản trị chấp thuận việc sử dụng tài sản, quyền tài sản hợp pháp của Công ty và/hoặc các biện pháp bảo đảm khác theo quy định của pháp luật để bảo đảm cho các khoản vay, hạn mức tín dụng, nghĩa vụ bảo lãnh tại Ngân hàng.</p>\n<p data-start=\"928\" data-end=\"1138\" data-is-last-node=\"\" data-is-only-node=\"\">Việc thông qua các biện pháp bảo đảm tiền vay/bảo lãnh nhằm bảo đảm nguồn vốn phục vụ hoạt động sản xuất kinh doanh, triển khai các dự án đầu tư và nâng cao hiệu quả sử dụng vốn của Công ty trong giai đoạn tới.</p>\n<p data-start=\"928\" data-end=\"1138\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/11/2025.11.05.-CBTT-NQ-HDQT.pdf\">Nghị quyết áp dụng các biện pháp bảo đảm tiền vay và/hoặc bảo lãnh tại Ngân hàng</a></span></p>', 364, '2025-11-05 13:07:54', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-thong-qua-bien-phap-bao-dam-tien-vay-bao-lanh-tai-ngan-hang/', 0, '2026-08-12 02:06:22', '2026-08-12 02:06:22', NULL);
INSERT INTO `pvn_news_posts` VALUES (97, 'nghi-quyet-hdqt-ve-viec-thong-qua-bien-phap-bao-dam-tien-vay-bao-lanh-tai-ngan-hang-2-1209', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC THÔNG QUA BIỆN PHÁP BẢO ĐẢM TIỀN VAY/BẢO LÃNH TẠI NGÂN HÀNG', NULL, '<p data-start=\"144\" data-end=\"463\">Hội đồng quản trị Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã ban hành Nghị quyết về việc thông qua chủ trương áp dụng các biện pháp bảo đảm tiền vay và/hoặc bảo lãnh tại Ngân hàng nhằm phục vụ nhu cầu cấp tín dụng, bảo lãnh và các nghĩa vụ tài chính của Công ty theo các hợp đồng tín dụng đã ký kết hoặc dự kiến ký kết.</p>\n<p data-start=\"465\" data-end=\"926\">Theo Nghị quyết, Hội đồng quản trị chấp thuận việc sử dụng tài sản, quyền tài sản hợp pháp của Công ty và/hoặc các biện pháp bảo đảm khác theo quy định của pháp luật để bảo đảm cho các khoản vay, hạn mức tín dụng, nghĩa vụ bảo lãnh tại Ngân hàng.</p>\n<p data-start=\"928\" data-end=\"1138\" data-is-last-node=\"\" data-is-only-node=\"\">Việc thông qua các biện pháp bảo đảm tiền vay/bảo lãnh nhằm bảo đảm nguồn vốn phục vụ hoạt động sản xuất kinh doanh, triển khai các dự án đầu tư và nâng cao hiệu quả sử dụng vốn của Công ty trong giai đoạn tới.</p>\n<p data-start=\"928\" data-end=\"1138\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/11/Nghi-quyet-HDQT-11.11.2025.pdf\">Nghị quyết áp dụng các biện pháp bảo đảm tiền vay và/hoặc bảo lãnh tại Ngân hàng</a></span></p>', 364, '2025-11-11 11:31:19', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-thong-qua-bien-phap-bao-dam-tien-vay-bao-lanh-tai-ngan-hang-2/', 0, '2026-08-12 02:06:22', '2026-08-12 02:06:22', NULL);
INSERT INTO `pvn_news_posts` VALUES (98, 'nghi-quyet-hdqt-ve-nhan-cap-han-muc-tin-dung-cua-ngan-hang-1213', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC NHẬN CẤP HẠN MỨC TÍN DỤNG CỦA NGÂN HÀNG', NULL, '<p data-start=\"278\" data-end=\"548\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Nghị quyết Hội đồng quản trị về việc thông qua chủ trương nhận cấp hạn mức tín dụng tại Ngân hàng nhằm phục vụ nhu cầu vốn cho hoạt động sản xuất kinh doanh, triển khai các dự án đầu tư và bổ sung vốn lưu động của Công ty.</p>\n<p data-start=\"550\" data-end=\"786\">Việc nhận cấp hạn mức tín dụng là một trong những giải pháp tài chính quan trọng, góp phần đảm bảo nguồn vốn ổn định, nâng cao năng lực thi công và tạo nền tảng thực hiện hiệu quả các kế hoạch kinh doanh của Công ty trong thời gian tới.</p>\n<p data-start=\"550\" data-end=\"786\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/11/20.11.2025-CBTT.pdf\">Nghị quyết thông qua chủ trương nhận cấp hạn mức tín dụng tại Ngân hàng</a></span></p>', 365, '2025-11-20 15:47:03', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-nhan-cap-han-muc-tin-dung-cua-ngan-hang/', 0, '2026-08-12 02:06:23', '2026-08-12 02:06:23', NULL);
INSERT INTO `pvn_news_posts` VALUES (99, 'thong-bao-giao-dich-quyen-mua-cua-nguoi-noi-bo-va-nguoi-co-lien-quan-cua-nguoi-noi-bo-1216', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO GIAO DỊCH QUYỀN MUA CỦA NGƯỜI NỘI BỘ VÀ NGƯỜI CÓ LIÊN QUAN CỦA NGƯỜI NỘI BỘ', NULL, 'Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố thông tin về giao dịch quyền mua cổ phiếu của người nội bộ và/hoặc người có liên quan của người nội bộ theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.\n<table style=\"width: 100%; table-layout: fixed; border-collapse: collapse;\" border=\"1\">\n<thead>\n<tr>\n<th style=\"width: 5%; text-align: center;\">STT</th>\n<th style=\"width: 20%; text-align: center;\">Họ tên người giao dịch</th>\n<th style=\"width: 20%; text-align: center;\">Chức vụ</th>\n<th style=\"width: 20%; text-align: center;\">Loại đăng ký giao dịch</th>\n<th style=\"width: 15%; text-align: center;\">Số lượng đăng ký giao dịch</th>\n<th style=\"width: 20%; text-align: center;\">Thời gian dự kiến thực hiện</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: center;\">1</td>\n<td style=\"text-align: center;\">Nguyễn Thị Minh Huệ</td>\n<td style=\"text-align: center;\">Chủ tịch HĐQT</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">2.000.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 07/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">2</td>\n<td style=\"text-align: center;\">Nguyễn Thị Minh Hoàn</td>\n<td style=\"text-align: center;\">Người có liên quan đến Chủ tịch HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">150.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 07/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">3</td>\n<td style=\"text-align: center;\">Nguyễn Trọng Hùng</td>\n<td style=\"text-align: center;\">Người có liên quan đến Chủ tịch HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">20.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 10/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">4</td>\n<td style=\"text-align: center;\">Phạm Duy</td>\n<td style=\"text-align: center;\">Người có liên quan đến Chủ tịch HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">1.000.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 10/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">5</td>\n<td style=\"text-align: center;\">Nguyễn Tiến Hưng</td>\n<td style=\"text-align: center;\">Tổng Giám đốc/Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">300.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 10/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">6</td>\n<td style=\"text-align: center;\">Nguyễn Giang Nam</td>\n<td style=\"text-align: center;\">Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">100.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 07/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">7</td>\n<td style=\"text-align: center;\">Nguyễn Thị Thu Thùy</td>\n<td style=\"text-align: center;\">Người phụ trách quản trị công ty/Người ủy quyền công bố thông tin</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">100.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 07/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">8</td>\n<td style=\"text-align: center;\">Lại Thành Nam</td>\n<td style=\"text-align: center;\">Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">10.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 07/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">9</td>\n<td style=\"text-align: center;\">Trần Minh Dũng</td>\n<td style=\"text-align: center;\">Phó Tổng giám đốc</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">50.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 07/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">10</td>\n<td style=\"text-align: center;\">Lại Cao Hạnh</td>\n<td style=\"text-align: center;\">Người có liên quan đến ông Lại Thành Nam - Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">10.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 10/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">11</td>\n<td style=\"text-align: center;\">Nguyễn Thị Hồng Thảo</td>\n<td style=\"text-align: center;\">Người có liên quan đến ông Lại Thành Nam - Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">90.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 10/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">12</td>\n<td style=\"text-align: center;\">Đậu Hiếu Thắng</td>\n<td style=\"text-align: center;\">Phó Tổng giám đốc</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">150.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 10/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">13</td>\n<td style=\"text-align: center;\">Trần Thị Thùy Dương</td>\n<td style=\"text-align: center;\">Người có liên quan đến ông Trần Minh Dũng - Phó Tổng giám đốc</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">50.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 10/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">14</td>\n<td style=\"text-align: center;\">Vũ Thị Kim Liên</td>\n<td style=\"text-align: center;\">Người có liên quan đến ông Trần Minh Dũng - Phó Tổng giám đốc</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">50.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 10/11/2025 đến ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">15</td>\n<td style=\"text-align: center;\">Lê Bích Ngọc</td>\n<td style=\"text-align: center;\">Kế toán trưởng</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">15.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 10/11/2025 đến ngày 17/11/2025</td>\n</tr>\n</tbody>\n</table>\n<p data-start=\"355\" data-end=\"809\">Theo nội dung thông báo, người nội bộ và/hoặc người có liên quan thực hiện đăng ký mua, chuyển nhượng hoặc không thực hiện quyền mua cổ phiếu phát hành thêm cho cổ đông hiện hữu trong thời gian quy định. Giao dịch quyền mua (nếu có) được thực hiện theo đúng trình tự, thủ tục và thời gian đã được Công ty công bố, đồng thời tuân thủ đầy đủ nghĩa vụ báo cáo, công bố thông tin theo quy định tại Luật Chứng khoán năm 2019 và các văn bản hướng dẫn thi hành.</p>\n<p data-start=\"811\" data-end=\"985\" data-is-last-node=\"\" data-is-only-node=\"\">Việc công bố thông tin nhằm đảm bảo tính minh bạch trong hoạt động của Công ty, bảo vệ quyền và lợi ích hợp pháp của cổ đông, nhà đầu tư và các bên liên quan trên thị trường.</p>', 366, '2025-11-07 16:10:06', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-giao-dich-quyen-mua-cua-nguoi-noi-bo-va-nguoi-co-lien-quan-cua-nguoi-noi-bo/', 0, '2026-08-12 02:06:23', '2026-08-12 02:06:23', NULL);
INSERT INTO `pvn_news_posts` VALUES (100, 'bao-cao-ket-qua-giao-dich-cua-nguoi-noi-bo-va-nguoi-co-lien-quan-cua-nguoi-noi-bo-1218', 13, 'BÁO CÁO KẾT QUẢ GIAO DỊCH CỦA NGƯỜI NỘI BỘ VÀ NGƯỜI CÓ LIÊN QUAN CỦA NGƯỜI NỘI BỘ', NULL, '<p data-start=\"129\" data-end=\"342\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Báo cáo kết quả giao dịch cổ phiếu của Người nội bộ và/hoặc Người có liên quan của Người nội bộ theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n<p data-start=\"344\" data-end=\"622\">Báo cáo nêu rõ thông tin về cá nhân/tổ chức thực hiện giao dịch; mối quan hệ với Người nội bộ; số lượng cổ phiếu đăng ký giao dịch; số lượng cổ phiếu đã thực hiện; thời gian thực hiện giao dịch; phương thức giao dịch; cùng số lượng, tỷ lệ sở hữu cổ phiếu trước và sau giao dịch.</p>\n\n<table style=\"width: 100%; table-layout: fixed; border-collapse: collapse;\" border=\"1\">\n<tbody>\n<tr>\n<th style=\"width: 5%; text-align: center;\">STT</th>\n<th style=\"width: 20%; text-align: center;\">Họ tên người giao dịch</th>\n<th style=\"width: 20%; text-align: center;\">Chức vụ</th>\n<th style=\"width: 15%; text-align: center;\">Loại giao dịch</th>\n<th style=\"width: 15%; text-align: center;\">Số lượng đăng ký giao dịch</th>\n<th style=\"width: 15%; text-align: center;\">Số lượng giao dịch</th>\n<th style=\"width: 15%; text-align: center;\">Thời gian thực hiện</th>\n</tr>\n<tr>\n<td style=\"text-align: center;\">1</td>\n<td style=\"text-align: center;\">Nguyễn Thị Minh Huệ</td>\n<td style=\"text-align: center;\">Chủ tịch HĐQT</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">2.000.000 quyền mua</td>\n<td style=\"text-align: center;\">2.000.000 quyền mua</td>\n<td style=\"text-align: center;\">Ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">2</td>\n<td style=\"text-align: center;\">Nguyễn Thị Minh Hoàn</td>\n<td style=\"text-align: center;\">Người có liên quan đến Chủ tịch HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">150.000 quyền mua</td>\n<td style=\"text-align: center;\">150.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">3</td>\n<td style=\"text-align: center;\">Nguyễn Trọng Hùng</td>\n<td style=\"text-align: center;\">Người có liên quan đến Chủ tịch HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">20.000 quyền mua</td>\n<td style=\"text-align: center;\">20.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">4</td>\n<td style=\"text-align: center;\">Phạm Duy</td>\n<td style=\"text-align: center;\">Người có liên quan đến Chủ tịch HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">1.000.000 quyền mua</td>\n<td style=\"text-align: center;\">1.000.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">5</td>\n<td style=\"text-align: center;\">Nguyễn Tiến Hưng</td>\n<td style=\"text-align: center;\">Tổng Giám đốc/Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">300.000 quyền mua</td>\n<td style=\"text-align: center;\">300.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">6</td>\n<td style=\"text-align: center;\">Nguyễn Giang Nam</td>\n<td style=\"text-align: center;\">Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">100.000 quyền mua</td>\n<td style=\"text-align: center;\">100.000 quyền mua</td>\n<td style=\"text-align: center;\">Ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">7</td>\n<td style=\"text-align: center;\">Nguyễn Thị Thu Thùy</td>\n<td style=\"text-align: center;\">Người phụ trách quản trị công ty/Người ủy quyền công bố thông tin</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">100.000 quyền mua</td>\n<td style=\"text-align: center;\">100.000 quyền mua</td>\n<td style=\"text-align: center;\">Ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">8</td>\n<td style=\"text-align: center;\">Lại Thành Nam</td>\n<td style=\"text-align: center;\">Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">10.000 quyền mua</td>\n<td style=\"text-align: center;\">10.000 quyền mua</td>\n<td style=\"text-align: center;\">Ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">9</td>\n<td style=\"text-align: center;\">Trần Minh Dũng</td>\n<td style=\"text-align: center;\">Phó Tổng Giám đốc</td>\n<td style=\"text-align: center;\">Thực hiện quyền mua</td>\n<td style=\"text-align: center;\">50.000 quyền mua</td>\n<td style=\"text-align: center;\">50.000 quyền mua</td>\n<td style=\"text-align: center;\">Ngày 17/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">10</td>\n<td style=\"text-align: center;\">Lại Cao Hạnh</td>\n<td style=\"text-align: center;\">Người có liên quan đến ông Lại Thành Nam - Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">10.000 quyền mua</td>\n<td style=\"text-align: center;\">10.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">11</td>\n<td style=\"text-align: center;\">Nguyễn Thị Hồng Thảo</td>\n<td style=\"text-align: center;\">Người có liên quan đến ông Lại Thành Nam - Thành viên HĐQT</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">90.000 quyền mua</td>\n<td style=\"text-align: center;\">90.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">12</td>\n<td style=\"text-align: center;\">Đậu Hiếu Thắng</td>\n<td style=\"text-align: center;\">Phó Tổng Giám đốc</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">150.000 quyền mua</td>\n<td style=\"text-align: center;\">150.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">13</td>\n<td style=\"text-align: center;\">Trần Thị Thùy Dương</td>\n<td style=\"text-align: center;\">Người có liên quan đến ông Trần Minh Dũng - Phó Tổng Giám đốc</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">50.000 quyền mua</td>\n<td style=\"text-align: center;\">50.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">14</td>\n<td style=\"text-align: center;\">Vũ Thị Kim Liên</td>\n<td style=\"text-align: center;\">Người có liên quan đến ông Trần Minh Dũng - Phó Tổng Giám đốc</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">50.000 quyền mua</td>\n<td style=\"text-align: center;\">50.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n<tr>\n<td style=\"text-align: center;\">15</td>\n<td style=\"text-align: center;\">Lê Bích Ngọc</td>\n<td style=\"text-align: center;\">Kế toán trưởng</td>\n<td style=\"text-align: center;\">Chuyển nhượng quyền mua</td>\n<td style=\"text-align: center;\">15.000 quyền mua</td>\n<td style=\"text-align: center;\">15.000 quyền mua</td>\n<td style=\"text-align: center;\">Từ ngày 11/11/2025 đến ngày 12/11/2025</td>\n</tr>\n</tbody>\n</table>\nViệc công bố thông tin được thực hiện nhằm đảm bảo tính minh bạch, kịp thời và tuân thủ đúng quy định tại Luật Chứng khoán, Nghị định số 155/2020/NĐ-CP và các văn bản hướng dẫn liên quan, đồng thời tạo điều kiện để cổ đông và nhà đầu tư nắm bắt đầy đủ thông tin về biến động sở hữu của Người nội bộ và Người có liên quan.', 367, '2025-11-18 16:19:30', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-ket-qua-giao-dich-cua-nguoi-noi-bo-va-nguoi-co-lien-quan-cua-nguoi-noi-bo/', 0, '2026-08-12 02:06:24', '2026-08-12 02:06:24', NULL);
INSERT INTO `pvn_news_posts` VALUES (101, 'nghi-quyet-hdqt-ve-viec-thong-qua-ket-qua-chao-ban-co-phieu-cho-co-dong-hien-huu-va-phuong-an-phan-phoi-co-phieu-chua-chao-ban-het-1220', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC THÔNG QUA KẾT QUẢ CHÀO BÁN CỔ PHIẾU CHO CỔ ĐÔNG HIỆN HỮU & PHƯƠNG ÁN PHÂN PHỐI CỔ PHIẾU CHƯA CHÀO BÁN HẾT', NULL, '<p data-start=\"194\" data-end=\"390\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Nghị quyết Hội đồng quản trị về việc thông qua kết quả chào bán cổ phiếu cho cổ đông hiện hữu theo phương án đã được Đại hội đồng cổ đông thông qua.</p>\n<p data-start=\"392\" data-end=\"691\">Đồng thời, Hội đồng quản trị cũng thông qua phương án xử lý, phân phối số lượng cổ phiếu chưa chào bán hết (nếu có) theo đúng quy định của pháp luật và phương án phát hành đã được phê duyệt, nhằm đảm bảo quyền lợi của cổ đông và tuân thủ các quy định hiện hành về chào bán chứng khoán ra công chúng.</p>\n<p data-start=\"693\" data-end=\"881\" data-is-last-node=\"\" data-is-only-node=\"\">Việc hoàn tất đợt chào bán cổ phiếu góp phần tăng vốn điều lệ, củng cố năng lực tài chính và tạo nguồn lực để Công ty triển khai các kế hoạch sản xuất kinh doanh trong giai đoạn tiếp theo</p>\n<p data-start=\"693\" data-end=\"881\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/11/26-11-2025-CBTT.pdf\">Kết quả chào bán cổ phiếu &amp; phương án phân phối cổ phiếu chưa chào bán hết</a></span></p>', 324, '2025-11-26 17:16:24', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-thong-qua-ket-qua-chao-ban-co-phieu-cho-co-dong-hien-huu-va-phuong-an-phan-phoi-co-phieu-chua-chao-ban-het/', 0, '2026-08-12 02:06:24', '2026-08-12 02:06:24', NULL);
INSERT INTO `pvn_news_posts` VALUES (102, 'thong-bao-thay-doi-so-luong-co-phieu-luu-hanh-va-bao-cao-ket-qua-chao-ban-co-phieu-ra-cong-chung-1227', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO THAY ĐỔI SỐ LƯỢNG CỔ PHIẾU LƯU HÀNH VÀ BÁO CÁO KẾT QUẢ CHÀO BÁN CỔ PHIẾU RA CÔNG CHÚNG', NULL, '<p data-start=\"147\" data-end=\"383\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Thông báo thay đổi số lượng cổ phiếu lưu hành sau khi hoàn tất đợt chào bán cổ phiếu ra công chúng theo phương án đã được Đại hội đồng cổ đông thông qua và được cơ quan quản lý chấp thuận.</p>\n<p data-start=\"385\" data-end=\"684\">Theo đó, tổng số cổ phiếu lưu hành của Công ty được điều chỉnh tương ứng với số lượng cổ phiếu đã phát hành thành công trong đợt chào bán. Đồng thời, Công ty thực hiện báo cáo kết quả chào bán cổ phiếu ra công chúng theo đúng quy định của pháp luật chứng khoán và các văn bản hướng dẫn có liên quan.</p>\n<p data-start=\"686\" data-end=\"937\" data-is-last-node=\"\" data-is-only-node=\"\">Việc hoàn tất đợt chào bán và thay đổi số lượng cổ phiếu lưu hành là cơ sở để Công ty tăng vốn điều lệ, nâng cao năng lực tài chính, tạo nền tảng vững chắc cho việc triển khai các kế hoạch sản xuất kinh doanh và dự án đầu tư trong giai đoạn tiếp theo.</p>\n<p data-start=\"686\" data-end=\"937\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/11/TB-thay-doi-so-luong-co-phieu-dang-luu-hanh-full.pdf\">Thông báo thay đổi số lượng cổ phiếu lưu hành sau khi hoàn tất đợt chào bán cổ phiếu ra công chúng</a></span></p>', 368, '2025-11-27 16:52:53', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-thay-doi-so-luong-co-phieu-luu-hanh-va-bao-cao-ket-qua-chao-ban-co-phieu-ra-cong-chung/', 0, '2026-08-12 02:06:25', '2026-08-12 02:06:25', NULL);
INSERT INTO `pvn_news_posts` VALUES (103, 'nghi-quyet-hdqt-ve-viec-thong-qua-ket-qua-dot-chao-ban-co-phieu-ra-cong-chung-cho-co-dong-hien-huu-nam-2025-1230', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC THÔNG QUA KẾT QUẢ ĐỢT CHÀO BÁN CỔ PHIẾU RA CÔNG CHÚNG CHO CỔ ĐÔNG HIỆN HỮU NĂM 2025', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-6\" data-testid=\"conversation-turn-250\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"cdb9d9e0-2aae-43ca-9def-9d61d6e37685\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"171\" data-end=\"458\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Nghị quyết Hội đồng quản trị về việc thông qua kết quả đợt chào bán cổ phiếu ra công chúng cho cổ đông hiện hữu năm 2025 theo phương án đã được Đại hội đồng cổ đông phê duyệt và hồ sơ đăng ký chào bán được cơ quan có thẩm quyền chấp thuận.</p>\n<p data-start=\"460\" data-end=\"783\">Nghị quyết ghi nhận kết quả thực hiện đợt chào bán, tổng số cổ phiếu đã phân phối, số tiền thu được từ đợt phát hành và các nội dung liên quan theo quy định. Trên cơ sở đó, Công ty thực hiện các thủ tục tiếp theo như báo cáo kết quả phát hành, đăng ký thay đổi vốn điều lệ và cập nhật thông tin theo quy định của pháp luật.</p>\n<p data-start=\"785\" data-end=\"976\" data-is-last-node=\"\" data-is-only-node=\"\">Việc hoàn tất đợt chào bán cổ phiếu góp phần tăng cường năng lực tài chính, bổ sung nguồn vốn cho hoạt động sản xuất kinh doanh và triển khai các dự án đầu tư của Công ty trong thời gian tới.</p>\n<p data-start=\"785\" data-end=\"976\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"font-size: 14.4px; color: #0000ff;\" href=\"/uploads/news/2025/11/Nghi-quyet-HDQT-ve-ket-qua-chao-ban.pdf\">Nghị quyết thông qua kết quả đợt chào bán cổ phiếu ra công chúng cho cổ đông hiện hữu năm 2025</a></span></p>\n\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</article></div>', 369, '2025-11-27 15:50:32', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-thong-qua-ket-qua-dot-chao-ban-co-phieu-ra-cong-chung-cho-co-dong-hien-huu-nam-2025/', 0, '2026-08-12 02:06:26', '2026-08-12 02:06:26', NULL);
INSERT INTO `pvn_news_posts` VALUES (104, 'ky-hop-dong-kiem-toan-bao-cao-von-gop-cua-chu-so-huu-1233', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN KÝ HỢP ĐỒNG KIỂM TOÁN BÁO CÁO VỐN GÓP CỦA CHỦ SỞ HỮU', NULL, '<p data-start=\"101\" data-end=\"341\"><strong>Ngày 28/11/2025, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã ký Hợp đồng kiểm toán số 2811/2025/HĐTC/IAV với Công ty TNHH Kiểm toán và Định giá Quốc Tế (IAV) về việc thực hiện kiểm toán Báo cáo vốn góp của chủ sở hữu theo quy định hiện hành.</strong></p>\n<p data-start=\"343\" data-end=\"708\">Việc ký kết hợp đồng kiểm toán được triển khai nhằm đảm bảo tính chính xác, trung thực và minh bạch của thông tin liên quan đến phần vốn góp của chủ sở hữu trong Công ty. Đây là bước thực hiện cần thiết trong quá trình hoàn thiện hồ sơ tài chính, đáp ứng yêu cầu quản trị doanh nghiệp, cũng như đảm bảo tuân thủ các quy định của pháp luật đối với công ty đại chúng.</p>\n<p data-start=\"710\" data-end=\"1052\">Thông qua hoạt động kiểm toán độc lập, các số liệu liên quan đến vốn góp sẽ được rà soát, đối chiếu và xác nhận theo chuẩn mực kiểm toán và quy định pháp lý hiện hành. Điều này góp phần nâng cao mức độ tin cậy của thông tin tài chính, tăng cường sự minh bạch trong công tác quản trị và củng cố niềm tin của cổ đông, nhà đầu tư và các đối tác.</p>\n<p data-start=\"1054\" data-end=\"1419\">Công ty TNHH Kiểm toán và Định giá Quốc Tế (IAV) là đơn vị có kinh nghiệm trong lĩnh vực kiểm toán và tư vấn tài chính cho nhiều doanh nghiệp niêm yết, đăng ký giao dịch và công ty đại chúng. Việc lựa chọn đơn vị kiểm toán độc lập phù hợp thể hiện sự chủ động và nghiêm túc của Công ty trong việc đảm bảo chất lượng báo cáo tài chính và tuân thủ quy định pháp luật.</p>\n<p data-start=\"1421\" data-end=\"1690\">Trong bối cảnh Công ty đang từng bước nâng cao năng lực quản trị và mở rộng quy mô hoạt động, việc hoàn thiện, kiểm toán đầy đủ các báo cáo liên quan đến vốn chủ sở hữu có ý nghĩa quan trọng, tạo nền tảng vững chắc cho các kế hoạch phát triển trong giai đoạn tiếp theo.</p>\n<p data-start=\"1692\" data-end=\"1950\" data-is-last-node=\"\" data-is-only-node=\"\">Việc ký kết Hợp đồng kiểm toán Báo cáo vốn góp của chủ sở hữu tiếp tục khẳng định cam kết của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trong việc minh bạch hóa thông tin, nâng cao chuẩn mực quản trị và đảm bảo quyền lợi chính đáng của cổ đông, nhà đầu tư.</p>', 370, '2025-11-28 13:10:35', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ky-hop-dong-kiem-toan-bao-cao-von-gop-cua-chu-so-huu/', 0, '2026-08-12 02:06:26', '2026-08-12 02:06:26', NULL);
INSERT INTO `pvn_news_posts` VALUES (105, 'nghi-quyet-hdqt-ve-thay-doi-von-dieu-le-1235', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC THAY ĐỔI VỐN ĐIỀU LỆ', NULL, '<p data-start=\"108\" data-end=\"279\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Nghị quyết Hội đồng quản trị về việc thay đổi vốn điều lệ của Công ty sau khi hoàn tất các thủ tục liên quan theo quy định.</p>\n<p data-start=\"281\" data-end=\"482\">Việc điều chỉnh vốn điều lệ được thực hiện trên cơ sở kết quả phát hành cổ phiếu đã được cơ quan quản lý chấp thuận và ghi nhận, đồng thời phù hợp với phương án đã được Đại hội đồng cổ đông thông qua.</p>\n<p data-start=\"484\" data-end=\"682\">Thay đổi vốn điều lệ là bước quan trọng nhằm củng cố năng lực tài chính, nâng cao quy mô hoạt động và tạo nền tảng vững chắc cho việc triển khai các kế hoạch sản xuất kinh doanh trong thời gian tới.</p>\n<p data-start=\"684\" data-end=\"724\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/12/NQ-vv-Thong-qua-viec-thay-doi-VDL.pdf\">Nghị quyết thay đổi vốn điều lệ của Công ty</a></span></p>', 371, '2025-12-01 17:02:17', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-thay-doi-von-dieu-le/', 0, '2026-08-12 02:06:26', '2026-08-12 02:06:26', NULL);
INSERT INTO `pvn_news_posts` VALUES (106, 'cong-van-xac-nhan-bao-cao-ket-qua-phat-hanh-cua-ubck-1238', 13, 'CÔNG VĂN XÁC NHẬN BÁO CÁO KẾT QUẢ PHÁT HÀNH CỦA ỦY BAN CHỨNG KHOÁN NHÀ NƯỚC', NULL, '<p data-start=\"286\" data-end=\"497\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố Công văn của Ủy ban Chứng khoán Nhà nước về việc xác nhận đã nhận được đầy đủ Báo cáo kết quả chào bán cổ phiếu ra công chúng của Công ty theo quy định.</p>\n<p data-start=\"499\" data-end=\"689\">Văn bản xác nhận của cơ quan quản lý là cơ sở pháp lý ghi nhận việc Công ty đã hoàn tất nghĩa vụ báo cáo sau đợt phát hành, đảm bảo tuân thủ các quy định của pháp luật chứng khoán hiện hành.</p>\n<p data-start=\"499\" data-end=\"689\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/12/Cong-van-chap-thuan-cua-UBCK.pdf\">Công văn của Ủy ban Chứng khoán Nhà nước</a></span></p>', 372, '2025-12-01 15:45:57', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/cong-van-xac-nhan-bao-cao-ket-qua-phat-hanh-cua-ubck/', 0, '2026-08-12 02:06:28', '2026-08-12 02:06:28', NULL);
INSERT INTO `pvn_news_posts` VALUES (107, 'dieu-chinh-so-luong-co-phieu-dang-ky-1242', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO ĐIỀU CHỈNH SỐ LƯỢNG CỔ PHIẾU ĐĂNG KÝ', NULL, '<p data-start=\"106\" data-end=\"328\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn thông báo về việc điều chỉnh thông tin số lượng cổ phiếu đăng ký tại Tổng Công ty Lưu ký và Bù trừ Chứng khoán Việt Nam (VSDC) kể từ ngày 11/12/2025, với các nội dung cụ thể như sau:</p>\n\n<ul data-start=\"330\" data-end=\"759\">\n 	<li data-start=\"330\" data-end=\"403\">\n<p data-start=\"332\" data-end=\"403\"><strong data-start=\"332\" data-end=\"352\">Tên chứng khoán:</strong> Cổ phiếu Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</p>\n</li>\n 	<li data-start=\"404\" data-end=\"448\">\n<p data-start=\"406\" data-end=\"448\"><strong data-start=\"406\" data-end=\"427\">Loại chứng khoán:</strong> Cổ phiếu phổ thông</p>\n</li>\n 	<li data-start=\"449\" data-end=\"476\">\n<p data-start=\"451\" data-end=\"476\"><strong data-start=\"451\" data-end=\"470\">Mã chứng khoán:</strong> DSH</p>\n</li>\n 	<li data-start=\"477\" data-end=\"506\">\n<p data-start=\"479\" data-end=\"506\"><strong data-start=\"479\" data-end=\"491\">Mã ISIN:</strong> VN000000DSH5</p>\n</li>\n 	<li data-start=\"507\" data-end=\"569\">\n<p data-start=\"509\" data-end=\"569\"><strong data-start=\"509\" data-end=\"547\">Số lượng cổ phiếu điều chỉnh tăng:</strong> 25.000.000 cổ phiếu</p>\n</li>\n 	<li data-start=\"570\" data-end=\"639\">\n<p data-start=\"572\" data-end=\"639\"><strong data-start=\"572\" data-end=\"617\">Số lượng cổ phiếu đăng ký sau điều chỉnh:</strong> 35.000.000 cổ phiếu</p>\n</li>\n 	<li data-start=\"640\" data-end=\"673\">\n<p data-start=\"642\" data-end=\"673\"><strong data-start=\"642\" data-end=\"664\">Hình thức đăng ký:</strong> Ghi sổ</p>\n</li>\n 	<li data-start=\"674\" data-end=\"759\">\n<p data-start=\"676\" data-end=\"759\"><strong data-start=\"676\" data-end=\"702\">Lý do điều chỉnh tăng:</strong> Phát hành cổ phiếu theo quyền mua của cổ đông hiện hữu</p>\n</li>\n</ul>\n<p data-start=\"761\" data-end=\"1031\" data-is-last-node=\"\" data-is-only-node=\"\">Việc điều chỉnh số lượng cổ phiếu đăng ký tại VSDC được thực hiện trên cơ sở kết quả hoàn tất đợt chào bán cổ phiếu cho cổ đông hiện hữu, đảm bảo phù hợp với số lượng cổ phiếu thực tế phát hành và tuân thủ quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\nChi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/12/DK-bo-sung-co-phieu.pdf\">Điều chỉnh thông tin số lượng cổ phiếu đăng ký</a></span>', 373, '2025-12-12 15:29:24', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/dieu-chinh-so-luong-co-phieu-dang-ky/', 0, '2026-08-12 02:06:28', '2026-08-12 02:06:28', NULL);
INSERT INTO `pvn_news_posts` VALUES (108, 'thong-bao-thay-doi-giay-chung-dang-ky-doanh-nghiep-1247', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO THAY ĐỔI GIẤY CHỨNG NHẬN ĐĂNG KÝ DOANH NGHIỆP', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-17\" data-testid=\"conversation-turn-272\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"01b774b6-8868-4a87-a4e6-b0ee9a844ab6\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"119\" data-end=\"372\">Căn cứ Giấy chứng nhận đăng ký doanh nghiệp số <strong data-start=\"166\" data-end=\"180\">0104291191</strong>, thay đổi lần thứ 18 ngày 18/12/2025 do Sở Tài chính Thành phố Hà Nội cấp, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng thông báo về việc thay đổi nội dung đăng ký doanh nghiệp như sau:</p>\n\n<h3 data-start=\"374\" data-end=\"403\">1. Thông tin doanh nghiệp</h3>\n<ul data-start=\"405\" data-end=\"675\">\n 	<li data-start=\"405\" data-end=\"465\">\n<p data-start=\"407\" data-end=\"465\"><strong data-start=\"407\" data-end=\"423\">Tên tổ chức:</strong> Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</p>\n</li>\n 	<li data-start=\"466\" data-end=\"493\">\n<p data-start=\"468\" data-end=\"493\"><strong data-start=\"468\" data-end=\"487\">Mã chứng khoán:</strong> DSH</p>\n</li>\n 	<li data-start=\"494\" data-end=\"569\">\n<p data-start=\"496\" data-end=\"569\"><strong data-start=\"496\" data-end=\"515\">Địa chỉ trụ sở:</strong> Số 2, phố Nguyễn Thị Duệ, Phường Yên Hòa, TP Hà Nội</p>\n</li>\n 	<li data-start=\"570\" data-end=\"603\">\n<p data-start=\"572\" data-end=\"603\"><strong data-start=\"572\" data-end=\"587\">Điện thoại:</strong> 024 3556 7799</p>\n</li>\n 	<li data-start=\"604\" data-end=\"641\">\n<p data-start=\"606\" data-end=\"641\"><strong data-start=\"606\" data-end=\"617\">E-mail:</strong> <span style=\"color: #0000ff;\"><a class=\"decorated-link cursor-pointer\" style=\"color: #0000ff;\" rel=\"noopener\" data-start=\"618\" data-end=\"639\">hatangdongson@htds.vn</a></span></p>\n</li>\n 	<li data-start=\"642\" data-end=\"675\">\n<p data-start=\"644\" data-end=\"675\"><strong data-start=\"644\" data-end=\"656\">Website:</strong> <span style=\"color: #0000ff;\"><a class=\"decorated-link\" style=\"color: #0000ff;\" href=\"https://htds.vn/\" target=\"_new\" rel=\"noopener\" data-start=\"657\" data-end=\"673\">https://htds.vn/</a></span></p>\n</li>\n</ul>\n<h3 data-start=\"682\" data-end=\"720\">2. Nội dung thay đổi – Vốn điều lệ</h3>\n<h4 data-start=\"722\" data-end=\"760\">2.1. Thông tin trước khi thay đổi</h4>\n<ul data-start=\"762\" data-end=\"926\">\n 	<li data-start=\"762\" data-end=\"836\">\n<p data-start=\"764\" data-end=\"836\"><strong data-start=\"764\" data-end=\"780\">Vốn điều lệ:</strong> 100.000.000.000 đồng<br data-start=\"801\" data-end=\"804\" />(Bằng chữ: Một trăm tỷ đồng)</p>\n</li>\n 	<li data-start=\"837\" data-end=\"882\">\n<p data-start=\"839\" data-end=\"882\"><strong data-start=\"839\" data-end=\"860\">Mệnh giá cổ phần:</strong> 10.000 đồng/cổ phần</p>\n</li>\n 	<li data-start=\"883\" data-end=\"926\">\n<p data-start=\"885\" data-end=\"926\"><strong data-start=\"885\" data-end=\"905\">Tổng số cổ phần:</strong> 10.000.000 cổ phần</p>\n</li>\n</ul>\n<h4 data-start=\"928\" data-end=\"964\">2.2. Thông tin sau khi thay đổi</h4>\n<ul data-start=\"966\" data-end=\"1138\">\n 	<li data-start=\"966\" data-end=\"1048\">\n<p data-start=\"968\" data-end=\"1048\"><strong data-start=\"968\" data-end=\"984\">Vốn điều lệ:</strong> 350.000.000.000 đồng<br data-start=\"1005\" data-end=\"1008\" />(Bằng chữ: Ba trăm năm mươi tỷ đồng)</p>\n</li>\n 	<li data-start=\"1049\" data-end=\"1094\">\n<p data-start=\"1051\" data-end=\"1094\"><strong data-start=\"1051\" data-end=\"1072\">Mệnh giá cổ phần:</strong> 10.000 đồng/cổ phần</p>\n</li>\n 	<li data-start=\"1095\" data-end=\"1138\">\n<p data-start=\"1097\" data-end=\"1138\"><strong data-start=\"1097\" data-end=\"1117\">Tổng số cổ phần:</strong> 35.000.000 cổ phần</p>\n</li>\n</ul>\n<p data-start=\"1140\" data-end=\"1341\"><strong data-start=\"1140\" data-end=\"1159\">Lý do thay đổi:</strong> Tăng vốn điều lệ do hoàn tất đợt chào bán cổ phiếu cho cổ đông hiện hữu theo phương án đã được Đại hội đồng cổ đông thông qua tại Nghị quyết số 02/2025/NQ/ĐHĐCĐ/DSH ngày 24/07/2025.</p>\n<p data-start=\"1343\" data-end=\"1471\"><strong data-start=\"1343\" data-end=\"1364\">Ngày có hiệu lực:</strong> 18/12/2025.<br data-start=\"1376\" data-end=\"1379\" /><strong data-start=\"1379\" data-end=\"1459\">Ngày Công ty nhận được Giấy xác nhận thay đổi nội dung đăng ký doanh nghiệp:</strong> 18/12/2025.</p>\n<p data-start=\"1473\" data-end=\"1691\" data-is-last-node=\"\" data-is-only-node=\"\">Việc thay đổi vốn điều lệ được thực hiện theo đúng quy định của pháp luật, phù hợp với kết quả chào bán cổ phiếu và là cơ sở để Công ty nâng cao năng lực tài chính, đáp ứng yêu cầu phát triển trong giai đoạn tiếp theo.</p>\n\n</div>\n</div>\n</div>\n</div>\n<div class=\"z-0 flex min-h-[46px] justify-start\"></div>\n<div class=\"mt-3 w-full empty:hidden\">\n<div class=\"text-center\"></div>\n</div>\n</div>\n</div>\n</article></div>\n<div class=\"pointer-events-none h-px w-px absolute bottom-0\" aria-hidden=\"true\" data-edge=\"true\"></div>', 374, '2025-12-19 10:08:24', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-thay-doi-giay-chung-dang-ky-doanh-nghiep/', 0, '2026-08-12 02:06:28', '2026-08-12 02:06:28', NULL);
INSERT INTO `pvn_news_posts` VALUES (109, 'phu-luc-dieu-le-va-bao-cao-kiem-toan-von-dieu-le-1251', 13, 'PHỤ LỤC ĐIỀU LỆ VÀ BÁO CÁO KIỂM TOÁN VỐN ĐIỀU LỆ', NULL, '<p data-start=\"99\" data-end=\"319\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố <strong data-start=\"147\" data-end=\"166\">Phụ lục Điều lệ</strong> và <strong data-start=\"170\" data-end=\"203\">Báo cáo kiểm toán vốn điều lệ</strong> sau khi hoàn tất đợt chào bán cổ phiếu cho cổ đông hiện hữu và thực hiện điều chỉnh tăng vốn điều lệ theo quy định.</p>\n<p data-start=\"321\" data-end=\"575\">Phụ lục Điều lệ được ban hành nhằm cập nhật các nội dung thay đổi liên quan đến vốn điều lệ, số lượng cổ phần và các thông tin có liên quan, đảm bảo Điều lệ Công ty phù hợp với tình hình thực tế và Giấy chứng nhận đăng ký doanh nghiệp đã được điều chỉnh.</p>\n<p data-start=\"577\" data-end=\"803\">Báo cáo kiểm toán vốn điều lệ được lập bởi đơn vị kiểm toán độc lập, xác nhận số vốn thực góp của chủ sở hữu sau đợt phát hành, làm cơ sở hoàn tất các thủ tục pháp lý theo quy định của pháp luật về doanh nghiệp và chứng khoán.</p>\n<p data-start=\"805\" data-end=\"856\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/12/CBTT-19.12.2025-da-gop.pdf\">Phụ lục Điều lệ và Báo cáo kiểm toán vốn điều lệ</a></span></p>', 375, '2025-12-19 16:32:07', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/phu-luc-dieu-le-va-bao-cao-kiem-toan-von-dieu-le/', 0, '2026-08-12 02:06:31', '2026-08-12 02:06:31', NULL);
INSERT INTO `pvn_news_posts` VALUES (110, 'ky-hop-dong-kiem-toan-bao-cao-su-dung-von-1254', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN KÝ HỢP ĐỒNG KIỂM TOÁN TÌNH HÌNH SỬ DỤNG VỐN TỪ ĐỢT CHÀO BÁN CỔ PHIẾU', NULL, '<p data-start=\"117\" data-end=\"369\">Ngày 23/12/2025, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã ký Hợp đồng kiểm toán số 2312/2025/HĐTC/IAV với Công ty TNHH Kiểm toán và Định giá Quốc Tế (IAV) về việc kiểm toán tình hình sử dụng vốn thu được từ đợt chào bán cổ phiếu cho cổ đông hiện hữu.</p>\n<p data-start=\"371\" data-end=\"649\">Theo nội dung hợp đồng, IAV sẽ thực hiện kiểm toán và xác nhận việc quản lý, phân bổ và sử dụng nguồn vốn huy động từ đợt phát hành cổ phiếu, đảm bảo phù hợp với phương án đã được Đại hội đồng cổ đông thông qua cũng như các quy định của pháp luật về chứng khoán và doanh nghiệp.</p>\n<p data-start=\"651\" data-end=\"914\">Việc ký kết hợp đồng kiểm toán thể hiện cam kết của Đông Sơn trong việc minh bạch hóa thông tin tài chính, nâng cao trách nhiệm giải trình với cổ đông và nhà đầu tư, đồng thời đảm bảo nguồn vốn huy động được sử dụng đúng mục đích, hiệu quả và đúng lộ trình đề ra.</p>\n<p data-start=\"916\" data-end=\"1161\" data-is-last-node=\"\" data-is-only-node=\"\">Kết quả kiểm toán sẽ là cơ sở quan trọng để Công ty thực hiện nghĩa vụ công bố thông tin theo quy định, đồng thời củng cố niềm tin của thị trường đối với năng lực quản trị và chiến lược phát triển bền vững của Đông Sơn trong giai đoạn tiếp theo.</p>', 376, '2025-12-23 09:18:21', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ky-hop-dong-kiem-toan-bao-cao-su-dung-von/', 0, '2026-08-12 02:06:31', '2026-08-12 02:06:31', NULL);
INSERT INTO `pvn_news_posts` VALUES (111, 'cong-ty-cp-dau-tu-bot-ha-noi-bac-giang-tro-thanh-cong-ty-con-1256', 13, 'CÔNG TY CỔ PHẦN ĐẦU TƯ BOT HÀ NỘI – BẮC GIANG TRỞ THÀNH CÔNG TY CON CỦA CÔNG TY CỔ PHẦN ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN', NULL, '<p data-start=\"89\" data-end=\"374\">Căn cứ Nghị quyết Đại hội đồng cổ đông ngày 24/07/2025 của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn (“DSH”), ngày 24/12/2025, DSH đã hoàn tất việc nhận chuyển nhượng 16.378.640 cổ phần tại Công ty Cổ phần Đầu tư BOT Hà Nội – Bắc Giang từ Công ty Cổ phần Phát triển Bất động sản Văn Phú.</p>\n<p data-start=\"376\" data-end=\"657\">Sau giao dịch, Đông Sơn sở hữu tổng cộng 28.786.700 cổ phần, tương đương 58% vốn điều lệ của Công ty Cổ phần Đầu tư BOT Hà Nội – Bắc Giang. Với tỷ lệ sở hữu chi phối này, kể từ ngày 24/12/2025, Công ty Cổ phần Đầu tư BOT Hà Nội – Bắc Giang chính thức trở thành công ty con của DSH.</p>\n<p data-start=\"659\" data-end=\"1071\" data-is-last-node=\"\" data-is-only-node=\"\">Việc nâng tỷ lệ sở hữu và đưa BOT Hà Nội – Bắc Giang trở thành công ty con là bước đi quan trọng trong chiến lược mở rộng quy mô hoạt động và tăng cường năng lực triển khai các dự án hạ tầng giao thông của Đông Sơn. Đồng thời, giao dịch này góp phần củng cố vị thế của Công ty trong lĩnh vực đầu tư, xây dựng và khai thác các dự án theo hình thức BOT, tạo nền tảng cho sự phát triển bền vững trong thời gian tới.</p>', 377, '2025-12-24 17:11:36', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/cong-ty-cp-dau-tu-bot-ha-noi-bac-giang-tro-thanh-cong-ty-con/', 0, '2026-08-12 02:06:31', '2026-08-12 02:06:31', NULL);
INSERT INTO `pvn_news_posts` VALUES (112, 'chap-thuan-dang-ky-giao-dich-bo-sung-co-phieu-dsh-tai-hnx-1258', 13, 'CHẤP THUẬN ĐĂNG KÝ GIAO DỊCH BỔ SUNG CỔ PHIẾU DSH TẠI HNX', NULL, '<p data-start=\"108\" data-end=\"267\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố thông tin về việc được Sở Giao dịch Chứng khoán Hà Nội (HNX) chấp thuận đăng ký giao dịch bổ sung cổ phiếu DSH.</p>\n<p data-start=\"269\" data-end=\"510\">Việc đăng ký giao dịch bổ sung được thực hiện trên cơ sở số lượng cổ phiếu đã phát hành thành công trong đợt chào bán cổ phiếu ra công chúng theo phương án đã được Đại hội đồng cổ đông thông qua và hoàn tất các thủ tục pháp lý theo quy định.</p>\n<p data-start=\"512\" data-end=\"751\">Sau khi được HNX chấp thuận, toàn bộ số cổ phiếu phát hành thêm sẽ được đưa vào giao dịch trên hệ thống UPCoM, đảm bảo quyền lợi và tính thanh khoản cho cổ đông, đồng thời phản ánh đầy đủ quy mô vốn điều lệ mới của Công ty trên thị trường.</p>\n<p data-start=\"753\" data-end=\"876\" data-is-last-node=\"\" data-is-only-node=\"\">Thông tin chi tiết về số lượng cổ phiếu đăng ký giao dịch bổ sung và ngày hiệu lực được nêu tại văn bản chấp thuận của HNX.</p>\n<p data-start=\"753\" data-end=\"876\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <a href=\"/uploads/news/2025/12/1491-QD-SGDHN.pdf\"><span style=\"color: #0000ff;\">Chấp thuận đăng ký giao dịch bổ sung cổ phiếu DSH</span></a></p>', 378, '2025-12-26 14:32:29', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/chap-thuan-dang-ky-giao-dich-bo-sung-co-phieu-dsh-tai-hnx/', 0, '2026-08-12 02:06:32', '2026-08-12 02:06:32', NULL);
INSERT INTO `pvn_news_posts` VALUES (113, 'nghi-quyet-hdqt-ve-co-cau-cac-khoan-dau-tu-va-chu-truong-ky-ket-thuc-hien-giao-dich-voi-cong-ty-con-cong-ty-lien-ket-nguoi-co-lien-quan-1261', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ CƠ CẤU CÁC KHOẢN ĐẦU TƯ VÀ CHỦ TRƯƠNG KÝ KẾT, THỰC HIỆN GIAO DỊCH VỚI CÔNG TY CON, CÔNG TY LIÊN KẾT, NGƯỜI CÓ LIÊN QUAN', NULL, '<p data-start=\"160\" data-end=\"465\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Nghị quyết Hội đồng quản trị về việc thông qua cơ cấu các khoản đầu tư của Công ty và chủ trương ký kết, thực hiện các hợp đồng, giao dịch với công ty con, công ty liên kết và người có liên quan theo quy định của Luật Doanh nghiệp và pháp luật có liên quan.</p>\n<p data-start=\"467\" data-end=\"899\">Theo đó, Hội đồng quản trị xem xét, đánh giá lại danh mục đầu tư hiện hữu nhằm tối ưu hóa hiệu quả sử dụng vốn, phù hợp với định hướng phát triển và chiến lược dài hạn của Công ty. Đồng thời, Hội đồng quản trị thống nhất chủ trương triển khai các hợp đồng, giao dịch phát sinh với các đơn vị có liên quan trên nguyên tắc công khai, minh bạch, đảm bảo tuân thủ đầy đủ quy định pháp luật và bảo vệ quyền, lợi ích hợp pháp của cổ đông.</p>\n<p data-start=\"901\" data-end=\"1168\">Việc cơ cấu các khoản đầu tư và chủ trương thực hiện giao dịch với các bên liên quan là bước đi nhằm nâng cao hiệu quả quản trị, tăng cường tính liên kết trong hệ sinh thái doanh nghiệp và tạo nền tảng cho sự phát triển bền vững của Công ty trong giai đoạn tiếp theo.</p>\n<p data-start=\"1170\" data-end=\"1235\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/12/Nghi-quyet-HDQT.pdf\">Nghị quyết Hội đồng quản trị</a></span></p>', 324, '2025-12-26 16:04:29', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-co-cau-cac-khoan-dau-tu-va-chu-truong-ky-ket-thuc-hien-giao-dich-voi-cong-ty-con-cong-ty-lien-ket-nguoi-co-lien-quan/', 0, '2026-08-12 02:06:32', '2026-08-12 02:06:32', NULL);
INSERT INTO `pvn_news_posts` VALUES (114, 'bao-cao-tien-do-su-dung-von-thu-duoc-tu-dot-chao-ban-cho-co-dong-hien-huu-1265', 13, 'BÁO CÁO TIẾN ĐỘ SỬ DỤNG VỐN THU ĐƯỢC TỪ ĐỢT CHÀO BÁN CHO CỔ ĐÔNG HIỆN HỮU', NULL, '<p data-start=\"124\" data-end=\"344\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Báo cáo tiến độ sử dụng vốn thu được từ đợt chào bán cổ phiếu cho cổ đông hiện hữu theo phương án đã được Đại hội đồng cổ đông thông qua và được cơ quan quản lý chấp thuận.</p>\n<p data-start=\"346\" data-end=\"684\">Báo cáo phản ánh tình hình phân bổ và sử dụng nguồn vốn huy động theo từng mục đích cụ thể, bao gồm bổ sung vốn lưu động, thanh toán các khoản nợ vay, đầu tư dự án và các nội dung khác theo đúng phương án phát hành. Đồng thời, báo cáo cập nhật tiến độ giải ngân, số dư vốn chưa sử dụng (nếu có) và kế hoạch triển khai trong thời gian tới.</p>\n<p data-start=\"686\" data-end=\"957\">Việc công bố báo cáo tiến độ sử dụng vốn nhằm đảm bảo tính minh bạch, nâng cao trách nhiệm giải trình của Công ty đối với cổ đông và nhà đầu tư, đồng thời khẳng định cam kết sử dụng nguồn vốn huy động đúng mục đích, hiệu quả và phù hợp với chiến lược phát triển đã đề ra.</p>\n<p data-start=\"959\" data-end=\"1018\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/12/BC-tien-do-su-dung-von.pdf\">Báo cáo tiến độ sử dụng vốn thu được từ đợt chào bán cổ phiếu cho cổ đông hiện hữu</a></span></p>', 379, '2025-12-29 15:01:45', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tien-do-su-dung-von-thu-duoc-tu-dot-chao-ban-cho-co-dong-hien-huu/', 0, '2026-08-12 02:06:33', '2026-08-12 02:06:33', NULL);
INSERT INTO `pvn_news_posts` VALUES (115, 'nghi-quyet-hdqt-ve-viec-thong-qua-bien-phap-bao-dam-tien-vay-bao-lanh-tai-ngan-hang-3-1268', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC THÔNG QUA BIỆN PHÁP BẢO ĐẢM TIỀN VAY/BẢO LÃNH TẠI NGÂN HÀNG', NULL, '<p data-start=\"105\" data-end=\"345\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Nghị quyết Hội đồng quản trị về việc thông qua biện pháp bảo đảm tiền vay/bảo lãnh tại Ngân hàng nhằm phục vụ nhu cầu vốn cho hoạt động sản xuất kinh doanh và triển khai các dự án của Công ty.</p>\n<p data-start=\"347\" data-end=\"714\">Theo đó, Hội đồng quản trị thống nhất chủ trương thực hiện các biện pháp bảo đảm cần thiết theo thỏa thuận với Ngân hàng, phù hợp với quy định của pháp luật và điều lệ Công ty. Việc triển khai các biện pháp bảo đảm là một phần trong giải pháp tài chính tổng thể, góp phần tăng cường năng lực tín dụng, đảm bảo nguồn vốn ổn định và linh hoạt cho hoạt động của Công ty.</p>\n<p data-start=\"716\" data-end=\"781\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/12/Nghi-quyet-HDQT-ngay-29.12.2025.pdf\">Nghị quyết thông qua biện pháp bảo đảm tiền vay/bảo lãnh tại Ngân hàng</a></span></p>', 364, '2025-12-29 16:57:47', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hdqt-ve-viec-thong-qua-bien-phap-bao-dam-tien-vay-bao-lanh-tai-ngan-hang-3/', 0, '2026-08-12 02:06:33', '2026-08-12 02:06:33', NULL);
INSERT INTO `pvn_news_posts` VALUES (116, 'bao-cao-tinh-hinh-sua-dung-von-cho-dot-tang-von-bang-hinh-thuc-chao-ban-co-phieu-ra-cong-chung-cho-co-dong-hien-huu-nam-2025-da-duoc-kiem-toan-1271', 13, 'BÁO CÁO TÌNH HÌNH SỬ DỤNG VỐN CHO ĐỢT TĂNG VỐN BẰNG HÌNH THỨC CHÀO BÁN CỔ PHIẾU RA CÔNG CHÚNG CHO CỔ ĐÔNG HIỆN HỮU NĂM 2025 (ĐÃ ĐƯỢC KIỂM TOÁN)', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-1\" data-testid=\"conversation-turn-292\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"6e41934a-fb45-4591-bcd1-52eca5bf8fc3\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"102\" data-end=\"435\">Ban Tổng Giám đốc Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trình bày Báo cáo của Ban Tổng Giám đốc cùng với Báo cáo tình hình sử dụng vốn cho đợt tăng vốn bằng hình thức chào bán cổ phiếu ra công chúng cho cổ đông hiện hữu năm 2025 cho giai đoạn từ ngày 28/11/2025 đến ngày 23/12/2025 và Bản thuyết minh Báo cáo tình hình sử dụng vốn.</p>\n<p data-start=\"437\" data-end=\"847\">Báo cáo phản ánh tình hình tiếp nhận, quản lý và sử dụng nguồn vốn thu được từ đợt chào bán cổ phiếu theo đúng phương án đã được Đại hội đồng cổ đông thông qua và phù hợp với quy định của pháp luật về chứng khoán.</p>\n<p data-start=\"849\" data-end=\"1116\">Bản thuyết minh Báo cáo tình hình sử dụng vốn cung cấp các thông tin chi tiết liên quan đến căn cứ pháp lý, nguyên tắc ghi nhận, phương thức quản lý và kiểm soát dòng tiền, cũng như các giải trình cần thiết nhằm đảm bảo tính minh bạch và đầy đủ của thông tin công bố.</p>\n<p data-start=\"1118\" data-end=\"1363\">Việc công bố Báo cáo và Bản thuyết minh thể hiện trách nhiệm của Ban Tổng Giám đốc trong việc quản lý, sử dụng hiệu quả nguồn vốn huy động, đồng thời tạo cơ sở để cổ đông và nhà đầu tư theo dõi, giám sát việc thực hiện các cam kết của Công ty.</p>\n<p data-start=\"1365\" data-end=\"1424\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <a style=\"color: #0000ff;\" href=\"/uploads/news/2025/12/Bao-cao-tinh-hinh-su-dung-von-cho-dot-tang-von-N2025.pdf\">Báo cáo tình hình sử dụng vốn &amp; Bản thuyết minh Báo cáo tình hình sử dụng vốn</a></p>\n\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</article></div>', 324, '2025-12-30 14:00:24', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tinh-hinh-sua-dung-von-cho-dot-tang-von-bang-hinh-thuc-chao-ban-co-phieu-ra-cong-chung-cho-co-dong-hien-huu-nam-2025-da-duoc-kiem-toan/', 0, '2026-08-12 02:06:34', '2026-08-12 02:06:34', NULL);
INSERT INTO `pvn_news_posts` VALUES (117, 'thong-bao-ngay-giao-dich-dau-tien-cua-co-phieu-dsh-dang-ky-giao-dich-bo-sung-1275', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO NGÀY GIAO DỊCH ĐẦU TIÊN CỦA CỔ PHIẾU DSH ĐĂNG KÝ GIAO DỊCH BỔ SUNG', NULL, '<p data-start=\"127\" data-end=\"311\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố thông tin về ngày giao dịch đầu tiên của số cổ phiếu DSH đăng ký giao dịch bổ sung tại Sở Giao dịch Chứng khoán Hà Nội (HNX).</p>\n<p data-start=\"313\" data-end=\"671\">Việc đăng ký giao dịch bổ sung được thực hiện trên cơ sở số lượng cổ phiếu đã phát hành thành công theo phương án chào bán cổ phiếu ra công chúng cho cổ đông hiện hữu và đã hoàn tất các thủ tục đăng ký, lưu ký theo quy định. Sau khi được HNX chấp thuận, số cổ phiếu phát hành thêm chính thức được đưa vào giao dịch trên hệ thống UPCoM kể từ ngày có hiệu lực.</p>\n<p data-start=\"673\" data-end=\"893\">Việc bổ sung cổ phiếu vào giao dịch góp phần đảm bảo quyền lợi hợp pháp của cổ đông, tăng tính thanh khoản cho cổ phiếu DSH trên thị trường, đồng thời phản ánh đầy đủ quy mô vốn điều lệ mới của Công ty sau đợt phát hành.</p>\n<p data-start=\"895\" data-end=\"1019\" data-is-last-node=\"\" data-is-only-node=\"\">Thông tin chi tiết về ngày giao dịch đầu tiên và số lượng cổ phiếu đăng ký giao dịch bổ sung được nêu tại thông báo của HNX.</p>\n<p data-start=\"895\" data-end=\"1019\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2025/12/TB-ngay-giao-dich-dau-tien-cua-co-phieu-DSH-dang-ky-bo-sung.pdf\">Thông báo ngày giao dịch đầu tiên của số cổ phiếu DSH đăng ký giao dịch bổ sung</a></span></p>', 380, '2025-12-31 16:13:12', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ngay-giao-dich-dau-tien-cua-co-phieu-dsh-dang-ky-giao-dich-bo-sung/', 0, '2026-08-12 02:06:35', '2026-08-12 02:06:35', NULL);
INSERT INTO `pvn_news_posts` VALUES (118, 'bo-nhiem-pho-tong-giam-doc-1280', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN BỔ NHIỆM PHÓ TỔNG GIÁM ĐỐC', NULL, '<p data-start=\"87\" data-end=\"315\">Căn cứ theo Nghị quyết Hội đồng quản trị số 05.01/2026/NQ-HĐQT/DSH ngày 05/01/2026 của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn, Công ty trân trọng thông báo về việc thay đổi nhân sự, cụ thể là bổ nhiệm Phó Tổng Giám đốc Công ty.</p>\n<p data-start=\"317\" data-end=\"588\">Theo nội dung Nghị quyết, Hội đồng quản trị đã thống nhất thông qua việc bổ nhiệm nhân sự giữ chức vụ Phó Tổng Giám đốc nhằm tăng cường năng lực điều hành, đáp ứng yêu cầu quản trị và triển khai các kế hoạch sản xuất kinh doanh trong giai đoạn phát triển mới của Công ty.</p>\n<p data-start=\"590\" data-end=\"817\">Việc kiện toàn bộ máy Ban điều hành thể hiện định hướng nâng cao hiệu quả quản lý, phân công rõ ràng chức năng, nhiệm vụ và đảm bảo sự linh hoạt trong công tác điều hành, phù hợp với quy mô và chiến lược phát triển của Công ty.</p>\n<p data-start=\"819\" data-end=\"950\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/wp-content/uploads/2026/01/VI_thongbaothaydoinhansu.pdf.pdf\">Bổ nhiệm Phó Tổng Giám đốc Công ty</a></span></p>', 381, '2026-01-05 16:08:48', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bo-nhiem-pho-tong-giam-doc/', 0, '2026-08-12 02:07:05', '2026-08-12 02:07:05', NULL);
INSERT INTO `pvn_news_posts` VALUES (119, 'thong-bao-thay-doi-nguoi-co-lien-quan-cua-nguoi-noi-bo-1297', 13, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO THAY ĐỔI NGƯỜI CÓ LIÊN QUAN CỦA NGƯỜI NỘI BỘ', NULL, '<p data-start=\"105\" data-end=\"293\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố thông tin về việc thay đổi người có liên quan của người nội bộ Công ty theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n<p data-start=\"295\" data-end=\"569\">Việc thay đổi người có liên quan được thực hiện trên cơ sở thông báo/đăng ký của cá nhân liên quan và được Công ty cập nhật theo đúng trình tự, thủ tục quy định. Thông tin thay đổi bao gồm mối quan hệ, thời điểm phát sinh/thay đổi và các nội dung có liên quan khác (nếu có).</p>\n<p data-start=\"571\" data-end=\"796\">Công ty thực hiện công bố thông tin nhằm đảm bảo tính minh bạch trong hoạt động quản trị, tạo điều kiện để cổ đông và nhà đầu tư theo dõi đầy đủ các thông tin liên quan đến người nội bộ và người có liên quan của người nội bộ.</p>\n<p data-start=\"798\" data-end=\"856\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/wp-content/uploads/2026/01/VI_EN_thongbaothaydoinguoinoibo.pdf.pdf\">Thay đổi người có liên quan của người nội bộ Công ty</a></span></p>', NULL, '2026-01-20 16:14:03', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-thay-doi-nguoi-co-lien-quan-cua-nguoi-noi-bo/', 0, '2026-08-12 02:07:47', '2026-08-12 02:07:47', NULL);
INSERT INTO `pvn_news_posts` VALUES (120, 'bao-cao-ve-thay-doi-so-huu-cua-co-dong-lon-nha-dau-tu-nam-giu-tu-5-tro-len-co-phieu-chung-chi-quy-dong-1303', 13, 'BÁO CÁO VỀ THAY ĐỔI SỞ HỮU CỦA CỔ ĐÔNG LỚN, NHÀ ĐẦU TƯ NẮM GIỮ TỪ CỔ PHIẾU 5% TRỞ LÊN', NULL, '<p data-start=\"93\" data-end=\"194\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố thông tin về thay đổi sở hữu của cổ đông lớn như sau:</p>\n\n<ul data-start=\"196\" data-end=\"750\">\n 	<li data-start=\"196\" data-end=\"238\">\n<p data-start=\"198\" data-end=\"238\"><strong data-start=\"198\" data-end=\"220\">Họ và tên cá nhân:</strong> Khuất Thảo Linh</p>\n</li>\n 	<li data-start=\"239\" data-end=\"308\">\n<p data-start=\"241\" data-end=\"308\"><strong data-start=\"241\" data-end=\"260\">Mã chứng khoán:</strong> DSH (Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn)</p>\n</li>\n 	<li data-start=\"310\" data-end=\"417\">\n<p data-start=\"312\" data-end=\"417\"><strong data-start=\"312\" data-end=\"379\">Số lượng, tỷ lệ cổ phiếu nắm giữ trước khi thực hiện giao dịch:</strong><br data-start=\"379\" data-end=\"382\" />4.375.000 cổ phiếu (tỷ lệ 12,50%)</p>\n</li>\n 	<li data-start=\"419\" data-end=\"531\">\n<p data-start=\"421\" data-end=\"531\"><strong data-start=\"421\" data-end=\"496\">Số lượng cổ phiếu đã giao dịch làm thay đổi tỷ lệ sở hữu qua ngưỡng 1%:</strong><br data-start=\"496\" data-end=\"499\" />850.000 cổ phiếu (tỷ lệ 2,43%)</p>\n</li>\n 	<li data-start=\"533\" data-end=\"638\">\n<p data-start=\"535\" data-end=\"638\"><strong data-start=\"535\" data-end=\"600\">Số lượng, tỷ lệ cổ phiếu nắm giữ sau khi thực hiện giao dịch:</strong><br data-start=\"600\" data-end=\"603\" />3.525.000 cổ phiếu (tỷ lệ 10,07%)</p>\n</li>\n 	<li data-start=\"640\" data-end=\"689\">\n<p data-start=\"642\" data-end=\"689\"><strong data-start=\"642\" data-end=\"668\">Lý do thay đổi sở hữu:</strong> Do nhu cầu cá nhân</p>\n</li>\n 	<li data-start=\"690\" data-end=\"750\">\n<p data-start=\"692\" data-end=\"750\"><strong data-start=\"692\" data-end=\"737\">Ngày giao dịch làm thay đổi tỷ lệ sở hữu:</strong> 26/01/2026</p>\n</li>\n</ul>\n<p data-start=\"752\" data-end=\"922\" data-is-last-node=\"\" data-is-only-node=\"\">Việc công bố thông tin được thực hiện theo quy định của pháp luật về chứng khoán và thị trường chứng khoán đối với cổ đông lớn khi có thay đổi tỷ lệ sở hữu từ 1% trở lên.</p>', 382, '2026-01-27 11:50:34', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-ve-thay-doi-so-huu-cua-co-dong-lon-nha-dau-tu-nam-giu-tu-5-tro-len-co-phieu-chung-chi-quy-dong/', 0, '2026-08-12 02:07:47', '2026-08-12 02:07:47', NULL);
INSERT INTO `pvn_news_posts` VALUES (121, 'bao-cao-quan-tri-nam-2025-1308', 13, 'BÁO CÁO QUẢN TRỊ CÔNG TY NĂM 2025', NULL, '<p data-start=\"84\" data-end=\"239\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố <strong data-start=\"132\" data-end=\"169\">Báo cáo quản trị công ty năm 2025</strong> theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n<p data-start=\"241\" data-end=\"512\">Báo cáo phản ánh tình hình hoạt động của Hội đồng quản trị, Ban kiểm soát, Ban điều hành; công tác quản trị, kiểm soát nội bộ; giao dịch với người có liên quan; tình hình thay đổi nhân sự quản lý; cũng như các nội dung khác liên quan đến công tác quản trị trong năm 2025.</p>\n<p data-start=\"514\" data-end=\"554\">Tài liệu được công bố song ngữ, bao gồm:</p>\n\n<ul data-start=\"556\" data-end=\"656\">\n 	<li data-start=\"556\" data-end=\"606\">\n<p data-start=\"558\" data-end=\"606\"><strong data-start=\"558\" data-end=\"577\">Bản tiếng Việt:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/01/VN.baocaoquantricongbo2025.pdf\">[VIE] BÁO CÁO QUẢN TRỊ CÔNG TY 2025</a></span></p>\n</li>\n 	<li data-start=\"607\" data-end=\"656\">\n<p data-start=\"609\" data-end=\"656\"><strong data-start=\"609\" data-end=\"627\">Bản tiếng Anh:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/chuong-trinh-tong-ket-nam-2025-dong-son-noi-vong-tay-lon/\">[ENG] BÁO CÁO QUẢN TRỊ CÔNG TY 2025</a></span></p>\n</li>\n</ul>', 383, '2026-01-30 16:27:20', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-quan-tri-nam-2025/', 0, '2026-08-12 02:07:54', '2026-08-12 02:07:54', NULL);
INSERT INTO `pvn_news_posts` VALUES (122, 'bao-cao-ket-qua-giao-dich-cua-nguoi-noi-bo-va-nguoi-co-lien-quan-cua-nguoi-noi-bo-2-1318', 13, 'BÁO CÁO KẾT QUẢ GIAO DỊCH CỦA NGƯỜI NỘI BỘ VÀ NGƯỜI CÓ LIÊN QUAN CỦA NGƯỜI NỘI BỘ', NULL, '<ul>\n 	<li>\n<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-18\" data-testid=\"conversation-turn-306\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:--spacing(4)] @w-sm/main:[--thread-content-margin:--spacing(6)] @w-lg/main:[--thread-content-margin:--spacing(16)] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"93eac309-be3a-4d31-ae76-5dd420cd18ef\" data-message-model-slug=\"gpt-5-2\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden first:pt-[1px]\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"132\" data-end=\"273\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố thông tin về giao dịch cổ phiếu của Người nội bộ/Người có liên quan của Người nội bộ như sau:</p>\n\n<ul data-start=\"275\" data-end=\"939\">\n 	<li data-start=\"275\" data-end=\"321\">\n<p data-start=\"277\" data-end=\"321\"><strong data-start=\"277\" data-end=\"299\">Họ và tên cá nhân:</strong> Nguyễn Thị Minh Huệ</p>\n</li>\n 	<li data-start=\"322\" data-end=\"389\">\n<p data-start=\"324\" data-end=\"389\"><strong data-start=\"324\" data-end=\"343\">Mã chứng khoán:</strong> DSH (Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn)</p>\n</li>\n 	<li data-start=\"391\" data-end=\"495\">\n<p data-start=\"393\" data-end=\"495\"><strong data-start=\"393\" data-end=\"460\">Số lượng, tỷ lệ cổ phiếu nắm giữ trước khi thực hiện giao dịch:</strong><br data-start=\"460\" data-end=\"463\" />7.000.000 cổ phiếu (tỷ lệ 20%)</p>\n</li>\n 	<li data-start=\"497\" data-end=\"558\">\n<p data-start=\"499\" data-end=\"558\"><strong data-start=\"499\" data-end=\"533\">Số lượng cổ phiếu đăng ký bán:</strong><br data-start=\"533\" data-end=\"536\" />3.500.000 cổ phiếu</p>\n</li>\n 	<li data-start=\"560\" data-end=\"639\">\n<p data-start=\"562\" data-end=\"639\"><strong data-start=\"562\" data-end=\"613\">Giá trị giao dịch dự kiến (tính theo mệnh giá):</strong><br data-start=\"613\" data-end=\"616\" />35.000.000.000 đồng</p>\n</li>\n 	<li data-start=\"641\" data-end=\"751\">\n<p data-start=\"643\" data-end=\"751\"><strong data-start=\"643\" data-end=\"716\">Số lượng, tỷ lệ cổ phiếu dự kiến nắm giữ sau khi thực hiện giao dịch:</strong><br data-start=\"716\" data-end=\"719\" />3.500.000 cổ phiếu (tỷ lệ 10%)</p>\n</li>\n 	<li data-start=\"753\" data-end=\"811\">\n<p data-start=\"755\" data-end=\"811\"><strong data-start=\"755\" data-end=\"788\">Mục đích thực hiện giao dịch:</strong> Theo nhu cầu cá nhân</p>\n</li>\n 	<li data-start=\"812\" data-end=\"853\">\n<p data-start=\"814\" data-end=\"853\"><strong data-start=\"814\" data-end=\"840\">Phương thức giao dịch:</strong> Thỏa thuận</p>\n</li>\n 	<li data-start=\"854\" data-end=\"939\">\n<p data-start=\"856\" data-end=\"939\"><strong data-start=\"856\" data-end=\"898\">Thời gian dự kiến thực hiện giao dịch:</strong> Từ ngày 10/02/2026 đến ngày 11/02/2026</p>\n</li>\n</ul>\n<p data-start=\"941\" data-end=\"1122\" data-is-last-node=\"\" data-is-only-node=\"\">Việc công bố thông tin được thực hiện theo quy định của pháp luật về chứng khoán và thị trường chứng khoán đối với giao dịch của Người nội bộ và Người có liên quan của Người nội bộ.</p>\n\n</div>\n</div>\n</div>\n</div>\n<div class=\"z-0 flex min-h-[46px] justify-start\"></div>\n<div class=\"mt-3 w-full empty:hidden\">\n<div class=\"text-center\"></div>\n</div>\n</div>\n</div>\n</article></div>\n<div class=\"pointer-events-none h-px w-px absolute bottom-0\" aria-hidden=\"true\" data-edge=\"true\"></div></li>\n</ul>', 384, '2026-02-05 11:44:06', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-ket-qua-giao-dich-cua-nguoi-noi-bo-va-nguoi-co-lien-quan-cua-nguoi-noi-bo-2/', 0, '2026-08-12 02:07:54', '2026-08-12 02:07:54', NULL);
INSERT INTO `pvn_news_posts` VALUES (123, 'chuong-trinh-tong-ket-nam-2025-dong-son-noi-vong-tay-lon-1321', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TỔ CHỨC CHƯƠNG TRÌNH TỔNG KẾT NĂM 2025 – ĐÔNG SƠN NỐI VÒNG TAY LỚN', NULL, '<span style=\"font-weight: 400;\">Trong hai ngày 06 – 07/02/2026, tại Flamingo Đại Lải Resort, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn (UpCOM: DSH) đã tổ chức Chương trình Tổng kết hoạt động năm 2025 dành cho toàn thể cán bộ nhân viên Công ty.</span>\n\n<span style=\"font-weight: 400;\">Chương trình là dịp để tập thể Đông Sơn cùng nhìn lại chặng đường một năm đã qua với nhiều nỗ lực, quyết tâm và tinh thần trách nhiệm cao trong từng nhiệm vụ được giao. Năm 2025 ghi nhận sự chủ động, linh hoạt trong điều hành, sự phối hợp chặt chẽ giữa các phòng ban và sự đồng lòng của toàn thể cán bộ nhân viên trong quá trình triển khai các dự án, công trình. Những kết quả đạt được là minh chứng rõ nét cho nền tảng tổ chức vững vàng và văn hóa doanh nghiệp đề cao tính kỷ luật, chuyên nghiệp và hiệu quả.</span>\n\n<span style=\"font-weight: 400;\">Bên cạnh nội dung tổng kết hoạt động, chương trình còn tạo không gian để các thành viên giao lưu, chia sẻ và tăng cường sự gắn kết nội bộ. Thông qua các hoạt động tập thể và sinh hoạt chung, tinh thần đoàn kết – yếu tố cốt lõi trong suốt hành trình phát triển của Công ty – tiếp tục được củng cố và lan tỏa mạnh mẽ trong toàn hệ thống.</span>\n\n<img class=\"alignnone wp-image-1322 size-full\" src=\"/uploads/news/2026/02/TVH00126-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1707\" />\n\n<span style=\"font-weight: 400;\">Với thông điệp </span><b>“Đông Sơn – Nối vòng tay lớn”</b><span style=\"font-weight: 400;\">, chương trình không chỉ là dịp nhìn lại thành quả đạt được mà còn là khoảnh khắc để mỗi thành viên thêm thấu hiểu giá trị của sự đồng hành, của tinh thần tập thể và trách nhiệm chung đối với sự phát triển bền vững của doanh nghiệp.</span>\n\n<span style=\"font-weight: 400;\">Khép lại năm 2025 với nhiều dấu ấn đáng ghi nhận, tập thể Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn tiếp tục giữ vững tinh thần đoàn kết, chuyên nghiệp và quyết tâm, cùng nhau tạo dựng những giá trị ngày càng bền vững trong chặng đường phía trước.</span>', 385, '2026-02-07 09:03:17', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/chuong-trinh-tong-ket-nam-2025-dong-son-noi-vong-tay-lon/', 0, '2026-08-12 02:07:55', '2026-08-12 02:07:55', NULL);
INSERT INTO `pvn_news_posts` VALUES (124, 'ban-tin-nha-dau-tu-2025-1325', 13, 'BẢN TIN NHÀ ĐẦU TƯ NĂM 2025', NULL, '<p data-start=\"78\" data-end=\"314\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"137\" data-end=\"168\">Bản tin Nhà đầu tư năm 2025</strong>, cung cấp thông tin tổng quan về tình hình hoạt động, kết quả kinh doanh, chiến lược phát triển và các dấu ấn nổi bật của Công ty trong năm 2025.</p>\n<p data-start=\"316\" data-end=\"343\">Bản tin tập trung cập nhật:</p>\n\n<ul data-start=\"345\" data-end=\"668\">\n 	<li data-start=\"345\" data-end=\"412\">\n<p data-start=\"347\" data-end=\"412\">Tình hình sản xuất kinh doanh và các chỉ tiêu tài chính chủ yếu</p>\n</li>\n 	<li data-start=\"413\" data-end=\"462\">\n<p data-start=\"415\" data-end=\"462\">Hoạt động đầu tư, triển khai dự án trọng điểm</p>\n</li>\n 	<li data-start=\"463\" data-end=\"520\">\n<p data-start=\"465\" data-end=\"520\">Công tác quản trị doanh nghiệp và minh bạch thông tin</p>\n</li>\n 	<li data-start=\"521\" data-end=\"593\">\n<p data-start=\"523\" data-end=\"593\">Diễn biến cơ cấu cổ đông, thay đổi vốn điều lệ và giao dịch cổ phiếu</p>\n</li>\n 	<li data-start=\"594\" data-end=\"668\">\n<p data-start=\"596\" data-end=\"668\">Định hướng chiến lược và kế hoạch phát triển trong giai đoạn tiếp theo</p>\n</li>\n</ul>\n<p data-start=\"670\" data-end=\"881\">Thông qua Bản tin Nhà đầu tư, Công ty mong muốn tăng cường tính minh bạch, củng cố niềm tin của cổ đông và nhà đầu tư, đồng thời thể hiện cam kết phát triển bền vững, nâng cao giá trị doanh nghiệp trong dài hạn.</p>\n<p data-start=\"883\" data-end=\"942\" data-is-last-node=\"\" data-is-only-node=\"\">Tài liệu được công bố song ngữ, bao gồm:</p>\n\n<ul data-start=\"556\" data-end=\"656\">\n 	<li data-start=\"556\" data-end=\"606\">\n<p data-start=\"558\" data-end=\"606\"><strong data-start=\"558\" data-end=\"577\">Bản tiếng Việt:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/02/VIE-BAN-TIN-IR-DHS.pdf\">[VIE] Bản tin Nhà đầu tư 2025</a></span></p>\n</li>\n 	<li data-start=\"607\" data-end=\"656\">\n<p data-start=\"609\" data-end=\"656\"><strong data-start=\"609\" data-end=\"627\">Bản tiếng Anh:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/02/ENG-IR-NEWS-DHS.pdf\">[ENG] Bản tin Nhà đầu tư 2025</a></span></p>\n</li>\n</ul>\n&nbsp;', 386, '2026-02-13 16:16:36', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ban-tin-nha-dau-tu-2025/', 0, '2026-08-12 02:08:06', '2026-08-12 02:08:06', NULL);
INSERT INTO `pvn_news_posts` VALUES (125, 'thong-bao-ngay-chot-danh-sach-co-dong-co-quyen-tham-du-dai-hoi-dong-co-dong-thuong-nien-nam-2026-1336', 12, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THÔNG BÁO NGÀY CHỐT DANH SÁCH CỔ ĐÔNG CÓ QUYỀN THAM DỰ ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2026', NULL, 'Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố thông tin về <strong data-start=\"219\" data-end=\"330\">ngày đăng ký cuối cùng để chốt danh sách cổ đông có quyền tham dự Đại hội đồng cổ đông thường niên năm 2026</strong> theo quy định của pháp luật và Điều lệ Công ty.\n<table width=\"651\">\n<tbody>\n<tr>\n<td width=\"210\">Tên chứng khoán</td>\n<td width=\"441\">: Cổ phiếu Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</td>\n</tr>\n<tr>\n<td width=\"210\">Mã chứng khoán</td>\n<td width=\"441\">: DSH</td>\n</tr>\n<tr>\n<td width=\"210\">Loại chứng khoán</td>\n<td width=\"441\">: Cổ phiếu phổ thông</td>\n</tr>\n<tr>\n<td width=\"210\">Mệnh giá giao dịch</td>\n<td width=\"441\">: 10.000 đồng</td>\n</tr>\n<tr>\n<td width=\"210\">Sàn giao dịch</td>\n<td width=\"441\">: UPCOM</td>\n</tr>\n<tr>\n<td width=\"210\">Ngày đăng ký cuối cùng</td>\n<td width=\"441\">: 18/03/2026</td>\n</tr>\n<tr>\n<td width=\"210\"><strong>1.   </strong><strong>Lý do và mục đích</strong></td>\n<td width=\"441\">: Tham dự Đại hội đồng cổ đông thường niên năm 2026</td>\n</tr>\n<tr>\n<td width=\"210\"><strong>2.   </strong><strong>Nội dung cụ thể</strong></td>\n<td width=\"441\"></td>\n</tr>\n<tr>\n<td width=\"210\">Tỷ lệ thực hiện</td>\n<td width=\"441\">: 01 cổ phần – 1 quyền biểu quyết</td>\n</tr>\n<tr>\n<td width=\"210\">Thời gian thực hiện</td>\n<td width=\"441\">: 09h00, Thứ Tư, ngày 22/04/2026</td>\n</tr>\n<tr>\n<td width=\"210\">Địa điểm thực hiện</td>\n<td width=\"441\">: Hội trường Athene 2, Khách sạn Grand Plaza, Hà Nội</td>\n</tr>\n<tr>\n<td width=\"210\">Nội dung họp:</td>\n<td width=\"441\">: Các nội dung thuộc thẩm quyền đại hội đồng cổ đông.</td>\n</tr>\n</tbody>\n</table>', 387, '2026-02-24 15:32:15', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ngay-chot-danh-sach-co-dong-co-quyen-tham-du-dai-hoi-dong-co-dong-thuong-nien-nam-2026/', 0, '2026-08-12 02:08:07', '2026-08-12 02:08:07', NULL);
INSERT INTO `pvn_news_posts` VALUES (126, 'nam-dinh-khoi-cong-khu-nha-o-xa-hoi-bai-vien-voi-hon-1-100-can-ho-cho-nguoi-thu-nhap-thap-1790', 11, 'CÔNG TY CỔ PHẦN ĐÔNG SƠN HOLDINGS ĐẦU TƯ DỰ ÁN NHÀ Ở XÃ HỘI BÃI VIÊN - NAM ĐỊNH', NULL, '<strong data-start=\"22\" data-end=\"36\">Tên dự án:</strong> Khu nhà ở xã hội Bãi Viên tại phường Mỹ Xá, thành phố Nam Định<br data-start=\"47\" data-end=\"50\" /><strong data-start=\"50\" data-end=\"62\">Địa chỉ:</strong> Phường Mỹ Xá – Thành phố Nam Định (nay là Phường Thành Nam, tỉnh Ninh Bình)\n<strong>Diện tích</strong>: 30.000m²\n<strong>Mật độ</strong>: 34,6%\n<strong>Quy mô</strong>: Tổng diện tích sàn xây dựng: khoảng 104.376m² với 1.100 căn hộ.\n<strong>Thiết kế</strong>: 6 tòa nhà cao 9 tầng\n<strong>Diện tích căn</strong>: 25m² – 70m²\n\nVới vốn đầu tư hơn 909 tỷ đồng, khu nhà ở xã hội Bãi Viên đã được khởi công ngày 19/5/2025 tại TP Nam Định sẽ mang đến hơn 1.100 căn hộ cho người thu nhập thấp, bước đi quan trọng trong chiến lược phát triển an sinh xã hội của tỉnh.\n\nĐây là dự án được UBND tỉnh Nam Định chấp thuận chủ trương đầu tư từ tháng 10/2024, do Liên danh Công ty cổ phần Đầu tư và Phát triển đô thị Nam Định cùng Công ty cổ phần Nhà Mỹ Xuân Hà Nội làm chủ đầu tư. Đặc biệt, đánh dấu một cột mốc chiến lược đầy tự hào, từ tháng 12/2025, Đông Sơn đã chính thức nhận chuyển nhượng và nắm giữ 45% cổ phần tại Công ty cổ phần Đầu tư và Phát triển đô thị Nam Định. Đứng sau dự án ngàn tỷ này với định hướng vươn tầm thành Đông Sơn Holdings, Đông Sơn mang vào đó không chỉ nguồn lực tài chính vững mạnh mà còn là khát vọng kiến tạo tổ ấm nhân văn.\n\nDự án được triển khai trên diện tích hơn 30.000m², gồm 6 tòa nhà cao 9 tầng với 1.100 căn hộ có diện tích từ 25 – 70m². Tổng diện tích sàn sử dụng lên tới 67.500m². Ngoài ra, công trình còn có tầng hầm rộng 8.300m² nhằm đáp ứng đầy đủ tiện ích sinh hoạt hiện đại, an toàn, thân thiện với môi trường.\n\n<img class=\"alignnone wp-image-1854 size-full\" src=\"/uploads/news/2026/03/z6617362324477_296d7bad0c9033deeb0c5c5bc23f2033.jpg\" alt=\"\" width=\"796\" height=\"521\" />\n<p style=\"text-align: center;\"><strong>Dự án khu nhà ở xã hội Bãi Viên, tọa lạc tại phường Mỹ Xá, Nam Định\n</strong></p>\nPhát biểu tại buổi lễ, Phó Chủ tịch thường trực UBND tỉnh Nam Định Trần Anh Dũng nhấn mạnh: Khởi công dự án Bãi Viên là bước cụ thể hóa cam kết của tỉnh Nam Định trong thực hiện chỉ đạo của Thủ tướng Chính phủ về việc xây dựng ít nhất 1 triệu căn hộ nhà ở xã hội cho người thu nhập thấp và công nhân khu công nghiệp giai đoạn 2021 – 2030. Đồng thời, đây cũng là một phần trong chiến lược phát triển đô thị bền vững, nâng cao chất lượng an sinh xã hội và tạo nền tảng vững chắc cho mục tiêu phát triển toàn diện của tỉnh.\n\nLãnh đạo tỉnh cho biết, thời gian qua, Nam Định đã chủ động bố trí quỹ đất, triển khai đồng bộ các giải pháp về quy hoạch, thu hút đầu tư để thúc đẩy lĩnh vực nhà ở xã hội. Hiện toàn tỉnh đang triển khai nhiều dự án, dự kiến cung cấp khoảng 3.000 căn hộ. Trong giai đoạn 2025 – 2030, Nam Định được giao chỉ tiêu xây dựng khoảng 9.800 căn hộ nhà ở xã hội, một thách thức lớn song cũng là cơ hội để tỉnh khẳng định vai trò tiên phong trong thực hiện chính sách an sinh xã hội của Chính phủ.\n\n<img class=\"alignnone wp-image-1853 size-full\" src=\"/uploads/news/2026/03/d82a95a3-b605-45f2-9f9c-b786ad66813a.jpg\" alt=\"\" width=\"1200\" height=\"621\" />\n<p style=\"text-align: center;\"><strong>Lãnh đạo tỉnh Nam Định và các sở, ban, ngành thực hiện nghi thức khởi công dự án</strong></p>\n<p style=\"text-align: left;\">Theo cam kết của nhà đầu tư, dự án sẽ được thi công theo 3 giai đoạn từ năm 2025 đến 2030, lần lượt hoàn thiện 6 tòa nhà với tổng số 1.100 căn hộ. Cụ thể: giai đoạn 1 (2025 – 2026) hoàn thành 2 tòa với 324 căn; giai đoạn 2 (2026 – 2028) hoàn thành 2 tòa với 304 căn; giai đoạn 3 (2028 – 2030) hoàn thành 2 tòa với 472 căn. Chủ đầu tư khẳng định sẽ tuân thủ nghiêm ngặt các quy định pháp luật về đầu tư, xây dựng, môi trường; đồng thời kêu gọi sự đồng hành từ chính quyền và người dân để dự án được triển khai thuận lợi, hiệu quả.</p>\nPhó Chủ tịch thường trực UBND tỉnh Nam Định cũng yêu cầu các cơ quan chức năng, đặc biệt là Sở Xây dựng và UBND TP. Nam Định tích cực hỗ trợ doanh nghiệp trong quá trình triển khai, kịp thời tháo gỡ các khó khăn, đẩy nhanh các thủ tục xác nhận điều kiện mua – thuê nhà ở xã hội cho người dân. Các ngân hàng, tổ chức tín dụng được đề nghị tạo điều kiện thuận lợi cho nhà đầu tư tiếp cận vốn, đồng thời đẩy mạnh việc hỗ trợ người dân tiếp cận gói vay ưu đãi để sớm hiện thực hóa giấc mơ an cư.\n\nVới vị trí nằm ở trung tâm thành phố, được đầu tư bài bản, hiện đại theo định hướng phát triển đô thị xanh, nhà ở cao tầng, Khu nhà ở xã hội Bãi Viên sẽ trở thành hình mẫu cho các dự án tương tự trong thời gian tới – góp phần quan trọng xây dựng diện mạo đô thị mới và đảm bảo an sinh xã hội cho Nam Định.\n\nWebsite dự án: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://noxhbaivien.vn/\">Nhà ở xã hội Bãi Viên - Nam Định</a>\n<span style=\"color: #333333;\">Nghị quyết:</span> <a style=\"color: #0000ff;\" href=\"https://htds.vn/nghi-quyet-hdqt-ve-co-cau-cac-khoan-dau-tu-va-chu-truong-ky-ket-thuc-hien-giao-dich-voi-cong-ty-con-cong-ty-lien-ket-nguoi-co-lien-quan/\">Đông Sơn thông qua mua 45% cổ phần công ty Nam Định</a></span>', 270, '2026-03-09 14:52:36', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nam-dinh-khoi-cong-khu-nha-o-xa-hoi-bai-vien-voi-hon-1-100-can-ho-cho-nguoi-thu-nhap-thap/', 0, '2026-08-12 02:08:07', '2026-08-12 02:08:07', NULL);
INSERT INTO `pvn_news_posts` VALUES (127, 'nhung-tram-thu-phi-cao-toc-co-doanh-thu-tren-100-ty-3-thang-dau-nam-1842', 5, 'NHỮNG TRẠM THU PHÍ CAO TỐC CÓ DOANH THU TRÊN 100 TỶ 3 THÁNG ĐẦU NĂM', NULL, '<p data-start=\"102\" data-end=\"249\">Theo danh sách <strong data-start=\"117\" data-end=\"142\">Cục Đường bộ Việt Nam</strong> vừa công bố, nhiều trạm thu phí cao tốc đã đạt <strong data-start=\"190\" data-end=\"248\">doanh thu trên 100 tỷ đồng trong ba tháng đầu năm 2025</strong>.</p>\n<p data-start=\"251\" data-end=\"437\">Cục Đường bộ Việt Nam cho biết hiện có <strong data-start=\"290\" data-end=\"335\">52 dự án BOT, BOO trong lĩnh vực đường bộ</strong> đang được các doanh nghiệp dự án thực hiện <strong data-start=\"379\" data-end=\"436\">báo cáo định kỳ về doanh thu và lưu lượng phương tiện</strong>.</p>\n<p data-start=\"439\" data-end=\"596\">Trong <strong data-start=\"445\" data-end=\"461\">tháng 3/2025</strong>, tổng doanh thu thu phí dịch vụ sử dụng đường bộ đạt <strong data-start=\"515\" data-end=\"536\">hơn 1.313 tỷ đồng</strong>, với <strong data-start=\"542\" data-end=\"595\">tổng lưu lượng phương tiện đạt 20.569.472 lượt xe</strong>.</p>\n<p data-start=\"598\" data-end=\"750\"><strong data-start=\"598\" data-end=\"640\">Lũy kế từ đầu năm đến hết tháng 3/2025</strong>, tổng doanh thu thu phí đạt <strong data-start=\"669\" data-end=\"690\">hơn 3.603 tỷ đồng</strong>, với <strong data-start=\"696\" data-end=\"749\">tổng lưu lượng phương tiện đạt 60.352.768 lượt xe</strong>.</p>\n<p data-start=\"752\" data-end=\"930\">Đáng chú ý, trong danh sách này có nhiều <strong data-start=\"793\" data-end=\"847\">trạm thu phí BOT trên các tuyến cao tốc và quốc lộ</strong> ghi nhận <strong data-start=\"857\" data-end=\"914\">mức doanh thu trên 100 tỷ đồng trong ba tháng đầu năm</strong>. Tiêu biểu như:</p>\n\n<ul data-start=\"932\" data-end=\"1583\">\n 	<li data-section-id=\"u0qi4t\" data-start=\"932\" data-end=\"1080\">\n<p data-start=\"934\" data-end=\"1080\"><strong data-start=\"934\" data-end=\"952\">Trạm Km152+080</strong> thuộc dự án cải tạo, nâng cấp và mở rộng <strong data-start=\"994\" data-end=\"1031\">Quốc lộ 1 đoạn Hà Nội – Bắc Giang</strong> theo hình thức BOT, doanh thu <strong data-start=\"1062\" data-end=\"1077\">162 tỷ đồng</strong>.</p>\n</li>\n 	<li data-section-id=\"ddxqme\" data-start=\"1081\" data-end=\"1179\">\n<p data-start=\"1083\" data-end=\"1179\"><strong data-start=\"1083\" data-end=\"1099\">Trạm thu kín</strong> thuộc dự án nâng cấp tuyến <strong data-start=\"1127\" data-end=\"1149\">Pháp Vân – Cầu Giẽ</strong>, doanh thu <strong data-start=\"1161\" data-end=\"1176\">281 tỷ đồng</strong>.</p>\n</li>\n 	<li data-section-id=\"1q9h38q\" data-start=\"1180\" data-end=\"1324\">\n<p data-start=\"1182\" data-end=\"1324\"><strong data-start=\"1182\" data-end=\"1202\">Trạm Bắc Hải Vân</strong> thuộc dự án <strong data-start=\"1215\" data-end=\"1290\">hầm đường bộ Phước Tượng – Phú Gia trên Quốc lộ 1 (tỉnh Thừa Thiên Huế)</strong>, doanh thu <strong data-start=\"1302\" data-end=\"1321\">gần 140 tỷ đồng</strong>.</p>\n</li>\n 	<li data-section-id=\"wxy6t2\" data-start=\"1325\" data-end=\"1469\">\n<p data-start=\"1327\" data-end=\"1469\"><strong data-start=\"1327\" data-end=\"1344\">Trạm Ninh Lộc</strong> thuộc dự án mở rộng <strong data-start=\"1365\" data-end=\"1439\">Quốc lộ 1 đoạn Km1374+525 – Km1392 và Km1405 – Km1425 (tỉnh Khánh Hòa)</strong>, doanh thu <strong data-start=\"1451\" data-end=\"1466\">107 tỷ đồng</strong>.</p>\n</li>\n 	<li data-section-id=\"fly9s1\" data-start=\"1470\" data-end=\"1583\">\n<p data-start=\"1472\" data-end=\"1583\">Các trạm thu phí thuộc dự án <strong data-start=\"1501\" data-end=\"1542\">đường ô tô cao tốc Hà Nội – Hải Phòng</strong> ghi nhận <strong data-start=\"1552\" data-end=\"1582\">tổng doanh thu 753 tỷ đồng</strong>.</p>\n</li>\n</ul>\n<p data-start=\"1585\" data-end=\"1616\"><strong data-start=\"1585\" data-end=\"1616\">Chi tiết danh sách như sau:</strong></p>\n<p data-start=\"1585\" data-end=\"1616\"> <img class=\"alignnone wp-image-1843 size-full\" src=\"/uploads/news/2026/03/Screenshot-1300.jpg\" alt=\"\" width=\"1040\" height=\"342\" /></p>\n<p data-start=\"1585\" data-end=\"1616\"><img class=\"alignnone wp-image-1844 size-full\" src=\"/uploads/news/2026/03/Screenshot-1299.jpg\" alt=\"\" width=\"1050\" height=\"409\" /></p>\n<p data-start=\"1585\" data-end=\"1616\"><img class=\"alignnone wp-image-1845 size-full\" src=\"/uploads/news/2026/03/Screenshot-1298.jpg\" alt=\"\" width=\"1149\" height=\"391\" /></p>\n<p data-start=\"1585\" data-end=\"1616\"><img class=\"alignnone wp-image-1846\" src=\"/uploads/news/2026/03/Screenshot-1296-01.jpg\" alt=\"\" width=\"1149\" height=\"573\" /></p>\n<p data-start=\"1585\" data-end=\"1616\">Cục Đường bộ Việt Nam cho biết, việc công khai, minh bạch các số liệu về doanh thu thu phí và lưu lượng phương tiện tại các trạm BOT là một trong những nội dung được đơn vị đặc biệt chú trọng. Hoạt động này nhằm tăng cường tính công khai, minh bạch trong công tác thu phí sử dụng đường bộ, đồng thời góp phần nâng cao hiệu quả giám sát của cơ quan quản lý nhà nước, các cơ quan chức năng và cộng đồng xã hội.</p>\n<p data-start=\"1585\" data-end=\"1616\"><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://amp.laodong.vn/xa-hoi/nhung-tram-thu-phi-cao-toc-tren-100-ti-ba-thang-dau-nam-1502801.ldo\">Những trạm thu phí cao tốc có doanh thu 100 tỷ 3 tháng đầu năm</a></span></p>', 388, '2025-05-11 16:35:47', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nhung-tram-thu-phi-cao-toc-co-doanh-thu-tren-100-ty-3-thang-dau-nam/', 0, '2026-08-12 02:08:09', '2026-08-12 02:08:09', NULL);
INSERT INTO `pvn_news_posts` VALUES (128, 'ctcp-dau-tu-ha-tang-dong-son-thi-cong-du-an-cau-hong-ha-thuoc-du-an-vanh-dai-4-vung-thu-do-ha-noi-1894', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN CẦU HỒNG HÀ THUỘC DỰ ÁN VÀNH ĐAI 4 - VÙNG THỦ ĐÔ HÀ NỘI', NULL, '<p data-start=\"272\" data-end=\"677\">Cầu Hồng Hà – một trong những công trình quan trọng của dự án đường Vành đai 4 – Vùng Thủ đô Hà Nội – hiện đang được các nhà thầu triển khai thi công nhiều hạng mục quan trọng nhằm đảm bảo tiến độ của dự án. Công trình có tổng mức đầu tư gần <strong data-start=\"514\" data-end=\"531\">9.800 tỷ đồng</strong>, được kỳ vọng sẽ trở thành điểm kết nối giao thông chiến lược, góp phần hoàn thiện mạng lưới hạ tầng khu vực phía Bắc Thủ đô trong thời gian tới.</p>\n<p data-start=\"679\" data-end=\"1018\">Trong dự án này, <strong data-start=\"696\" data-end=\"739\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</strong> tham gia thi công <strong data-start=\"758\" data-end=\"895\">gói thầu XL-NS.01.01: Thi công xây lắp cầu Hồng Hà đoạn Km10+663,3 – Km13+674,6 và cầu vượt đê hữu Hồng đoạn Km14+840,75 – Km15+040,9</strong>, thuộc <strong data-start=\"903\" data-end=\"996\">Dự án thành phần 3 – Đầu tư xây dựng đường cao tốc theo phương thức đối tác công tư (PPP)</strong> của dự án Vành đai 4.</p>\n<p data-start=\"1020\" data-end=\"1184\">Gói thầu được thực hiện theo hợp đồng ký kết giữa <strong data-start=\"1070\" data-end=\"1121\">Công ty Cổ phần Đường cao tốc Vành đai 4 Hà Nội</strong> và <strong data-start=\"1125\" data-end=\"1159\">Liên danh thi công cầu Hồng Hà</strong>, gồm các doanh nghiệp:</p>\n\n<ul data-start=\"1185\" data-end=\"1377\">\n 	<li data-section-id=\"1bjdvk\" data-start=\"1185\" data-end=\"1224\">\n<p data-start=\"1187\" data-end=\"1224\">Công ty Cổ phần Tập đoàn Đạt Phương</p>\n</li>\n 	<li data-section-id=\"cxhqj7\" data-start=\"1225\" data-end=\"1276\">\n<p data-start=\"1227\" data-end=\"1276\">Công ty TNHH Thương mại và Xây dựng Trung Chính</p>\n</li>\n 	<li data-section-id=\"xgxoho\" data-start=\"1277\" data-end=\"1333\">\n<p data-start=\"1279\" data-end=\"1333\">Công ty Cổ phần Đầu tư Xây dựng Hạ tầng Khang Nguyên</p>\n</li>\n 	<li data-section-id=\"10njxso\" data-start=\"1334\" data-end=\"1377\">\n<p data-start=\"1336\" data-end=\"1377\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</p>\n</li>\n</ul>\n<p data-start=\"1379\" data-end=\"1578\">Ngoài phần thi công xây lắp, gói thầu còn bao gồm các công việc như <strong data-start=\"1447\" data-end=\"1532\">khảo sát, thiết kế bản vẽ thi công và xây dựng mô hình thông tin công trình (BIM)</strong> phục vụ công tác quản lý và triển khai dự án.</p>\n\n<h3 data-section-id=\"11ma2cp\" data-start=\"1580\" data-end=\"1612\">Quy mô và vị trí cầu Hồng Hà</h3>\n<img class=\"alignnone wp-image-1898 size-full\" src=\"/uploads/news/2026/03/Cau-Hong-Ha-12-e1773300590681.jpg\" alt=\"\" width=\"660\" height=\"372\" />\n<p data-start=\"1614\" data-end=\"1949\">Cầu Hồng Hà được quy hoạch bắc qua <strong data-start=\"1649\" data-end=\"1662\">sông Hồng</strong>, với <strong data-start=\"1668\" data-end=\"1722\">điểm đầu tại xã Đồng Hà, huyện Đan Phượng (Hà Nội)</strong> và <strong data-start=\"1726\" data-end=\"1778\">điểm cuối tại xã Văn Khê, huyện Mê Linh (Hà Nội)</strong>. Đây là vị trí có vai trò quan trọng trong việc kết nối khu vực phía Bắc Thủ đô, đồng thời tạo trục giao thông thuận lợi giữa các huyện ngoại thành với khu vực trung tâm.</p>\n<p data-start=\"1951\" data-end=\"2211\">Theo quy hoạch, dự án bao gồm <strong data-start=\"1981\" data-end=\"2046\">cầu Hồng Hà và hệ thống đường dẫn hai đầu cầu dài khoảng 6 km</strong>. Tuyến đường có <strong data-start=\"2063\" data-end=\"2092\">mặt cắt ngang rộng 24,5 m</strong>, gồm <strong data-start=\"2098\" data-end=\"2156\">4 làn xe cơ giới và 2 làn dành cho xe thô sơ và xe máy</strong>, đáp ứng nhu cầu lưu thông ngày càng tăng của khu vực.</p>\n<p data-start=\"2213\" data-end=\"2464\">Hiện nay, trên công trường dự án, nhiều hạng mục đang được triển khai đồng loạt như <strong data-start=\"2297\" data-end=\"2394\">khoan cọc nhồi, lắp đặt kết cấu dầm thép, thi công nền đường và các hạng mục hạ tầng kỹ thuật</strong>, cho thấy tiến độ thi công đang được các nhà thầu tích cực đẩy nhanh.</p>\n\n<h3 data-section-id=\"1ok7s24\" data-start=\"2466\" data-end=\"2512\">Công trình quan trọng của tuyến Vành đai 4</h3>\n<img class=\"alignnone wp-image-1900 size-full\" src=\"/uploads/news/2026/03/img_dd6d900a.jpg\" alt=\"\" width=\"1700\" height=\"1064\" />\n<p data-start=\"2514\" data-end=\"2882\">Cầu Hồng Hà là một trong những hạng mục quan trọng của <strong data-start=\"2569\" data-end=\"2616\">dự án đường Vành đai 4 – Vùng Thủ đô Hà Nội</strong>, tuyến giao thông chiến lược có <strong data-start=\"2649\" data-end=\"2683\">tổng chiều dài khoảng 112,8 km</strong>, đi qua địa bàn <strong data-start=\"2700\" data-end=\"2732\">Hà Nội, Hưng Yên và Bắc Ninh</strong>. Dự án có tổng mức đầu tư khoảng <strong data-start=\"2766\" data-end=\"2784\">85.813 tỷ đồng</strong> và được triển khai nhằm tạo trục giao thông liên vùng, giảm tải áp lực cho khu vực nội đô Hà Nội.</p>\n<p data-start=\"2884\" data-end=\"3132\">Việc xây dựng cầu Hồng Hà được xem là bước đi quan trọng trong chiến lược phát triển hạ tầng của Hà Nội giai đoạn <strong data-start=\"2998\" data-end=\"3013\">2023 – 2025</strong>, hướng tới mục tiêu hình thành mạng lưới giao thông hiện đại, tăng cường liên kết vùng và thúc đẩy phát triển kinh tế.</p>\n<p data-start=\"3134\" data-end=\"3268\">Theo kế hoạch, dự án cầu Hồng Hà được triển khai thi công từ năm <strong data-start=\"3199\" data-end=\"3207\">2024</strong> và dự kiến <strong data-start=\"3219\" data-end=\"3267\">hoàn thành, đưa vào khai thác trong năm 2028</strong>.</p>\n\n<h3 data-section-id=\"19f9p70\" data-start=\"3270\" data-end=\"3318\">Tác động đối với phát triển kinh tế – xã hội</h3>\n<p data-start=\"3320\" data-end=\"3559\">Khi hoàn thành, cầu Hồng Hà sẽ góp phần <strong data-start=\"3360\" data-end=\"3433\">giảm áp lực giao thông cho cầu Thăng Long và các tuyến đường hiện hữu</strong>, đồng thời tăng cường kết nối giữa các khu vực phía Bắc Hà Nội như <strong data-start=\"3501\" data-end=\"3534\">Mê Linh, Đông Anh, Đan Phượng</strong> với trung tâm thành phố.</p>\n<p data-start=\"3561\" data-end=\"3901\">Bên cạnh đó, công trình còn tạo điều kiện thuận lợi cho việc <strong data-start=\"3622\" data-end=\"3679\">kết nối các tỉnh trong vùng kinh tế trọng điểm Bắc Bộ</strong>, đặc biệt là Hà Nội, Vĩnh Phúc và các địa phương lân cận. Hệ thống giao thông thuận lợi được kỳ vọng sẽ thúc đẩy hoạt động giao thương, thu hút đầu tư và góp phần thúc đẩy quá trình đô thị hóa tại khu vực phía Bắc Thủ đô.</p>\n\n<h3 data-section-id=\"do01ra\" data-start=\"3903\" data-end=\"3948\">Khẳng định năng lực thi công của Đông Sơn</h3>\n<p data-start=\"3950\" data-end=\"4313\">Việc tham gia thi công cầu Hồng Hà tiếp tục khẳng định năng lực của <strong data-start=\"4018\" data-end=\"4061\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</strong> trong lĩnh vực xây dựng hạ tầng giao thông. Trong quá trình triển khai dự án, doanh nghiệp phối hợp chặt chẽ với các đơn vị trong liên danh để đảm bảo <strong data-start=\"4213\" data-end=\"4256\">tiến độ, chất lượng và an toàn lao động</strong>, đồng thời tuân thủ các yêu cầu kỹ thuật của chủ đầu tư.</p>\n<p data-start=\"4315\" data-end=\"4766\">Những năm gần đây, Đông Sơn đã tham gia thi công nhiều dự án giao thông quan trọng trên cả nước như <strong data-start=\"4415\" data-end=\"4527\">cải tạo, nâng cấp Quốc lộ 14B (Đà Nẵng), tuyến đường Nam Định – Lạc Quần – đường ven biển, cầu vượt sông Đáy</strong>, cùng nhiều công trình hạ tầng khác. Việc tiếp tục góp mặt trong dự án <strong data-start=\"4599\" data-end=\"4634\">Vành đai 4 – Vùng Thủ đô Hà Nội</strong> được xem là bước tiến quan trọng trong chiến lược phát triển của doanh nghiệp trong lĩnh vực xây dựng và đầu tư hạ tầng giao thông.</p>\n<p data-start=\"4768\" data-end=\"5016\">Khi toàn tuyến Vành đai 4 cùng các công trình như cầu Hồng Hà được hoàn thành, mạng lưới giao thông khu vực Thủ đô sẽ được hoàn thiện hơn, góp phần tạo động lực mới cho phát triển kinh tế – xã hội của Hà Nội và các tỉnh lân cận trong những năm tới.</p>\n<p data-start=\"4768\" data-end=\"5016\"><img class=\"alignnone wp-image-1901 size-full\" src=\"/uploads/news/2026/03/img_c249af4c.jpg\" alt=\"\" width=\"1700\" height=\"956\" /></p>', 389, '2025-10-11 14:27:58', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ctcp-dau-tu-ha-tang-dong-son-thi-cong-du-an-cau-hong-ha-thuoc-du-an-vanh-dai-4-vung-thu-do-ha-noi/', 0, '2026-08-12 02:08:10', '2026-08-12 02:08:10', NULL);
INSERT INTO `pvn_news_posts` VALUES (129, 'ctcp-dau-tu-ha-tang-dong-son-thi-cong-du-an-cau-ngoc-hoi-va-duong-dan-hai-dau-cau-1903', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN CẦU NGỌC HỒI VÀ ĐƯỜNG DẪN HAI ĐẦU CẦU', NULL, '<div class=\"flex flex-col text-sm pb-25\"><article class=\"text-token-text-primary w-full focus:outline-none [--shadow-height:45px] has-data-writing-block:pointer-events-none has-data-writing-block:-mt-(--shadow-height) has-data-writing-block:pt-(--shadow-height) [&amp;:has([data-writing-block])&gt;*]:pointer-events-auto scroll-mt-[calc(var(--header-height)+min(200px,max(70px,20svh)))]\" dir=\"auto\" tabindex=\"-1\" data-turn-id=\"request-69816019-69fc-8320-8e23-e0a276ac3450-2\" data-testid=\"conversation-turn-478\" data-scroll-anchor=\"true\" data-turn=\"assistant\">\n<div class=\"text-base my-auto mx-auto pb-10 [--thread-content-margin:var(--thread-content-margin-xs,calc(var(--spacing)*4))] @w-sm/main:[--thread-content-margin:var(--thread-content-margin-sm,calc(var(--spacing)*6))] @w-lg/main:[--thread-content-margin:var(--thread-content-margin-lg,calc(var(--spacing)*16))] px-(--thread-content-margin)\">\n<div class=\"[--thread-content-max-width:40rem] @w-lg/main:[--thread-content-max-width:48rem] mx-auto max-w-(--thread-content-max-width) flex-1 group/turn-messages focus-visible:outline-hidden relative flex w-full min-w-0 flex-col agent-turn\" tabindex=\"-1\">\n<div class=\"flex max-w-full flex-col gap-4 grow\">\n<div class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal [.text-message+&amp;]:mt-1\" dir=\"auto\" data-message-author-role=\"assistant\" data-message-id=\"4e4a70b7-4f1c-4b73-b66a-d0d12812f258\" data-message-model-slug=\"gpt-5-3\">\n<div class=\"flex w-full flex-col gap-1 empty:hidden\">\n<div class=\"markdown prose dark:prose-invert w-full wrap-break-word light markdown-new-styling\">\n<p data-start=\"74\" data-end=\"478\">Dự án đầu tư xây dựng <strong data-start=\"96\" data-end=\"137\">cầu Ngọc Hồi và đường dẫn hai đầu cầu</strong> là một trong những công trình giao thông trọng điểm đang được triển khai nhằm tăng cường năng lực kết nối giữa Thủ đô Hà Nội với các tỉnh, thành trong khu vực. Công trình được kỳ vọng sẽ góp phần hoàn thiện hệ thống hạ tầng giao thông khu vực phía Nam Hà Nội, đồng thời tạo động lực phát triển kinh tế – xã hội cho các địa phương dọc tuyến.</p>\n<p data-start=\"480\" data-end=\"964\">Theo chủ trương đầu tư đã được phê duyệt, dự án được chia thành <strong data-start=\"544\" data-end=\"573\">hai nhóm dự án thành phần</strong> nhằm đảm bảo việc triển khai đồng bộ các hạng mục liên quan. Trong đó, <strong data-start=\"645\" data-end=\"679\">nhóm dự án giải phóng mặt bằng</strong> bao gồm <strong data-start=\"688\" data-end=\"711\">ba dự án thành phần</strong>, còn <strong data-start=\"717\" data-end=\"747\">nhóm dự án đầu tư xây dựng</strong> gồm <strong data-start=\"752\" data-end=\"776\">hai dự án thành phần</strong>. Tổng mức đầu tư của toàn bộ dự án dự kiến khoảng <strong data-start=\"827\" data-end=\"845\">11.844 tỷ đồng</strong>, bao gồm chi phí cho công tác giải phóng mặt bằng, xây dựng cầu, đường dẫn và các hạng mục hạ tầng kỹ thuật liên quan.</p>\n<p data-start=\"966\" data-end=\"1672\">Về quy mô, <strong data-start=\"977\" data-end=\"1030\">tổng chiều dài toàn tuyến của dự án khoảng 7,5 km</strong>, kết nối trực tiếp giữa Hà Nội và tỉnh Hưng Yên. <strong data-start=\"1080\" data-end=\"1102\">Điểm đầu của tuyến</strong> nằm tại khu vực kết nối với <strong data-start=\"1131\" data-end=\"1210\">đường Vành đai 3,5 đoạn từ Phúc La – Văn Phú đến cao tốc Pháp Vân – Cầu Giẽ</strong>, cách tuyến cao tốc khoảng <strong data-start=\"1238\" data-end=\"1267\">360 m về phía đê Hữu Hồng</strong>, thuộc địa bàn <strong data-start=\"1283\" data-end=\"1317\">xã Thanh Trì, thành phố Hà Nội</strong>. <strong data-start=\"1319\" data-end=\"1354\">Điểm cuối của dự án tại Km7+500</strong> kết nối với <strong data-start=\"1367\" data-end=\"1389\">đường Vành đai 3,5</strong>, cách <strong data-start=\"1396\" data-end=\"1458\">đê Tả Hồng khoảng 700 m về phía cao tốc Hà Nội – Hải Phòng</strong>, thuộc địa phận <strong data-start=\"1475\" data-end=\"1506\">xã Văn Giang, tỉnh Hưng Yên</strong>. Với vị trí kết nối này, tuyến đường sẽ hình thành một trục giao thông quan trọng liên kết giữa khu vực phía Nam Hà Nội với các tuyến giao thông huyết mạch của vùng.</p>\n<p data-start=\"966\" data-end=\"1672\"> <img class=\"alignnone wp-image-1906 size-full\" src=\"/uploads/news/2026/03/img_c0e5c737.jpg\" alt=\"\" width=\"1920\" height=\"1080\" /></p>\n<p data-start=\"1674\" data-end=\"2106\">Công tác <strong data-start=\"1683\" data-end=\"1706\">giải phóng mặt bằng</strong> của dự án được triển khai trên địa bàn <strong data-start=\"1746\" data-end=\"1754\">5 xã</strong>, bao gồm <strong data-start=\"1764\" data-end=\"1812\">Thanh Trì, Nam Phù, Bát Tràng (thuộc Hà Nội)</strong> và <strong data-start=\"1816\" data-end=\"1863\">Phụng Công, Văn Giang (thuộc tỉnh Hưng Yên)</strong>. Tổng mức đầu tư cho các dự án thành phần liên quan đến giải phóng mặt bằng dự kiến khoảng <strong data-start=\"1955\" data-end=\"1970\">784 tỷ đồng</strong>. Đây là khâu quan trọng nhằm tạo điều kiện để các hạng mục xây dựng được triển khai thuận lợi, đảm bảo tiến độ chung của toàn bộ dự án.</p>\n<p data-start=\"2108\" data-end=\"2619\">Phần <strong data-start=\"2113\" data-end=\"2179\">đầu tư xây dựng cầu Ngọc Hồi và hệ thống đường dẫn hai đầu cầu</strong> có tổng mức đầu tư khoảng <strong data-start=\"2206\" data-end=\"2224\">10.198 tỷ đồng</strong>. Khi hoàn thành, công trình sẽ góp phần <strong data-start=\"2265\" data-end=\"2313\">cải thiện điều kiện giao thông qua sông Hồng</strong>, tạo thêm một tuyến kết nối mới giữa hai bờ, đồng thời nâng cao khả năng lưu thông giữa Hà Nội và tỉnh Hưng Yên. Sự xuất hiện của cầu Ngọc Hồi cũng được kỳ vọng sẽ <strong data-start=\"2478\" data-end=\"2515\">giảm tải cho các cây cầu hiện hữu</strong> đang phải chịu áp lực giao thông lớn như <strong data-start=\"2557\" data-end=\"2618\">Chương Dương, Long Biên, Nhật Tân, Thăng Long và Vĩnh Tuy</strong>.</p>\n<p data-start=\"2621\" data-end=\"3058\">Bên cạnh ý nghĩa về giao thông, dự án còn đóng vai trò quan trọng trong việc <strong data-start=\"2698\" data-end=\"2785\">thúc đẩy quá trình đô thị hóa tại khu vực phía Nam Hà Nội và các địa phương lân cận</strong>. Hệ thống hạ tầng giao thông được cải thiện sẽ tạo điều kiện thuận lợi cho việc phát triển các khu đô thị mới, khu công nghiệp và các trung tâm dịch vụ, từ đó góp phần thực hiện chủ trương <strong data-start=\"2975\" data-end=\"3002\">giãn dân khu vực nội đô</strong>, giảm áp lực hạ tầng trong khu vực trung tâm thành phố.</p>\n<p data-start=\"3060\" data-end=\"3480\">Ngoài ra, công trình còn góp phần <strong data-start=\"3094\" data-end=\"3158\">tăng cường liên kết vùng giữa Thủ đô Hà Nội và tỉnh Hưng Yên</strong>, thúc đẩy giao thương hàng hóa, phát triển các hoạt động kinh tế và nâng cao chất lượng đời sống của người dân trong khu vực. Không chỉ mang ý nghĩa về kinh tế, dự án còn mở ra cơ hội phát triển <strong data-start=\"3354\" data-end=\"3409\">du lịch sinh thái và các hoạt động giao lưu văn hóa</strong>, tạo sự kết nối chặt chẽ hơn giữa các địa phương hai bên bờ sông Hồng.</p>\n<p data-start=\"3482\" data-end=\"4022\">Về kiến trúc, <strong data-start=\"3496\" data-end=\"3549\">cầu Ngọc Hồi được thiết kế theo dạng cầu dây văng</strong>, với <strong data-start=\"3555\" data-end=\"3595\">hai trụ tháp mang hình tượng chữ “H”</strong>, thể hiện ý nghĩa về <strong data-start=\"3617\" data-end=\"3666\">sự hòa hợp và hợp tác giữa Hà Nội và Hưng Yên</strong>. Ý tưởng kiến trúc mang tên <strong data-start=\"3695\" data-end=\"3714\">“Cổng mặt trời”</strong> được kỳ vọng sẽ tạo nên điểm nhấn nổi bật cho công trình khi hoàn thành. Với thiết kế này, cầu Ngọc Hồi không chỉ đóng vai trò là công trình giao thông quan trọng mà còn được định hướng trở thành <strong data-start=\"3911\" data-end=\"3939\">biểu tượng kiến trúc mới</strong>, góp phần làm phong phú thêm cảnh quan đô thị và không gian kiến trúc của khu vực.</p>\n<p data-start=\"4024\" data-end=\"4349\">Trong dự án này, <strong data-start=\"4041\" data-end=\"4084\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</strong> tham gia thi công các hạng mục thuộc <strong data-start=\"4122\" data-end=\"4204\">gói thầu 07/TP3-EPC: Thiết kế, cung cấp vật tư, thiết bị và xây lắp công trình</strong>, bao gồm các nội dung như khảo sát, lập mô hình thông tin công trình (BIM) và triển khai thi công các hạng mục xây dựng theo kế hoạch của dự án.</p>\n<p data-start=\"4351\" data-end=\"4797\" data-is-last-node=\"\" data-is-only-node=\"\">Theo kế hoạch triển khai, <strong data-start=\"4377\" data-end=\"4482\">dự án cầu Ngọc Hồi và đường dẫn hai đầu cầu dự kiến sẽ hoàn thành và đưa vào khai thác trong năm 2028</strong>. Khi công trình đi vào hoạt động, tuyến giao thông này được kỳ vọng sẽ trở thành <strong data-start=\"4564\" data-end=\"4635\">trục kết nối quan trọng giữa Hà Nội và các địa phương trong khu vực</strong>, góp phần hoàn thiện mạng lưới giao thông liên vùng, thúc đẩy phát triển kinh tế – xã hội và mở rộng không gian phát triển đô thị của Thủ đô trong những năm tới.</p>\n<p data-start=\"4351\" data-end=\"4797\" data-is-last-node=\"\" data-is-only-node=\"\"><img class=\"alignnone wp-image-1905 size-full\" src=\"/uploads/news/2026/03/cau-ngoc-hoi-hn2-1007.jpg\" alt=\"\" width=\"1920\" height=\"1080\" /></p>\n\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</article></div>', 390, '2025-09-05 12:08:54', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ctcp-dau-tu-ha-tang-dong-son-thi-cong-du-an-cau-ngoc-hoi-va-duong-dan-hai-dau-cau/', 0, '2026-08-12 02:08:11', '2026-08-12 02:08:11', NULL);
INSERT INTO `pvn_news_posts` VALUES (130, 'ctcp-dau-tu-ha-tang-dong-son-thi-cong-du-an-cao-toc-tuyen-quang-ha-giang-1911', 10, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN THI CÔNG DỰ ÁN CAO TỐC TUYÊN QUANG - HÀ GIANG', NULL, '<p data-start=\"306\" data-end=\"632\">Dự án đầu tư xây dựng <strong data-start=\"328\" data-end=\"376\">cao tốc Tuyên Quang – Hà Giang (giai đoạn 1)</strong> đang từng bước được triển khai nhằm hoàn thiện hệ thống hạ tầng giao thông kết nối khu vực trung du và miền núi phía Bắc. Trong khuôn khổ dự án, <strong data-start=\"522\" data-end=\"540\">gói thầu số 68</strong> đã được ký kết hợp đồng và đang chuẩn bị triển khai thi công trên địa bàn tỉnh Tuyên Quang.</p>\n<p data-start=\"634\" data-end=\"929\">Theo <strong data-start=\"639\" data-end=\"716\">Hợp đồng thi công xây dựng công trình số 68/2025/HĐ-XL ký ngày 20/12/2025</strong>, gói thầu số 68 do <strong data-start=\"736\" data-end=\"807\">Ban Quản lý dự án đầu tư xây dựng công trình số 01 tỉnh Tuyên Quang</strong> làm chủ đầu tư, được thực hiện bởi <strong>Liên danh Công ty TNHH Xây dựng Tự Lập và Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</strong>.</p>\n<p data-start=\"931\" data-end=\"1298\">Phạm vi công việc của gói thầu là <strong data-start=\"965\" data-end=\"1021\">thi công xây dựng đoạn tuyến từ Km2+715 đến Km10+815</strong> thuộc Dự án cao tốc Tuyên Quang – Hà Giang (giai đoạn 1), đoạn đi qua địa bàn tỉnh Tuyên Quang. Tổng chiều dài đoạn tuyến khoảng <strong data-start=\"1151\" data-end=\"1161\">8,1 km</strong>. Đây là một trong những hạng mục quan trọng trong tổng thể dự án, góp phần từng bước hình thành trục giao thông cao tốc kết nối khu vực.</p>\n<p data-start=\"1300\" data-end=\"1683\"><strong data-start=\"1300\" data-end=\"1355\">Tổng giá trị hợp đồng của gói thầu hơn 769 tỷ đồng.</strong> Theo kế hoạch thực hiện, <strong data-start=\"1381\" data-end=\"1427\">thời gian thi công dự kiến khoảng 18 tháng</strong> kể từ thời điểm chủ đầu tư ban hành thông báo khởi công bằng văn bản cho nhà thầu. Trong thời gian này, các đơn vị thi công sẽ triển khai các hạng mục theo thiết kế được phê duyệt, bảo đảm tuân thủ các yêu cầu về kỹ thuật, chất lượng và tiến độ của dự án.</p>\n<p data-start=\"1300\" data-end=\"1683\"><img class=\"alignnone wp-image-1913 size-full\" src=\"/uploads/news/2026/03/cao-toc-tuyen-quang-ha-giang.jpg\" alt=\"\" width=\"800\" height=\"449\" /></p>\n<p data-start=\"1685\" data-end=\"2041\">Sau khi được bàn giao mặt bằng thi công và hoàn tất các công tác chuẩn bị, các nhà thầu sẽ huy động nhân lực, máy móc, thiết bị để tổ chức thi công đồng bộ các hạng mục của tuyến đường. Đồng thời, tiến độ chi tiết của từng phần công việc sẽ được lập và trình chủ đầu tư xem xét, phê duyệt nhằm bảo đảm quá trình triển khai dự án diễn ra theo đúng kế hoạch.</p>\n<p data-start=\"2043\" data-end=\"2455\">Dự án cao tốc Tuyên Quang – Hà Giang giai đoạn 1 được triển khai trong bối cảnh nhu cầu kết nối giao thông giữa các địa phương trong khu vực ngày càng tăng. Tuyến cao tốc này khi từng bước được hoàn thiện sẽ góp phần rút ngắn thời gian di chuyển giữa các tỉnh, tạo điều kiện thuận lợi cho việc giao thương hàng hóa, đi lại của người dân cũng như thúc đẩy phát triển kinh tế – xã hội tại các địa phương dọc tuyến.</p>\n<p data-start=\"2457\" data-end=\"2944\">Bên cạnh đó, việc triển khai các gói thầu thuộc dự án cũng đóng vai trò quan trọng trong việc từng bước hoàn thiện mạng lưới giao thông khu vực, kết nối với các tuyến quốc lộ và hệ thống đường bộ hiện hữu. Khi các hạng mục được hoàn thành và đưa vào khai thác, tuyến cao tốc Tuyên Quang – Hà Giang được kỳ vọng sẽ trở thành một trong những trục giao thông quan trọng, góp phần tăng cường khả năng liên kết vùng giữa các tỉnh miền núi phía Bắc với các trung tâm kinh tế lớn trong cả nước.</p>\n<p data-start=\"2946\" data-end=\"3140\">Hiện nay, các bước chuẩn bị triển khai thi công gói thầu số 68 đang được thực hiện theo kế hoạch của dự án, hướng tới mục tiêu bảo đảm tiến độ và chất lượng của công trình theo yêu cầu đã đề ra.</p>\n<p data-start=\"2946\" data-end=\"3140\"><img class=\"alignnone wp-image-1914 size-full\" src=\"/uploads/news/2026/03/Cao-Toc-Tuyen-Quang1.jpg\" alt=\"\" width=\"1000\" height=\"616\" /></p>', 391, '2025-12-25 09:24:38', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ctcp-dau-tu-ha-tang-dong-son-thi-cong-du-an-cao-toc-tuyen-quang-ha-giang/', 0, '2026-08-12 02:08:11', '2026-08-12 02:08:11', NULL);
INSERT INTO `pvn_news_posts` VALUES (131, 'bao-cao-tai-chinh-rieng-nam-2025-da-duoc-kiem-toan-1918', 15, 'BÁO CÁO TÀI CHÍNH RIÊNG NĂM 2025 (ĐÃ ĐƯỢC KIỂM TOÁN)', NULL, 'Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"163\" data-end=\"220\">Báo cáo tài chính riêng năm 2025 đã được kiểm toán</strong> theo quy định của pháp luật về kế toán, kiểm toán và công bố thông tin trên thị trường chứng khoán.\n<p data-start=\"676\" data-end=\"839\">Báo cáo đã được kiểm toán bởi đơn vị kiểm toán độc lập theo các chuẩn mực và quy định hiện hành, với ý kiến kiểm toán được thể hiện tại Báo cáo kiểm toán đính kèm.</p>\n<p data-start=\"841\" data-end=\"1022\">Việc công bố Báo cáo tài chính riêng đã được kiểm toán nhằm đảm bảo tính minh bạch, cung cấp thông tin đầy đủ, kịp thời và chính xác tới cổ đông, nhà đầu tư và các bên liên quan.</p>\nChi tiết:\n<ul>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Việt:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/03/VN.Baocaotaichinhrieng_2025.pdf\">[VIE] Báo cáo tài chính riêng năm 2025</a></span></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Anh:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/03/EN.AuditedseparatedFS_2025.pdf\">[ENG] Báo cáo tài chính riêng 2025</a></span></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Công văn giải trình báo cáo tài chính riêng:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/03/VI.EN_.congvanbaocaotaichinhrieng_2025.pdf\">Công văn giải trình</a></span></li>\n</ul>', 324, '2026-03-17 13:50:11', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-rieng-nam-2025-da-duoc-kiem-toan/', 0, '2026-08-12 02:08:23', '2026-08-12 02:08:23', NULL);
INSERT INTO `pvn_news_posts` VALUES (132, 'bao-cao-tai-chinh-hop-nhat-nam-2025-da-duoc-kiem-toan-1924', 15, 'BÁO CÁO TÀI CHÍNH HỢP NHẤT NĂM 2025 (ĐÃ ĐƯỢC KIỂM TOÁN)', NULL, 'Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"163\" data-end=\"220\">Báo cáo tài chính hợp nhất năm 2025 đã được kiểm toán</strong> theo quy định của pháp luật về kế toán, kiểm toán và công bố thông tin trên thị trường chứng khoán.\n<p data-start=\"676\" data-end=\"839\">Báo cáo đã được kiểm toán bởi đơn vị kiểm toán độc lập theo các chuẩn mực và quy định hiện hành, với ý kiến kiểm toán được thể hiện tại Báo cáo kiểm toán đính kèm.</p>\n<p data-start=\"841\" data-end=\"1022\">Việc công bố Báo cáo tài chính hợp nhất đã được kiểm toán nhằm đảm bảo tính minh bạch, cung cấp thông tin đầy đủ, kịp thời và chính xác tới cổ đông, nhà đầu tư và các bên liên quan.</p>\nChi tiết:\n<ul>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Việt:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/03/VI.Baocaotaichinhhopnhat_2025.pdf\">[VIE] Báo cáo tài chính hợp nhất 2025</a></span></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Anh:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/03/EN.AuditedconsolidatedFS_2025.pdf\">[ENG] Báo cáo tài chính hợp nhất 2025</a></span></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Công văn giải trình báo cáo tài chính hợp nhất:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/03/VI.EN_.congvanbaocaotaichinhhopnhat_2025.pdf\">Công văn giải trình</a></span></li>\n</ul>', 324, '2026-03-17 13:52:55', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-hop-nhat-nam-2025-da-duoc-kiem-toan/', 0, '2026-08-12 02:08:34', '2026-08-12 02:08:34', NULL);
INSERT INTO `pvn_news_posts` VALUES (133, 'giai-pickleball-mo-rong-dong-son-2026-dau-an-gan-ket-va-nang-luong-tich-cuc-1939', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TỔ CHỨC GIẢI PICKLEBALL MỞ RỘNG 2026 – DẤU ẤN GẮN KẾT VÀ NĂNG LƯỢNG TÍCH CỰC', NULL, '<p data-start=\"201\" data-end=\"576\">Ngày 14/3/2026, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã tổ chức <strong data-start=\"268\" data-end=\"352\">Giải Pickleball Mở rộng Đông Sơn 2026 (Dong Son Pickleball Open Tournament 2026)</strong> với sự tham gia của đông đảo vận động viên là cán bộ nhân viên, đối tác và khách mời. Sự kiện diễn ra trong không khí sôi nổi, hào hứng, tạo nên một điểm nhấn ý nghĩa trong chuỗi hoạt động văn hóa – thể thao của các đơn vị.</p>\n<p data-start=\"578\" data-end=\"1085\">Giải đấu có sự tham gia và phối hợp tổ chức giữa ba doanh nghiệp: <strong data-start=\"644\" data-end=\"772\">Công ty Cổ phần Đầu tư BOT Hà Nội – Bắc Giang, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn và Công ty Cổ phần Đông Quang Holding</strong>. Sự đồng hành của các đơn vị không chỉ góp phần nâng cao quy mô, chất lượng tổ chức mà còn thể hiện tinh thần hợp tác, liên kết chặt chẽ giữa các doanh nghiệp trong quá trình phát triển. Đây cũng là dịp để các bên tăng cường giao lưu, mở rộng kết nối và thúc đẩy các mối quan hệ hợp tác bền vững trong tương lai.</p>\n<p data-start=\"578\" data-end=\"1085\"><img class=\"alignnone wp-image-1946 size-full\" src=\"/uploads/news/2026/03/DMQ00035-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1707\" /></p>\n<p data-start=\"1087\" data-end=\"1478\">Giải Pickleball Mở rộng Đông Sơn 2026 được tổ chức với mục tiêu xây dựng một sân chơi thể thao lành mạnh, chuyên nghiệp, tạo điều kiện để các vận động viên giao lưu, học hỏi kinh nghiệm, nâng cao thể chất và tinh thần. Đồng thời, hoạt động này còn góp phần làm phong phú đời sống tinh thần cho cán bộ nhân viên, hướng tới xây dựng môi trường làm việc tích cực, cân bằng và giàu tính gắn kết.</p>\n<p data-start=\"1480\" data-end=\"1913\">Trong suốt thời gian diễn ra, giải đấu đã thu hút sự quan tâm, cổ vũ nhiệt tình từ đông đảo khán giả. Các trận đấu diễn ra với nhịp độ nhanh, kịch tính và hấp dẫn, thể hiện rõ sự chuẩn bị kỹ lưỡng cũng như tinh thần thi đấu nghiêm túc của các vận động viên. Nhiều pha bóng đẹp mắt, những tình huống xử lý linh hoạt cùng chiến thuật hợp lý đã mang đến những màn tranh tài chất lượng, góp phần nâng cao giá trị chuyên môn của giải đấu.</p>\n<p data-start=\"1915\" data-end=\"2316\">Bên cạnh yếu tố thi đấu, giải còn tạo nên một không gian giao lưu cởi mở và thân thiện, nơi các thành viên có cơ hội gặp gỡ, trao đổi và tăng cường sự thấu hiểu lẫn nhau. Thông qua các hoạt động bên lề và sự tương tác tích cực giữa các đội tham gia, tinh thần đồng đội và sự phối hợp đã được phát huy mạnh mẽ, góp phần củng cố nền tảng văn hóa doanh nghiệp hướng tới sự đoàn kết và phát triển lâu dài.</p>\n<p data-start=\"2318\" data-end=\"2672\">Việc tổ chức giải đấu cũng thể hiện sự quan tâm của Ban Lãnh đạo các đơn vị đối với đời sống tinh thần của cán bộ nhân viên, đồng thời khuyến khích việc rèn luyện thể dục thể thao, nâng cao sức khỏe và hiệu quả làm việc. Đây là một trong những yếu tố quan trọng góp phần xây dựng nguồn nhân lực chất lượng, đáp ứng yêu cầu phát triển trong giai đoạn mới.</p>\n<p data-start=\"2318\" data-end=\"2672\"><img class=\"alignnone wp-image-1943 size-full\" src=\"/uploads/news/2026/03/DMQ00891-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1707\" /> <img class=\"alignnone wp-image-1945 size-full\" src=\"/uploads/news/2026/03/DMQ00877-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1707\" /></p>\n<p data-start=\"2674\" data-end=\"3060\">Khép lại với nhiều dấu ấn tích cực, <strong data-start=\"2710\" data-end=\"2751\">Giải Pickleball Mở rộng Đông Sơn 2026</strong> đã diễn ra thành công tốt đẹp, để lại những ấn tượng sâu sắc không chỉ về công tác tổ chức mà còn về tinh thần thi đấu và sự gắn kết giữa các đơn vị tham gia. Thành công của giải đấu là tiền đề quan trọng để các doanh nghiệp tiếp tục duy trì và phát triển các hoạt động giao lưu, hợp tác trong thời gian tới.</p>\n<p data-start=\"3062\" data-end=\"3326\">Trong chặng đường phía trước, với nền tảng là sự đồng hành, chia sẻ và gắn kết, các đơn vị kỳ vọng sẽ tiếp tục phát huy những giá trị đã được xây dựng, cùng hướng tới mục tiêu phát triển bền vững, nâng cao vị thế và đóng góp tích cực cho cộng đồng cũng như xã hội.</p>\n<p data-start=\"3062\" data-end=\"3326\"><img class=\"alignnone wp-image-1941 size-full\" src=\"/uploads/news/2026/03/DMQ01154-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1707\" /></p>', 392, '2026-03-15 14:03:13', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/giai-pickleball-mo-rong-dong-son-2026-dau-an-gan-ket-va-nang-luong-tich-cuc/', 0, '2026-08-12 02:08:35', '2026-08-12 02:08:35', NULL);
INSERT INTO `pvn_news_posts` VALUES (134, 'ctcp-dau-tu-ha-tang-dong-son-ung-ho-dong-bao-tinh-gia-lai-khac-phuc-hau-qua-thien-tai-1952', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN ỦNG HỘ ĐỒNG BÀO TỈNH GIA LAI KHẮC PHỤC HẬU QUẢ THIÊN TAI', NULL, '<p data-start=\"253\" data-end=\"585\">Ngày 02/12/2025, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã trao số tiền <strong data-start=\"326\" data-end=\"346\">100.000.000 đồng</strong> ủng hộ đồng bào tỉnh Gia Lai nhằm hỗ trợ khắc phục hậu quả thiên tai. Khoản hỗ trợ được chuyển tới địa phương thông qua Ủy ban Mặt trận Tổ quốc Việt Nam tỉnh Gia Lai để kịp thời phục vụ công tác cứu trợ và phục hồi đời sống cho người dân bị ảnh hưởng.</p>\n<p data-start=\"572\" data-end=\"911\">Trong thời gian qua, do ảnh hưởng của thiên tai, nhiều khu vực trên địa bàn tỉnh Gia Lai đã chịu thiệt hại nặng nề về nhà cửa, tài sản và đời sống sinh hoạt. Trước tình hình đó, nhu cầu hỗ trợ khẩn cấp và phục hồi sau thiên tai là hết sức cần thiết, đòi hỏi sự chung tay của toàn xã hội, trong đó có sự đóng góp của cộng đồng doanh nghiệp.</p>\n<p data-start=\"913\" data-end=\"1332\">Với tinh thần trách nhiệm và sẻ chia, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn mong muốn thông qua hoạt động ủng hộ lần này có thể góp phần hỗ trợ người dân địa phương sớm ổn định cuộc sống, từng bước khắc phục hậu quả thiên tai và tái thiết sinh kế. Sự đóng góp không chỉ mang ý nghĩa vật chất mà còn là nguồn động viên tinh thần, thể hiện sự đồng hành của doanh nghiệp đối với cộng đồng trong những thời điểm khó khăn.</p>\n<p data-start=\"1334\" data-end=\"1665\">Việc thực hiện ủng hộ thông qua Ủy ban Mặt trận Tổ quốc Việt Nam cũng đảm bảo nguồn lực được phân bổ đúng đối tượng, kịp thời và hiệu quả, góp phần nâng cao ý nghĩa thiết thực của hoạt động an sinh xã hội. Đây là cầu nối quan trọng giúp các tổ chức, doanh nghiệp gửi gắm sự hỗ trợ tới người dân một cách minh bạch và đúng mục đích.</p>\n<p data-start=\"1334\" data-end=\"1665\"><img class=\"alignnone wp-image-1954 size-full\" src=\"/uploads/news/2026/03/2098066434683635478.jpg\" alt=\"\" width=\"1600\" height=\"1066\" /></p>\n<p data-start=\"1667\" data-end=\"2057\">Bên cạnh hoạt động sản xuất kinh doanh, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn luôn chú trọng thực hiện trách nhiệm xã hội của doanh nghiệp thông qua các chương trình thiện nguyện, hỗ trợ cộng đồng và các hoạt động vì an sinh xã hội. Những đóng góp này không chỉ thể hiện cam kết phát triển bền vững mà còn góp phần lan tỏa các giá trị nhân văn, tinh thần tương thân tương ái trong xã hội.</p>\n<p data-start=\"2059\" data-end=\"2286\">Trong thời gian tới, Công ty sẽ tiếp tục đồng hành cùng các hoạt động vì cộng đồng, phát huy vai trò của doanh nghiệp trong việc chung tay xây dựng xã hội phát triển bền vững, hài hòa giữa lợi ích kinh tế và trách nhiệm xã hội.</p>', 393, '2025-12-04 09:17:29', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ctcp-dau-tu-ha-tang-dong-son-ung-ho-dong-bao-tinh-gia-lai-khac-phuc-hau-qua-thien-tai/', 0, '2026-08-12 02:08:36', '2026-08-12 02:08:36', NULL);
INSERT INTO `pvn_news_posts` VALUES (135, 'ctcp-dau-tu-ha-tang-dong-son-ung-ho-150-trieu-dong-chuong-trinh-xoa-nha-tam-nha-dot-nat-tai-huyen-giao-thuy-1957', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN ỦNG HỘ 150 TRIỆU ĐỒNG CHƯƠNG TRÌNH XÓA NHÀ TẠM, NHÀ DỘT NÁT TẠI HUYỆN GIAO THỦY', NULL, '<p data-start=\"256\" data-end=\"605\">Ngày 22/5/2025, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã trao số tiền <strong data-start=\"328\" data-end=\"348\">150.000.000 đồng</strong> ủng hộ Chương trình xóa nhà tạm, nhà dột nát trên địa bàn huyện Giao Thủy. Khoản hỗ trợ được gửi tới chương trình nhằm góp phần cải thiện điều kiện sống cho các hộ gia đình có hoàn cảnh khó khăn, từng bước nâng cao chất lượng đời sống người dân địa phương.</p>\n<p data-start=\"607\" data-end=\"985\">Chương trình xóa nhà tạm, nhà dột nát là một trong những hoạt động an sinh xã hội có ý nghĩa thiết thực, hướng tới mục tiêu đảm bảo điều kiện sinh hoạt an toàn, ổn định cho người dân, đặc biệt là các hộ nghèo, hộ cận nghèo và gia đình chính sách. Việc triển khai chương trình không chỉ giúp người dân “an cư” mà còn tạo nền tảng để phát triển kinh tế, ổn định cuộc sống lâu dài.</p>\n<p data-start=\"987\" data-end=\"1374\">Hưởng ứng chủ trương chung của Nhà nước và địa phương, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã tích cực tham gia đóng góp với tinh thần trách nhiệm và sẻ chia cùng cộng đồng. Sự hỗ trợ của Công ty không chỉ mang giá trị về vật chất mà còn thể hiện sự quan tâm, đồng hành của doanh nghiệp đối với các hoạt động vì cộng đồng, góp phần lan tỏa tinh thần tương thân tương ái trong xã hội.</p>\n<p data-start=\"1376\" data-end=\"1732\">Nguồn kinh phí ủng hộ sẽ được sử dụng để hỗ trợ xây dựng, sửa chữa nhà ở cho các hộ gia đình khó khăn trên địa bàn huyện Giao Thủy, giúp người dân có điều kiện sinh hoạt tốt hơn, yên tâm lao động sản xuất và từng bước cải thiện đời sống. Đây cũng là một trong những yếu tố quan trọng góp phần thực hiện hiệu quả mục tiêu giảm nghèo bền vững tại địa phương.</p>\n<p data-start=\"1734\" data-end=\"2018\">Hoạt động ủng hộ lần này tiếp tục khẳng định sự đồng hành thiết thực của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đối với các chương trình an sinh tại địa phương, góp phần lan tỏa những giá trị tích cực và đóng góp vào mục tiêu nâng cao chất lượng đời sống người dân một cách bền vững.</p>', 394, '2025-05-24 11:33:02', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ctcp-dau-tu-ha-tang-dong-son-ung-ho-150-trieu-dong-chuong-trinh-xoa-nha-tam-nha-dot-nat-tai-huyen-giao-thuy/', 0, '2026-08-12 02:08:36', '2026-08-12 02:08:36', NULL);
INSERT INTO `pvn_news_posts` VALUES (136, 'ctcp-dau-tu-ha-tang-dong-son-to-chuc-chuong-trinh-du-xuan-dau-nam-2026-tai-den-ong-hoang-bay-den-mau-au-co-1961', 5, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TỔ CHỨC CHƯƠNG TRÌNH DU XUÂN ĐẦU NĂM 2026 TẠI ĐỀN ÔNG HOÀNG BẢY – ĐỀN MẪU ÂU CƠ', NULL, '<p data-start=\"183\" data-end=\"464\">Ngày 06/3/2026, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã tổ chức chương trình du xuân đầu năm dành cho cán bộ nhân viên, với hành trình về thăm <strong data-start=\"329\" data-end=\"360\">Đền Ông Hoàng Bảy (Lào Cai)</strong> và <strong data-start=\"364\" data-end=\"391\">Đền Mẫu Âu Cơ (Phú Thọ)</strong> – những địa danh tâm linh mang đậm giá trị văn hóa, lịch sử của dân tộc.</p>\n<p data-start=\"466\" data-end=\"808\">Chương trình du xuân là hoạt động thường niên, thể hiện nét đẹp trong văn hóa doanh nghiệp, đồng thời là dịp để cán bộ nhân viên cùng nhau khởi đầu năm mới trong không khí trang nghiêm, thành kính. Tại các điểm đến, đoàn đã dâng hương, bày tỏ lòng tri ân đối với các bậc tiền nhân, cầu mong một năm mới bình an, thuận lợi và nhiều thành công.</p>\n<p data-start=\"810\" data-end=\"1237\">Hành trình về nguồn không chỉ mang ý nghĩa tâm linh mà còn là dịp để mỗi cá nhân thêm hiểu hơn về các giá trị văn hóa truyền thống, từ đó nuôi dưỡng tinh thần hướng về cội nguồn. Đền Ông Hoàng Bảy – nơi gắn liền với tín ngưỡng thờ Mẫu và đời sống văn hóa tâm linh của người dân vùng Tây Bắc, cùng Đền Mẫu Âu Cơ – biểu tượng thiêng liêng của nguồn cội dân tộc Việt Nam, đã mang đến cho đoàn những trải nghiệm ý nghĩa và sâu sắc.</p>\n<p data-start=\"810\" data-end=\"1237\"><img class=\"alignnone wp-image-1962 size-full\" src=\"/uploads/news/2026/03/293493294423543049.jpg\" alt=\"\" width=\"2560\" height=\"1920\" /></p>\n<p data-start=\"1239\" data-end=\"1529\">Bên cạnh các hoạt động dâng hương, chương trình còn tạo cơ hội để các cán bộ nhân viên giao lưu, chia sẻ và tăng cường sự gắn kết. Không khí gần gũi, cởi mở trong suốt hành trình đã góp phần làm phong phú đời sống tinh thần, đồng thời tiếp thêm năng lượng tích cực cho một năm làm việc mới.</p>\n<p data-start=\"1531\" data-end=\"1860\">Chuyến du xuân đầu năm 2026 khép lại với nhiều ấn tượng tốt đẹp, không chỉ ở ý nghĩa tâm linh mà còn ở giá trị kết nối nội bộ. Đây cũng là một trong những hoạt động góp phần xây dựng môi trường làm việc hài hòa, gắn kết và hướng tới sự phát triển bền vững của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trong chặng đường phía trước.</p>', 395, '2026-03-09 09:46:56', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ctcp-dau-tu-ha-tang-dong-son-to-chuc-chuong-trinh-du-xuan-dau-nam-2026-tai-den-ong-hoang-bay-den-mau-au-co/', 0, '2026-08-12 02:08:37', '2026-08-12 02:08:37', NULL);
INSERT INTO `pvn_news_posts` VALUES (137, 'thu-moi-hop-dai-hoi-dong-co-dong-thuong-nien-nam-2026-1966', 12, 'THƯ MỜI HỌP ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2026', NULL, '<p data-path-to-node=\"3\"><b data-path-to-node=\"3\" data-index-in-node=\"0\">Kính gửi Quý cổ đông,</b></p>\n<p data-path-to-node=\"4\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng kính mời Quý cổ đông tham dự Đại hội đồng cổ đông thường niên năm 2026. Đại hội sẽ được tổ chức vào lúc 09h00, Thứ Tư, ngày 22/04/2026 tại Hội trường Athene 2, Khách sạn Grand Plaza, Hà Nội.</p>\n<p data-path-to-node=\"5\">Để tiện cho việc theo dõi và chuẩn bị, Công ty xin gửi tới Quý cổ đông các tài liệu đính kèm dưới đây:</p>\n\n<ol start=\"1\" data-path-to-node=\"6\">\n 	<li>\n<p data-path-to-node=\"6,0,0\">Thư mời tham dự Đại hội đồng cổ đông.</p>\n</li>\n 	<li>\n<p data-path-to-node=\"6,1,0\">Mẫu Giấy xác nhận tham dự / Giấy ủy quyền tham dự.</p>\n</li>\n</ol>\n<p data-path-to-node=\"7\">Nhằm đảm bảo công tác tổ chức diễn ra chu đáo và đúng kế hoạch, kính đề nghị Quý cổ đông điền đầy đủ thông tin và gửi xác nhận tham dự hoặc văn bản ủy quyền về Công ty <b data-path-to-node=\"7\" data-index-in-node=\"168\">chậm nhất vào 17h00 ngày 20/04/2026</b>. Việc gửi phản hồi đúng thời hạn là rất cần thiết để Ban tổ chức hoàn thiện công tác chuẩn bị.</p>\n<p data-path-to-node=\"8\">Trân trọng cảm ơn sự đồng hành của Quý cổ đông!</p>\n<p data-path-to-node=\"8\">Tài liệu được công bố bao gồm:</p>\n\n<ul>\n 	<li data-path-to-node=\"8\"><strong>Thư mời họp:</strong>  <span style=\"color: #0000ff;\"> <a style=\"color: #0000ff;\" href=\"/uploads/news/2026/03/VI.EN_.thumoihopdhdcd2026.pdf\">Thư mời họp ĐHĐCĐ 2026</a></span></li>\n 	<li data-path-to-node=\"8\"><strong>Giấy ủy quyền:</strong> <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/03/VI.EN_.giayuyquyenhopdhdcd2026.pdf\">Giấy ủy quyền họp ĐHĐCĐ 2026</a></span></li>\n</ul>', 324, '2026-03-30 14:36:53', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thu-moi-hop-dai-hoi-dong-co-dong-thuong-nien-nam-2026/', 0, '2026-08-12 02:08:38', '2026-08-12 02:08:38', NULL);
INSERT INTO `pvn_news_posts` VALUES (138, 'tai-lieu-hop-dai-hoi-dong-co-dong-thuong-nien-2026-1975', 12, 'TÀI LIỆU HỌP ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN 2026', NULL, '<p data-path-to-node=\"3\"><b data-path-to-node=\"3\" data-index-in-node=\"0\">Kính gửi: Quý Cổ đông Công ty CP Đầu tư Hạ tầng Đông Sơn (Mã CK: DSH)</b></p>\n<p data-path-to-node=\"4\">Công ty CP Đầu tư Hạ tầng Đông Sơn trân trọng công bố bộ tài liệu phục vụ kỳ họp ĐHĐCĐ thường niên năm 2026 sẽ diễn ra vào ngày 22/04/2026 sắp tới. Bao gồm:</p>\n<p data-path-to-node=\"6\"><b data-path-to-node=\"6\" data-index-in-node=\"0\">1. Các Báo cáo Hoạt động:</b></p>\n\n<ul data-path-to-node=\"7\">\n 	<li>\n<p data-path-to-node=\"7,0,0\">Kết quả kinh doanh năm 2025 và Kế hoạch kinh doanh năm 2026.</p>\n</li>\n 	<li>\n<p data-path-to-node=\"7,1,0\">Báo cáo hoạt động của HĐQT, từng thành viên HĐQT và Ban Kiểm soát (BKS).</p>\n</li>\n</ul>\n<p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">2. Các Tờ trình Tài chính &amp; Quản trị:</b></p>\n\n<ul data-path-to-node=\"9\">\n 	<li>\n<p data-path-to-node=\"9,0,0\"><b data-path-to-node=\"9,0,0\" data-index-in-node=\"0\">Kiểm toán:</b> Thông qua báo cáo kiểm toán vốn điều lệ, tình hình sử dụng vốn và báo cáo tài chính năm 2025.</p>\n</li>\n 	<li>\n<p data-path-to-node=\"9,1,0\"><b data-path-to-node=\"9,1,0\" data-index-in-node=\"0\">Lợi nhuận &amp; Cổ tức:</b> Phương án phân phối lợi nhuận và phát hành cổ phiếu trả cổ tức năm 2025.</p>\n</li>\n 	<li>\n<p data-path-to-node=\"9,2,0\"><b data-path-to-node=\"9,2,0\" data-index-in-node=\"0\">Chiến lược doanh nghiệp:</b> Thay đổi tên Công ty và đăng ký niêm yết cổ phiếu tại Sở Giao dịch Chứng khoán TP. Hồ Chí Minh (HOSE).</p>\n</li>\n 	<li>\n<p data-path-to-node=\"9,3,0\"><b data-path-to-node=\"9,3,0\" data-index-in-node=\"0\">Phê duyệt hạn mức:</b> Hạn mức tín dụng và lựa chọn đơn vị kiểm toán cho năm 2026.</p>\n</li>\n 	<li>\n<p data-path-to-node=\"9,4,0\"><b data-path-to-node=\"9,4,0\" data-index-in-node=\"0\">Sửa đổi Điều lệ:</b> Cập nhật Điều lệ Công ty, Quy chế quản trị nội bộ và Quy chế hoạt động của HĐQT/BKS.</p>\n</li>\n</ul>\nTài liệu được công bố song ngữ, bao gồm:\n<ul>\n 	<li><strong>Bản tiếng Việt:  </strong><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/wp-content/uploads/2026/03/VIE-Tai-lieu-hop-DHDCD-2026-1.pdf\">[VIE] Tài liệu họp ĐHĐCĐ 2026</a></span></li>\n 	<li><strong>Bản tiếng Anh: </strong><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/wp-content/uploads/2026/03/ENG-Tai-lieu-hop-DHDCD-2026-1.pdf\">[ENG] Tài liệu họp ĐHĐCĐ 2026</a></span></li>\n</ul>', 324, '2026-03-30 15:03:30', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/tai-lieu-hop-dai-hoi-dong-co-dong-thuong-nien-2026/', 0, '2026-08-12 02:09:29', '2026-08-12 02:09:29', NULL);
INSERT INTO `pvn_news_posts` VALUES (139, 'bao-cao-thuong-nien-2026-1999', 13, 'BÁO CÁO THƯỜNG NIÊN NĂM 2025', NULL, '<p data-path-to-node=\"3\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng gửi đến Quý cổ đông và Đối tác <b data-path-to-node=\"3\" data-index-in-node=\"82\">Báo cáo Thường niên năm 2025</b>.</p>\n<p data-path-to-node=\"4\">Chi tiết báo cáo xem tại:</p>\nBản tiếng Việt: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/wp-content/uploads/2026/04/VIE-Bao-cao-thuong-nien-2025-1.pdf\">[VIE] Báo cáo thường niên 2025</a></span>\n\nBản tiếng Anh:<span style=\"color: #0000ff;\"> <a style=\"color: #0000ff;\" href=\"/uploads/news/2026/04/ENG-Bao-cao-thuong-nien-2025-1.pdf\">[ENG] Báo cáo thường niên 2025</a></span>', 324, '2026-04-03 17:27:08', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-thuong-nien-2026/', 0, '2026-08-12 02:09:56', '2026-08-12 02:09:56', NULL);
INSERT INTO `pvn_news_posts` VALUES (140, '2029-2-2029', 13, 'BẢN TIN NHÀ ĐẦU TƯ - QUÝ I NĂM 2026', NULL, '<p data-start=\"90\" data-end=\"307\"><strong data-start=\"90\" data-end=\"184\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn công bố Bản tin Nhà đầu tư (IR) - Quý I 2026</strong>, cung cấp thông tin cập nhật về tình hình hoạt động, kết quả kinh doanh và các nội dung trọng tâm trong giai đoạn đầu năm.</p>\n<p data-start=\"309\" data-end=\"618\">Báo cáo tập trung vào kết quả sản xuất kinh doanh năm 2025, tình hình tài chính, định hướng của Hội đồng quản trị, đồng thời cập nhật các nội dung quan trọng trình tại Đại hội đồng cổ đông thường niên năm 2026 như phương án phân phối lợi nhuận, kế hoạch niêm yết, thay đổi doanh nghiệp và các vấn đề quản trị.</p>\n<p data-start=\"620\" data-end=\"800\">Thông qua Báo cáo IR, Công ty tiếp tục khẳng định cam kết minh bạch thông tin, nâng cao hiệu quả quản trị và đồng hành cùng cổ đông, nhà đầu tư trong quá trình phát triển bền vững.</p>\n<p data-start=\"883\" data-end=\"942\" data-is-last-node=\"\" data-is-only-node=\"\">Tài liệu được công bố song ngữ, bao gồm:</p>\n\n<ul data-start=\"556\" data-end=\"656\">\n 	<li data-start=\"556\" data-end=\"606\">\n<p data-start=\"558\" data-end=\"606\"><strong data-start=\"558\" data-end=\"577\">Bản tiếng Việt: </strong><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/04/VIE-BAO-CAO-IR-QUY-I-2025.pdf\">[VIE] Bản tin Nhà đầu tư - Quý I 2026</a></span></p>\n</li>\n 	<li><strong data-start=\"558\" data-end=\"577\">Bản tiếng Anh: </strong><span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"/uploads/news/2026/04/BAO-CAO-IR-QUY-I-2025-Ver-2-eng.pdf\">[ENG] Bản tin Nhà đầu tư - Quý I 2026</a></span></li>\n</ul>', 324, '2026-04-16 13:54:13', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/2029-2/', 0, '2026-08-12 02:09:58', '2026-08-12 02:09:58', NULL);
INSERT INTO `pvn_news_posts` VALUES (141, 'nghi-quyet-hoi-dong-quan-tri-ve-viec-cham-dut-hoat-dong-chi-nhanh-6-2043', 13, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ VIỆC CHẤM DỨT HOẠT ĐỘNG CHI NHÁNH 6', NULL, '<span data-path-to-node=\"2,0\"><b data-path-to-node=\"2,0\" data-index-in-node=\"0\"><span class=\"citation-46\">CÔNG TY CỔ PHẦN ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN </span></b><span class=\"citation-46\">(MCK: DSH)</span><span class=\"citation-46\"> công bố <strong>Nghị quyết Hội đồng quản trị số 16.04/2026/NQ-HĐQT/DSH ngày 16/04/2026</strong> về việc thông qua chấm dứt hoạt động Chi nhánh 6</span></span><span data-path-to-node=\"2,2\">. </span><span data-path-to-node=\"2,4\"><span class=\"citation-45\">Theo đó, Hội đồng quản trị thống nhất chủ trương dừng hoạt động chi nhánh tại địa chỉ V11-A07 KĐT mới An Hưng, Phường Dương Nội, Hà Nội nhằm mục đích cơ cấu lại hoạt động các chi nhánh của Công ty</span></span><span data-path-to-node=\"2,6\">. </span><span data-path-to-node=\"2,8\"><span class=\"citation-44\">Việc triển khai các thủ tục pháp lý, thanh toán công nợ và tất toán hợp đồng liên quan sẽ được thực hiện đúng quy định, góp phần tối ưu hóa bộ máy vận hành và đảm bảo hiệu quả quản trị tổng thể của Công ty</span></span><span data-path-to-node=\"2,10\">.</span>\n\nChi tiết:<span style=\"color: #0000ff;\"> <a style=\"color: #0000ff;\" href=\"/uploads/news/2026/04/VI.EN_.CBTTkhac.pdf\">Nghị quyết HĐQT số 16.04/2026/NQ-HĐQT/DSH</a></span>', 324, '2026-04-16 10:39:25', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hoi-dong-quan-tri-ve-viec-cham-dut-hoat-dong-chi-nhanh-6/', 0, '2026-08-12 02:09:58', '2026-08-12 02:09:58', NULL);
INSERT INTO `pvn_news_posts` VALUES (142, 'danh-sach-thu-moi-hop-dai-hoi-dong-co-dong-2026-bi-hoan-lai-2053', 13, 'DANH SÁCH THƯ MỜI HỌP ĐẠI HỘI ĐỒNG CỔ ĐÔNG 2026 BỊ HOÀN LẠI', NULL, '<p data-path-to-node=\"4\"><b data-path-to-node=\"4\" data-index-in-node=\"0\">Kính gửi: Quý Cổ đông Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn</b></p>\n<p data-path-to-node=\"5\">Căn cứ kế hoạch tổ chức Đại hội đồng cổ đông thường niên năm 2026, Hội đồng quản trị Công ty đã thực hiện gửi Thư mời họp và tài liệu kèm theo đến các Quý cổ đông qua đường bưu điện (chuyển phát đảm bảo).</p>\n<p data-path-to-node=\"6\">Tuy nhiên, tính đến thời điểm hiện tại, do một số lý do khách quan (như cổ đông thay đổi địa chỉ nhưng không thông báo, địa chỉ không rõ ràng, hoặc không có người nhận tại nơi cư trú...), một số Thư mời đã bị đơn vị bưu điện hoàn trả về Công ty.</p>\n<p data-path-to-node=\"7\">Để đảm bảo quyền lợi của Quý cổ đông trong việc tham dự và biểu quyết tại Đại hội, Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn xin thông báo:</p>\n\n<ol start=\"1\" data-path-to-node=\"8\">\n 	<li>\n<p data-path-to-node=\"8,0,0\"><b data-path-to-node=\"8,0,0\" data-index-in-node=\"0\">Danh sách thư mời bị hoàn lại:</b> Quý cổ đông vui lòng tra cứu danh sách chi tiết các thư mời bị hoàn dưới đây:</p>\n\n<table style=\"height: 776px;\" width=\"869\">\n<tbody>\n<tr>\n<td style=\"text-align: center;\" colspan=\"4\" width=\"690\">Danh sách thư mời họp ĐHĐCĐ bị hoàn lại</td>\n</tr>\n<tr>\n<td>STT</td>\n<td>HỌ VÀ TÊN CỔ ĐÔNG</td>\n<td>ĐỊA CHỈ</td>\n<td>LÝ DO BỊ HOÀN</td>\n</tr>\n<tr>\n<td>1</td>\n<td>Phạm Đức Quý</td>\n<td>Nghĩa Hòa, Bắc Giang</td>\n<td>Thiếu địa chỉ/Không nghe máy</td>\n</tr>\n<tr>\n<td>2</td>\n<td>Lê Chí Quyết</td>\n<td>Phú Mỹ, Bà Rịa Vũng Tàu</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>3</td>\n<td>Trần Linh Linh</td>\n<td>Bình Tân, Hồ Chí Minh</td>\n<td>Shipper xác nhận người nhận đã chuyển đi/SĐT thuê bao</td>\n</tr>\n<tr>\n<td>4</td>\n<td>Trần Thăng Long</td>\n<td>Đống Đa, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>5</td>\n<td>Hoàng Trọng Nghĩa</td>\n<td>Tương Mai, Hà Nội</td>\n<td>Nhà đóng cửa/SĐT thuê bao</td>\n</tr>\n<tr>\n<td>6</td>\n<td>Nguyễn Thu Hà</td>\n<td>Hoàn Kiếm, Hà Nội</td>\n<td>Khu liên cơ quan/Không có SĐT</td>\n</tr>\n<tr>\n<td>7</td>\n<td>Đỗ Hồng Tiềm</td>\n<td>Phú Riềng, Bình Phước</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>8</td>\n<td>Ngô Phạm Dinh</td>\n<td>Phú Riềng, Bình Phước</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>9</td>\n<td>Nguyễn Mạnh Hà</td>\n<td>Lê Duẩn, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>10</td>\n<td>Thái Anh Tuấn</td>\n<td>Hai Bà Trưng, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>11</td>\n<td>Đinh Tất Thắng</td>\n<td>Hai Bà Trưng, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>12</td>\n<td>Đinh Quang Hùng</td>\n<td>Thanh Trì, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>13</td>\n<td>Vũ Hoàng Tùng</td>\n<td>Hai Bà Trưng, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>14</td>\n<td>Đoàn Phương</td>\n<td>Phạm Hùng, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>15</td>\n<td>Phạm Thị Thu Trang</td>\n<td>Thường Tín, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>16</td>\n<td>Quách Trọng Thành</td>\n<td>Thanh Xuân, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>17</td>\n<td>Đỗ Thị Thu Thương</td>\n<td>Nam Từ Liêm, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>18</td>\n<td>Dương Thị Ngọc Lan</td>\n<td>Nam Từ Liêm, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>19</td>\n<td>Trần Quỳnh Trang</td>\n<td>Nam Từ Liêm, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>20</td>\n<td>Nguyễn Thị Hà</td>\n<td>Từ Liêm, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>21</td>\n<td>Nguyễn Hoàng Quân</td>\n<td>Hoàn Kiếm, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>22</td>\n<td>Nguyễn Thanh Yên</td>\n<td>Nam Từ Liêm, Hà Nội</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n<tr>\n<td>23</td>\n<td>Vũ Thị Mai Anh</td>\n<td>Bình Thành, Hồ Chí Minh</td>\n<td>Shipper không tìm được địa chỉ/Không có SĐT</td>\n</tr>\n</tbody>\n</table>\n<b style=\"color: #555555; font-size: 14.4px;\" data-path-to-node=\"8,1,0\" data-index-in-node=\"0\"><b data-path-to-node=\"8,2,0\" data-index-in-node=\"0\">\nCách thức nhận tài liệu và đăng ký họp</b>:</b>\n<ul data-path-to-node=\"8,1,1\">\n 	<li>\n<p data-path-to-node=\"8,1,1,0,0\">Đối với các cổ đông có tên trong danh sách bị hoàn thư, Quý cổ đông có thể trực tiếp đến văn phòng Công ty để nhận thư mời hoặc liên hệ với Ban tổ chức để được hỗ trợ gửi lại.</p>\n</li>\n 	<li>\n<p data-path-to-node=\"8,1,1,1,0\">Quý cổ đông cũng có thể truy cập website công ty tại mục <b data-path-to-node=\"8,1,1,1,0\" data-index-in-node=\"57\">Quan hệ cổ đông</b> để tải toàn bộ hồ sơ, tài liệu họp và mẫu Giấy ủy quyền tham dự.</p>\n</li>\n</ul>\n</li>\n</ol>\n<p data-path-to-node=\"8,2,0\">     3.<b data-path-to-node=\"8,2,0\" data-index-in-node=\"0\"> Thông tin liên hệ hỗ trợ:</b></p>\n\n<ul data-path-to-node=\"8,2,1\">\n 	<li>\n<p data-path-to-node=\"8,2,1,0,0\"><b data-path-to-node=\"8,2,1,0,0\" data-index-in-node=\"0\">Văn phòng Công ty: </b>Tầng 11, CIC Tower, số 2 phố Nguyễn Thị Duệ, phường Yên Hòa, TP Hà Nội</p>\n</li>\n 	<li>\n<p data-path-to-node=\"8,2,1,2,0\"><b data-path-to-node=\"8,2,1,2,0\" data-index-in-node=\"0\">Số điện thoại:</b> <a title=\"\" href=\"tel:02439335708\">024 3933 5708</a></p>\n</li>\n 	<li>\n<p data-path-to-node=\"8,2,1,3,0\"><b data-path-to-node=\"8,2,1,3,0\" data-index-in-node=\"0\">Email:</b> <a title=\"\" href=\"mailto:hatangdongson@htds.vn\">dsh@htds.vn</a></p>\n</li>\n</ul>\n<p data-path-to-node=\"9\">Công ty rất mong Quý cổ đông thông cảm cho sự bất tiện này và sớm liên hệ với chúng tôi để đảm bảo việc tham dự Đại hội được diễn ra thuận lợi.</p>\n<p data-path-to-node=\"10\">Trân trọng thông báo!</p>', 324, '2026-04-20 14:48:31', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/danh-sach-thu-moi-hop-dai-hoi-dong-co-dong-2026-bi-hoan-lai/', 0, '2026-08-12 02:09:58', '2026-08-12 02:09:58', NULL);
INSERT INTO `pvn_news_posts` VALUES (143, 'bien-ban-nghi-quyet-dai-hoi-dong-co-dong-thuong-nien-nam-2026-2063', 12, 'BIÊN BẢN & NGHỊ QUYẾT ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2026', NULL, '<p data-start=\"69\" data-end=\"471\">Đại hội đồng cổ đông thường niên năm 2026 của Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã được tổ chức theo đúng quy định của Luật Doanh nghiệp và Điều lệ Công ty. Đại hội đã tiến hành thảo luận và biểu quyết thông qua các nội dung thuộc thẩm quyền, bao gồm các vấn đề quan trọng liên quan đến định hướng hoạt động, kế hoạch triển khai và các quyết sách phục vụ hoạt động sản xuất kinh doanh của Công ty.</p>\n<p data-start=\"473\" data-end=\"704\" data-is-last-node=\"\" data-is-only-node=\"\">Biên bản họp và Nghị quyết Đại hội đồng cổ đông thường niên năm 2026 ghi nhận đầy đủ diễn biến, ý kiến thảo luận và kết quả biểu quyết đối với từng nội dung được trình tại Đại hội, làm cơ sở triển khai thực hiện trong thời gian tới.</p>\n<p data-start=\"473\" data-end=\"704\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết:\nBản tiếng Việt: <a href=\"/uploads/news/2026/04/VI.bienbannghiquyetdhdcd2026phan1_compressed.pdf\">VI.bienbannghiquyetdhdcd2026phan1</a> <a href=\"/uploads/news/2026/04/VI.bienbannghiquyetdhdcd2026phan2.pdf\">VI.bienbannghiquyetdhdcd2026phan2</a>\nBản tiếng Anh: <a href=\"/uploads/news/2026/04/EN.bienbannghiquyetdhdcd2026phan1_compressed.pdf\">EN.bienbannghiquyetdhdcd2026phan1</a><a href=\"/uploads/news/2026/04/EN.bienbannghiquyetdhdcd2026phan2.pdf\">EN.bienbannghiquyetdhdcd2026phan2</a></p>', 324, '2026-04-23 15:49:55', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bien-ban-nghi-quyet-dai-hoi-dong-co-dong-thuong-nien-nam-2026/', 0, '2026-08-12 02:10:13', '2026-08-12 02:10:13', NULL);
INSERT INTO `pvn_news_posts` VALUES (144, 'cong-ty-co-phan-dau-tu-ha-tang-dong-son-dieu-le-cong-ty-sua-doi-bo-sung-nam-2025-2067', 14, 'ĐIỀU LỆ, QUY CHẾ CÔNG TY SỬA ĐỔI, BỔ SUNG NĂM 2026', NULL, '<p data-start=\"92\" data-end=\"283\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"151\" data-end=\"196\">Điều lệ, quy chế Công ty sửa đổi, bổ sung năm 2026</strong> đã được Đại hội đồng cổ đông thông qua theo đúng thẩm quyền và quy định của pháp luật.</p>\n<p data-start=\"285\" data-end=\"587\">Việc sửa đổi, bổ sung Điều lệ, quy chế được thực hiện nhằm cập nhật các nội dung liên quan đến vốn điều lệ, cơ cấu tổ chức quản lý, quyền và nghĩa vụ của cổ đông, thẩm quyền của các cơ quan quản lý trong Công ty cũng như các nội dung khác phù hợp với tình hình hoạt động thực tế và quy định pháp luật hiện hành.</p>\n<p data-start=\"589\" data-end=\"872\">Điều lệ, quy chế sửa đổi, bổ sung năm 2026 là căn cứ pháp lý quan trọng điều chỉnh toàn bộ hoạt động tổ chức và quản trị của Công ty trong giai đoạn tiếp theo, đảm bảo tính minh bạch, hiệu quả và tuân thủ quy định của Luật Doanh nghiệp, Luật Chứng khoán và các văn bản pháp luật có liên quan.</p>\n<p data-start=\"874\" data-end=\"967\" data-is-last-node=\"\" data-is-only-node=\"\">Chi tiết:</p>\n<p data-start=\"874\" data-end=\"967\" data-is-last-node=\"\" data-is-only-node=\"\">Bản tiếng Việt: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/wp-content/uploads/2026/04/VI.quychedieule2026.pdf\">VI.quychedieule2026</a></span></p>\n<p data-start=\"874\" data-end=\"967\" data-is-last-node=\"\" data-is-only-node=\"\">Bản tiếng Anh: <span style=\"color: #0000ff;\"><a style=\"color: #0000ff;\" href=\"https://htds.vn/wp-content/uploads/2026/04/EN.quychedieule2026.pdf\">EN.quychedieule2026</a></span></p>', 311, '2026-04-23 15:57:05', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/cong-ty-co-phan-dau-tu-ha-tang-dong-son-dieu-le-cong-ty-sua-doi-bo-sung-nam-2025/', 0, '2026-08-12 02:11:46', '2026-08-12 02:11:46', NULL);
INSERT INTO `pvn_news_posts` VALUES (145, 'cong-ty-co-phan-dau-tu-ha-tang-dong-son-to-chuc-thanh-cong-dai-hoi-dong-co-dong-thuong-nien-nam-2026-2073', 12, 'CTCP ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN TỔ CHỨC THÀNH CÔNG ĐẠI HỘI ĐỒNG CỔ ĐÔNG THƯỜNG NIÊN NĂM 2026', NULL, '<span style=\"font-weight: 400;\">Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn đã tổ chức thành công </span><b>Đại hội đồng cổ đông thường niên năm 2026</b><span style=\"font-weight: 400;\">, với sự tham dự của các cổ đông và đại diện được ủy quyền, cùng Hội đồng quản trị, Ban Kiểm soát và Ban Điều hành Công ty. Đại hội được tiến hành theo đúng quy định của pháp luật và Điều lệ Công ty, đảm bảo tính minh bạch, công khai và quyền lợi hợp pháp của các cổ đông tham dự.</span>\n\n<span style=\"font-weight: 400;\">Với tinh thần làm việc nghiêm túc, trách nhiệm và cầu thị, Đại hội đã tập trung thảo luận, đánh giá toàn diện tình hình hoạt động của Công ty trong năm vừa qua, đồng thời xem xét và thông qua nhiều nội dung quan trọng liên quan đến định hướng phát triển trong giai đoạn tiếp theo. Các báo cáo trình tại Đại hội bao gồm báo cáo kết quả hoạt động sản xuất kinh doanh, báo cáo tài chính đã được kiểm toán, báo cáo của Hội đồng quản trị và Ban Kiểm soát. Nội dung các báo cáo đã phản ánh đầy đủ những kết quả đạt được, những khó khăn, thách thức cũng như các giải pháp điều hành trong bối cảnh thị trường còn nhiều biến động.</span>\n\n<img class=\"alignnone wp-image-2074 size-full\" src=\"/uploads/news/2026/04/LTD03656-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1706\" />\n\n<span style=\"font-weight: 400;\">Trên cơ sở đó, Đại hội đã tiến hành thảo luận và thống nhất thông qua phương án phân phối lợi nhuận, các chỉ tiêu tài chính chủ yếu cùng nhiều nội dung quan trọng khác liên quan đến công tác quản trị, điều hành và chiến lược phát triển của Công ty. Các ý kiến đóng góp của cổ đông được ghi nhận, trao đổi thẳng thắn, qua đó góp phần hoàn thiện các định hướng điều hành trong thời gian tới.</span>\n\n<span style=\"font-weight: 400;\">Một trong những nội dung đáng chú ý tại Đại hội là việc cổ đông đã biểu quyết thông qua </span><b>chủ trương thay đổi tên Công ty</b><span style=\"font-weight: 400;\">, nhằm phù hợp hơn với tầm nhìn phát triển, định vị thương hiệu và chiến lược mở rộng trong giai đoạn mới. Cùng với đó, Đại hội cũng thông qua nội dung </span><b>bổ sung, mở rộng ngành nghề kinh doanh</b><span style=\"font-weight: 400;\">, tạo cơ sở pháp lý để Công ty đa dạng hóa lĩnh vực hoạt động, nâng cao năng lực cạnh tranh và chủ động nắm bắt các cơ hội từ thị trường.</span>\n\n<span style=\"font-weight: 400;\">Bên cạnh các nội dung nêu trên, Đại hội cũng dành thời gian trao đổi, thảo luận về các giải pháp nâng cao hiệu quả hoạt động, hoàn thiện hệ thống quản trị doanh nghiệp theo hướng hiện đại, tăng cường kiểm soát nội bộ và minh bạch thông tin. Các vấn đề liên quan đến định hướng phát triển trung và dài hạn, kế hoạch tham gia thị trường vốn, cũng như các bước chuẩn bị nhằm đáp ứng yêu cầu niêm yết trên Sở Giao dịch Chứng khoán TP. Hồ Chí Minh (HOSE) đã được trình bày và nhận được sự quan tâm, đồng thuận của các cổ đông.</span>\n\n<span style=\"font-weight: 400;\">Các nghị quyết của Đại hội đã được thông qua với tỷ lệ biểu quyết cao, thể hiện sự thống nhất trong định hướng phát triển cũng như niềm tin của cổ đông đối với Ban Lãnh đạo Công ty. Đây là cơ sở quan trọng để Công ty triển khai hiệu quả các kế hoạch đã đề ra, hướng tới mục tiêu tăng trưởng ổn định, nâng cao hiệu quả sử dụng vốn và gia tăng giá trị cho cổ đông trong dài hạn.</span>\n\n<img class=\"alignnone wp-image-2076 size-full\" src=\"/uploads/news/2026/04/LTD03829-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1706\" />\n\n<span style=\"font-weight: 400;\">Thành công của Đại hội đồng cổ đông thường niên năm 2026 không chỉ thể hiện sự tuân thủ chặt chẽ các quy định pháp luật trong công tác tổ chức, mà còn khẳng định bước tiến trong việc nâng cao chất lượng quản trị doanh nghiệp, tăng cường tính minh bạch và chuyên nghiệp trong hoạt động điều hành. Đồng thời, những nội dung được thông qua tại Đại hội sẽ là nền tảng quan trọng để Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn tiếp tục củng cố nội lực, mở rộng quy mô hoạt động và nâng cao vị thế trên thị trường trong giai đoạn phát triển mới.</span>\n\n<span style=\"font-weight: 400;\">Trong bối cảnh nền kinh tế tiếp tục có những biến động và yêu cầu ngày càng cao về năng lực quản trị, sự chủ động đổi mới, hoàn thiện mô hình tổ chức và mở rộng lĩnh vực hoạt động được xem là yếu tố then chốt để doanh nghiệp phát triển bền vững. Với những định hướng đã được Đại hội thông qua, Công ty kỳ vọng sẽ tiếp tục phát huy các lợi thế sẵn có, nâng cao hiệu quả hoạt động và từng bước hiện thực hóa các mục tiêu chiến lược đã đề ra.</span>\n\n<img class=\"alignnone wp-image-2075 size-full\" src=\"/uploads/news/2026/04/LTD03691-scaled.jpg\" alt=\"\" width=\"2560\" height=\"1706\" />', 396, '2026-04-23 09:00:52', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/cong-ty-co-phan-dau-tu-ha-tang-dong-son-to-chuc-thanh-cong-dai-hoi-dong-co-dong-thuong-nien-nam-2026/', 0, '2026-08-12 02:11:55', '2026-08-12 02:11:55', NULL);
INSERT INTO `pvn_news_posts` VALUES (146, 'bao-cao-tai-chinh-rieng-quy-1-nam-2026-2090', 15, 'BÁO CÁO TÀI CHÍNH RIÊNG QUÝ 1 NĂM 2026', NULL, 'Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"163\" data-end=\"220\">Báo cáo tài chính riêng Quý 1 năm 2026</strong> theo quy định của pháp luật về kế toán, kiểm toán và công bố thông tin trên thị trường chứng khoán.\n<p data-start=\"841\" data-end=\"1022\">Việc công bố Báo cáo tài chính riêng Quý 1 năm 2026 nhằm đảm bảo tính minh bạch, cung cấp thông tin đầy đủ, kịp thời và chính xác tới cổ đông, nhà đầu tư và các bên liên quan.</p>\nChi tiết:\n<ul>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Việt:</strong> <a href=\"/uploads/news/2026/04/VN.baocaotaichinhriengquy12026-2.pdf\">VN.baocaotaichinhriengquy12026</a></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Anh: </strong><a href=\"/uploads/news/2026/04/EN.baocaotaichinhriengquy12026-1.pdf\">EN.baocaotaichinhriengquy12026</a></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Công văn giải trình báo cáo tài chính riêng:</strong> <a href=\"/uploads/news/2026/04/VN.EN_.congvanbaocaotaichinhriengquy12026-1.pdf\">VN.EN.congvanbaocaotaichinhriengquy12026</a></li>\n</ul>', 324, '2026-04-29 17:19:01', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-rieng-quy-1-nam-2026/', 0, '2026-08-12 02:12:01', '2026-08-12 02:12:01', NULL);
INSERT INTO `pvn_news_posts` VALUES (147, 'bao-cao-tai-chinh-hop-nhat-quy-1-nam-2026-2098', 15, 'BÁO CÁO TÀI CHÍNH HỢP NHẤT QUÝ 1 NĂM 2026', NULL, 'Công ty Cổ phần Đầu tư Hạ tầng Đông Sơn trân trọng công bố <strong data-start=\"163\" data-end=\"220\">Báo cáo tài chính hợp nhất Quý 1 năm 2026</strong> theo quy định của pháp luật về kế toán, kiểm toán và công bố thông tin trên thị trường chứng khoán.\n<p data-start=\"841\" data-end=\"1022\">Việc công bố Báo cáo tài chính hợp nhất Quý 1 năm 2026 nhằm đảm bảo tính minh bạch, cung cấp thông tin đầy đủ, kịp thời và chính xác tới cổ đông, nhà đầu tư và các bên liên quan.</p>\nChi tiết:\n<ul>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Việt:</strong> <a href=\"/uploads/news/2026/04/VN.baocaotaichinhhopnhatquy12026.pdf\">VN.baocaotaichinhhopnhatquy12026</a></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Anh: </strong><a href=\"/uploads/news/2026/04/EN.baocaotaichinhhopnhatquy12026.pdf\">EN.baocaotaichinhhopnhatquy12026</a></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Công văn giải trình báo cáo tài chính riêng:</strong> <a href=\"/uploads/news/2026/04/VN.EN_.congvanbaocaotaichinhhopnhatquy12026.pdf\">VN.EN.congvanbaocaotaichinhhopnhatquy12026</a></li>\n</ul>', 324, '2026-04-29 17:21:09', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-hop-nhat-quy-1-nam-2026/', 0, '2026-08-12 02:12:07', '2026-08-12 02:12:07', NULL);
INSERT INTO `pvn_news_posts` VALUES (148, 'thong-bao-thay-doi-noi-dung-dang-ky-doanh-nghiep-2-2102', 13, 'THÔNG BÁO THAY ĐỔI NỘI DUNG ĐĂNG KÝ DOANH NGHIỆP', NULL, 'Căn cứ theo Giấy xác nhận về việc thay đổi nội dung đăng ký doanh nghiệp số 0104291191 ngày 14/05/2026, do Phòng đăng ký kinh doanh và tài chính doanh nghiệp, Sở tài chính thành phố Hà Nội cấp, Công ty Cổ phần Đông Sơn Holdings trân trọng thông báo về việc thay đổi Giấy chứng nhận doanh nghiệp của Công ty chúng tôi như sau:\n<ol>\n 	<li><strong> Thay đổi tên công ty</strong></li>\n</ol>\n1.1: Thông tin trước khi thay đổi\n\nTên công ty viết bằng tiếng Việt: CÔNG TY CỔ PHẦN ĐẦU TƯ HẠ TẦNG ĐÔNG SƠN\n\nTên công ty viết bằng tiếng nước ngoài: DONG SON INFRASTRUCTURE INVESMENT JOINT STOCK COMPANY\nTên công ty viết tắt: DONG SON INVEST ., JSC\n\n1.2: Thông tin sau khi thay đổi\n\nTên công ty viết bằng tiếng Việt: CÔNG TY CỔ PHẦN ĐÔNG SƠN HOLDINGS\n\nTên công ty viết bằng tiếng nước ngoài: DONG SON HOLDINGS JOINT STOCK COMPANY\nTên công ty viết tắt: DONG SON HOLDINGS., JSC\n<ol start=\"2\">\n 	<li><strong> Bổ sung ngành, nghề công ty</strong>\nCông ty bổ sung một số ngành, nghề kinh doanh như sau:\n<table width=\"642\">\n<tbody>\n<tr>\n<td width=\"54\"><strong>STT</strong></td>\n<td width=\"504\"><strong>Tên ngành</strong></td>\n<td width=\"84\"><strong>Mã ngành</strong></td>\n</tr>\n<tr>\n<td width=\"54\">         1.</td>\n<td width=\"504\">Sản xuất điện từ nguồn năng lượng không tái tạo</td>\n<td width=\"84\">3511</td>\n</tr>\n<tr>\n<td width=\"54\">2.</td>\n<td width=\"504\">Sản xuất điện từ nguồn năng lượng tái tạo</td>\n<td width=\"84\">3512</td>\n</tr>\n<tr>\n<td width=\"54\">         3.</td>\n<td width=\"504\">Truyền tải và phân phối điện\n\n(Trừ truyền tải và phân phối hệ thống điện quốc gia)</td>\n<td width=\"84\">3513</td>\n</tr>\n<tr>\n<td width=\"54\">         4.</td>\n<td width=\"504\">Thoát nước và xử lý nước thải</td>\n<td width=\"84\">3700</td>\n</tr>\n<tr>\n<td width=\"54\">         5.</td>\n<td width=\"504\">Xử lý và tiêu hủy rác thải không độc hại</td>\n<td width=\"84\">3821</td>\n</tr>\n<tr>\n<td width=\"54\">         6.</td>\n<td width=\"504\">Hoạt động bất động sản khác trên cơ sở phí hoặc hợp đồng\n\nChi tiết:\n\n- Dịch vụ tư vấn bất động sản\n\n(Điều 67 Luật kinh doanh bất động sản 2023)\n\n- Dịch vụ quản lý bất động sản\n\n(Điều 67 Luật kinh doanh bất động sản 2023)\n\n(Trừ hoạt động đấu giá bất động sản, Sàn giao dịch bất động sản)</td>\n<td width=\"84\">6829</td>\n</tr>\n</tbody>\n</table>\n<ol start=\"3\">\n 	<li><strong> Lý do thay đổi</strong></li>\n</ol>\nTheo nghị quyết ĐHĐCĐ thường niên năm 2026 ngày 22/04/2026 Công ty Cổ phần Đông Sơn Holdings.\n<ol start=\"4\">\n 	<li><strong> Ngày có hiệu lực: 14/05/2026</strong></li>\n 	<li><strong> Ngày Công ty nhận được Giấy xác nhận về việc thay đổi nội dung đăng ký doanh nghiệp Sở Kế hoạch &amp; Đầu tư: 15/05/2026\n</strong></li>\n</ol>\nChi tiết công bố: <a href=\"/uploads/news/2026/05/VI.EN_.thongbaothaydoinoidungdangkydoanhnghiep.pdf\">VI.EN.thongbaothaydoinoidungdangkydoanhnghiep</a></li>\n</ol>', 397, '2026-05-15 13:49:58', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-thay-doi-noi-dung-dang-ky-doanh-nghiep-2/', 0, '2026-08-12 02:12:08', '2026-08-12 02:12:08', NULL);
INSERT INTO `pvn_news_posts` VALUES (149, 'bao-cao-ve-thay-doi-so-huu-cua-co-dong-lon-nha-dau-tu-nam-giu-tu-co-phieu-5-tro-len-2112', 13, 'BÁO CÁO VỀ THAY ĐỔI SỞ HỮU CỦA CỔ ĐÔNG LỚN, NHÀ ĐẦU TƯ NẮM GIỮ TỪ CỔ PHIẾU 5% TRỞ LÊN', NULL, '<p data-start=\"93\" data-end=\"194\">Công ty Cổ phần Đông Sơn Holdings công bố thông tin về thay đổi sở hữu của cổ đông lớn như sau:</p>\n\n<ul data-start=\"196\" data-end=\"750\">\n 	<li data-start=\"196\" data-end=\"238\">\n<p data-start=\"198\" data-end=\"238\"><strong data-start=\"198\" data-end=\"220\">Họ và tên cá nhân:</strong> Vũ Hoàng Việt</p>\n</li>\n 	<li data-start=\"239\" data-end=\"308\">\n<p data-start=\"241\" data-end=\"308\"><strong data-start=\"241\" data-end=\"260\">Mã chứng khoán:</strong> DSH (Công ty Cổ phần Đông Sơn Holdings)</p>\n</li>\n 	<li data-start=\"310\" data-end=\"417\">\n<p data-start=\"312\" data-end=\"417\"><strong data-start=\"312\" data-end=\"379\">Số lượng, tỷ lệ cổ phiếu nắm giữ trước khi thực hiện giao dịch:</strong><br data-start=\"379\" data-end=\"382\" />3.281.250 cổ phiếu (tỷ lệ 9,38%)</p>\n</li>\n 	<li data-start=\"419\" data-end=\"531\">\n<p data-start=\"421\" data-end=\"531\"><strong data-start=\"421\" data-end=\"496\">Số lượng cổ phiếu đã giao dịch làm thay đổi tỷ lệ sở hữu qua ngưỡng 1%:</strong><br data-start=\"496\" data-end=\"499\" />500.000 cổ phiếu</p>\n</li>\n 	<li data-start=\"533\" data-end=\"638\">\n<p data-start=\"535\" data-end=\"638\"><strong data-start=\"535\" data-end=\"600\">Số lượng, tỷ lệ cổ phiếu nắm giữ sau khi thực hiện giao dịch:</strong><br data-start=\"600\" data-end=\"603\" />2.781.250 cổ phiếu (tỷ lệ 7,95%)</p>\n</li>\n 	<li data-start=\"640\" data-end=\"689\">\n<p data-start=\"642\" data-end=\"689\"><strong data-start=\"642\" data-end=\"668\">Lý do thay đổi sở hữu:</strong> Do nhu cầu cá nhân</p>\n</li>\n 	<li data-start=\"690\" data-end=\"750\">\n<p data-start=\"692\" data-end=\"750\"><strong data-start=\"692\" data-end=\"737\">Ngày giao dịch làm thay đổi tỷ lệ sở hữu:</strong> Ngày giao dịch 15/05/2026 (ngày hoàn tất giao dịch 19/05/2026)</p>\n</li>\n</ul>\n<p data-start=\"752\" data-end=\"922\" data-is-last-node=\"\" data-is-only-node=\"\">Việc công bố thông tin được thực hiện theo quy định của pháp luật về chứng khoán và thị trường chứng khoán đối với cổ đông lớn khi có thay đổi tỷ lệ sở hữu từ 1% trở lên.</p>', 397, '2026-05-22 09:24:54', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-ve-thay-doi-so-huu-cua-co-dong-lon-nha-dau-tu-nam-giu-tu-co-phieu-5-tro-len/', 0, '2026-08-12 02:12:08', '2026-08-12 02:12:08', NULL);
INSERT INTO `pvn_news_posts` VALUES (150, 'bao-cao-thuong-nien-2025-2132', 17, 'BÁO CÁO THƯỜNG NIÊN NĂM 2025', NULL, NULL, NULL, '2026-05-27 16:55:31', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-thuong-nien-2025/', 0, '2026-08-12 02:12:08', '2026-08-12 02:12:08', NULL);
INSERT INTO `pvn_news_posts` VALUES (151, 'bao-cao-ve-ngay-khong-con-la-co-dong-lon-nhat-nha-dau-tu-nam-giu-tu-5-tro-len-co-phieu-chung-chi-quy-dong-2143', 13, 'BÁO CÁO VỀ NGÀY KHÔNG CÒN LÀ CỔ ĐÔNG LỚN NHẤT CỦA NHÀ ĐẦU TƯ NẮM GIỮ TRÊN 5% CỔ PHIẾU', NULL, '<p data-start=\"93\" data-end=\"194\">Công ty Cổ phần Đông Sơn Holdings công bố thông tin về thay đổi sở hữu của cổ đông lớn như sau:</p>\n\n<ul data-start=\"196\" data-end=\"750\">\n 	<li data-start=\"196\" data-end=\"238\">\n<p data-start=\"198\" data-end=\"238\"><strong data-start=\"198\" data-end=\"220\">Họ và tên cá nhân:</strong> Khuất Thảo Linh</p>\n</li>\n 	<li data-start=\"239\" data-end=\"308\">\n<p data-start=\"241\" data-end=\"308\"><strong data-start=\"241\" data-end=\"260\">Mã chứng khoán:</strong> DSH (Công ty Cổ phần Đông Sơn Holdings)</p>\n</li>\n 	<li data-start=\"310\" data-end=\"417\">\n<p data-start=\"312\" data-end=\"417\"><strong data-start=\"312\" data-end=\"379\">Số lượng, tỷ lệ cổ phiếu nắm giữ trước khi thực hiện giao dịch:</strong><br data-start=\"379\" data-end=\"382\" />3.525.000 cổ phiếu (tỷ lệ 10,07%)</p>\n</li>\n 	<li data-start=\"419\" data-end=\"531\">\n<p data-start=\"421\" data-end=\"531\"><strong data-start=\"421\" data-end=\"496\">Số lượng cổ phiếu đã giao dịch làm thay đổi tỷ lệ sở hữu không còn là cổ đông lớn sở hữu từ 5% cổ phiếu:</strong><br data-start=\"496\" data-end=\"499\" />3.525.000 cổ phiếu</p>\n</li>\n 	<li data-start=\"533\" data-end=\"638\">\n<p data-start=\"535\" data-end=\"638\"><strong data-start=\"535\" data-end=\"600\">Số lượng, tỷ lệ cổ phiếu nắm giữ sau khi thực hiện giao dịch (hoặc thực hiện hoán đổi):</strong><br data-start=\"600\" data-end=\"603\" />0 cổ phiếu (tỷ lệ 0%)</p>\n</li>\n 	<li data-start=\"640\" data-end=\"689\">\n<p data-start=\"642\" data-end=\"689\"><strong data-start=\"642\" data-end=\"668\">Lý do thay đổi sở hữu:</strong> Do nhu cầu cá nhân</p>\n</li>\n 	<li data-start=\"690\" data-end=\"750\">\n<p data-start=\"692\" data-end=\"750\"><strong data-start=\"692\" data-end=\"737\">Ngày giao dịch làm thay đổi tỷ lệ sở hữu:</strong> Ngày giao dịch 27/05/2026</p>\n</li>\n</ul>\n<p data-start=\"752\" data-end=\"922\" data-is-last-node=\"\" data-is-only-node=\"\">Việc công bố thông tin được thực hiện theo quy định của pháp luật về chứng khoán và thị trường chứng khoán đối với cổ đông lớn khi có thay đổi tỷ lệ sở hữu từ 1% trở lên.</p>', 397, '2026-05-28 09:29:58', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-ve-ngay-khong-con-la-co-dong-lon-nhat-nha-dau-tu-nam-giu-tu-5-tro-len-co-phieu-chung-chi-quy-dong/', 0, '2026-08-12 02:12:08', '2026-08-12 02:12:08', NULL);
INSERT INTO `pvn_news_posts` VALUES (152, 'ctcp-dong-son-holdings-thong-bao-ve-viec-ten-cua-to-chuc-dang-ky-chung-khoan-duoc-thuc-hien-dieu-chinh-tai-vsdc-2154', 13, 'CTCP ĐÔNG SƠN HOLDINGS THÔNG BÁO VỀ VIỆC TÊN CỦA TỔ CHỨC ĐĂNG KÝ CHỨNG KHOÁN ĐƯỢC THỰC HIỆN ĐIỀU CHỈNH TẠI VSDC', NULL, 'Công ty Cổ phần Đông Sơn Holdings thông báo đã nhận được công văn số 6292/VSDC-ĐKCP.NV của Tổng công ty Lưu ký và Bù trừ chứng khoán Việt Nam về việc được thực hiện điều chỉnh tên của tổ chức đăng ký chứng khoán tại VSDC, cụ thể như sau:\n\n- Tên TCĐKCK: <strong>Công ty cổ phần Đông Sơn Holdings</strong>\n<em>(Tên trước đây: Công ty cổ phần Đầu tư Hạ tầng Đông Sơn)\n</em>\n\n- Tên tiếng Anh: <strong>Dong Son Holdings Joint Stock Company</strong><em>\n(Tên trước đây: Dong Son Infrastructure Investment Joint Stock Company)\n</em>\n\n- Tên chứng khoán: <strong>Cổ phiếu Công ty cổ phần Đông Sơn Holdings</strong><em>\n(Tên trước đây: Cổ phiếu Công ty cổ phần Đầu tư Hạ tầng Đông Sơn)\n</em>\n\n- Mã chứng khoán: <strong>DSH</strong>\n\n- Mã ISIN: <strong>VN00000DSH5</strong>\n\n- Ngày hiệu lực thay đổi tại VSDC: <strong>27/05/2026</strong>\n\nChi tiết: <span style=\"color: #000000;\"><a style=\"color: #000000;\" href=\"/uploads/news/2026/05/VSDCdieuchinhthongtinTCPH.pdf\">VSDCdieuchinhthongtinTCPH</a></span>', 397, '2026-05-29 10:47:11', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ctcp-dong-son-holdings-thong-bao-ve-viec-ten-cua-to-chuc-dang-ky-chung-khoan-duoc-thuc-hien-dieu-chinh-tai-vsdc/', 0, '2026-08-12 02:12:08', '2026-08-12 02:12:08', NULL);
INSERT INTO `pvn_news_posts` VALUES (153, 'bao-cao-ve-ngay-khong-con-la-co-dong-lon-nhat-cua-nha-dau-tu-nam-giu-tren-5-co-phieu-2161', 18, 'BÁO CÁO VỀ NGÀY KHÔNG CÒN LÀ CỔ ĐÔNG LỚN NHẤT CỦA NHÀ ĐẦU TƯ NẮM GIỮ TRÊN 5% CỔ PHIẾU', NULL, '<p data-start=\"93\" data-end=\"194\">Công ty Cổ phần Đông Sơn Holdings công bố thông tin về thay đổi sở hữu của cổ đông lớn như sau:</p>\n\n<ul data-start=\"196\" data-end=\"750\">\n 	<li data-start=\"196\" data-end=\"238\">\n<p data-start=\"198\" data-end=\"238\"><strong data-start=\"198\" data-end=\"220\">Họ và tên cá nhân:</strong> Vũ Hoàng Việt</p>\n</li>\n 	<li data-start=\"239\" data-end=\"308\">\n<p data-start=\"241\" data-end=\"308\"><strong data-start=\"241\" data-end=\"260\">Mã chứng khoán:</strong> DSH (Công ty Cổ phần Đông Sơn Holdings)</p>\n</li>\n 	<li data-start=\"310\" data-end=\"417\">\n<p data-start=\"312\" data-end=\"417\"><strong data-start=\"312\" data-end=\"379\">Số lượng, tỷ lệ cổ phiếu nắm giữ trước khi thực hiện giao dịch:</strong><br data-start=\"379\" data-end=\"382\" />2.781.250 cổ phiếu (tỷ lệ 7,95%)</p>\n</li>\n 	<li data-start=\"419\" data-end=\"531\">\n<p data-start=\"421\" data-end=\"531\"><strong data-start=\"421\" data-end=\"496\">Số lượng cổ phiếu đã giao dịch làm thay đổi tỷ lệ sở hữu không còn là cổ đông lớn sở hữu từ 5% cổ phiếu:</strong><br data-start=\"496\" data-end=\"499\" />2.781.250 cổ phiếu</p>\n</li>\n 	<li data-start=\"533\" data-end=\"638\">\n<p data-start=\"535\" data-end=\"638\"><strong data-start=\"535\" data-end=\"600\">Số lượng, tỷ lệ cổ phiếu nắm giữ sau khi thực hiện giao dịch (hoặc thực hiện hoán đổi):</strong><br data-start=\"600\" data-end=\"603\" />0 cổ phiếu (tỷ lệ 0%)</p>\n</li>\n 	<li data-start=\"640\" data-end=\"689\">\n<p data-start=\"642\" data-end=\"689\"><strong data-start=\"642\" data-end=\"668\">Lý do thay đổi sở hữu:</strong> Do nhu cầu cá nhân</p>\n</li>\n 	<li data-start=\"690\" data-end=\"750\">\n<p data-start=\"692\" data-end=\"750\"><strong data-start=\"692\" data-end=\"737\">Ngày giao dịch làm thay đổi tỷ lệ sở hữu:</strong> Ngày giao dịch 10/06/2026</p>\n</li>\n</ul>\n<p data-start=\"752\" data-end=\"922\" data-is-last-node=\"\" data-is-only-node=\"\">Việc công bố thông tin được thực hiện theo quy định của pháp luật về chứng khoán và thị trường chứng khoán đối với cổ đông lớn khi có thay đổi tỷ lệ sở hữu từ 1% trở lên.</p>', 397, '2026-06-15 09:16:27', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-ve-ngay-khong-con-la-co-dong-lon-nhat-cua-nha-dau-tu-nam-giu-tren-5-co-phieu/', 0, '2026-08-12 02:12:08', '2026-08-12 02:12:08', NULL);
INSERT INTO `pvn_news_posts` VALUES (154, 'ctcp-dong-son-holdings-cong-bo-thong-tin-bo-sung-tai-lieu-2163', 13, 'CTCP ĐÔNG SƠN HOLDINGS CÔNG BỐ THÔNG TIN BỔ SUNG TÀI LIỆU', NULL, '<span style=\"color: #000000;\">Công ty Cổ phần Đông Sơn Holdings trân trọng công bố thông tin bổ sung tài liệu và Nghị quyết Đại hội đồng cổ đông thường niên 2026: Bản tiếng Anh Báo cáo kiểm toán vốn điều lệ đã góp tăng thêm từ 01/01/2025 đến 27/11/2025 và Báo cáo kiểm toán tính hình sử dụng vốn cho đợt tăng vốn bằng hình thức chào bán cổ phiếu ra công chúng cho giai đoạn từ 28/11/2025 đến 23/12/2025, chi tiết xem tại đường link sau</span>\n\n<span style=\"color: #000000;\">Công văn công bố thông tin: <a style=\"color: #000000;\" href=\"/uploads/news/2026/06/VI.EN_.congvancongbothongtinbatthuong.pdf\">VI.EN.congvancongbothongtinbatthuong</a></span>\n<span style=\"color: #000000;\">Báo cáo kiểm toán vốn điều lệ đã góp tăng thêm (Bản tiếng Anh): <a style=\"color: #000000;\" href=\"/uploads/news/2026/06/EN.baocaokiemtoanvondieuledatangthem.pdf\">EN.baocaokiemtoanvondieuledatangthem</a></span>\n<span style=\"color: #000000;\">Báo cáo tình hình sử dụng vốn cho đợt tăng vốn bằng hình thức chào bán cổ phiếu ra công chúng (Bản tiếng Anh): <a style=\"color: #000000;\" href=\"/uploads/news/2026/06/EN.baocaotinhhinhsudungvonchodottangvon.pdf\">EN.baocaotinhhinhsudungvonchodottangvon</a></span>\n\n&nbsp;', 397, '2026-06-16 18:12:23', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ctcp-dong-son-holdings-cong-bo-thong-tin-bo-sung-tai-lieu/', 0, '2026-08-12 02:12:11', '2026-08-12 02:12:11', NULL);
INSERT INTO `pvn_news_posts` VALUES (155, 'ctcp-dong-son-holdings-ve-viec-ky-hop-dong-kiem-toan-2172', 13, 'CTCP ĐÔNG SƠN HOLDINGS CÔNG BỐ THÔNG TIN VỀ VIỆC KÝ HỢP ĐỒNG KIỂM TOÁN', NULL, 'Công ty Cổ phần Đông Sơn Holdings trân trọng công bố vào ngày 25/06/2026, Công ty Cổ phần Đông Sơn Holdings đã ký Hợp đồng kiểm toán số 25062/2026/HĐTC/IAV ngày 25/06/2026 với Công ty TNHH kiểm toán và định giá Quốc tế (IAV) về việc soát xét và kiểm toán báo cáo tài chính năm 2026, chi tiết xem tại đường link sau:\nCông văn công bố thông tin:<a href=\"/uploads/news/2026/06/VI.EN_.congbothongtinbatthuong.pdf\"> VI.EN.congbothongtinbatthuong</a>\n\nTrân trọng cảm ơn!', 397, '2026-06-25 17:19:39', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/ctcp-dong-son-holdings-ve-viec-ky-hop-dong-kiem-toan/', 0, '2026-08-12 02:12:12', '2026-08-12 02:12:12', NULL);
INSERT INTO `pvn_news_posts` VALUES (156, 'thong-bao-cham-dut-hoat-dong-van-phong-dai-dien-thanh-pho-ho-chi-minh-2178', 6, 'THÔNG BÁO CHẤM DỨT HOẠT ĐỘNG VĂN PHÒNG ĐẠI DIỆN THÀNH PHỐ HỒ CHÍ MINH', NULL, '<p class=\"PDq2pG_selectionAnchorContainer\" data-start=\"112\" data-end=\"264\">Ngày 30/6/2026, Hội đồng quản trị CTCP Đông Sơn Holdings đã ban hành Nghị quyết về việc chấm dứt hoạt động Văn phòng đại diện tại Thành phố Hồ Chí Minh.</p>\n<p data-start=\"266\" data-end=\"555\">Việc chấm dứt hoạt động được thực hiện theo định hướng sắp xếp, kiện toàn cơ cấu tổ chức nhằm nâng cao hiệu quả quản trị và tối ưu hóa hoạt động của Công ty. Các thủ tục liên quan sẽ được triển khai theo đúng quy định của pháp luật, đảm bảo quyền và lợi ích hợp pháp của các bên liên quan.</p>\n<p data-start=\"883\" data-end=\"942\" data-is-last-node=\"\" data-is-only-node=\"\">Tài liệu được công bố song ngữ, bao gồm:</p>\n\n<ul data-start=\"556\" data-end=\"656\">\n 	<li data-start=\"556\" data-end=\"606\">\n<p data-start=\"558\" data-end=\"606\"><strong data-start=\"558\" data-end=\"577\">Bản tiếng Việt: </strong><a href=\"/uploads/news/2026/07/VI_VN_CBTTBT.pdf\">[VIE] Thông báo chấm dứt hoạt động VPĐD TP HCM</a></p>\n</li>\n 	<li><strong data-start=\"558\" data-end=\"577\">Bản tiếng Anh: </strong><a href=\"/uploads/news/2026/07/VI_EN_CBTTBT.pdf\">[ENG] Thông báo chấm dứt hoạt động VPĐD TP HCM</a></li>\n</ul>\n<p data-start=\"266\" data-end=\"555\"></p>', 397, '2026-07-01 16:54:23', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-cham-dut-hoat-dong-van-phong-dai-dien-thanh-pho-ho-chi-minh/', 0, '2026-08-12 02:12:12', '2026-08-12 02:12:12', NULL);
INSERT INTO `pvn_news_posts` VALUES (157, 'thong-bao-ngay-dang-ky-cuoi-cung-chot-danh-sach-co-dong-thuc-hien-lay-y-kien-co-dong-bang-van-ban-2284', 13, 'THÔNG BÁO NGÀY ĐĂNG KÝ CUỐI CÙNG CHỐT DANH SÁCH CỔ ĐÔNG THỰC HIỆN LẤY Ý KIẾN CỔ ĐÔNG BẰNG VĂN BẢN', NULL, '<p data-start=\"883\" data-end=\"942\" data-is-last-node=\"\" data-is-only-node=\"\"><strong data-start=\"78\" data-end=\"143\">Công ty Cổ phần Đông Sơn Holdings (mã chứng khoán: DSH)</strong> trân trọng thông báo <strong data-start=\"165\" data-end=\"265\">ngày đăng ký cuối cùng để chốt danh sách cổ đông thực hiện quyền lấy ý kiến cổ đông bằng văn bản</strong> theo quy định của pháp luật và Điều lệ Công ty. Kính đề nghị Quý cổ đông theo dõi nội dung thông báo để đảm bảo quyền và lợi ích hợp pháp của mình.</p>\n<p data-start=\"883\" data-end=\"942\" data-is-last-node=\"\" data-is-only-node=\"\">Tài liệu được công bố song ngữ, bao gồm:</p>\n\n<ul data-start=\"556\" data-end=\"656\">\n 	<li data-start=\"556\" data-end=\"606\">\n<p data-start=\"558\" data-end=\"606\"><strong data-start=\"558\" data-end=\"577\">Bản tiếng Việt: <a href=\"/uploads/news/2026/07/DOC150726-15072026025408.pdf\">[VIE] Thông báo ngày đăng ký cuối cùng để chốt danh sách cổ đông</a></strong></p>\n</li>\n 	<li data-start=\"556\" data-end=\"606\">\n<p data-start=\"558\" data-end=\"606\"><strong data-start=\"558\" data-end=\"577\">Bản tiếng Anh: <a href=\"/uploads/news/2026/07/DOC150726-15072026025536.pdf\">[ENG] Thông báo ngày đăng ký cuối cùng để chốt danh sách cổ đông</a></strong></p>\n</li>\n</ul>\n&nbsp;', 397, '2026-07-15 17:10:57', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/thong-bao-ngay-dang-ky-cuoi-cung-chot-danh-sach-co-dong-thuc-hien-lay-y-kien-co-dong-bang-van-ban/', 0, '2026-08-12 02:12:13', '2026-08-12 02:12:13', NULL);
INSERT INTO `pvn_news_posts` VALUES (161, 'nghi-quyet-hoi-dong-quan-tri-ve-phuong-an-de-nghi-cap-tin-dung-tai-ngan-hang-tmcp-dau-tu-va-phat-trien-viet-nam-chi-nhanh-mi-2306', 6, 'NGHỊ QUYẾT HỘI ĐỒNG QUẢN TRỊ VỀ PHƯƠNG ÁN ĐỀ NGHỊ CẤP TÍN DỤNG TẠI NGÂN HÀNG TMCP ĐẦU TƯ VÀ PHÁT TRIỂN VIỆT NAM - CHI NHÁNH MỸ ĐÌNH', NULL, '<p data-start=\"278\" data-end=\"548\">Công ty Cổ phần Đông Sơn Holdings công bố Nghị quyết Hội đồng quản trị về việc thông qua phương án đề nghị cấp tín dụng tại Ngân hàng TMCP Đầu tư và Phát triển Việt Nam - chi nhánh Mỹ Đình.\nChi tiết: <a href=\"/uploads/news/2026/07/VI.EN_.cbttnghiquyethoidongquantri.pdf\">VI.EN.cbttnghiquyethoidongquantri</a></p>', 397, '2026-07-17 15:20:00', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/nghi-quyet-hoi-dong-quan-tri-ve-phuong-an-de-nghi-cap-tin-dung-tai-ngan-hang-tmcp-dau-tu-va-phat-trien-viet-nam-chi-nhanh-mi/', 0, '2026-08-12 02:12:14', '2026-08-12 02:12:14', NULL);
INSERT INTO `pvn_news_posts` VALUES (183, 'bao-cao-tinh-hinh-quan-tri-cong-ty-6-thang-dau-nam-2025-2371', 13, 'BÁO CÁO TÌNH HÌNH QUẢN TRỊ CÔNG TY 6 THÁNG ĐẦU NĂM 2026', NULL, '<p data-start=\"155\" data-end=\"328\">Công ty Cổ phần Đông Sơn Holdings công bố Báo cáo tình hình quản trị công ty 6 tháng đầu năm  theo quy định của pháp luật về chứng khoán và thị trường chứng khoán.</p>\n<p data-start=\"330\" data-end=\"623\" data-is-last-node=\"\" data-is-only-node=\"\">Báo cáo cung cấp thông tin về hoạt động của Hội đồng quản trị, Ban kiểm soát và Ban điều hành; việc thực hiện các nghị quyết của Đại hội đồng cổ đông; tình hình giao dịch với cổ đông, người nội bộ và người có liên quan; cũng như việc tuân thủ các quy định về quản trị công ty trong kỳ báo cáo.\nChi tiết: <a href=\"/uploads/news/2026/07/VI.baocaoquantri6thangdaunam2026bancongbo.pdf\">[Bản tiếng Việt] Báo cáo quản trị 6 tháng đầu năm 2026</a></p>\n<p data-start=\"330\" data-end=\"623\" data-is-last-node=\"\" data-is-only-node=\"\">             <a href=\"/uploads/news/2026/07/EN.baocaoquantri6thangdaunam2026bancongbo.pdf\">[Bản tiếng Anh] Báo cáo quản trị 6 tháng đầu năm 2026</a></p>', 397, '2026-07-30 14:29:44', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tinh-hinh-quan-tri-cong-ty-6-thang-dau-nam-2025/', 0, '2026-08-12 02:12:16', '2026-08-12 02:12:16', NULL);
INSERT INTO `pvn_news_posts` VALUES (184, 'bao-cao-tai-chinh-rieng-quy-nam-2026-2377', 15, 'BÁO CÁO TÀI CHÍNH RIÊNG QUÝ 2 NĂM 2026', NULL, 'Công ty Cổ phần Đông Sơn Holdings trân trọng công bố <strong data-start=\"163\" data-end=\"220\">Báo cáo tài chính riêng Quý 2 năm 2026</strong> theo quy định của pháp luật về kế toán, kiểm toán và công bố thông tin trên thị trường chứng khoán.\n<p data-start=\"841\" data-end=\"1022\">Việc công bố Báo cáo tài chính riêng Quý 2 năm 2026 nhằm đảm bảo tính minh bạch, cung cấp thông tin đầy đủ, kịp thời và chính xác tới cổ đông, nhà đầu tư và các bên liên quan.</p>\nChi tiết:\n<ul>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Việt:</strong> <a href=\"/uploads/news/2026/07/VI.baocaotaichinhriengquy22026-1.pdf\">VI.baocaotaichinhriengquy22026</a></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Anh:</strong> <a href=\"/uploads/news/2026/07/EN.baocaotaichinhriengquy22026-1.pdf\">EN.baocaotaichinhriengquy22026</a></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Công văn giải trình báo cáo tài chính riêng:</strong> <a href=\"/uploads/news/2026/07/VI.EN_.congvangiaitrinhbctcriengquy22026-1.pdf\">VI.EN.congvangiaitrinhbctcriengquy22026</a></li>\n</ul>\n<div class=\"blog-share text-center\"></div>', 397, '2026-07-30 19:06:38', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-rieng-quy-nam-2026/', 0, '2026-08-12 02:12:20', '2026-08-12 02:12:20', NULL);
INSERT INTO `pvn_news_posts` VALUES (185, 'bao-cao-tai-chinh-hop-quy-2-nam-2026-2382', 15, 'BÁO CÁO TÀI CHÍNH HỢP NHẤT QUÝ 2 NĂM 2026', NULL, 'Công ty Cổ phần Đông Sơn Holdings trân trọng công bố <strong data-start=\"163\" data-end=\"220\">Báo cáo tài chính hợp nhất Quý 2 năm 2026</strong> theo quy định của pháp luật về kế toán, kiểm toán và công bố thông tin trên thị trường chứng khoán.\n<p data-start=\"841\" data-end=\"1022\">Việc công bố Báo cáo tài chính hợp nhất Quý 2 năm 2026 nhằm đảm bảo tính minh bạch, cung cấp thông tin đầy đủ, kịp thời và chính xác tới cổ đông, nhà đầu tư và các bên liên quan.</p>\nChi tiết:\n<ul>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Việt:</strong> <a href=\"/uploads/news/2026/07/VI.baocaotaichinhhopnhatquy22026-1.pdf\">VI.baocaotaichinhhopnhatquy22026</a></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Bản tiếng Anh:</strong> <a href=\"/uploads/news/2026/07/EN.baocaotaichinhhopnhatquy22026-1.pdf\">EN.baocaotaichinhhopnhatquy22026</a></li>\n 	<li data-start=\"1024\" data-end=\"1129\"><strong>Công văn giải trình báo cáo tài chính riêng:</strong> <a href=\"/uploads/news/2026/07/VI.EN_.congvangiaitrinhbctchopnhatquy22026.pdf\">VI.EN.congvangiaitrinhbctchopnhatquy22026</a></li>\n</ul>', 397, '2026-07-30 19:12:39', 'd/m/Y', NULL, 'sm', 0, 0, 1, 0, 'published', 'https://pvnsoft.cloud/bao-cao-tai-chinh-hop-quy-2-nam-2026/', 0, '2026-08-12 02:12:25', '2026-08-12 02:12:25', NULL);
INSERT INTO `pvn_news_posts` VALUES (186, 'thong-bao-ve-viec-lay-y-kien-co-dong-bang-van-ban-2398', 13, 'THÔNG BÁO VỀ VIỆC LẤY Ý KIẾN CỔ ĐÔNG BẰNG VĂN BẢN', NULL, '<strong data-start=\"78\" data-end=\"143\">Công ty Cổ phần Đông Sơn Holdings (mã chứng khoán: DSH)</strong> trân trọng thông báo về việc<strong data-start=\"165\" data-end=\"265\"> lấy ý kiến cổ đông bằng văn bản</strong> theo quy định của pháp luật và Điều lệ Công ty. Kính đề nghị Quý cổ đông theo dõi nội dung thông báo để đảm bảo quyền và lợi ích hợp pháp của mình.\n<p data-path-to-node=\"5\"><b data-path-to-node=\"5\" data-index-in-node=\"0\">I. Nội dung xin ý kiến</b>\nHội đồng Quản trị kính trình Quý Cổ đông xem xét và thông qua nội dung sau:</p>\n\n<ul data-path-to-node=\"6\">\n 	<li>\n<p data-path-to-node=\"6,0,0\"><b data-path-to-node=\"6,0,0\" data-index-in-node=\"0\">Tờ trình số 09/2026/TTr/ĐHĐCĐ/DSH</b> ngày 31/07/2026 về việc sửa đổi Điều lệ Công ty (đính kèm).</p>\n</li>\n</ul>\n<p data-path-to-node=\"7\"><b data-path-to-node=\"7\" data-index-in-node=\"0\">II. Tài liệu đính kèm</b>\nNội dung chi tiết:\nBản tiếng Việt:  <a href=\"/uploads/news/2026/08/VI.tailieulayykiencodongbangvanban.pdf\">VI.tailieulayykiencodongbangvanban</a>\nBản tiếng Anh:  <a href=\"/uploads/news/2026/08/EN.tailieulayykiencodongbangvanban.pdf\">EN.tailieulayykiencodongbangvanban</a></p>\n<p data-path-to-node=\"8\"><b data-path-to-node=\"8\" data-index-in-node=\"0\">III. Hướng dẫn cách thức biểu quyết</b>\nĐể đảm bảo quyền lợi và tính hợp lệ của phiếu biểu quyết, Quý Cổ đông vui lòng lưu ý các bước sau:</p>\n\n<ul data-path-to-node=\"9\">\n 	<li>\n<p data-path-to-node=\"9,0,0\">Ghi nhận ý kiến bằng cách đánh dấu <b data-path-to-node=\"9,0,0\" data-index-in-node=\"35\">\"X\"</b> hoặc <b data-path-to-node=\"9,0,0\" data-index-in-node=\"44\">\"v\"</b> vào 01 (một) trong 03 ô: <b data-path-to-node=\"9,0,0\" data-index-in-node=\"73\">Tán thành</b>, <b data-path-to-node=\"9,0,0\" data-index-in-node=\"84\">Không tán thành</b>, hoặc <b data-path-to-node=\"9,0,0\" data-index-in-node=\"106\">Không có ý kiến</b> trên Phiếu lấy ý kiến.</p>\n</li>\n 	<li>\n<p data-path-to-node=\"9,1,0\"><b data-path-to-node=\"9,1,0\" data-index-in-node=\"0\">Trường hợp ủy quyền:</b> Người được ủy quyền thực hiện quyền biểu quyết phải gửi kèm theo Phiếu lấy ý kiến đã trả lời cùng <b data-path-to-node=\"9,1,0\" data-index-in-node=\"119\">Văn bản Ủy quyền</b> (bản gốc hoặc bản sao y công chứng/chứng thực hợp lệ của cơ quan có thẩm quyền). <i data-path-to-node=\"9,1,0\" data-index-in-node=\"217\">Lưu ý: Phiếu lấy ý kiến không gửi kèm Văn bản Ủy quyền sẽ bị coi là không hợp lệ.</i></p>\n</li>\n</ul>\n<p data-path-to-node=\"10\">Sự tham gia ý kiến của Quý Cổ đông đóng vai trò rất quan trọng trong sự phát triển bền vững của Công ty. Rất mong nhận được sự hợp tác và phản hồi từ Quý Cổ đông.</p>\n<p data-path-to-node=\"11\">Trân trọng,</p>\n<p data-path-to-node=\"12\"><b data-path-to-node=\"12\" data-index-in-node=\"0\">Công ty Cổ phần Đông Sơn Holdings</b></p>', 397, '2026-07-31 16:19:39', 'd/m/Y', NULL, 'sm', 0, 0, 1, 1, 'published', 'https://pvnsoft.cloud/thong-bao-ve-viec-lay-y-kien-co-dong-bang-van-ban/', 0, '2026-08-12 02:12:27', '2026-08-12 02:12:27', NULL);
