INSERT INTO `pvn_sector_capabilities` VALUES (1, 5, 'Giao thông', 'Thi công đường cao tốc, quốc lộ, cầu lớn, hầm đường bộ và các dự án hạ tầng giao thông huyết mạch, áp dụng công nghệ thi công tiên tiến nhất.', NULL, NULL, 'assets/images/linhvuc-giaothong.webp', 'assets/images/linhvuc-icon-giaothong.svg', 'large', 1, 1, '2026-08-11 14:36:56', '2026-08-11 14:36:56', NULL);
