INSERT INTO `pvn_sector_capabilities` VALUES (10, 8, 'Khu công nghiệp', 'Đầu tư, phát triển hạ tầng khu công nghiệp hiện đại, thu hút đầu tư.', NULL, NULL, NULL, 'assets/images/linhvuc-icon-congnghiep.svg', 'large', 1, 1, '2026-08-11 14:36:56', '2026-08-11 14:36:56', NULL);
